local E = ns.DB.entries
E["item:bag-of-empty-ooze-containers"] = {t="item",n="Bag of Empty Ooze Containers",z="ironforge",s="The Bag of Empty Ooze Containers is a set of sterile glassware supplied by the gnome researcher Laris Geardawdle in Ironforge. Prepared for delicate field collection, it holds empty sample jars intended to capture pristine, uncorrupted slime specimens across Azeroth.",h="The Bag of Empty Ooze Containers is a set of sterile glassware supplied by the gnome researcher Laris...",sec={{t="Field Research Equipment",b="While investigating the bizarre biology of Azeroth's oozes, Laris Geardawdle realized that slime creatures rapidly absorb and mirror the corruption of their surroundings. Having studied tainted residues from places like Felwood, the gnome scientist commissioned these robust sample jars to withstand acidic specimens while preserving their natural state. The satchel holds enough jars for an explorer to gather clean, unpolluted slime from wild, untouched regions—most notably the primordial wilderness of Un'Goro Crater, where ancient glutinous oozes thrive free from demonic taint.",sp=0}},faq={{q="What is inside the Bag of Empty Ooze Containers?",a="The bag contains ten Empty Pure Sample Jars, specially crafted glass vessels designed to safely store caustic ooze specimens without degrading or contaminating the sample.",al={"what's in the bag","bag contents","ooze container contents"},it="item"},{q="Who provided these containers?",a="They are provided by Laris Geardawdle, an eccentric gnome researcher operating out of the Hall of Explorers in Ironforge who is studying the environmental adaptations of slime.",al={"who gives the ooze bag","laris geardawdle bag","who gives bag of empty ooze containers"},it="origin"},{q="What kind of oozes are these jars meant to collect?",a="The jars are meant for pure, uncorrupted ooze samples. Unlike the blighted specimens found in Felwood, pristine slime can be collected from the glutinous oozes inhabiting Un'Goro Crater.",al={"what slime goes in the jars","pure sample jar target","where to fill jars"},it="purpose"},{q="Why does Laris need pure ooze samples?",a="Laris realized that oozes absorb the qualities of their environment, like a biological sponge. To understand how that adaptation works, he needs an uncorrupted baseline specimen to compare against polluted slimes from blighted regions.",al={"why collect pure slime","geardawdle research goal","why pure oozes"},it="why_wanted"},{q="What is the Bag of Empty Ooze Containers?",a="This sack is a kit of specialized field gear given to you by Laris Geardawdle in Ironforge. Inside are ten empty sample jars designed to hold and safely transport volatile slime specimens back to his workshop without leaking or contaminating the contents.",al={"bag of empty ooze containers","what are ooze containers","laris ooze bag"},it="identity",add=true}},ang={["race:Gnome"]="The durable, chemical-resistant jars inside the bag reflect standard gnomish ingenuity, enabling field researchers to transport dangerous, corrosive wildlife samples safely.",["faction:Alliance"]="Laris Geardawdle coordinates his ecological research from Ironforge, sending Alliance adventurers deep into untamed territories like Un'Goro Crater to bring back critical field samples."},kw={"bag of empty ooze containers","empty pure sample jar","ironforge","laris geardawdle","ooze containers","pure sample jar","slime"},rel={"quest:4512","item:filled-pure-sample-jar","npc:laris-geardawdle","zone:ironforge","zone:ungoro","zone:felwood"},src={"Bag of Empty Ooze Containers","A Little Slime Goes a Long Way (2)"}}
E["item:crocolisk-skin-classic"] = {t="item",n="Crocolisk Skin (Classic)",z="ironforge",s="Crocolisk skins are harvested from the tough hides of the crocolisks inhabiting the islands and waters of the Loch in Loch Modan. Prized by merchants and leatherworkers for their durability, they fetch a respectable price despite the danger involved in securing them.",h="Crocolisk skins are harvested from the tough hides of the crocolisks inhabiting the islands and waters of the...",sec={{t="A Dangerous Trade",b="The cold waters of the Loch teem with aggressive crocolisks that make their dens along the lake's islands and shores. Hunting them is no simple task, as these ferocious beasts possess razor-sharp teeth and thick, resilient scales capable of turning away careless blades. Despite the hazards, hunters operating out of Farstrider Lodge frequently harvest the creatures. Tailors, leatherworkers, and distant merchants continually seek out the skins to craft durable garments and protective armor, making a bundle of undamaged hides a valuable trade commodity in the region.",sp=0}},faq={{q="Where do crocolisk skins come from?",a="They are gathered from the Loch Crocolisks and Large Loch Crocolisks that inhabit the waters and islands of the Loch in Loch Modan.",al={"where to get croc skins","loch croc skin source","who drops crocolisk skin"},it="origin"},{q="Who buys or trades these hides in Loch Modan?",a="Marek Ironheart, an experienced dwarven hunter stationed at the Farstrider Lodge, collects them alongside crocolisk meat to sell to visiting merchants and craftsmen.",al={"who wants croc skins","farstrider lodge croc skins","marek ironheart skins"}},{q="Why are these skins in demand?",a="Merchants prize the tough, scaly hides for crafting sturdy clothing and armor. Because the beasts are fierce and hard to kill, good-quality skins command a reliable payout.",al={"what are croc skins used for","crocolisk leather use","why hunt crocs"},it="why_wanted"},{q="Is hunting crocolisks in the Loch considered dangerous?",a="Yes. The crocolisks are notoriously aggressive, possessing powerful jaws and serrated teeth capable of severing limbs. Local hunters like Marek Ironheart often trade tales of near-fatal encounters while trying to pin down their quarry.",al={"are loch crocs dangerous","crocolisk hunting danger"},it="danger"},{q="What is a Crocolisk Skin?",a="A Crocolisk Skin is the tough, scaled hide harvested from the crocolisks inhabiting the waters and islands of Loch Modan. Prized for its durability and distinctive texture, it serves as a valuable raw material for leatherworkers and tailors looking to craft sturdy clothing, protective gear, or specialized armor.",al={"what is crocolisk skin","crocolisk hide","what are croc skins"},it="identity",add=true}},ang={["class:Hunter"]="Farstrider Lodge respects any tracker willing to wade out to the islands and wrestle a thrashing crocolisk into submission for its hide.",["race:Dwarf"]="Loch Modan's famous crocs are a well-known local test of grit among mountaineers and lodge woodsmen alike."},kw={"crocolisk hunting","crocolisk skin","farstrider lodge","loch crocolisk","loch modan","marek ironheart","the loch"},rel={"quest:385","npc:marek-ironheart","subzone:farstrider-lodge","subzone:the-loch","zone:lochmodan","topic:hunter"},src={"Crocolisk Skin (Classic)","Crocolisk Hunting"}}
E["item:filled-cursed-ooze-jar"] = {t="item",n="Filled Cursed Ooze Jar",z="ironforge",s="A Filled Cursed Ooze Jar contains the noxious remains of a cursed ooze collected from the corrupted forests of Felwood. It is gathered on behalf of Laris Geardawdle, a gnome scholar in Ironforge seeking to uncover the primordial origins of slimes across Azeroth.",h="A Filled Cursed Ooze Jar contains the noxious remains of a cursed ooze collected from the corrupted forests...",sec={{t="A Curious Specimen",b="While most adventurers avoid the vile puddles and caustic slimes crawling across Kalimdor, the gnomish researcher Laris Geardawdle sees them as a biological mystery. Noticing that slimes appear in diverse environments and observing Forsaken apothecaries diligently harvesting them, Geardawdle developed a controversial theory: oozes might be primordial secretions tied directly to Azeroth's creation. Gathering a sample requires braving Felwood's blighted woods, defeating a cursed ooze, and scooping the acidic matter into an empty jar before it completely dissolves.",sp=0},{t="Academic Ambition",b="Securing these pungent samples serves a dual purpose for Geardawdle. Beyond the pursuit of natural science, he hopes a major discovery will cement his reputation within the dwarven-led Explorers' League. In the wake of Gnomeregan's devastating fall, many gnome refugees in Ironforge feel an intense pressure to prove their worth to their dwarven hosts, and Geardawdle believes that unlocking the ancient secrets of ooze will show everyone that welcoming gnomes was no mistake.",sp=0}},faq={{q="Where does this jar come from?",a="It is obtained by using an Empty Cursed Ooze Jar on the remains of a defeated Cursed Ooze in the corrupted lands of Felwood.",al={"where do i get cursed ooze jar","how to get filled cursed ooze jar","ooze jar location"},it="origin"},{q="Who wants these ooze samples?",a="Laris Geardawdle, a gnome researcher located in the Hall of Explorers in Ironforge, requests them to advance his natural history research.",al={"who needs ooze jars","laris geardawdle quest","who turns in ooze jar"},it="why_wanted"},{q="Why is Laris Geardawdle studying oozes?",a="He noticed that both nature and the Royal Apothecary Society take great interest in oozes. He hypothesizes that slimes might be ancient secretions tied to the very creation and development of life on Azeroth, though he needs physical samples to test his theories.",al={"why study slimes","geardawdle ooze theory","why ooze"},it="motive"},{q="Why does a gnome care about the Explorers' League?",a="Following the fall of Gnomeregan, gnome refugees took shelter among the dwarves in Ironforge. Geardawdle hopes that making a major scientific breakthrough through the Explorers' League will prove to their hosts that sheltering gnomes was the right choice.",al={"why explorers league","gnomes in ironforge"},it="ties"},{q="What is the Filled Cursed Ooze Jar?",a="It is a specially prepared specimen container packed with a fresh sample taken from a slain cursed ooze in Felwood. These foul, corrupted slimes thrive amidst the demonic decay of the tainted forest, making even small remnants volatile and dangerous to handle without proper glasswork.",al={"what is filled cursed ooze jar","filled cursed ooze jar purpose","cursed ooze jar"},it="identity",add=true}},ang={["race:Gnome"]="Laris Geardawdle's obsession with slime research is deeply personal, driven by a desire to bring honor to displaced gnomes and prove their intellectual value to the dwarven hosts in Ironforge.",["faction:Alliance"]="The Alliance's natural philosophers in Ironforge keep a watchful eye on Forsaken movements, noting that the Royal Apothecary Society has also shown a dark interest in gathering ooze samples across Azeroth."},kw={"cursed ooze","explorers' league","felwood","filled cursed ooze jar","ironforge","laris geardawdle","slime"},rel={"quest:4512","item:filled-tainted-ooze-jar","npc:laris-geardawdle","zone:felwood","zone:ironforge","topic:explorers-league","topic:royal-apothecary-society","item:package-of-empty-ooze-containers"},src={"Filled Cursed Ooze Jar","A Little Slime Goes a Long Way"}}
E["item:filled-pure-sample-jar"] = {t="item",n="Filled Pure Sample Jar",z="ironforge",s="A Filled Pure Sample Jar contains an uncorrupted specimen of primordial ooze gathered from the remote wilds. It serves as crucial baseline data for the gnome scholar Laris Geardawdle in Ironforge, who is studying how environmental corruption alters living matter.",h="A Filled Pure Sample Jar contains an uncorrupted specimen of primordial ooze gathered from the remote wilds.",sec={{t="A Search for Uncorrupted Slime",b="In his study of oozes across Azeroth, the gnomish researcher Laris Geardawdle discovered a troubling phenomenon: these amorphous creatures absorb and reflect the magical and environmental corruption of their habitats. After cataloging the tainted slimes of Felwood, Laris determined that deciphering the nature of the rot required a control group. A Filled Pure Sample Jar holds ooze harvested from pristine, untainted wilderness—such as the primordial ecology of Un'Goro Crater—offering scholars an unaltered specimen to compare against diseased and corrupted strains.",sp=0},{t="Primordial Ecology",b="Because oozes are extraordinarily malleable organisms, true 'pure' samples cannot be collected near modern civilization, demonic blights, or necromantic fallout. The glutinous oozes inhabiting the untamed basin of Un'Goro Crater remain relatively isolated from outside corruption, making them an ideal scientific standard for Ironforge's inquiring minds.",sp=0}},faq={{q="Who wants these pure samples?",a="Laris Geardawdle, a gnomish researcher stationed in Ironforge, seeks these pure jars to continue his ongoing study of Azeroth's ooze populations.",al={"laris geardawdle quest","who needs filled pure sample jar","who wants the jars"},it="why_wanted"},{q="Why does Laris need pure ooze instead of tainted ooze?",a="Laris realized that slimes rapidly adapt and absorb the properties of their surrounding environment, such as the demonic rot in Felwood. To understand the extent and mechanism of that corruption, he requires uncorrupted baseline samples for scientific comparison.",al={"why pure ooze","why pure sample","slime study purpose"},it="motive"},{q="Where can pure ooze samples be collected?",a="Pure samples are collected from the glutinous oozes inhabiting the primordial wilderness of Un'Goro Crater, where the flora and fauna remain isolated from external blights.",al={"where do i find pure ooze","pure sample jar location","where to fill pure jars"},it="target",gp=true},{q="What happens once the samples are delivered to Ironforge?",a="Laris uses the samples to conduct laboratory tests on adaptation and environmental resilience, rewarding adventurers who brave hazardous wilds to fetch them.",al={"quest reward laris","what does laris do with them"},it="next_step"},{q="What is a Filled Pure Sample Jar?",a="It is an airtight glass container packed with an untainted ooze specimen. Unlike slimes corrupted by demonic energies or blight, the substance inside represents an unpolluted baseline of ooze life, preserved carefully for academic study.",al={"what is filled pure sample jar","pure sample jar meaning","filled pure sample jar"},it="identity",add=true},{q="Where does a Filled Pure Sample Jar come from?",a="The empty containers are crafted and provided by Laris Geardawdle in Ironforge. You fill them yourself in the field by harvesting viscous remnants from wild, uncorrupted oozes found flourishing in pristine natural environments like Un'Goro Crater.",al={"filled pure sample jar origin","where do pure samples come from","who made pure sample jar"},it="origin",add=true}},ang={["race:Gnome"]="Gnomish scholars view field biology through rigorous empirical lenses; contrasting contaminated Felwood slimes against pure Un'Goro specimens exemplifies standard academic method.",["faction:Alliance"]="Alliance explorers heading into extreme territories like Un'Goro Crater provide vital natural history data back to scholars stationed safely in Ironforge."},kw={"filled pure sample jar","glutinous ooze","ironforge","laris geardawdle","ooze","slime","un'goro crater"},rel={"npc:laris-geardawdle","quest:4512","zone:ironforge","zone:ungoro","zone:felwood","item:bag-of-empty-ooze-containers"},src={"Filled Pure Sample Jar","A Little Slime Goes a Long Way (2)"}}
E["item:filled-tainted-ooze-jar"] = {t="item",n="Filled Tainted Ooze Jar",z="ironforge",s="A Filled Tainted Ooze Jar contains viscous, tainted ooze scooped directly from the remains of oozes wandering the corrupted forests of Felwood. Secured in specialized containment jars, these samples are brought to Ironforge to support radical theories regarding the origin of life on Azeroth.",h="A Filled Tainted Ooze Jar contains viscous, tainted ooze scooped directly from the remains of oozes wandering...",sec={{t="Slime of the Corrupted Wood",b="The tainted oozes roaming northern Kalimdor carry the deep, lingering corruption of Felwood. Harvesting them requires careful containment using jars provided by gnomish researchers. While most travelers avoid the noxious creatures entirely, collecting these samples provides rare material for natural philosophy and biological study far from the blighted forests.",sp=0},{t="Geardawdle's Grand Theory",b="The samples are gathered on behalf of Laris Geardawdle, an ambitious gnome scholar stationed with the Explorers' League in Ironforge. Geardawdle is fascinated by the ubiquitous nature of slimes and noticed that the Forsaken's Royal Apothecary Society has also been taking an active interest in them. Defying popular academic skepticism, he theorizes that slimes and oozes may be primal secretions tied to the very creation of Azeroth itself. Securing these samples is his attempt to prove his standing among dwarven scholars following the tragic fall of Gnomeregan.",sp=0}},faq={{q="What is inside a Filled Tainted Ooze Jar?",a="It contains a fresh, captured sample taken from the remains of a defeated Tainted Ooze native to Felwood, sealed inside a gnomish collection jar.",al={"what is in the jar","tainted ooze jar contents","what is tainted ooze"},it="identity"},{q="Who wants these ooze samples?",a="Laris Geardawdle, a gnomish researcher working alongside the Explorers' League in the Hall of Explorers in Ironforge, requests them to advance his natural history studies.",al={"who takes the ooze","laris geardawdle quest","who wants tainted ooze"},it="motive"},{q="Why is Laris Geardawdle studying oozes?",a="Geardawdle observed the Royal Apothecary Society gathering slime samples and grew determined to unravel their nature first. He harbors an unconventional theory that oozes are primordial secretions connected to the creation of Azeroth, and he hopes to cement his scientific reputation in Ironforge.",al={"why study slime","geardawdle slime theory","why does the gnome want ooze"},it="why_wanted"},{q="Where are these samples collected?",a="They are collected in Felwood by defeating Tainted Oozes and using an empty containment jar on their remains.",al={"where to find tainted ooze","tainted ooze jar location","where do i fill the jar"},it="place",gp=true},{q="Where does a Filled Tainted Ooze Jar come from, and who made it?",a="The jar itself is provided by the gnome researcher Laris Geardawdle in Ironforge, who crafts specialized empty glass containers to safely collect volatile specimens. It becomes filled only after an adventurer slays a tainted ooze in the corrupted forests of Felwood and uses the jar to scrape up remnants of the creature's gelatinous remains.",al={"tainted ooze jar origin","who made tainted ooze jar","where do tainted ooze jars come from"},it="origin",add=true}},ang={["race:Gnome"]="For gnomish refugees living in Ironforge, groundbreaking scientific contributions to the Explorers' League are vital to proving their worth and repaying dwarven hospitality after Gnomeregan's tragedy.",["faction:Alliance"]="Alliance scouts monitor the Forsaken's Royal Apothecary Society closely; understanding why the Undercity harvests slime across the continents is a key intelligence priority."},kw={"explorers' league","felwood","ironforge","laris geardawdle","royal apothecary society","slime","tainted ooze"},rel={"quest:4512","item:filled-cursed-ooze-jar","npc:laris-geardawdle","item:package-of-empty-ooze-containers","zone:felwood","zone:ironforge","topic:explorers-league","topic:royal-apothecary-society"},src={"Filled Tainted Ooze Jar","A Little Slime Goes a Long Way"}}
E["item:honorary-picks"] = {t="item",n="Honorary Picks",z="ironforge",s="The Honorary Picks are a bundle of ceremonial tools crafted in Ironforge for young dwarven mining apprentices. Entrusted to travelers by way of the gryphon network, they are delivered to Brock Stoneseeker in Thelsamar to mark his students' readiness to work the rich ore veins of Loch Modan.",h="The Honorary Picks are a bundle of ceremonial tools crafted in Ironforge for young dwarven mining apprentices.",sec={{t="Tools for the Next Generation",b="In dwarven society, mining is far more than a trade; it is a cultural cornerstone that keeps the great forges burning and the kingdom supplied with iron and stone. The Honorary Picks represent formal recognition for novice prospectors learning under Brock Stoneseeker in Thelsamar. Sourced directly from Ironforge, these picks are presented to students who have proven their dedication and are ready to tackle the open ore deposits across Loch Modan.",sp=0},{t="Testing the Gryphon Lines",b="Transporting the picks serves a secondary purpose for the mountaineers and merchants of the Alliance: introducing couriers to the kingdom's gryphon network. Ferried from Ironforge's Great Forge directly to Gryth Thurden and flown across the mountains to Thorgrum Borrelson in Thelsamar, the shipment illustrates how closely tied the capital remains to its outlying outposts through swift aerial passage.",sp=0}},faq={{q="What are the Honorary Picks used for?",a="The Honorary Picks are crafted for the mining students of Brock Stoneseeker in Loch Modan. They serve as ceremonial yet functional tools given to apprentices ready to mine ore veins across the region.",al={"what are honorary picks","use of honorary picks","honorary picks purpose"},it="purpose"},{q="Who sends the picks, and who receives them?",a="The picks are prepared in Ironforge and brought to Gryth Thurden at the city's gryphon roost. From there, they are flown east to Thelsamar and hand-delivered to mining instructor Brock Stoneseeker.",al={"who gets honorary picks","honorary picks delivery","honorary picks recipient"},it="people"},{q="Why do the picks need to be delivered by gryphon?",a="While they could be carried by foot through the North Gate Pass, sending them via gryphon master Gryth Thurden ensures rapid transport and teaches travelers how to utilize the established Alliance flight routes between Ironforge and Loch Modan.",al={"why fly picks","why take gryphon","honorary picks flight"}},{q="Are the Honorary Picks actual weapons or tools you can equip?",a="No. The courier carries them only as cargo; they are meant for Brock Stoneseeker's mining students, who are eager to put them to use on the ore deposits of Loch Modan.",al={"can i equip honorary picks","are honorary picks an item","honorary picks usable"},it="item",gp=true},{q="What are the Honorary Picks?",a="The Honorary Picks are a bundle of ceremonial or commemorative mining tools crafted in Ironforge. They are designated as a special presentation for novitiate miners learning the craft under the guidance of seasoned prospectors in the hills of Loch Modan.",al={"what are honorary picks","honorary picks item","honorary picks lore"},it="identity",add=true},{q="Where do the Honorary Picks come from, and who made them?",a="The picks are procured in the dwarven capital of Ironforge. Crafted by skilled mountain smiths in the city's Great Forge, they are packaged together specifically for transport out to instructors training apprentices beyond Dun Morogh's borders.",al={"who made honorary picks","honorary picks origin","where did the picks come from"},it="origin",add=true},{q="Why does anyone want the Honorary Picks?",a="Mining instructor Brock Stoneseeker in Thelsamar requested the picks to present to his novice students. As aspiring prospectors working in Loch Modan, the students eagerly await these honors and tools to begin working the rich mineral veins of the region.",al={"why deliver honorary picks","who wants the honorary picks","why does brock want the picks"},it="why_wanted",add=true}},ang={["profession:Mining"]="Every miner in Khaz Modan understands the value of a solid pick, and receiving an honorary tool marks a novice's true passage into the profession.",["race:Dwarf"]="To a dwarf, presenting tools forged in Ironforge to apprentices working out in the provinces is a celebrated tradition of kinship and craft."},kw={"brock stoneseeker","gryth thurden","honorary picks","ironforge","loch modan","mining picks","thelsamar","thorgrum borrelson"},rel={"npc:brock-stoneseeker","subzone:thelsamar","zone:ironforge","zone:lochmodan","quest:6388","quest:6392","npc:thorgrum-borrelson"},src={"Honorary Picks","Gryth Thurden (Classic)","Return to Brock"}}
E["item:moldy-tome"] = {t="item",n="Moldy Tome",z="ironforge",s="The Moldy Tome is a water-damaged, salvaged remnant containing half of the original Tome of the Cabal. Lost in a shipwreck off the coast of Hillsbrad Foothills, it holds dark esoteric rituals coveted by warlocks seeking to master demonic summonings.",h="The Moldy Tome is a water-damaged, salvaged remnant containing half of the original Tome of the Cabal.",sec={{t="Lost to the Waves",b="The Tome of the Cabal was a singular, irreplaceable treatise on dark arts once held within the kingdom of Lordaeron. At some point in its murky history, the grimoire was ruthlessly vandalized and split in two. The portion now designated as the Moldy Tome was being transported south by ship toward Menethil Harbor and Ironforge. The vessel never reached its destination, succumbing to the treacherous waters west of Southshore. Swept ashore south of Azurelode Mine, the surviving half lay ruined by damp and surf amidst the scavenging murlocs that stalk the Hillsbrad coast.",sp=0},{t="Reclaiming the Dark Work",b="Despite its mildewed and rotting vellum, the Moldy Tome retains potent demonic lore. Practitioners of the dark arts—guided by mentors such as Krom Stoutarm in Ironforge or Jorah Annison in the Undercity—brave the coastal encampments to recover it. Rejoined with its counterpart, the Tattered Manuscript found in the dusty caves of Thousand Needles, the restored work provides the exacting incantations needed to summon and bind a felhunter.",sp=1}},faq={{q="What is the Moldy Tome?",a="It is half of the rare Tome of the Cabal, an occult grimoire containing rituals for demonic summoning. Waterlogged and decayed, it represents the shipwrecked portion of the original text.",al={"moldy book","what is this item","moldy tome lore"},it="identity"},{q="Where did the Moldy Tome end up?",a="It washed up on the shoreline of Hillsbrad Foothills, west of Southshore and south of the Azurelode Mine. It fell into the hands of local coastal murlocs who hoard it in their encampment.",al={"moldy tome location","where is moldy tome","where to find moldy tome"}},{q="Why was the tome on a ship?",a="Originally preserved in Lordaeron, this portion was dispatched on a vessel bound for Menethil Harbor to reach Ironforge scholars. The ship foundered off the Hillsbrad coast and never completed its journey.",al={"why was it lost at sea","shipwreck tome","tome transit"}},{q="What is needed to complete the Tome of the Cabal?",a="The Moldy Tome must be reunited with the Tattered Manuscript, the other torn half of the book that wound up carried far away to Splithoof Hold in Thousand Needles.",al={"other half of the tome","missing pages","tome of the cabal parts"}},{q="Where does the Moldy Tome come from?",a="The Moldy Tome was originally part of a single, unique volume known as the Tome of the Cabal, once preserved within the great halls of Lordaeron. Long ago, the singular grimoire was vandalized, and a substantial portion of its parchment was torn away from the binding. The surviving portion of the book was slated to be shipped south from Hillsbrad across the sea to Menethil Harbor and Ironforge, but the vessel carrying it wrecked along the shore west of Southshore, leaving the damp pages to rot in the shallows.",al={"moldy tome origin","who made moldy tome","where was moldy tome kept","history of moldy tome"},it="origin",add=true},{q="Why does anyone want the Moldy Tome?",a="Scholars and practitioners of the dark arts seek it because only a single copy of the Tome of the Cabal was ever written. Its arcane passages contain rare and closely guarded warlock lore, including secrets essential for mastering the summoning and binding of felhunters. Scholars like Krom Stoutarm in Ironforge and Jorah Annison in the Undercity covet even a brief glimpse at its forbidden text, making the recovery of this waterlogged remnant vital to reuniting the full work.",al={"why find moldy tome","who wants moldy tome","why is moldy tome important","why do warlocks want moldy tome"},it="why_wanted",add=true}},ang={["class:Warlock"]="Recovering this sodden grimoire is a crucial rite of passage for warlocks seeking to piece together the rituals required to dominate a felhunter."},kw={"azurelode","felhunter","hillsbrad","moldy tome","southshore","tattered manuscript","tome of the cabal","warlock"},rel={"item:tattered-manuscript","quest:1758","quest:1471","topic:warlock","zone:hillsbrad","subzone:southshore","npc:krom-stoutarm","npc:jorah-annison"},src={"Moldy Tome","Tome of the Cabal (Alliance, 2)","Tome of the Cabal (Horde, 2)"}}
E["item:package-of-empty-ooze-containers"] = {t="item",n="Package of Empty Ooze Containers",z="ironforge",s="This package is a kit of specialized, empty specimen jars supplied by the gnome researcher Laris Geardawdle in Ironforge. Intended for dangerous field sampling in the blighted forests of Felwood, it contains jars designed to safely hold tainted and cursed ooze extracts without dissolving.",h="This package is a kit of specialized, empty specimen jars supplied by the gnome researcher Laris Geardawdle...",sec={{t="Field Research Equipment",b="Containing a dozen empty jars—split between containers meant for cursed and tainted oozes—this kit was assembled by Laris Geardawdle for intrepid travelers heading out to Felwood. Because raw ooze specimens are notoriously caustic and prone to digesting ordinary luggage, sturdy, sealed glass is essential for transporting the acidic residues across continents back to the tinker's workbench in Ironforge.",sp=0},{t="The Mystery of the Ooze",b="Geardawdle's interest in ooze is far from a simple eccentric hobby. Noticing that Forsaken researchers from the Royal Apothecary Society routinely harvest these bizarre organisms across Azeroth, he suspects oozes may hold profound secrets about the world's origin. Geardawdle theorizes that slimes might be primordial secretions connected to the planet's very creation, and he relies on field agents using this kit to collect the evidence he needs to win acclaim within the Explorers' League.",sp=0}},faq={{q="What is inside the package of empty ooze containers?",a="The package contains twelve specimen jars: six empty jars calibrated for cursed ooze and six designated for tainted ooze.",al={"package contents","what does package contain","ooze jars inside"},it="item",gp=true},{q="Who provides this package?",a="It is handed to Alliance adventurers by Laris Geardawdle, a gnomish scholar and researcher working out of Ironforge.",al={"who gives the jars","laris geardawdle quest item","where do i get the ooze package"},it="origin"},{q="Where are these containers meant to be used?",a="They are intended for use in the corrupted wilderness of Felwood, where adventurers must defeat tainted and cursed oozes to harvest residue samples directly from the fallen creatures.",al={"where do i use ooze jars","which zone for oozes","ooze jar location"},it="place",gp=true},{q="Why does Laris Geardawdle want these ooze samples?",a="Laris has noticed the Forsaken Royal Apothecary Society gathering ooze across the world and wants to uncover their secrets. He also harbors an unconventional theory that slimes might be primordial secretions tied to the creation of Azeroth, and hopes proving it will earn him status in the Explorers' League.",al={"why collect slime","geardawdle research","why does laris want ooze"},it="why_wanted"},{q="What is the Package of Empty Ooze Containers?",a="It is a field kit assembled by the gnome researcher Laris Geardawdle in Ironforge. The parcel contains a set of specially prepared jars designed to collect and safely store samples harvested from the corrupted oozes and slimes found throughout Felwood.",al={"what is package of empty ooze containers","ooze containers package","empty ooze container bundle"},it="identity",add=true}},ang={["race:Gnome"]="Laris Geardawdle sees this ooze research as a vital opportunity to show the Dwarves of Ironforge that hosting refugee gnomes was well worth the trouble.",["faction:Alliance"]="Gathering these samples helps the Alliance keep pace with the unsettling research being conducted by the Forsaken's Royal Apothecary Society."},kw={"containers","cursed","felwood","ironforge","jars","laris geardawdle","ooze","package","slime","tainted"},rel={"quest:4512","npc:laris-geardawdle","zone:felwood","zone:ironforge","item:filled-cursed-ooze-jar","item:filled-tainted-ooze-jar","topic:explorers-league","topic:royal-apothecary-society"},src={"Package of Empty Ooze Containers","A Little Slime Goes a Long Way"}}
E["item:searing-coral"] = {t="item",n="Searing Coral",z="ironforge",s="Searing Coral is a rare, resilient mineral substance harvested from living iron corals off the coast of the Wetlands. Prized by tinkerers and smiths, it possesses remarkable thermal properties that allow it to be smelted and forged into protective armor.",h="Searing Coral is a rare, resilient mineral substance harvested from living iron corals off the coast of the...",sec={{t="A Rare coastal Resource",b="Searing Coral grows exclusively in the chilly ocean waters along the coast south of Menethil Harbor in the Wetlands. Despite thriving in cold saltwater, this unique marine organism yields a mineral-rich material capable of enduring extreme heat. Harvesters brave the Wetlands' treacherous surf and coastal predators to pry the hardened formations loose.",sp=0},{t="Application in Smithing",b="While traditionally outside standard dwarven metallurgy, Searing Coral caught the attention of inquisitive minds in Ironforge. Gnome craftsmen such as Klockmort Spannerspan adapt the techniques of veteran armorsmith Furen Longbeard, smelting and hammering the coral directly into metal alloys to produce lightweight, exceptionally durable armor for aspiring warriors.",sp=0}},faq={{q="Where does Searing Coral grow?",a="Searing Coral is harvested from the seabed along the shoreline south of Menethil Harbor in the Wetlands. It grows within natural beds of iron coral submerged beneath the shallow coastal waters.",al={"searing coral location","where to find searing coral","iron coral location"},it="place",gp=true},{q="Who wants Searing Coral in Ironforge?",a="Klockmort Spannerspan, a gnomish artificer residing in Ironforge's Tinkertown, seeks Searing Coral. He uses it to experiment with smithing methods learned from the legendary dwarven armorer Furen Longbeard.",al={"who uses searing coral","klockmort spannerspan coral","furen longbeard coral"},it="why_wanted"},{q="How can coral be forged into armor?",a="Searing Coral possesses an unusually dense, heat-resistant structure. When smelted in a forge and hammered into metal alloys, it strengthens the composite plating, resulting in exceptionally tough protective gear.",al={"coral forging","can you smelt coral","searing coral metallurgy"}},{q="Is Searing Coral dangerous to harvest?",a="The coral itself is safe to gather once located, but harvesting it requires swimming through the open waters off the Wetlands' coast, where wild murlocs and aggressive aquatic beasts roam.",al={"is searing coral hot","harvesting iron coral"},it="danger",gp=true},{q="What is Searing Coral?",a="Searing Coral is a rare, mineral-rich marine growth harvested from Iron Coral formations beneath the waves along the coast of the Wetlands, south of Menethil Harbor. Despite being an oceanic specimen, its dense and peculiar properties allow it to be smelted, hammered, and worked like metal by skilled smiths.",al={"what is searing coral","searing coral info","searing coral lore"},it="identity",add=true},{q="Where does Searing Coral come from?",a="Searing Coral is a natural aquatic growth rather than a manufactured artifact. It grows exclusively in one known place in the world: amidst the iron coral beds submerged along the coastal waters south of Menethil Harbor in the Wetlands.",al={"origin of searing coral","where does searing coral come from","who made searing coral"},it="origin",add=true}},ang={["class:Warrior"]="Gathering Searing Coral is a crucial step in proving your dedication to Ironforge's master armorers, earning you a custom-forged breastplate designed to withstand heavy frontline combat.",["profession:Blacksmithing"]="The integration of Searing Coral demonstrates the inventive fusion of gnomish ingenuity and classic dwarven metalworking, turning oceanic minerals into tempered plate."},kw={"furen longbeard","iron coral","ironforge","klockmort spannerspan","menethil harbor","searing coral","warrior armor","wetlands"},rel={"quest:1708","quest:1704","subzone:menethil-harbor","zone:wetlands","zone:ironforge","npc:furen-longbeard"},src={"Searing Coral","Iron Coral (quest)"}}
E["item:senir-s-report"] = {t="item",n="Senir's Report",z="ironforge",s="Senir's Report is a dispatched document penned by Mountaineer Senir Whitebeard detailing the Frostmane troll threat in Dun Morogh. It carries findings commissioned under royal directive and is destined for Senator Barin Redstone in Ironforge.",h="Senir's Report is a dispatched document penned by Mountaineer Senir Whitebeard detailing the Frostmane troll...",sec={{t="A Royal Directive",b="Drafted after scouting missions against the Frostmane trolls nestled in the crags of Dun Morogh, this field report contains mountaineer observations intended for the dwarf Senate. Senir Whitebeard, stationed out in the cold foothills, penned the document and enclosed his brother Grelin's report on Coldridge Valley, which states that Grelin acted under a sanction from King Magni Bronzebeard. Senir tasks adventurers with hauling the findings straight to Senator Barin Redstone in the High Seat of Ironforge—cautiously advising couriers to omit just how much outside help he required to compile it.",sp=0},{t="Friction in the High Seat",b="Upon delivery to the royal court, the document sparks an immediate uproar. Reading through Whitebeard's account, Senator Barin Redstone is outraged not merely by the contents of the troll threat, but by the executive authority stamped upon it. Magni bypassing legislative oversight and Whitebeard acting on unchecked royal orders stokes long-simmering resentment within the dwarven Senate, illustrating the political strain between King Magni's decisive rule and the indignant senators who demand procedural control.",sp=1}},faq={{q="What is Senir's Report?",a="It is an official written dispatch authored by Mountaineer Senir Whitebeard summarizing his investigations into the Frostmane trolls in Dun Morogh, written to be delivered directly to the dwarven Senate in Ironforge.",al={"senirs report","what is this report","the report"},it="identity"},{q="Who is supposed to receive the report?",a="The report is addressed to Senator Barin Redstone, a sour dwarven politician situated near King Magni Bronzebeard's throne in the High Seat of Ironforge.",al={"who gets the report","who do i give the report to","report recipient"},it="target"},{q="Why does Senator Redstone get so angry when he reads it?",a="Senator Redstone is furious because the enclosed report from Senir's brother, Grelin Whitebeard, reveals that Grelin acted under King Magni's authority rather than consulting the dwarven Senate. Redstone resents the crown taking unilateral action over defense matters without senatorial approval.",al={"why is barin mad","why is the senator angry","redstone reaction"},sp=1,it="conflict"},{q="Why does Senir ask you not to mention helping him?",a="Senir Whitebeard prefers his superiors to believe he handled the hazardous scouting work in the snowy hills entirely on his own, wanting to protect his reputation as a diligent and capable mountaineer.",al={"why keep quiet","senir secret","senir credit"},it="motive"},{q="Where does Senir's Report come from, and who made it?",a="Senir Whitebeard drafted this dispatch himself in Dun Morogh after scouting out the local Frostmane troll threats and securing aid in dealing with Frostmane Hold. Along with his own findings, it encloses his brother Grelin's report on Coldridge Valley, which Grelin wrote under a sanction from King Magni Bronzebeard, and carries both from the snowy frontiers into the great halls of the capital.",al={"who wrote senirs report","where did senirs report come from","author of senirs report"},it="origin",add=true},{q="Why does anyone want Senir's Report?",a="Senator Barin Redstone and the Ironforge Senate require official field assessments to track regional developments and military actions in Dun Morogh. However, because this specific dispatch asserts King Magni's unilateral authority over local maneuvers, it carries sharp political weight, informing the Senate of crown actions they feel bypass their oversight.",al={"why deliver senirs report","why does redstone need senirs report","purpose of senirs report"},it="why_wanted",add=true}},ang={["race:Dwarf"]="Carrying Senir's Report exposes the sharp political divide between King Magni Bronzebeard's royal decrees and the traditional authority demanded by the Senate in Ironforge.",["faction:Alliance"]="Handling Senir's Report aids the defense of Dun Morogh while navigating the prickly internal politics of Ironforge's ruling class."},kw={"barin redstone","frostmane","ironforge","magni bronzebeard","senate","senir whitebeard","senir's report","the reports"},rel={"quest:291","quest:287","zone:ironforge","subzone:kharanos"},src={"Senir's Report","The Reports"}}
E["item:tattered-manuscript"] = {t="item",n="Tattered Manuscript",z="ironforge",s="The Tattered Manuscript consists of loose, vandalized pages torn from the singular copy of the Tome of the Cabal. Hidden away in the dusty depths of southern Kalimdor, this battered portion of the text holds arcane secrets vital to warlocks seeking mastery over felhunters.",h="The Tattered Manuscript consists of loose, vandalized pages torn from the singular copy of the Tome of the...",sec={{t="A Vandalized Grimoire",b="The Tome of the Cabal was once an intact, unique volume safeguarded within the fallen kingdom of Lordaeron. At some point, an unknown defiler ripped almost half of the treatise directly from its binding. While the surviving spine and remainder of the book—now known as the Moldy Tome—were shipped south toward Khaz Modan and lost at sea, these torn parchment leaves drifted far across the Great Sea into Kalimdor, ultimately falling into the hands of the Galak centaur inside Splithoof Hold.",sp=0},{t="Reclaiming the Words",b="Kept within a battered chest deep within the labyrinthine caverns of Splithoof Hold, the manuscript survived the harsh arid winds of Thousand Needles. Despite its fragile, tattered state, practitioners of the dark arts—both Alliance warlocks working with Krom Stoutarm in Ironforge and Horde practitioners aiding Jorah Annison in the Undercity—brave the aggressive centaur to reunite these lost leaves with the Moldy Tome. Once combined, the completed treatise contains the dark rituals necessary to summon and bind a demonic felhunter.",sp=0}},faq={{q="What is the Tattered Manuscript?",a="It is a collection of torn parchment leaves comprising roughly half of the Tome of the Cabal, a legendary and unique grimoire on demonology.",al={"tattered manuscript lore","what is manuscript","pages tome cabal"},it="identity"},{q="How did these pages end up in Thousand Needles?",a="After the grimoire was vandalized in Lordaeron, the ripped pages somehow crossed the sea and fell into the possession of the Galak centaur, who stashed them in a chest inside Splithoof Hold.",al={"why in splithoof","centaur tome","thousand needles manuscript"},it="place"},{q="What is the manuscript used for?",a="Warlocks must recombine the Tattered Manuscript with the waterlogged Moldy Tome to reconstruct the full text of the Tome of the Cabal, unlocking the ritual to summon a felhunter.",al={"why do i need manuscript","felhunter quest pages"},it="why_wanted"},{q="Who was responsible for tearing the original book apart?",a="The culprit remains unknown. Both Krom Stoutarm in Ironforge and Jorah Annison in the Undercity lament the vandalism, baffled by who would commit such an act against a one-of-a-kind scholarly work.",al={"who ripped the tome","who vandalized tome cabal"},it="origin"}},ang={["class:Warlock"]="Retrieving the manuscript is an essential rite of passage for aspiring warlocks, granting the knowledge required to bend predatory felhunters to their will."},kw={"felhunter","jorah annison","krom stoutarm","moldy tome","splithoof hold","tattered manuscript","thousand needles","tome of the cabal"},rel={"item:moldy-tome","quest:1758","quest:1471","subzone:splithoof-hold","zone:thousandneedles","npc:krom-stoutarm","npc:jorah-annison","topic:warlock"},src={"Tattered Manuscript","Tome of the Cabal (Alliance, 2)","Tome of the Cabal (Horde, 2)"}}
E["npc:brandur-ironhammer"] = {t="npc",n="Brandur Ironhammer",z="ironforge",s="Brandur Ironhammer is a dwarven paladin trainer residing in the Hall of Mysteries within Ironforge. He guides aspiring champions of the Holy Light through their early rites, testing their devotion and dispatching them across the Alliance.",h="Brandur Ironhammer is a dwarven paladin trainer residing in the Hall of Mysteries within Ironforge.",sec={{t="A Guide in the Mystic Ward",b="Stationed within the quiet alcoves of the Hall of Mysteries, Brandur Ironhammer serves the Alliance by instructing novice paladins in the ways of the Holy Light. Alongside his peer, Tiza Battleforge, Brandur keeps a watchful eye on young dwarven champions, guiding them through the trials of the Tome of Divinity. While deeply committed to his holy duties, he has acknowledged personal flaws under Tiza's frank counsel, working diligently to temper his envy and maintain the inner purity demanded of a warrior of the Light.",sp=0},{t="Connecting the Silver Hand",b="Brandur serves as an essential liaison between Ironforge and the wider Alliance brotherhood. When human initiates find their way into the dwarven mountain, he redirects them back south to Duthorian Rall in the Cathedral of Light. As paladins grow seasoned in the field, Brandur coordinates their deployment to battlegrounds such as Chillwind Camp in the Western Plaguelands, eventually sending veteran crusaders to Lord Grayson Shadowbreaker to undertake the demanding trials of the war charger.",sp=0}},faq={{q="Where is Brandur Ironhammer located?",a="Brandur is located inside the Hall of Mysteries, which sits in the Mystic Ward on the northern side of Ironforge.",al={"brandur ironhammer location","find brandur ironhammer","where is brandur"},it="place",gp=true},{q="What role does Brandur Ironhammer play for paladins?",a="He is a paladin class trainer who teaches new spells and abilities, guides initiates through their class quests like the Tome of Divinity, and directs seasoned paladins toward advanced trials across the Alliance.",al={"brandur paladin trainer","what does brandur do","brandur purpose"},it="purpose"},{q="Who is Brandur's peer in the Hall of Mysteries?",a="Brandur works alongside Tiza Battleforge, another dwarven paladin trainer in the Hall of Mysteries. Tiza acts as a candid mentor to him, having pointed out that his jealousy is his weakness—a fault Brandur has sworn to overcome.",al={"brandur partner","who works with brandur","tiza battleforge relation"},it="ties"},{q="Why does Brandur send paladins to Stormwind City?",a="Human paladins training in Ironforge are often redirected by Brandur to Duthorian Rall or Lord Grayson Shadowbreaker in Stormwind's Cathedral of Light, ensuring they undergo the formal rites prescribed by their own kingdom.",al={"brandur stormwind quest","why go to duthorian rall","brandur human paladins"},it="purpose"},{q="Does Brandur have connections to the fight against the Scourge?",a="Yes. Brandur relays urgent calls from Commander Ashlam Valorfist, dispatching proven paladins of purity and valor to assist the Alliance crusade at Chillwind Camp on the border of the Western Plaguelands.",al={"brandur plaguelands","chillwind camp brandur","ashlam valorfist brandur"},it="purpose"},{q="Who is Brandur Ironhammer?",a="Brandur Ironhammer is a dwarven paladin trainer stationed in the Hall of Mysteries within Ironforge's Mystic Ward. Dedicated to the Holy Light, he mentors ascending paladins in combat, faith, and virtue, guiding both dwarven initiates and human allies toward the trials and masters needed to hone their sacred calling.",al={"brandur ironhammer","who is brandur","brandur lore"},it="identity",add=true},{q="Whose side is Brandur Ironhammer on?",a="Brandur is firmly loyal to the Kingdom of Ironforge and the Grand Alliance. He serves the paladins of the Holy Light, cooperating closely with fellow defenders in Stormwind and relaying calls to support Alliance commanders on active fronts against the Scourge.",al={"brandur ironhammer faction","who does brandur serve","brandur alliance"},it="side",add=true},{q="What does Brandur Ironhammer want?",a="Brandur seeks to foster a capable, righteous new generation of paladins to protect the Alliance and combat the darkness threatening Azeroth. On a personal level, he strives to overcome his own inner flaws, having sworn to his colleague Tiza Battleforge that he would work to conquer his lingering jealousy.",al={"brandur goal","what does brandur want","brandur purpose"},it="wants",add=true},{q="Why is Brandur Ironhammer in Ironforge?",a="He is stationed in the Hall of Mysteries to serve as a beacon and instructor for holy warriors within the dwarven capital. From here, he teaches martial and spiritual disciplines, tests novices, and coordinates with mentors across the Alliance to ensure that knights of the Light are ready for battle.",al={"why is brandur here","brandur in hall of mysteries","why brandur ironforge"},it="why_here",add=true}},ang={["class:Paladin"]="For dwarven and Alliance paladins, Brandur is a key mentor in Ironforge, offering essential martial training, sacred seals, and directives that lead to advanced holy trials.",["race:Dwarf"]="Brandur exemplifies the Khaz Modan tradition of dwarven paladins who blend martial steel with reverence for the Holy Light within the heart of Ironforge."},kw={"brandur","hall of mysteries","ironforge","ironhammer","mystic ward","paladin","tiza battleforge","tome of divinity","trainer"},rel={"zone:ironforge","subzone:hall-of-mysteries","subzone:mystic-ward","npc:tiza-battleforge","quest:2997","npc:duthorian-rall","npc:lord-grayson-shadowbreaker","subzone:chillwind-camp"},src={"Brandur Ironhammer"}}
E["npc:doctor-gustaf-vanhowzen"] = {t="npc",n="Doctor Gustaf VanHowzen",z="ironforge",s="Doctor Gustaf VanHowzen serves as the trauma surgeon and chief physician of Alliance Trauma in Theramore Isle. Stationed within Foothold Citadel, he trains the island's healers and evaluates medics who wish to master the highest tiers of field triage and bandage work.",h="Doctor Gustaf VanHowzen serves as the trauma surgeon and chief physician of Alliance Trauma in Theramore Isle.",sec={{t="Chief Physician of Theramore",b="Located on the ground floor of Foothold Citadel in Theramore Isle, Doctor Gustaf VanHowzen oversees the medical care of Lady Jaina Proudmoore's forces and trains the outpost's frontline healers. Facing harsh conditions in Dustwallow Marsh, VanHowzen insists on rigorous field competence, personally putting experienced medics through an intense triage test to ensure they can prioritize critical wounds under severe pressure.",sp=0}},faq={{q="Where can Doctor Gustaf VanHowzen be found?",a="Doctor VanHowzen is stationed on the ground floor of Foothold Citadel, the main fortress situated on Theramore Isle in Dustwallow Marsh.",al={"vanhowzen location","where is gustaf vanhowzen","gustaf vanhowzen spot"},it="place",gp=true},{q="What role does VanHowzen serve for the Alliance?",a="He is the chief physician of Alliance Trauma and the leading trauma surgeon in Theramore. In addition to overseeing the garrison's medical ward, he serves as an Artisan First Aid trainer for seasoned Alliance field medics.",al={"what does vanhowzen do","vanhowzen role","who is doctor vanhowzen"},it="purpose"},{q="What does Doctor VanHowzen teach players?",a="He offers the Artisan First Aid triage assessment, allowing skilled medics to raise their skill cap, and instructs qualified practitioners in crafting advanced bandages such as Heavy Mageweave and Runecloth bandages.",al={"what can i learn from vanhowzen","vanhowzen training","first aid from vanhowzen"},it="purpose",gp=true},{q="Does the Horde have a counterpart to Doctor VanHowzen?",a="Yes. The Horde's equivalent trauma specialist is Doctor Gregory Victor, who trains field medics and conducts triage examinations at Hammerfall in the Arathi Highlands.",al={"horde triage trainer","horde vanhowzen counterpart","who is horde first aid master"},gp=true},{q="Who is Doctor Gustaf VanHowzen?",a="Doctor Gustaf VanHowzen is the chief physician of Alliance Trauma and a master trauma surgeon stationed in Theramore Isle. Renowned across the Alliance for his battlefield medical expertise, he is responsible for overseeing the training of Theramore's healers and teaching advanced triage techniques to field medics.",al={"who is vanhowzen","gustaf vanhowzen","who is doctor gustaf vanhowzen"},it="identity",add=true},{q="Whose side is Doctor Gustaf VanHowzen on?",a="Doctor VanHowzen is thoroughly loyal to the Alliance. He directs the medical corps known as Alliance Trauma, serving under Lady Jaina Proudmoore's banner to ensure soldiers and frontline adventurers are kept alive through rigorous field medicine.",al={"vanhowzen faction","is vanhowzen alliance","doctor gustaf vanhowzen allegiance"},it="side",add=true},{q="What does Doctor Gustaf VanHowzen want?",a="Doctor VanHowzen wants to maintain the highest standards of trauma care across the Alliance's forces. In the field, hesitation costs lives, so he seeks to test and instruct competent field medics in triage methods to handle severe battle casualties under extreme pressure.",al={"what does vanhowzen want","vanhowzen motive","doctor vanhowzen goal"},it="wants",add=true},{q="Why is Doctor Gustaf VanHowzen here?",a="Stationed within Foothold Citadel on Theramore Isle, Doctor VanHowzen tends to the military bastion's injured and trains the local garrison's healers. From here, he tests prospective trauma medics venturing through Kalimdor who demonstrate mastery in first aid.",al={"why is vanhowzen in theramore","why is doctor vanhowzen here","where does vanhowzen work"},it="why_here",add=true},{q="Who is Doctor Gustaf VanHowzen tied to?",a="Doctor VanHowzen serves the Alliance garrison at Theramore Isle, working under Lady Jaina Proudmoore's regional forces. He coordinates directly with Alliance military healers and commands the Alliance Trauma medical wing.",al={"vanhowzen affiliations","who does vanhowzen serve","doctor gustaf vanhowzen ties"},it="ties",add=true}},ang={["faction:Alliance"]="Every Alliance medic aspiring to master field surgery must travel to Theramore and prove their triage skills under Doctor VanHowzen's watchful eye."},kw={"alliance trauma","artisan first aid","first aid","foothold citadel","gustaf vanhowzen","theramore","triage","vanhowzen"},rel={"subzone:foothold-citadel","subzone:theramore-isle","zone:dustwallow","quest:6625","npc:doctor-gregory-victor","npc:jaina-proudmoore","topic:alliance"},src={"Doctor Gustaf VanHowzen"}}
E["npc:elder-bronzebeard"] = {t="npc",n="Elder Bronzebeard",z="ironforge",s="Elder Bronzebeard is an ancient spirit of the earthen who appears in the Mystic Ward of Ironforge during the Lunar Festival. Bearing the name of the clan that rules the city, his spectral presence serves as a bridge between modern dwarves and their stony stone-hewn ancestors.",h="Elder Bronzebeard is an ancient spirit of the earthen who appears in the Mystic Ward of Ironforge during the...",sec={{t="A Progenitor in the Mystic Ward",b="Appearing near the pool in Ironforge's Mystic Ward, Elder Bronzebeard does not wear the flesh of modern dwarves; instead, his ghostly form is that of an earthen, the ancient race forged from living stone by the Titans. Dwarven scholars and explorers are only beginning to uncover their origins through excavations across Khaz Modan and beyond, making this spirit's presence a striking living relic. His very name and visage suggest he is a direct ancestor of the Bronzebeard clan, standing silent witness to how far his stoneborn progeny have evolved.",sp=0}},faq={{q="Why does Elder Bronzebeard look like an earthen instead of a regular dwarf?",a="Dwarves are the descendants of the earthen, ancient beings crafted from stone by the Titans who later succumbed to the Curse of Flesh. Because Elder Bronzebeard lived in the distant past before this transformation fully took hold, his spirit retains the stony form of his earthen era.",al={"why is elder bronzebeard stone","is elder bronzebeard earthen","elder bronzebeard race"},it="origin"},{q="Is he related to King Magni Bronzebeard?",a="While the exact branches of ancient family trees are lost to history, his name and presence in the dwarven capital strongly indicate he is a venerated progenitor of the Bronzebeard clan, the lineage that currently rules Ironforge under King Magni.",al={"is he magni's ancestor","magni bronzebeard relative","bronzebeard family tree"},it="ties"},{q="Why is Elder Bronzebeard in Ironforge?",a="During the Lunar Festival, spirits of the elders materialize throughout Azeroth to bestow wisdom and blessings upon travelers. Elder Bronzebeard manifests in the Mystic Ward of Ironforge, resting near the tranquil pool where dwarven mages and scholars gather.",al={"what is elder bronzebeard doing here","where is elder bronzebeard","mystic ward ghost"},it="why_here"},{q="Who is Elder Bronzebeard?",a="Elder Bronzebeard is an ancient earthen spirit lingering in the Mystic Ward of Ironforge. Appearing in the stony form of his Titan-forged forebears rather than flesh and bone, he represents the deep, ancestral roots of the dwarven people and their enduring lineage.",al={"who is elder bronzebeard","elder bronzebeard identity","what is elder bronzebeard"},it="identity",add=true},{q="Whose side is Elder Bronzebeard on?",a="As an honored ancestor standing in the heart of Ironforge, Elder Bronzebeard watches peacefully over the dwarven capital and aligns with his kin and the Alliance, offering greetings to travelers and pilgrims who approach him.",al={"elder bronzebeard faction","whose side is elder bronzebeard on","is elder bronzebeard alliance"},it="side",add=true},{q="What does Elder Bronzebeard want?",a="Elder Bronzebeard seeks nothing beyond sharing communion with those who pay homage to the ancient ways. As a wandering spirit of the past, he greets pilgrims and bestows his presence upon respectful visitors.",al={"what does elder bronzebeard want","elder bronzebeard motive","why does elder bronzebeard want to talk"},it="wants",add=true}},ang={["race:Dwarf"]="For dwarves, meeting Elder Bronzebeard offers a rare, direct look at their earthen ancestry, validating the historical findings being uncovered by the Explorers' League.",["faction:Alliance"]="Alliance pilgrims visiting Ironforge during the Lunar Festival find an elder who represents the very foundations of the dwarven kingdom."},kw={"ancestor","earthen","elder bronzebeard","ironforge","lunar festival","magni","mystic ward"},rel={"zone:ironforge","subzone:mystic-ward","topic:bronzebeard-clan","quest:8866"},src={"Elder Bronzebeard"}}
E["npc:field-marshal-snowfall"] = {t="npc",n="Field Marshal Snowfall",z="ironforge",s="Field Marshal Snowfall is a dwarven military officer stationed in Ironforge's Military Ward to coordinate the Alliance war effort against the rising silithid threat. Facing an ancient evil stirring in the southern sands of Silithus, he oversees the massive logistical drive required to equip the allied armies. Snowfall tracks donated raw materials and rewards those who aid the realm's preparation for war.",h="Field Marshal Snowfall is a dwarven military officer stationed in Ironforge's Military Ward to coordinate the...",sec={{t="Quartermaster of the Ahn'Qiraj Effort",b="Standing watch in Ironforge's Military Ward, Field Marshal Snowfall serves as the central coordinator for the Alliance's mobilization against Ahn'Qiraj. He views the brewing conflict not merely as a border skirmish, but as a critical fight against an ancient enemy hostile to all creations of the Titans. Snowfall oversees staggering stockpiles of supplies—millions of bandages, tons of metal bars, leathers, herbs, and rations gathered by adventurers—ensuring that Alliance forces will be armed, armored, and fed when the march south to Silithus begins.",sp=0},{t="The Road to Silithus",b="Mobilizing an entire faction requires coordination between blacksmiths, gathers, cooks, and soldiers across every Alliance territory. Snowfall monitors each stage of this immense operation, accepting commendation signets and offering supply requisitions to volunteers. Once the required war supplies are fully gathered across both factions, the stockpiles are packed and hauled south to Cenarion Hold, readying the grand assault against the insectoid swarms and the Old God lurking behind the Scarab Wall.",sp=0}},faq={{q="Who is Field Marshal Snowfall?",a="Field Marshal Snowfall is a high-ranking dwarven commander based in the Military Ward of Ironforge. He is tasked with overseeing and tallying the Alliance's extensive supply collection for the impending war against the qiraji in Silithus.",al={"snowfall role","who is snowfall","field marshal snowfall lore"},it="identity"},{q="Why is the Alliance collecting so many supplies?",a="An ancient power threatens Kalimdor from beyond the gates of Ahn'Qiraj. To mount a successful campaign across the harsh deserts of Silithus, the Alliance must amass enormous reserves of armor, metal ingots, medical bandages, food, and herbs before its armies can march.",al={"why donate cloth","war effort purpose","why war supplies"},it="why_wanted"},{q="Where do the gathered materials go once finished?",a="Once both the Alliance and the Horde meet their total gathering quotas, caravans and supply ships transport the vast stockpiles to Cenarion Hold in Silithus, where the combined forces establish their forward staging grounds.",al={"where do supplies go","what happens to the supplies"}},{q="What are the Signets for War Supplies used for?",a="Signets are awarded to contributors who donate requested arms and materials to the war effort. Field Marshal Snowfall accepts these signets in bundles, rewarding dutiful Alliance citizens with supply crates and equipment for their service.",al={"signet turn ins","what are signets for"},gp=true},{q="Whose side is Field Marshal Snowfall on?",a="Field Marshal Snowfall is a stalwart commander of the Alliance. Stationed in the Military Ward of Ironforge, he oversees the faction-wide logistics and resource gathering required to mount a joint offensive in Kalimdor. Though this campaign demands an uneasy parallel cooperation alongside the Horde to amass enough supplies, Snowfall's loyalties lie firmly with the kingdoms of the Grand Alliance.",al={"field marshal snowfall alliance or horde","snowfall faction","who does snowfall serve"},it="side",add=true},{q="What does Field Marshal Snowfall want?",a="Snowfall wants to stockpile staggering amounts of raw materials, bandages, metal bars, herbs, and food supplies from across the Alliance's lands. He aims to ensure that when the Gates of Ahn'Qiraj are breached, the standing army arriving in the harsh desert of Silithus has every weapon, potion, and ration needed to withstand C'Thun's legions without collapsing from attrition.",al={"field marshal snowfall goal","what is snowfall asking for","snowfall objective"},it="wants",add=true},{q="Why is Field Marshal Snowfall in Ironforge?",a="Snowfall has set up command in Ironforge's Military Ward because the dwarven mountain city serves as a central hub of Alliance industry and trade. From here, he can track shipping manifests, coordinate incoming materials gathered by citizen-soldiers, and assemble the mountain of provisions before they are dispatched across the sea to the staging grounds in Silithus.",al={"why is snowfall in ironforge","snowfall military ward","why is field marshal snowfall here"},it="why_here",add=true}},ang={["faction:Alliance"]="Snowfall represents the unified industrial and military will of the Alliance, calling on every race from Stormwind to Darnassus to empty their storehouses and prepare for the battle ahead.",["race:Dwarf"]="Stationed within the Great Forge's martial district, Snowfall speaks with pride of protecting the creations of the Titans against an ancient, deep-seated depravity."},kw={"ahn'qiraj","field marshal snowfall","ironforge","military ward","signets","silithus","snowfall","war effort"},rel={"subzone:military-ward","zone:ironforge","zone:silithus","subzone:cenarion-hold","quest:8846","quest:8852","topic:old-god"},src={"Field Marshal Snowfall"}}
E["npc:gelbin-mekkatorque"] = {t="npc",n="Gelbin Mekkatorque",z="ironforge",s="Gelbin Mekkatorque is the High Tinker of the gnomes, currently residing in exile in Tinker Town within Ironforge. Renowned as a visionary engineer whose inventions include the mechanostrider and the Deeprun Tram, he now carries the heavy burden of Gnomeregan's fall and oversees efforts to reclaim his people's ancestral home.",h="Gelbin Mekkatorque is the High Tinker of the gnomes, currently residing in exile in Tinker Town within...",sec={{t="The High Tinker and Master Inventor",b="Gnomish leadership is earned through intellect and merit rather than bloodlines, and Gelbin Mekkatorque's rise to High Tinker was propelled by pure inventive genius. A graduate of Gearshaft University, Mekkatorque revolutionized personal transportation with the creation of the first functioning mechanostrider. Over decades of innovation, he drafted the gyromatic micro-adjustor, automated repair bots, and partnered with the Bronzebeard dwarves to engineer their formidable siege engines. When Stormwind required a rapid transit connection to Ironforge after the Second War, King Magni Bronzebeard turned to Mekkatorque, who personally drew the schematics and oversaw construction of the subterranean Deeprun Tram.",sp=0},{t="Betrayal and Exile in Ironforge",b="Mekkatorque's greatest tragedy struck when troggs invaded Gnomeregan from deep below. Urged by his trusted friend and chief advisor, Sicco Thermaplugg, Mekkatorque ordered the venting of radioactive waste into the lower corridors to exterminate the attackers. Instead, the toxic gas slaughtered thousands of innocent gnomes and mutated the survivors, while Thermaplugg seized the ruined city. Crushed by guilt yet determined to fix his mistake, Mekkatorque led the surviving refugees across Dun Morogh to Ironforge. Operating out of Tinker Town under King Magni's hospitality, the High Tinker directs gnomekind's military and scientific energies toward a single unwavering objective: liberating Gnomeregan.",sp=1}},faq={{q="Who is Gelbin Mekkatorque?",a="Gelbin Mekkatorque is the elected High Tinker and leader of the gnomes. He is a master engineer who designed pivotal gnomish technologies, including the mechanostrider, repair bots, and the Deeprun Tram.",al={"high tinker","gnome leader","who is the gnome king"},it="identity"},{q="Why is Mekkatorque in Ironforge instead of Gnomeregan?",a="Gnomeregan was overrun by a savage trogg invasion followed by a catastrophic radioactive fallout. Mekkatorque led the evacuation of his people across Dun Morogh to Ironforge, where King Magni Bronzebeard granted them refuge in Tinker Town while plans are made to take the city back.",al={"why is mekkatorque in ironforge","why are gnomes in ironforge","gnomeregan fall"},it="why_here"},{q="What caused the catastrophe in Gnomeregan?",a="Facing endless waves of troggs, Mekkatorque was persuaded by a trusted advisor to vent toxic radioactive coolant into the lower chambers to halt the beasts. Tragically, the gas failed to stop the troggs and instead irradiated the city, killing thousands of gnomes.",al={"what happened to gnomeregan","why is gnomeregan irradiated","thermaplugg betrayal"}},{q="What did Mekkatorque invent before becoming High Tinker?",a="Mekkatorque invented the mechanostrider, giving gnomes their own agile mount. He also designed the gyromatic micro-adjustor, repair bots, the schematics for the Deeprun Tram between Ironforge and Stormwind, and co-developed the dwarven siege engine.",al={"mekkatorque inventions","what did gelbin build"}},{q="Is Mekkatorque an actual king?",a="Gnomes do not have a hereditary monarchy; their leader is an elected High Tinker chosen on merit and intellectual achievement. His title and authority derive from his election as High Tinker.",al={"is mekkatorque a king","king of gnomes"}},{q="Whose side is Gelbin Mekkatorque on?",a="Gelbin Mekkatorque stands firmly with the Alliance. As the leader of the gnomes, he maintains an unbreakable bond with King Magni Bronzebeard and the dwarves of Ironforge, who opened their gates to shelter his displaced people. Mekkatorque has pledged gnomish engineering, ingenuity, and military resources to aid their Alliance allies across Azeroth.",al={"mekkatorque faction","gelbin alliance","who does mekkatorque serve"},it="side",add=true},{q="What does Gelbin Mekkatorque want?",a="Mekkatorque's singular focus is reclaiming Gnomeregan. The loss of his home and the tragic deaths of countless gnomes weigh heavily upon him, driving him to find a way to purge the troggs and radiation poisoning their halls. From Tinker Town, he directs reconnaissance and organizes strike teams to prepare the groundwork for retaking the city.",al={"mekkatorque goal","what is gelbin trying to do","gelbin plan"},it="wants",add=true},{q="Who is Gelbin Mekkatorque tied to?",a="Mekkatorque works closely with King Magni Bronzebeard, his gracious host in Ironforge, and coordinates with Alliance leadership in Stormwind. On a personal level, he is haunted by the loss of Gnomeregan and the thousands of gnomes who died after the radioactive venting he ordered on a trusted advisor's counsel.",al={"mekkatorque allies","gelbin relationships","who does mekkatorque work with"},it="ties",add=true},{q="Why is Gelbin Mekkatorque famous?",a="Mekkatorque is renowned across Azeroth as one of the greatest engineering geniuses in history. He invented the first functioning mechanostrider, developed the gyromatic micro-adjustor, helped design the dwarven siege engine, and drafted the grand schematics for the Deeprun Tram connecting Ironforge to Stormwind.",al={"why is mekkatorque famous","what is gelbin known for","mekkatorque inventions"},it="fame",add=true}},ang={["race:Gnome"]="Mekkatorque is the heart of your people in exile. Though the guilt of Gnomeregan's poisoning weighs on him, his brilliance and devotion to liberating your ancestral home command absolute loyalty in Tinker Town.",["profession:Engineering"]="Standing before the High Tinker is standing before the author of the mechanostrider, the gyromatic micro-adjustor, and the Deeprun Tram. His workshop in Tinker Town represents the cutting edge of technological innovation."},kw={"deeprun tram","gelbin","gnome","gnomeregan","high tinker","ironforge","mechanostrider","mekkatorque","thermaplugg","tinker town"},rel={"zone:ironforge","zone:gnomeregan","subzone:deeprun-tram","npc:sicco-thermaplugg","npc:magni-bronzebeard","topic:gnome","topic:alliance","zone:dunmorogh"},src={"Gelbin Mekkatorque"}}
E["npc:gerrig-bonegrip"] = {t="npc",n="Gerrig Bonegrip",z="ironforge",s="Gerrig Bonegrip is an unassuming dwarven shopkeeper tucked away in the shadowy corridors of Ironforge's Forlorn Cavern. Behind the counter of Bonegrip's Runes and Dooms, he quietly buys and sells esoteric texts concerning dark rituals and forgotten ancient powers.",h="Gerrig Bonegrip is an unassuming dwarven shopkeeper tucked away in the shadowy corridors of Ironforge's...",sec={{t="Bonegrip's Runes and Dooms",b="Operating in the dingy recesses of the Forlorn Cavern, Gerrig Bonegrip appears to most citizens as just an eccentric purveyor of bizarre relics and forbidden lore. However, his humble shop serves a far darker function. Bonegrip is an active member of the nihilistic Twilight's Hammer cult, using his storefront to gather dangerous manuscripts and obscure texts relating to the Old Gods under the very noses of the Ironforge Senate and the High Seat.",sp=1},{t="Collecting Forbidden Knowledge",b="Gerrig actively enlists unwitting Alliance adventurers to retrieve ancient artifacts, such as the Lorgalis Manuscript lost deep within Blackfathom Deeps. Once these relics are in his hands, he transcribes and disseminates the profane knowledge directly to his cult brethren across Azeroth. Through subtle connections to shadowy associates like Skuerto and figures dealing with ancient primordial entities like Myzrael, Bonegrip works tirelessly to advance the cult's apocalyptic designs.",sp=1}},faq={{q="Who is Gerrig Bonegrip?",a="Gerrig Bonegrip is a dwarf running Bonegrip's Runes and Dooms in Ironforge's Forlorn Cavern. He deals in eccentric curiosities and obscure texts concerning ancient rituals.",al={"who is bonegrip","gerrig bonegrip lore","bonegrip ironforge"},sp=2,it="identity"},{q="What does he do with the Lorgalis Manuscript?",a="He seeks the Lorgalis Manuscript from Blackfathom Deeps for his collection of rare texts. Further investigation can uncover more about his use of it.",al={"why does bonegrip want lorgalis manuscript","knowledge in the deeps turn in","lorgalis manuscript use"},sp=1,it="wants"},{q="How does Gerrig operate in Ironforge?",a="Gerrig maintains a low profile as an eccentric scholar and merchant in the Forlorn Cavern, where he buys and sells obscure texts.",al={"does ironforge know bonegrip is a cultist","why is bonegrip allowed in ironforge"},sp=2},{q="What is his connection to Myzrael?",a="Gerrig is an old associate of the dwarf Skuerto, who investigates the sealed earth elemental Myzrael in the Arathi Highlands. Through these connections, Gerrig helps orchestrate tasks tied to ancient binding rituals and primordial powers.",al={"gerrig bonegrip and myzrael","skuerto and gerrig"},it="ties"},{q="Whose side is Gerrig Bonegrip on?",a="Gerrig secretly serves the Twilight's Hammer cult, devoted to the Old Gods and apocalyptic rituals. Though he operates in the heart of Ironforge under the guise of an eccentric merchant running Bonegrip's Runes and Dooms, his true allegiance lies with his cultist brothers and sisters.",al={"gerrig bonegrip faction","who does gerrig work for","is gerrig bonegrip evil"},sp=1,it="side",add=true},{q="Why is Gerrig Bonegrip in Ironforge?",a="Gerrig operates out of the shadowy Forlorn Cavern to gather dark lore, artifacts, and occult manuscripts right beneath the mountain king's nose. Running a curio and reagent shop provides him the perfect cover to buy, copy, and disseminate forbidden knowledge to his fellow cultists across the realm.",al={"why is gerrig in ironforge","what is gerrig bonegrip doing here","why is gerrig bonegrip in the forlorn cavern"},sp=1,it="why_here",add=true}},ang={["race:Dwarf"]="For dwarven visitors, Bonegrip's trade in forbidden lore casts an unsettling shadow over Ironforge's scholarly life.",["class:Warlock"]="For warlocks frequenting the shadowy corners of the Forlorn Cavern, Bonegrip's collection of esoteric rituals and dark tomes offers a convenient well of dangerous knowledge."},kw={"blackfathom deeps","bonegrip","forlorn cavern","gerrig","ironforge","lorgalis manuscript","runes and dooms"},rel={"subzone:forlorn-cavern","topic:twilight-s-hammer","zone:ironforge","quest:971","zone:blackfathom","npc:skuerto","topic:old-god","topic:dwarf"},src={"Gerrig Bonegrip"}}
E["npc:gnoarn"] = {t="npc",n="Gnoarn",z="ironforge",s="Gnoarn is an exiled gnome residing in Tinker Town within the dwarven mountain city of Ironforge. Displaced following the devastating fall of Gnomeregan, he assists his scattered people by directing adventurers to assist fellow gnomish engineers and survivors.",h="Gnoarn is an exiled gnome residing in Tinker Town within the dwarven mountain city of Ironforge.",sec={{t="A Displaced Citizen of Gnomeregan",b="Like the majority of his brethren, Gnoarn was forced to flee the depths of Gnomeregan when troggs invaded and catastrophic radiation rendered the great subterranean metropolis uninhabitable. Taking refuge in Ironforge's Tinker Town under the hospitality of the Bronzebeard dwarves, Gnoarn spends his days keeping track of other survivors. He serves as an informal coordinator among the refugees, pointing capable travelers toward gnomes abroad who urgently require assistance, such as the stranded pilot Bingles Blastenheimer in Loch Modan or the ambitious engineer Shoni the Shilent in Stormwind.",sp=0}},faq={{q="Who is Gnoarn?",a="Gnoarn is a gnomish survivor living among the refugee population in Tinker Town, the gnomish quarter of Ironforge. He directs travelers to aid fellow exiled gnomes working on various projects across Alliance lands.",al={"who is this gnome","gnoarn lore","gnoarn npc"},it="identity"},{q="Where can Gnoarn be found?",a="He can be found in Tinker Town, located in the northeastern section of Ironforge, surrounded by the whirring machinery, gears, and workbenches of his exiled kin.",al={"gnoarn location","where is gnoarn","find gnoarn"},it="place",gp=true},{q="What tasks does Gnoarn give out?",a="Gnoarn directs adventurers to assist other scattered gnomes. Notably, he sends adventurers to Loch Modan to check on the missing pilot Bingles Blastenheimer, and dispatches travelers to Stormwind to speak with the inventor Shoni the Shilent regarding her gyrodrillmatic excavationators.",al={"gnoarn quests","what does gnoarn want"},it="purpose",gp=true},{q="What happened to Gnoarn's hair?",a="Before the fall of Gnomeregan, Gnoarn was known for sporting an eccentric 'gnomefro' hairstyle. Tragically, he lost his distinctive coiffure following the catastrophic fallout and radioactive venting that devastated his home city.",al={"gnoarn gnomefro","gnoarn hair"}},{q="Whose side is Gnoarn on?",a="Gnoarn is loyal to his fellow gnomes of Gnomeregan and the Grand Alliance. Residing among the displaced gnomish population in Tinker Town, he works to keep his community organized and connected with their allies in Ironforge.",al={"gnoarn faction","is gnoarn alliance","who does gnoarn serve"},it="side",add=true},{q="Why is Gnoarn in Ironforge?",a="Like thousands of other gnomes, Gnoarn was driven from his home following the fall of Gnomeregan. When troggs overran the subterranean technological marvel and toxic radiation polluted its corridors, the survivors fled upward to seek sanctuary among their dwarven cousins in Ironforge, carving out a home in Tinker Town.",al={"why is gnoarn here","why did gnoarn come to ironforge","what brought gnoarn to ironforge"},it="why_here",add=true},{q="What does Gnoarn want?",a="Gnoarn is concerned with the safety and whereabouts of his displaced kin. In the disarray following Gnomeregan's evacuation, he looks for missing comrades like Bingles and directs capable adventurers to aid prominent inventors and specialists such as Shoni the Shilent.",al={"what is gnoarn trying to do","gnoarn goals","what does gnoarn need"},it="wants",add=true},{q="Who is Gnoarn tied to?",a="Gnoarn maintains close ties with other Gnomeregan survivors in Ironforge, notably liaising with the renowned inventor Shoni the Shilent and coordinating efforts to locate fellow refugees like Bingles Blastenheimer.",al={"gnoarn allies","who does gnoarn know","gnoarn connections"},it="ties",add=true}},ang={["race:Gnome"]="For fellow gnomes, Gnoarn embodies the resilience of the refugee community in Tinker Town, ensuring displaced engineers maintain communication across the Eastern Kingdoms.",["faction:Alliance"]="Alliance heroes passing through Ironforge can speak with Gnoarn to find leads on critical gnomish engineering efforts underway across Dun Morogh, Loch Modan, and Stormwind."},kw={"bingles","gnoarn","gnomefro","gnomeregan","ironforge","shoni the shilent","tinker town"},rel={"subzone:tinker-town","zone:ironforge","zone:gnomeregan","topic:gnome","quest:2039","quest:2041","quest:2927"},src={"Gnoarn"}}
E["npc:golnir-bouldertoe"] = {t="npc",n="Golnir Bouldertoe",z="ironforge",s="Golnir Bouldertoe is a dwarven mining vendor stationed beside the bustling Great Forge in Ironforge. He provides essential supplies for miners and prospectors while handling dispatches for local couriers and travelers.",h="Golnir Bouldertoe is a dwarven mining vendor stationed beside the bustling Great Forge in Ironforge.",sec={{t="Merchant of the Great Forge",b="Standing within the roaring heat of Ironforge's Great Forge, Golnir Bouldertoe outfits prospectors and craftsmen with the necessities of their trade. From sturdy mining picks to fluxes and coal, his wares fuel the tireless smelting fires and smithies that define the dwarven capital. Kin to Geofram Bouldertoe, Golnir is a reliable point of contact for workers arriving in the city, often directing fresh hands or receiving supply missives shuttled in from nearby outposts.",sp=0}},faq={{q="Where can I find Golnir Bouldertoe?",a="Golnir Bouldertoe is located in the Great Forge in Ironforge, standing near the central smelting and blacksmithing areas alongside fellow trade merchants.",al={"golnir location","where is golnir","golnir bouldertoe ironforge"},it="place",gp=true},{q="What goods does Golnir sell?",a="He serves as a mining supplier, selling essential trade gear such as mining picks, coal, and fluxes to assist prospectors in digging and refining raw ore.",al={"golnir vendor wares","what does golnir sell","golnir inventory"},gp=true},{q="Is Golnir Bouldertoe involved in any quests?",a="Yes. Courier quests connecting surrounding dwarven settlements to the capital, such as errands involving Gryth Thurden and incoming flights from outposts like Thelsamar, direct travelers to deliver messages directly into Golnir's hands.",al={"golnir quests","ride to ironforge golnir"},gp=true},{q="Is Golnir related to anyone else in Dun Morogh?",a="Golnir shares his clan name with Geofram Bouldertoe, the mining trainer who works beside him in the Great Forge of Ironforge.",al={"bouldertoe family","geofram bouldertoe relative"},it="ties"},{q="Who is Golnir Bouldertoe?",a="Golnir Bouldertoe is a dwarven merchant who works as a mining supplier within the Great Forge of Ironforge. He provides essential provisions, picks, and smelting supplies to the prospectors and smiths laboring at the city's molten heart.",al={"who is golnir","golnir bouldertoe lore","golnir identity"},it="identity",add=true},{q="Whose side is Golnir Bouldertoe on?",a="Golnir is a loyal subject of Ironforge and the Bronzebeard clan, standing firmly with the Grand Alliance. He keeps his trade situated in the kingdom's bustling center, serving fellow dwarves and visiting Alliance travelers alike.",al={"golnir faction","golnir allegiance","golnir side"},it="side",add=true},{q="Why is Golnir Bouldertoe here?",a="Golnir stays close to the Great Forge where the heat never dies and ore is constantly smelted. Because miners and blacksmiths from across Dun Morogh and beyond bring their finds directly to Ironforge's central hearth, Golnir keeps his shop nearby to outfit them with necessary gear.",al={"why is golnir in ironforge","golnir role great forge","why is golnir here"},it="why_here",add=true}},ang={["profession:Mining"]="Miners visiting the Great Forge rely on Golnir for vital tools of the craft, including spare picks and fluxes needed to smelt raw vein-work into refined bars.",["race:Dwarf"]="For dwarves returning from their first journeys out in Coldridge or Kharanos, Golnir serves as an early contact in the capital, welcoming travelers right beside the mountain's fiery heart."},kw={"bouldertoe","coal","flux","golnir","great forge","ironforge","mining supplier"},rel={"subzone:great-forge","zone:ironforge","quest:6391","quest:6388","topic:dwarf"},src={"Golnir Bouldertoe"}}
E["npc:grand-mason-marblesten"] = {t="npc",n="Grand Mason Marblesten",z="ironforge",s="Grand Mason Marblesten is an esteemed dwarven stonemason stationed in the busy Commons of Ironforge. Deeply devoted to the royal legacy of Khaz Modan, he has been commissioned by King Magni Bronzebeard to build a memorial to Sully Balloo, a dwarven soldier who died in the Thandol Span tragedy. Adventurers often meet him when assisting with the materials needed to complete this solemn tribute.",h="Grand Mason Marblesten is an esteemed dwarven stonemason stationed in the busy Commons of Ironforge.",sec={{t="Master of the Stone",b="Dwarven stonemasonry is not merely a trade; it is an enduring art form that shapes the very soul of Ironforge. Grand Mason Marblesten stands among the city's foremost masters of the chisel, representing the centuries-old tradition of carving halls, pillars, and great effigies straight from the living mountain. Based in the Commons, he oversees civic projects and commemorative monuments that immortalize Bronzebeard history.",sp=0},{t="A King's Tribute",b="Marblesten's most poignant task is a memorial King Magni commissioned for Sully Balloo, a soldier who died in the Thandol Span tragedy, as a tribute to his grieving widow. Wanting a truly lasting piece, the Grand Mason insists on one of the finest stones available: Alterac Granite from Darrow Hill in Hillsbrad.",sp=0}},faq={{q="Who is Grand Mason Marblesten?",a="Grand Mason Marblesten is a senior dwarven stonemason located in the Commons of Ironforge. He is entrusted with civic and royal sculpting projects, most notably a memorial to the fallen soldier Sully Balloo, commissioned by King Magni Bronzebeard.",al={"who is marblesten","marblesten role","grand mason npc"},it="identity"},{q="Where can I find Grand Mason Marblesten?",a="He can be found in the Commons district of Ironforge, surrounded by stone blocks and architectural works not far from the city's bustling shops and banks.",al={"marblesten location","where is marblesten","ironforge marblesten"},it="place",gp=true},{q="What monument is Marblesten working on?",a="He is building a memorial to Sully Balloo, a dwarven soldier who died in the Thandol Span tragedy. King Magni Bronzebeard commissioned it in tribute to Balloo and his grieving widow.",al={"what is he building","kings tribute quest","marblesten statue"},it="purpose"},{q="Why does Marblesten need adventurers to gather materials?",a="Marblesten wants a truly epic and lasting piece, so he will only work with one of the finest stones available. He sends travelers to Darrow Hill in Hillsbrad to gather Alterac Granite.",al={"marblesten quests","why need stones","materials for monument"},it="motive"},{q="What does the title 'Grand Mason' mean in dwarven society?",a="Among dwarves, stoneworking is revered alongside blacksmithing. A 'Grand Mason' is an accomplished master of stonecraft, trusted with major state projects, royal architectural designs, and ceremonial memorials.",al={"what is a grand mason","dwarf mason rank"}},{q="Is Marblesten an Alliance official or a private contractor?",a="Marblesten operates directly within Ironforge and serves the Ironforge kingdom and the Alliance, coordinating closely with King Magni Bronzebeard's court for royal commissions.",al={"who does marblesten work for","marblesten faction"}},{q="Whose side is Grand Mason Marblesten on?",a="Marblesten is entirely loyal to Ironforge and the Alliance. Stationed right in the heart of the city's Commons, he serves King Magni Bronzebeard and the dwarven kingdom, dedicating his craft and masonry to honoring dwarven heritage and the throne.",al={"marblesten faction","who does marblesten serve","marblesten alliance"},it="side",add=true},{q="What does Grand Mason Marblesten want?",a="Marblesten is overseeing a royal monument and requires fine materials to see it completed. Through his work on 'A King's Tribute,' he seeks capable adventurers to help procure the essential resources needed for the memorial to the fallen soldier Sully Balloo, commissioned by King Magni.",al={"what does marblesten want","marblesten goal","why does marblesten need help"},it="wants",add=true},{q="Why is Grand Mason Marblesten in the Commons?",a="Marblesten makes his workshop in the bustling Commons of Ironforge to oversee the stonework of the great mountain fortress and organize construction efforts for the throne. The open plaza allows him to coordinate projects and enlist travelers passing through the city.",al={"why is marblesten in ironforge","why is marblesten here","marblesten commons ironforge"},it="why_here",add=true}},ang={["race:Dwarf"]="For dwarves, stonecraft is ancestral heritage; aiding Marblesten pays homage both to the craft of Khaz Modan and to the memory of the fallen soldier Sully Balloo.",["profession:Mining"]="Miners who work closely with the rock of Dun Morogh and beyond will appreciate Marblesten's exacting standards for raw mineral quality.",["faction:Alliance"]="Honoring the sacrifice of Sully Balloo reminds the Alliance of every soldier lost in its wars."},kw={"a king's tribute","bronzebeard","commons","grand mason","ironforge","magni","marblesten","stonemason","sully balloo"},rel={"quest:686","zone:ironforge","subzone:commons","topic:dwarf"},src={"Grand Mason Marblesten"}}
E["npc:granis-swiftaxe"] = {t="npc",n="Granis Swiftaxe",z="ironforge",s="Granis Swiftaxe is a dwarf warrior trainer stationed inside the Thunderbrew Distillery in Kharanos. Known for his blunt demeanor and hardy training regimen, he mentors fledgling Alliance fighters emerging from Coldridge Pass before directing seasoned warriors to the city of Ironforge.",h="Granis Swiftaxe is a dwarf warrior trainer stationed inside the Thunderbrew Distillery in Kharanos.",sec={{t="A Gruff Mentor in Kharanos",b="Found warming himself among the casks of the Thunderbrew Distillery, Granis Swiftaxe serves as the primary combat instructor for young warriors traversing Dun Morogh. He possesses the unyielding pride typical of dwarven fighters, showing open amusement and disdain toward non-warriors who try to catch his ear. Once a student demonstrates sufficient prowess in combat, Granis sends them up the mountain path to seek out master trainer Muren Stormpike in the Military Ward of Ironforge.",sp=0}},faq={{q="Who is Granis Swiftaxe?",a="Granis Swiftaxe is a dwarven warrior trainer located on the ground floor of the Thunderbrew Distillery in Kharanos. He teaches early martial techniques to young dwarf and gnome warriors adventuring across Dun Morogh.",al={"granis swiftaxe","who is granis","kharanos warrior trainer"},it="identity"},{q="Why does Granis mock my character?",a="Granis has no patience for those who do not walk the path of the warrior. If an adventurer of another class speaks to him, he scoffs at the notion of them surviving even a single day under his intense training regimen.",al={"granis rude quote","why is granis laughing at me","granis non warrior text"}},{q="Where does Granis send advancing warriors?",a="Once a warrior gains enough experience in Dun Morogh, Granis directs them to seek out Muren Stormpike, a senior warrior trainer located in the Military Ward of Ironforge.",al={"muren stormpike quest","granis questline","who does granis send you to"},it="next_step",gp=true},{q="Is Granis related to other Swiftaxes in Khaz Modan?",a="He shares the Swiftaxe surname with other dwarves, but no family relationship is confirmed.",al={"swiftaxe family","granis swiftaxe relatives"},it="ties"},{q="Whose side is Granis Swiftaxe on?",a="Granis stands firmly with the Ironforge dwarves and the broader Alliance. Stationed in Kharanos, he dedicates his martial expertise to drilling the next generation of defenders against the troggs, frost trolls, and other threats surrounding Dun Morogh.",al={"granis swiftaxe faction","who does granis fight for","granis alliance"},it="side",add=true},{q="Why is Granis Swiftaxe in Kharanos?",a="Granis is stationed inside the Thunderbrew Distillery in Kharanos to train fledgling Alliance warriors who set out from Coldridge Pass. Dun Morogh faces mounting pressure from native troggs and Wendigos, making his rigorous combat drills vital for local defense.",al={"why is granis here","granis swiftaxe location reason","what brought granis to kharanos"},it="why_here",add=true},{q="What does Granis Swiftaxe want?",a="Granis wants nothing less than hardened, disciplined warriors capable of holding the line for Khaz Modan. He has little patience for the weak or untrained, demanding relentless dedication from recruits before directing promising veterans to masters like Muren Stormpike in Ironforge.",al={"granis swiftaxe goals","what does granis want","granis purpose"},it="wants",add=true}},ang={["class:Warrior"]="For dwarven and gnomish fighters leaving Coldridge Valley, Granis provides essential early combat instruction right alongside a fresh pint at the distillery.",["race:Dwarf"]="Embodying the robust and stubborn spirit of Ironforge's foot soldiers, Granis blends martial discipline with the comforts of local ale."},kw={"dun morogh","granis swiftaxe","kharanos","muren stormpike","thunderbrew distillery","warrior trainer"},rel={"subzone:thunderbrew-distillery","subzone:kharanos","quest:1679","zone:dunmorogh","topic:dwarf","quest:117"},src={"Granis Swiftaxe"}}
E["npc:greatfather-winter"] = {t="npc",n="Greatfather Winter",z="ironforge",s="Greatfather Winter is the legendary personification of the winter season and the central figure of the Feast of Winter Veil. While ancient legends revere him as a mythical being who blankets Azeroth in snow to allow the land to rest and renew, modern city-dwellers know him primarily through the commercial spectacle managed by the goblins of Smokywood Pastures.",h="Greatfather Winter is the legendary personification of the winter season and the central figure of the Feast...",sec={{t="Myth and Renewal",b="According to ancient lore, Greatfather Winter is an ethereal wanderer who walks the world late in the year, casting his billowing snowy cloak across the land so nature may slumber and be reborn. Dwarves view him as an embodiment or herald of the titans, pointing to the frosted crags of Dun Morogh as living proof of his favor. Other traditions, such as those of the tauren, respect his role in the season's turning while attributing the cold and storms to the elemental work of the Sun and Moon, giving the Earth Mother time to rest. Wherever the legend traveled, communities learned to gather and feast together against the cold, celebrating the promise of returning life.",sp=0},{t="Smokywood Pastures and City Festivities",b="In major settlements like Ironforge and Orgrimmar, the ancient spirit has been thoroughly reshaped by the enterprising goblins of Smokywood Pastures. The trading cartel popularized the depiction of Greatfather Winter as a jolly, red-suited elder with a white beard who rides a flying sleigh and hands out holiday treats and toys. Smokywood Pastures hires local actors—a dwarf in Ironforge and an orc in Orgrimmar—to listen to children's wishlists, receive offerings of milk and gingerbread cookies, and advertise seasonal merchandise beneath lavishly decorated trees.",sp=0}},faq={{q="Is the Greatfather Winter in Ironforge the real spirit?",a="No, the Greatfather Winter sitting by the festive tree in Ironforge is an actor hired by the goblin merchant company Smokywood Pastures. The company stages appearances to delight children and sell seasonal confections, though real legends speak of an actual ethereal being who walks the world in winter.",al={"is greatfather winter real","who is the guy in ironforge","is he an actor"},it="identity"},{q="Why do dwarves revere Greatfather Winter?",a="Dwarves associate Greatfather Winter with their creators, the titans. They regard the snowy blanket he casts over the land as a blessing, holding up their perpetually frigid homeland of Dun Morogh as prime evidence of his favor.",al={"dwarf winter veil","dwarven father winter","ironforge greatfather winter"},it="fame"},{q="What does Greatfather Winter do with the cookies and milk brought to him?",a="According to the holiday lore popularized by Smokywood Pastures, Greatfather Winter loves to snack on festive gingerbread cookies and ice cold milk while reviewing wishlists and spreading holiday cheer.",al={"treats for greatfather winter","why milk and cookies","gingerbread cookies quest"}},{q="How does the Horde view Greatfather Winter?",a="The Horde participates in the festivities largely through Smokywood Pastures' city promotion in Orgrimmar, where the Greatfather is portrayed as an orc. Culturally, the tauren recognize winter as a vital period of slumber and elemental renewal for the Earth Mother, respecting the Greatfather's role in the seasonal cycle while avoiding literal titan worship.",al={"horde greatfather winter","orgrimmar greatfather winter","tauren winter veil"}},{q="Whose side is Greatfather Winter on?",a="He belongs to neither faction. In legend, Greatfather Winter is an ancient, supernatural force of nature who bestows seasonal renewal and bounty across the entire world, regardless of mortal allegiances. The figure you see sitting in Ironforge is sponsored by the goblin trade company Smokywood Pastures, who maintain a strictly neutral, profit-driven operation. In fact, Smokywood Pastures hires an orc counterpart to sit in Orgrimmar and spread holiday cheer among the Horde simultaneously.",al={"greatfather winter alliance or horde","is greatfather winter alliance","greatfather winter faction"},it="side",add=true},{q="What does Greatfather Winter want?",a="The ancient spirit of myth seeks only to cloak the world in winter, giving the land necessary time for rest, rebirth, and eventual renewal while granting bounty to those who welcome him. The mortal impersonator you meet in Ironforge, however, is employed by Smokywood Pastures. Their goal is entirely festive and commercial: bringing cheer, handing out treats to good children, and driving enthusiastic sales for their holiday goods and toys.",al={"greatfather winter motives","what does greatfather winter want","why does greatfather winter give gifts"},it="wants",add=true},{q="Why is Greatfather Winter in Ironforge?",a="Smokywood Pastures stationed him beside the Winter Veil tree to anchor their seasonal festivities. During the weeks leading up to the holiday, the jolly figure meets with citizens and children to hear their holiday wishes, collect letters, and spread goodwill alongside his goblin helpers—all while helping Smokywood Pastures promote their seasonal wares.",al={"why is greatfather winter in ironforge","why is greatfather winter here","greatfather winter location ironforge"},it="why_here",add=true},{q="Who is Greatfather Winter tied to?",a="Dwarven tradition closely links the ancient spirit to the titans, believing he personifies their shaping power over Azeroth's seasons. In everyday practice, the festive Greatfather seen in the city is partnered with Smokywood Pastures, surrounded by their diminutive Little Helpers, festive snowmen, and eight legendary flying reindeer—most notably Metzen.",al={"who is greatfather winter associated with","greatfather winter connections","who works with greatfather winter"},it="ties",add=true}},ang={["race:Dwarf"]="Dwarves see the Greatfather as an aspect of the titans who carved the world, looking at the snowy peaks of Dun Morogh as living testimony of his touch.",["profession:Cooking"]="The holiday relies on skilled cooks to craft gingerbread cookies and other festive treats for Smokywood Pastures and Greatfather Winter himself."},kw={"dun morogh","gingerbread cookies","great-father winter","greatfather winter","ironforge","orgrimmar","smokywood pastures","winter veil"},rel={"zone:ironforge","zone:orgrimmar","zone:dunmorogh","topic:dwarf","topic:tauren","topic:goblin","topic:titan","quest:7025"},src={"Greatfather Winter"}}
E["npc:high-priest-rohan"] = {t="npc",n="High Priest Rohan",z="ironforge",s="High Priest Rohan is the preeminent leader of the Church of the Holy Light within Ironforge, found pacing inside the Hall of Mysteries. He oversees the spiritual development of fledgling priests across the Alliance and aids those seeking mastery over the Holy Light. Through his guidance and sacred relics, he maintains spiritual ties between the mountain kingdom, Stormwind, and distant allies.",h="High Priest Rohan is the preeminent leader of the Church of the Holy Light within Ironforge, found pacing...",sec={{t="Shepherd of the Hall of Mysteries",b="Pacing the quiet flagstones of the Hall of Mysteries in the Mystic Ward, High Priest Rohan acts as the highest-ranking representative of the Church of the Holy Light in Ironforge. While dwarves historically honored the titans, dwarven priests have deeply embraced the Light's virtues of wisdom, compassion, and justice. Rohan serves as a patient teacher to young acolytes, teaching them the discipline necessary to channel holy magic and steel their minds against despair.",sp=0},{t="Bridges Across the Alliance",b="Rohan recognizes that spiritual insight takes many shapes across the Alliance. Once priests under his tutelage grasp the fundamentals, he directs them outward—sending human and dwarven students to High Priestess Laurena in Stormwind City, or dispatching night elf disciples to Priestess Alathea at the Temple of the Moon in Darnassus to master elusive mysteries like Elune's Grace. Beyond the capitals, he urges devotees to render assistance wherever hardship strikes, even directing healers abroad to aid the druids of the Cenarion Circle in distant Azshara.",sp=0},{t="The Exorcism Censer",b="In addition to his teachings, Rohan holds custody over sacred relics essential to the wider Alliance priesthood and paladin brotherhoods. Among his possessions is a blessed exorcism censer, seasoned through years of cleansing vile spirits. When the Order of the Silver Hand and Lord Grayson Shadowbreaker require the vessel to temper the holy calling of their knights, Rohan freely yields it—asking only for charitable alms to replenish Ironforge's dwindling food reserves for the city's needy.",sp=0}},faq={{q="Where can I find High Priest Rohan?",a="High Priest Rohan is located inside the Hall of Mysteries, situated within the Mystic Ward on the northern side of Ironforge. He paces back and forth between the holy library and the altar.",al={"rohan location","where is priest trainer ironforge","rohan map","hall of mysteries priest trainer"},it="place",gp=true},{q="What role does Rohan serve in Ironforge?",a="He is the senior priest trainer in Ironforge and the leading dwarven representative of the Church of the Holy Light in Khaz Modan. He trains new priests, provides spiritual counsel, and directs practitioners to further advanced study across Azeroth.",al={"who is rohan","what does rohan do","rohan lore"},it="purpose"},{q="Why does Rohan send priests to Darnassus or Stormwind?",a="Rohan believes spiritual growth requires learning from diverse traditions. He sends human and dwarven initiates to the Cathedral of Light in Stormwind to learn specialized prayers like Desperate Prayer, and directs night elves back to Darnassus's Temple of the Moon so they may attune with Elune's Grace.",al={"rohan class quests","desperate prayer rohan","temple of the moon quest"},it="allies"},{q="Why do paladins seek out Rohan?",a="Paladins sent by Lord Grayson Shadowbreaker visit Rohan to secure his blessed exorcism censer. Rohan donates the relic to help the Order of the Silver Hand complete their rites, requesting in return a modest donation of supplies to feed the impoverished of Ironforge.",al={"paladin quest rohan","exorcism censer","emphasis on sacrifice"},it="ties"},{q="Why does Rohan send priests to Azshara?",a="Guided by the Light's tenets of charity and service, Rohan dispatches healers to aid the night elf druids of the Cenarion Circle who are working in the wild, rugged lands of Azshara.",al={"cenarion aid rohan","rohan cenarion circle"},it="motive"},{q="Does Rohan only train dwarves?",a="Rohan guides any Alliance devotee walking the path of the priesthood, including dwarves, humans, and night elves, offering early instruction before sending them onward to mentors tailored to their specific traditions.",al={"can humans train with rohan","who does rohan train"},it="people"},{q="Who is High Priest Rohan?",a="High Priest Rohan is the highest-ranking member of the Church of the Holy Light residing in Ironforge. A venerable and devout dwarf, he serves as the principal spiritual mentor for priests within the mountain kingdom, guiding novices in the ways of devotion, healing, and holy wrath.",al={"who is rohan","high priest rohan","rohan lore"},it="identity",add=true},{q="Whose side is High Priest Rohan on?",a="Rohan stands firmly with the Kingdom of Ironforge, the Grand Alliance, and the Church of the Holy Light. He works closely with human clergy in Stormwind, the night elves of Darnassus, and even sends aid to neutral groups like the Cenarion Circle when lives need saving.",al={"rohan faction","is rohan alliance","rohan allegiance"},it="side",add=true},{q="What does High Priest Rohan want?",a="Rohan is dedicated to spreading the virtues of the Holy Light and tending to those in need. He seeks to cultivate wisdom and resilience in young priests, care for Ironforge's impoverished residents, and dispatch aid wherever suffering threatens innocent lives across Azeroth.",al={"what does rohan want","rohan goals","rohan motivations"},it="wants",add=true},{q="Why is High Priest Rohan here in the Hall of Mysteries?",a="The Hall of Mysteries serves as Ironforge's sanctuary for divine study and arcane contemplation. Rohan paces its sacred halls to oversee the city's spiritual well-being, minister to visiting supplicants, and personally instruct rising priests before sending them out into the wider world.",al={"why is rohan in ironforge","why is rohan here","rohan hall of mysteries"},it="why_here",add=true}},ang={["class:Priest"]="High Priest Rohan offers essential guidance and early ability training, eventually directing you to renowned mentors in Stormwind or Darnassus to unlock unique racial devotions.",["class:Paladin"]="Holy knights sent by Lord Grayson Shadowbreaker must visit Rohan to obtain his famed exorcism censer in exchange for aid to the needy of Ironforge.",["race:Dwarf"]="Rohan embodies the dwarven devotion to the Holy Light, showing that the stout folk of Khaz Modan possess deep spiritual conviction alongside their titan heritage.",["faction:Alliance"]="Through his close cooperation with the Cathedral of Light, the Temple of the Moon, and the Cenarion Circle, Rohan keeps Ironforge's clergy woven tightly into the wider Alliance."},kw={"church of the holy light","exorcism censer","grayson shadowbreaker","hall of mysteries","high priest rohan","ironforge","mystic ward","priest trainer","rohan"},rel={"subzone:hall-of-mysteries","subzone:mystic-ward","zone:ironforge","npc:high-priestess-laurena","npc:priestess-alathea","npc:lord-grayson-shadowbreaker","topic:church-of-the-holy-light","quest:5634"},src={"High Priest Rohan"}}
E["npc:innkeeper-firebrew"] = {t="npc",n="Innkeeper Firebrew",z="ironforge",s="Innkeeper Firebrew manages the Stonefire Tavern in the bustling Commons of Ironforge. A genial host to weary mountaineers and visiting dignitaries alike, he serves hearty dwarven staples and keeps travelers rested beneath the mountain.",h="Innkeeper Firebrew manages the Stonefire Tavern in the bustling Commons of Ironforge.",sec={{t="Keeper of the Stonefire",b="Situated in the central ring of the Commons, Innkeeper Firebrew's establishment is often the first sanctuary encountered by travelers entering through the Great Gates of Ironforge. Behind a counter laden with flagons of ale, skins of stout, and roasted joints of meat, Firebrew offers hospitality to adventurers bound for the snowy passes of Dun Morogh or deeper into the mountain kingdom. His tavern remains a lively crossroad where miners, riflemen, and emissaries gather to escape the drafty tunnels and exchange tales around the hearth.",sp=0}},faq={{q="Where can I find Innkeeper Firebrew?",a="Innkeeper Firebrew is found inside the Stonefire Tavern, located along the southern edge of the Commons in Ironforge.",al={"firebrew location","where is innkeeper firebrew","ironforge tavern keeper"},it="place",gp=true},{q="What kind of goods does Firebrew sell?",a="He offers standard innkeeper provisions, specializing in robust dwarven rations. Travelers can purchase drinks ranging from local Dwarven Stout and Mead to imported wines, alongside meats and hearty meals suited for long journeys.",al={"what does firebrew sell","firebrew drinks","stonefire tavern food"},it="item",gp=true},{q="Is Firebrew part of any dwarven brewing family?",a="He bears the surname Firebrew, but his family relationships are not confirmed.",al={"firebrew family","who is firebrew related to"},it="ties"},{q="What services does he provide to travelers?",a="As a tavern keeper, Firebrew allows travelers of the Alliance to bind their hearthstones to the Stonefire Tavern and provides a warm bed to rest and recover beneath the mountain.",al={"can i bind hearthstone here","ironforge hearthstone inn"},it="purpose",gp=true},{q="Who is Innkeeper Firebrew?",a="Innkeeper Firebrew is the dwarven proprietor of the Stonefire Tavern, located in the bustling Commons of Ironforge. A welcoming figure within the mountain city, he tends the hearth, serves ale, and provides food and lodging to locals and weary travelers alike.",al={"who is firebrew","innkeeper firebrew","stonefire tavern innkeeper"},it="identity",add=true},{q="Whose side is Innkeeper Firebrew on?",a="Firebrew is loyal to the Kingdom of Ironforge and stands firmly with the Alliance. He keeps his tavern open to all allied adventurers seeking refuge from the cold winds of Dun Morogh or resting after long journeys across Azeroth.",al={"firebrew faction","firebrew alliance","is firebrew alliance"},it="side",add=true},{q="What does Innkeeper Firebrew want?",a="Firebrew is focused on running a lively and hospitable tavern. He wants to keep the Stonefire Tavern's hearth roaring, fill patrons' mugs with strong dwarven drink, and ensure visitors to the great forge city have a warm place to rest and bind their hearthstones.",al={"what does firebrew want","firebrew motive","firebrew goals"},it="wants",add=true},{q="Why is Innkeeper Firebrew here?",a="Firebrew manages the Stonefire Tavern in the Commons, making him the central host for travelers entering the heart of Ironforge. He stays right by the hearth to offer lodging, sell rations and drink, and provide a welcoming anchor for adventurers arriving in the capital.",al={"why is firebrew in ironforge","why is firebrew at the stonefire tavern"},it="why_here",add=true}},ang={["race:Dwarf"]="For dwarves returning from patrols across Khaz Modan, Firebrew's tavern offers the comforting warmth of home and a reliable mug of dwarven stout.",["faction:Alliance"]="As the primary innkeeper near the front gates, Firebrew provides foreign Alliance travelers a central, safe haven to rest when visiting King Magni Bronzebeard's capital."},kw={"commons","dwarf","firebrew","hearthstone","innkeeper","ironforge","stonefire tavern"},rel={"subzone:stonefire-tavern","subzone:commons","zone:ironforge","topic:dwarf","topic:alliance","quest:8353"},src={"Innkeeper Firebrew"}}
E["npc:krom-stoutarm"] = {t="npc",n="Krom Stoutarm",z="ironforge",s="Krom Stoutarm is a dwarven scholar and warlock found deep within the Library of the Hall of Explorers in Ironforge. Unlike most of his kin who delve solely into ancient stone and titan relics, Krom studies darker, arcane texts and demonic rituals. He acts as an indispensable contact for Alliance warlocks seeking esoteric knowledge across Kalimdor and the Eastern Kingdoms.",h="Krom Stoutarm is a dwarven scholar and warlock found deep within the Library of the Hall of Explorers in...",sec={{t="A Darker Corner of the Hall",b="The Hall of Explorers is typically known for dwarven archaeologists obsessed with picks, shovels, and titan artifacts. Krom Stoutarm cuts an unusual figure among them. Lurking in the Library surrounded by massive tomes, he pursues occult lore and the binding rites of demonic summoners. His presence in Ironforge demonstrates that while warlock arts are widely distrusted, scholar-practitioners who study the forbidden arts still operate within the mountain city's halls.",sp=0},{t="The Tome of the Cabal",b="When Alliance warlocks seek to bind potent demonic servants like the felhunter, their journey inevitably crosses paths with Krom. Possessing knowledge of scattered occult volumes, he directs aspiring summoners far across the seas—including dangerous forays into hostile territories like the Barrens—to recover torn pages and fragments of the infamous Tome of the Cabal.",sp=0}},faq={{q="Where can I find Krom Stoutarm?",a="Krom Stoutarm is located inside the Library wing of the Hall of Explorers in the dwarven capital of Ironforge.",al={"krom stoutarm location","where is krom stoutarm","krom stoutarm ironforge"},it="place",gp=true},{q="What role does Krom Stoutarm play for players?",a="Krom serves as a crucial quest contact for Alliance warlocks pursuing their class-defining demonic rituals, particularly guiding them through the retrieval of the Tome of the Cabal.",al={"what does krom do","krom stoutarm purpose","krom stoutarm quests"},it="purpose",gp=true},{q="Is Krom Stoutarm related to other Stoutarms?",a="Several dwarves share the Stoutarm surname, but a family relationship between Krom and the others is unconfirmed.",al={"krom relatives","sten stoutarm related"},it="ties"},{q="Why is a warlock permitted inside the Hall of Explorers?",a="Krom is both a warlock and a scholar working from the Hall of Explorers. The source does not explain the terms under which his work is permitted.",al={"why is krom in hall of explorers","ironforge warlock allowed"}},{q="Why is Krom connected to the Barrens?",a="In his research into dark manuscripts, Krom sends warlocks to retrieve lost segments of the Tome of the Cabal, with one such critical piece hidden in a chest deep within the Quillboar-infested lands of the Barrens.",al={"krom stoutarm barrens","why barrens quest krom"},it="why_here"},{q="Does Krom Stoutarm train spells?",a="Krom is a scholarly quest giver rather than a standard class trainer. He directs warlocks along specific rites of passage rather than teaching everyday grimoires.",al={"can krom train me","krom warlock trainer"},gp=true},{q="Who is Krom Stoutarm?",a="Krom Stoutarm is a dwarven warlock who studies dark lore from within the Library of the Hall of Explorers in Ironforge. Unlike many practitioners of the fel arts who hide in shadowed basements and secluded covens, Krom operates openly among the scholars and excavators of the Explorers' League, delving into ancient relics, obscure arcana, and occult tomes.",al={"who is krom","krom stoutarm lore","who is krom stoutarm"},it="identity",add=true},{q="Whose side is Krom Stoutarm on?",a="Krom Stoutarm is loyal to Ironforge and the Alliance. Though he practices warlock arts that draw suspicion and unease from many of his kin, he remains a respected scholar within the Hall of Explorers, offering his esoteric expertise and arcane knowledge solely to aid Alliance champions in their endeavors.",al={"krom stoutarm faction","krom stoutarm alliance or horde","who does krom serve"},it="side",add=true}},ang={["class:Warlock"]="Alliance warlocks must consult Krom during their pursuit of dark bindings, notably the dangerous task of assembling the Tome of the Cabal.",["race:Dwarf"]="Dwarves usually disown the fell arts, making Krom's position among the revered shelves of the Hall of Explorers a curious rarity.",["faction:Alliance"]="Krom provides the Alliance's covert practitioners a safe intellectual haven within Ironforge's mighty mountain bastions."},kw={"hall of explorers","ironforge","krom stoutarm","library","stoutarm","tome of the cabal","warlock"},rel={"quest:1758","subzone:library-ironforge","subzone:hall-of-explorers","zone:ironforge","npc:sten-stoutarm","zone:barrens","topic:dwarf","topic:alliance"},src={"Krom Stoutarm"}}
E["npc:laris-geardawdle"] = {t="npc",n="Laris Geardawdle",z="ironforge",s="Laris Geardawdle is an eccentric gnomish researcher stationed in the Library of the Hall of Explorers in Ironforge. He dedicates his academic life to studying the bizarre nature and origins of oozes across Azeroth. Adventurers willing to collect noxious slime samples find him an eager, if slightly unhinged, patron.",h="Laris Geardawdle is an eccentric gnomish researcher stationed in the Library of the Hall of Explorers in...",sec={{t="Scholar of Slime",b="Tucked away among the towering bookshelves and ancient relics of the Hall of Explorers, Laris Geardawdle pursues a rather unglamorous niche of natural philosophy: the genesis of oozes. While his dwarven colleagues pore over Titan tablets and ancient stone carvings, Laris is convinced that Azeroth's vile, gelatinous horrors hold fascinating alchemical and biological secrets. He tasks roving explorers with gathering caustic samples from remote corners of the world, eager to test his strange hypotheses on how these mindless puddles of malice come to life.",sp=0}},faq={{q="Who is Laris Geardawdle?",a="Laris Geardawdle is a gnome researcher dwelling in the Library of the Hall of Explorers in Ironforge. He focuses his unconventional studies on oozes, slimes, and the bizarre mechanics behind their spontaneous generation.",al={"laris","geardawdle","who is laris"},it="identity"},{q="Where can I find Laris Geardawdle?",a="He can be found in the northern wing of Ironforge inside the Hall of Explorers, specifically tucked into the quiet confines of the Library.",al={"laris location","where is laris","find laris geardawdle"},it="place",gp=true},{q="Why is he studying oozes?",a="Laris possesses a keen, eccentric scientific mind and has developed distinct theories regarding the nature and creation of living slime. He believes analyzing caustic residue from different oozes will unlock deeper understanding of how these bizarre organisms form and replicate.",al={"why oozes","laris slime research","ooze study"},it="wants"},{q="What tasks does he offer adventurers?",a="Laris recruits bold travelers to venture into treacherous lands to collect pure ooze samples. Through his task, 'A Little Slime Goes a Long Way', he provides empty collection jars and asks adventurers to harvest viscous residue from living slimes in the field.",al={"laris quests","a little slime goes a long way"},gp=true},{q="Whose side is Laris Geardawdle on?",a="Laris Geardawdle stands firmly with the Alliance and the Gnomeregan Exiles. Operating out of the Hall of Explorers in Ironforge alongside dwarven scholars and researchers, he contributes his keen mind and eccentric biological theories toward advancing Alliance knowledge and understanding of strange phenomena across the world.",al={"laris geardawdle faction","laris geardawdle alliance","is laris geardawdle friendly"},it="side",add=true},{q="Why is Laris Geardawdle in Ironforge?",a="Following the fall of Gnomeregan, many gnomes sought refuge among their dwarven allies in Ironforge. Laris Geardawdle made his home in the Library within the Hall of Explorers, an ideal sanctuary where he can pursue his eccentric academic research and catalog his theories on the origin of oozes with full access to extensive historical and natural archives.",al={"why is laris geardawdle here","laris geardawdle hall of explorers","why is laris in ironforge"},it="why_here",add=true}},ang={["race:Gnome"]="Laris exemplifies the quintessential gnomish drive to seek knowledge in places everyone else overlooks, even if it involves plunging hands into foul-smelling swamp muck.",["faction:Alliance"]="Stationed within the Hall of Explorers, Laris works under the broad umbrella of Alliance-sponsored scholarship, adding eccentric natural science to the League's historical digging."},kw={"gnome","hall of explorers","ironforge","laris geardawdle","library","ooze","slime"},rel={"zone:ironforge","subzone:hall-of-explorers","subzone:library-ironforge","quest:4512","topic:gnome"},src={"Laris Geardawdle"}}
E["npc:lieutenant-nevell"] = {t="npc",n="Lieutenant Nevell",z="ironforge",s="Lieutenant Nevell is an officer of the Argent Dawn stationed outside the gates of Ironforge in Dun Morogh. Serving as a bulwark against the spreading darkness of the Scourge, he coordinates local defenders and alerts arriving adventurers to undead threats probing the dwarf kingdom's borders.",h="Lieutenant Nevell is an officer of the Argent Dawn stationed outside the gates of Ironforge in Dun Morogh.",sec={{t="A Watch in the Snow",b="While the Argent Dawn is most renowned for holding the line in the shattered Plaguelands of Lordaeron, its vigilance reaches far into the south. Stationed in the freezing winds outside Ironforge, Lieutenant Nevell represents the order's proactive defense against necromantic incursions. When Scourge activity stirs in the mountain passes of Dun Morogh, Nevell directs recruits and capable adventurers toward the front lines to ensure Ironforge's snowy doorstep remains secure.",sp=0}},faq={{q="Who is Lieutenant Nevell?",a="Lieutenant Nevell is an officer of the Argent Dawn stationed near Ironforge in Dun Morogh. His mission is to rally local defenders and investigate signs of Scourge presence encroaching upon the dwarven realm.",al={"nevell role","who is nevell","lieutenant nevell"},it="identity"},{q="Why is the Argent Dawn outside Ironforge?",a="Though based primarily in Lordaeron, the Argent Dawn monitors the entire continent for undead incursions. If the Lich King attempts to strike deep into allied territories like Dun Morogh, officers like Nevell are dispatched to coordinate city defenses and scout enemy movements.",al={"argent dawn in dun morogh","argent dawn ironforge"},it="why_here"},{q="What does Lieutenant Nevell ask adventurers to do?",a="Nevell charges capable heroes with venturing beyond Ironforge's gates to scout and beat back nearby Scourge forces, neutralizing the undead threat before it can establish a foothold in the mountain passes.",al={"nevell quests","investigate the scourge"},it="wants"},{q="Whose side is Lieutenant Nevell on?",a="Lieutenant Nevell serves the Argent Dawn, a dedicated neutral order committed to protecting Azeroth from the Scourge. Though human, he stands outside the gates of Ironforge as an ally to all who oppose the undead menace, coordinating defenses alongside the dwarves rather than serving the Alliance military directly.",al={"lieutenant nevell faction","who does lieutenant nevell fight for","is nevell argent dawn"},it="side",add=true},{q="Who is Lieutenant Nevell tied to?",a="Nevell answers directly to the leadership of the Argent Dawn. Stationed on the slopes of Dun Morogh, he acts as a liaison between the order and the defenders of Ironforge, rallying local adventurers and mountain guards to confront any creeping threat of the Scourge in the region.",al={"nevell connections","lieutenant nevell argent dawn ties","who does nevell report to"},it="ties",add=true}},ang={["race:Dwarf"]="Dwarves appreciate the Argent Dawn's watchful eye outside their mountain home, knowing that vigilance against necromancy is needed even on the cold slopes of Dun Morogh.",["faction:Alliance"]="For Alliance champions heading into Ironforge, Nevell stands as a reminder that the war against the Scourge is not confined to the north."},kw={"argent dawn","dun morogh","ironforge","lieutenant nevell","nevell","scourge"},rel={"quest:9261","topic:argent-dawn","zone:ironforge","zone:dunmorogh","topic:scourge","npc:lieutenant-orrin"},src={"Lieutenant Nevell"}}
E["npc:lomac-gearstrip"] = {t="npc",n="Lomac Gearstrip",z="ironforge",s="Lomac Gearstrip is an ambitious gnome inventor based in Tinker Town within Ironforge. Renowned for formulating the devastating NG-5 explosive, he liaises with fellow gnomish researchers operating across Kalimdor.",h="Lomac Gearstrip is an ambitious gnome inventor based in Tinker Town within Ironforge.",sec={{t="A Spark in Tinker Town",b="Amid the clanging gears and hissing pipes of Ironforge's Tinker Town, Lomac Gearstrip pursues the finer points of gnomish ordnance. Like many exiled gnomes who fled the tragedy at Gnomeregan, Lomac has integrated his tinkering operations directly into the dwarven capital. His workshop focuses on volatile chemical mixtures and specialized munitions designed to overcome heavily defended enemy strongholds.",sp=0},{t="The NG-5 Explosive",b="Lomac's proudest contribution to modern combat engineering is the NG-5 explosive. Formulated for maximum destructive yield, the compound demands precise handling and rare chemical reagents. To refine and deploy such hazardous inventions in the field, Lomac maintains contact with old colleagues stationed in distant theaters, exchanging technical orders and dangerous supplies across the Great Sea.",sp=0}},faq={{q="Where can I find Lomac Gearstrip?",a="Lomac Gearstrip resides in Tinker Town, the gnomish quarter located in the eastern portion of the mountain city of Ironforge.",al={"lomac gearstrip location","where is lomac","find lomac gearstrip"},it="place",gp=true},{q="What is Lomac Gearstrip famous for inventing?",a="Lomac is best known as the creator of the NG-5 explosive, a potent ordnance formula designed to provide devastating firepower for gnomish endeavors.",al={"what did lomac make","lomac invention","ng-5 explosive creator"},it="fame"},{q="Why does Lomac deal with contacts in Kalimdor?",a="Lomac keeps in touch with former research peers and colleagues working in frontier regions like Stonetalon Mountains, coordinating the procurement of hazardous chemical ingredients and testing his high-yield explosives in active operations.",al={"lomac stonetalon","why stonetalon quest","lomac colleagues"},it="why_here"},{q="What kind of tasks does Lomac offer to adventurers?",a="Lomac tasks trustworthy Alliance couriers with transporting purchase orders and volatile chemical reagents between Ironforge and researchers stationed abroad, often involving his NG-5 explosive experiments.",al={"lomac quests","ineptitude chemicals fun","an old colleague quest"},it="purpose",gp=true},{q="What is the Purchase Order Receipt tied to Lomac?",a="Lomac authored the Purchase Order Receipt, a manifest used to organize and document shipments of specialized equipment and dangerous volatile reagents between tinkerers.",al={"purchase order receipt","lomac receipt"},it="item",gp=true},{q="Is Lomac affiliated with Gnomeregan's refugees?",a="Yes. Like the rest of the residents of Tinker Town, Lomac is part of the displaced Gnomeregan community living under the hospitality of the Ironforge dwarves while continuing his engineering work.",al={"is lomac from gnomeregan","lomac faction"},it="side"},{q="Who is Lomac Gearstrip?",a="Lomac Gearstrip is an ambitious gnomish inventor and tinker operating out of Tinker Town within the dwarven stronghold of Ironforge. Deeply engrossed in volatile experimentation and chemical engineering, he is best known for developing potent ordnances like the NG-5 explosive. Despite the distance across the Great Sea, he maintains contacts and business arrangements stretching as far as Kalimdor to acquire the rare materials and field testing he needs.",al={"who is lomac","who is gearstrip","lomac gearstrip lore"},it="identity",add=true},{q="What does Lomac Gearstrip want?",a="Lomac Gearstrip is driven by his explosive engineering projects, most notably the refinement of his prized NG-5 charge. To keep his chemical trials moving forward, he requires couriers, volatile compounds, and field tests conducted with his concoctions. He relies on travelers and old acquaintances across the world to fulfill purchase orders and procure the rare reagents necessary to perfect his volatile inventions.",al={"what does lomac want","lomac gearstrip goals","why does lomac need help"},it="wants",add=true},{q="Who is Lomac Gearstrip tied to?",a="Lomac maintains ties with distant associates and fellow tinkers, including an old colleague based abroad who assists with orders and specialized testing. Working from Tinker Town, he operates comfortably alongside both the Gnomeregan exiles and Ironforge's resident craftsmen, directing couriers and adventurers to liaise between his workbench in the Eastern Kingdoms and testing grounds across Kalimdor.",al={"who does lomac work with","lomac gearstrip associates","lomac old colleague"},it="ties",add=true}},ang={["profession:Engineering"]="Lomac's NG-5 explosive represents the cutting edge of gnomish pyrotechnics, serving as inspiration for tinkerers interested in high-yield blasting compounds.",["race:Gnome"]="Lomac embodies the resilient drive of Tinker Town's gnomes, maintaining high-stakes technical research even while living in exile from Gnomeregan.",["faction:Alliance"]="Alliance operatives moving between Ironforge and expedition outposts in Kalimdor often handle sensitive munitions and volatile formulas on Lomac's behalf."},kw={"an old colleague","gnome engineer","ineptitude + chemicals = fun","ironforge","lomac gearstrip","ng-5 explosive","stonetalon","tinker town"},rel={"subzone:tinker-town","zone:ironforge","quest:1072","quest:1073","zone:stonetalon","topic:gnome"},src={"Lomac Gearstrip"}}
E["npc:lord-grayson-shadowbreaker"] = {t="npc",n="Lord Grayson Shadowbreaker",z="ironforge",s="Lord Grayson Shadowbreaker is a veteran paladin commander of the Knights of the Silver Hand stationed within Stormwind's Cathedral of Light. Recognizable by his towering build and missing right eye, he trains budding champions of the Light and oversees the sacred, arduous trials required for senior paladins to claim their holy chargers.",h="Lord Grayson Shadowbreaker is a veteran paladin commander of the Knights of the Silver Hand stationed within...",sec={{t="Master of the Silver Hand",b="Lord Grayson Shadowbreaker stands among the foremost defenders of the Alliance, anchoring the order's presence in Stormwind City. A veteran warrior who sacrificed his right eye in battle, Grayson does not merely instruct recruits in martial skill; he tests their spiritual conviction. When promising knights demonstrate their readiness, Grayson dispatches them north toward the contested front lines of the Western Plaguelands to aid Commander Ashlam Valorfist at Chillwind Camp.",sp=0},{t="The Trials of the Holy Charger",b="For paladins seeking their sacred warhorse, Shadowbreaker demands profound sacrifice and unquestioned virtue. His trials require humbling acts of charity—such as aiding Ironforge's impoverished via High Priest Rohan—as well as perilous journeys to exorcise Terrordale and cleanse ancient spirits within Dire Maul. The trial culminates in the dark depths of Scholomance, where an initiate must confront the death knight Darkreaver and redeem an unholy steed from servitude through the Light.",sp=1}},faq={{q="Where can I find Lord Grayson Shadowbreaker?",a="Lord Grayson Shadowbreaker resides inside the Cathedral of Light, situated in the Cathedral Square of Stormwind City. He stands inside the main halls overseeing the paladins of the Silver Hand.",al={"where is grayson shadowbreaker","shadowbreaker location","where is lord grayson"},it="place",gp=true},{q="What is Lord Grayson's role for paladins?",a="He serves as a high-ranking paladin trainer for the Alliance. In addition to directing young knights toward front-line combat against the Scourge in Lordaeron, he orchestrates the sacred ritual questline required to forge holy barding and claim a paladin charger.",al={"what does grayson do","grayson shadowbreaker purpose","why visit lord grayson"},it="purpose"},{q="How did Lord Grayson lose his right eye?",a="Grayson lost his right eye fighting on the battlefield during his long service to the Alliance and the Order of the Silver Hand, bearing the scar as a testament to decades of war.",al={"how did grayson lose his eye","why is grayson missing an eye","grayson eyepatch"},it="history"},{q="What is his connection to the Forsaken?",a="His sister Jubeka perished during the Scourging of Lordaeron and was reanimated as one of the Forsaken. When she later sought him out hoping to reconcile, Grayson rejected her as an unholy monster, fiercely maintaining that his true sister died with Lordaeron.",al={"grayson sister","jubeka shadowbreaker","does grayson have undead family"},it="conflict"},{q="Why does Grayson send paladins to Grimand Elmore?",a="Grimand Elmore forged the barding for Grayson's own charger years ago. Because a holy charger requires flawless craftsmanship that balances physical endurance with spiritual harmony, Grayson sends all worthy initiates to Grimand to craft their Arcanite Barding.",al={"grayson and grimand elmore","who makes the paladin barding","arcanite barding quest"},it="item"},{q="Who is Lord Grayson Shadowbreaker?",a="Lord Grayson Shadowbreaker is one of the foremost paladins of Stormwind and the Alliance. A tall, battle-hardened veteran of the Knights of the Silver Hand who lost his right eye in combat, he serves as a senior master of the holy order, training and guiding promising knights in the ways of the Light.",al={"who is grayson shadowbreaker","who is lord grayson","about grayson shadowbreaker"},it="identity",add=true},{q="Whose side is Lord Grayson Shadowbreaker on?",a="Lord Grayson stands firmly with the Grand Alliance, the kingdom of Stormwind, and the Order of the Silver Hand. He is dedicated completely to the Holy Light and the defense of the living against the Scourge and other dark threats.",al={"grayson shadowbreaker faction","who does grayson serve","is grayson alliance"},it="side",add=true},{q="What does Lord Grayson Shadowbreaker want?",a="Lord Grayson seeks to forge the next generation of holy warriors to push back the darkness consuming Azeroth. He tests paladins through arduous spiritual and martial trials, sending them to fight the Scourge in the Plaguelands and proving their worthiness to earn a blessed charger.",al={"grayson shadowbreaker goals","what does grayson want","grayson motive"},it="wants",add=true},{q="Why is Lord Grayson Shadowbreaker in the Cathedral of Light?",a="He is stationed within Stormwind's Cathedral of Light to oversee the development of the city's paladins. From this central bastion of faith, he coordinates missions against the Scourge and guides senior champions through the demanding trials required to summon their holy warhorses.",al={"why is grayson in stormwind","why is grayson here","grayson cathedral of light"},it="why_here",add=true},{q="Who is Lord Grayson Shadowbreaker tied to?",a="Within Stormwind, Grayson works closely with High Priest Rohan, the blacksmith Grimand Elmore, and commanders fighting the Scourge in the north like Ashlam Valorfist. He also took in Arator the Redeemer, son of Turalyon and Alleria Windrunner, training him as his personal squire.",al={"grayson shadowbreaker allies","who does grayson know","grayson squires"},it="ties",add=true}},ang={["class:Paladin"]="Grayson acts as one of your highest spiritual mentors in the Alliance, guiding your path against the Scourge in Lordaeron and conducting the exacting trials needed to summon a true charger.",["faction:Alliance"]="A stoic veteran of the Silver Hand, Lord Grayson helps reinforce Stormwind's defense and bolsters expeditionary aid toward the contested northern kingdoms."},kw={"cathedral of light","charger","grayson","grimand elmore","jubeka","paladin","scholomance","shadowbreaker","silver hand"},rel={"subzone:cathedral-of-light","quest:1700","zone:stormwind","npc:high-priest-rohan","subzone:chillwind-camp","subzone:scholomance","subzone:dire-maul","topic:light"},src={"Lord Grayson Shadowbreaker"}}
E["npc:nissa-firestone"] = {t="npc",n="Nissa Firestone",z="ironforge",s="Nissa Firestone is a dwarven physician stationed above the bustle of the Great Forge in Ironforge. She serves as an instructor in field medicine, teaching travelers and soldiers how to dress wounds and bind trauma.",h="Nissa Firestone is a dwarven physician stationed above the bustle of the Great Forge in Ironforge.",sec={{t="A Healer Above the Anvils",b="Amid the clanging metal and blistering heat of the Great Forge, Nissa Firestone practices medicine from the upper floor of the Ironforge Physician shop. While dwarven warriors are famed for their endurance, even stone-hard skin splits against blade and claw. Nissa ensures that those heading out into the snows of Dun Morogh or beyond know how to keep themselves and their allies alive with basic bandaging and field dressings.",sp=0},{t="Triage and Advanced Trauma",b="For field medics who have mastered the basics of cloth and lint, Nissa recognizes when a student has outgrown her clinic. When practitioners reach the limits of what she can teach, she points them toward specialized triage officers in far-flung outposts, directing skilled healers to where the Alliance's casualties are heaviest.",sp=0}},faq={{q="Who is Nissa Firestone?",a="Nissa Firestone is a dwarf first aid trainer who operates out of the Ironforge Physician shop, located on the southern perimeter of the Great Forge.",al={"who is nissa firestone","nissa firestone role","ironforge first aid trainer"},it="identity"},{q="Where can I find Nissa Firestone?",a="She can be found on the upper floor of the Ironforge Physician shop, which sits on the southern edge of the Great Forge ring in Ironforge.",al={"nissa firestone location","where is nissa","ironforge physician location"},it="place",gp=true},{q="What does Nissa Firestone teach?",a="She instructs Alliance adventurers in the art of First Aid, teaching the craft of preparing bandages and antidotes to treat injuries sustained in the field.",al={"what does nissa teach","first aid ironforge","learn bandages ironforge"},gp=true},{q="Can Nissa teach master-level triage?",a="No. Once a medic reaches advanced proficiency, Nissa directs them elsewhere via the Alliance Trauma assignment, sending them to seasoned field surgeons stationed near active war zones.",al={"alliance trauma quest","master first aid ironforge","first aid over 225"},gp=true},{q="Whose side is Nissa Firestone on?",a="Nissa Firestone stands firmly with Ironforge and the Alliance. Stationed high in the capital, she dedicates her medical knowledge to keeping Ironforge's defenders and Alliance travelers alive through field dressing and trauma care.",al={"nissa firestone faction","is nissa alliance","who does nissa serve"},it="side",add=true},{q="Why is Nissa Firestone in Ironforge?",a="Nissa works out of the Ironforge Physician shop above the Great Forge. From this central position within the dwarven capital, she can tend to the city's sick and injured while training adventurous field medics to bind wounds and staunch bleeding before they march into battle.",al={"why is nissa here","nissa firestone location why","what brought nissa to ironforge"},it="why_here",add=true},{q="What does Nissa Firestone want?",a="As a physician and trainer, Nissa's primary aim is ensuring that Alliance fighters know how to patch themselves up in the field. When promising medics outgrow her tutelage, she directs them to advanced field surgeons who can teach wartime triage.",al={"what does nissa want","nissa firestone goals","nissa firestone motive"},it="wants",add=true}},ang={["race:Dwarf"]="For dwarves returning from skirmishes with troggs or frost trolls, Nissa represents the practical, no-nonsense approach of Ironforge's medical tradition.",["faction:Alliance"]="Any Alliance adventurer passing through Khaz Modan relies on trainers like Nissa to acquire essential survivability skills without needing divine or arcane magic."},kw={"alliance trauma","bandages","first aid","great forge","healer","ironforge physician","nissa firestone"},rel={"zone:ironforge","subzone:great-forge","quest:6625","topic:dwarf","topic:alliance"},src={"Nissa Firestone"}}
E["npc:prospector-stormpike"] = {t="npc",n="Prospector Stormpike",z="ironforge",s="Prospector Stormpike is a blunt, short-tempered dwarf stationed within the Library of the Hall of Explorers in Ironforge. A member of the renowned Stormpike clan, he oversees logistical support for distant archaeological digs and lends his sharp intellect to deciphering coded missives.",h="Prospector Stormpike is a blunt, short-tempered dwarf stationed within the Library of the Hall of Explorers...",sec={{t="Scholar of the Hall of Explorers",b="Tucked away amid the towering bookshelves of the Hall of Explorers, Prospector Stormpike coordinates excavation efforts across Khaz Modan and beyond. Despite his gruff demeanor and impatience with idle chatter, he is deeply dedicated to uncovering dwarven history, keeping distant sites supplied with essentials like blasting powder. Beneath his rough exterior lies a keen analytical mind skilled at breaking intricate ciphers, making him an unexpected asset to Alliance scouts dealing with clandestine threats.",sp=0}},faq={{q="Who is Prospector Stormpike?",a="He is an archaeologist and logistics coordinator belonging to the well-known Stormpike clan, based in the Library wing of Ironforge's Hall of Explorers.",al={"who is stormpike","prospector stormpike lore","stormpike npc"},it="identity"},{q="Where can I find Prospector Stormpike?",a="He can be found standing inside the Library, located within the Hall of Explorers in the eastern reaches of Ironforge.",al={"stormpike location","where is prospector stormpike"},it="place",gp=true},{q="What kind of work does he do?",a="Stormpike handles supply lines and reports for archaeological excavations—such as dispatching blasting powder out to field prospectors like Prospector Ironband in Loch Modan—and assists with breaking complex encrypted ciphers brought back by scouts.",al={"stormpike quests","what does stormpike do"},it="purpose"},{q="Why does Southshore need his help?",a="Alliance authorities in Southshore rely on his knack for cryptography to decode intercepted letters written by the secretive Argus Wake cult.",al={"argus wake cipher","southshore stormpike"}},{q="Whose side is Prospector Stormpike on?",a="Prospector Stormpike is loyal to the Kingdom of Ironforge and the Alliance. As an operative of the dwarven Explorers' League, his field duties and archaeological research directly serve King Magni Bronzebeard and the interests of the dwarven realm.",al={"stormpike faction","prospector stormpike alliance","who does stormpike serve"},it="side",add=true},{q="What does Prospector Stormpike want?",a="Prospector Stormpike wants to decipher vital intelligence and coordinate archaeological expeditions without needless disruption. He oversees research for excavations like Ironband's Compound and applies his expertise in cryptanalysis to untangle encoded messages, demanding utmost focus and impatience with idle distractions.",al={"what does stormpike need","prospector stormpike goal","stormpike motives"},it="wants",add=true},{q="Why is Prospector Stormpike in Ironforge?",a="You can find Prospector Stormpike stationed in the Library of Ironforge's Hall of Explorers because it serves as the operational nerve center for the Explorers' League. From here, he reviews field reports, translates recovered relics, and deciphers intercepted correspondence requiring scholarly attention.",al={"why is stormpike here","prospector stormpike library","why hall of explorers stormpike"},it="why_here",add=true},{q="Who is Prospector Stormpike tied to?",a="He is a member of the influential Stormpike clan, an esteemed dwarven lineage renowned across Khaz Modan. Beyond his clan, he works directly with fellow field prospectors such as Prospector Ironband and assists Alliance leaders in Southshore by breaking enemy ciphers.",al={"stormpike clan connections","prospector stormpike allies","stormpike league ties"},it="ties",add=true},{q="Why is Prospector Stormpike famous or feared?",a="Prospector Stormpike is renowned for his brilliant knack for deciphering complex, encrypted documents, alongside a notorious, fiery temper. Few scholars possess both his sharp cryptanalytic mind and his volcanic lack of patience for anyone wasting his time.",al={"stormpike reputation","why is prospector stormpike known","stormpike hot temper"},it="fame",add=true}},ang={["race:Dwarf"]="Stormpike embodies the driven, no-nonsense spirit of the Explorers' League, treating ancient research and logistics as matters of utmost dwarven pride.",["faction:Alliance"]="Beyond excavation work, Stormpike's knack for cryptography aids Alliance operations in northern lands against shadowy human cults like the Argus Wake."},kw={"argus wake","explorers league","hall of explorers","ironforge","joren ironband","library","prospector stormpike","stormpike clan"},rel={"subzone:library-ironforge","subzone:hall-of-explorers","zone:ironforge","quest:301","quest:302","subzone:southshore","topic:dwarf"},src={"Prospector Stormpike"}}
E["npc:roetten-stonehammer"] = {t="npc",n="Roetten Stonehammer",z="ironforge",s="Roetten Stonehammer is an enterprising dwarf found wandering the Library in Ironforge's Hall of Explorers. Representing the interests of Reclaimers Inc., he organizes expeditions and recruits adventurers to handle salvage operations in distant lands like Desolace.",h="Roetten Stonehammer is an enterprising dwarf found wandering the Library in Ironforge's Hall of Explorers.",sec={{t="Business in the Library",b="Amid the ancient tomes and dust of the Hall of Explorers' Library, Roetten Stonehammer keeps his eye on matters of practical recovery. Operating on behalf of Reclaimers Inc., Roetten connects daring mercenaries with lucrative salvage contracts across Kalimdor. Rather than digging purely for historical curiosity, his associates look to reclaim valuable cargo, wreckage, and rare reagents from perilous frontiers like the rugged wastes of Desolace.",sp=0}},faq={{q="Who is Roetten Stonehammer?",a="Roetten Stonehammer is a dwarf quest giver stationed in the Library of the Hall of Explorers in Ironforge. He coordinates operations and scouts talent for Reclaimers Inc., directing adventurers toward high-risk recovery contracts abroad.",al={"who is roetten","who is roetten stonehammer","roetten stonehammer lore"},it="identity"},{q="What is Reclaimers Inc.?",a="Reclaimers Inc. is an enterprise focused on salvaging lost shipments, gathering rare reagents, and investigating valuable wrecks in hazardous, untamed territories such as the shores and ruins of Desolace.",al={"what is reclaimers inc","reclaimers inc","reclaimers business"},it="ties"},{q="Where does Roetten send adventurers?",a="Roetten directs capable travelers across the sea to Desolace in western Kalimdor, where his partners look into shipwreck salvage and reagent collection along the rugged coastline and barren wilderness.",al={"roetten stonehammer quests","where does roetten send you","reclaimers business in desolace"},gp=true},{q="Whose side is Roetten Stonehammer on?",a="Roetten Stonehammer is allied with Ironforge and the Alliance, operating openly within the Hall of Explorers. His business ventures, particularly on behalf of Reclaimers Inc., serve Alliance interests by hiring dependable travelers to recover lost assets and supplies in distant, hazardous lands.",al={"roetten stonehammer alliance or horde","who does roetten stonehammer serve","roetten stonehammer faction"},it="side",add=true},{q="What does Roetten Stonehammer want?",a="Roetten is seeking capable adventurers to assist with overseas salvage and recovery operations for Reclaimers Inc. He directs hired help toward dangerous wildernesses like the barren shores of Desolace, aiming to secure salvage from lost shipments and gather exotic reagents necessary for his associates' work.",al={"what is roetten stonehammer looking for","roetten stonehammer motive","why does roetten stonehammer need help"},it="wants",add=true},{q="Why is Roetten Stonehammer here?",a="You can find Roetten wandering the grand Library within Ironforge's Hall of Explorers. He bases himself here to consult ancient archives, stay in close contact with fellow scholars and prospectors, and recruit daring explorers passing through the dwarven capital.",al={"why is roetten in ironforge","what is roetten doing in hall of explorers","roetten stonehammer library"},it="why_here",add=true}},ang={["race:Dwarf"]="For dwarves browsing the grand archives of Ironforge, Roetten proves that archaeological curiosity often pairs hand-in-hand with shrewd commercial salvage.",["faction:Alliance"]="Roetten serves as a key Alliance liaison in Ironforge for expeditions crossing the sea to the contested, barren wilds of Kalimdor's Desolace."},kw={"desolace","hall of explorers","ironforge","library","reclaimers inc","roetten stonehammer","salvage"},rel={"subzone:library-ironforge","subzone:hall-of-explorers","zone:ironforge","quest:1453","zone:desolace","topic:dwarf"},src={"Roetten Stonehammer"}}
E["npc:royal-historian-archesonus"] = {t="npc",n="Royal Historian Archesonus",z="ironforge",s="Royal Historian Archesonus is a dwarven scholar serving King Magni Bronzebeard within Ironforge's High Seat. Renowned for her scholarly works documenting recent catastrophes in the northern human kingdoms, she also directs research into ancient dwarven tragedies, notably the scorched remains of the Dark Iron kingdom.",h="Royal Historian Archesonus is a dwarven scholar serving King Magni Bronzebeard within Ironforge's High Seat.",sec={{t="Chronicler of Catastrophe",b="Stationed steps from King Magni Bronzebeard's throne in the High Seat, Royal Historian Archesonus maintains historical records on behalf of the Ironforge crown. Her academic gaze extends well beyond the Khaz Modan mountains. She authored 'The Fall of Lordaeron and the Scouring of the Eastweald' as well as 'On Plagues, Curses, and Blights,' tracking the horrific collapse of humanity's northern realm under the Scourge. Rather than hiding from dark histories, Archesonus approaches disasters methodically, seeking to record the truth of ruinous magic and political collapse.",sp=0},{t="The Ashes of Thaurissan",b="In addition to her texts on Lordaeron, Archesonus oversees inquiries into the War of the Three Hammers and the catastrophic fall of Emperor Thaurissan. Seeking recovered relics and charred tablets from the Burning Steppes, she enlists adventurers to search the Smoldering Ruins of Thaurissan. For Archesonus, understanding the cataclysm that rent the Redridge Mountains and bound the Dark Iron clan to the Firelord is vital statecraft—ensuring the Bronzebeard kingdom remembers exactly what sorcery and desperation can unleash.",sp=0}},faq={{q="Where can I find Royal Historian Archesonus?",a="Royal Historian Archesonus is located in the High Seat of Ironforge, just near King Magni Bronzebeard's throne room.",al={"archesonus location","where is royal historian archesonus","archesonus ironforge"},it="place",gp=true},{q="What books did Royal Historian Archesonus write?",a="She is the author of 'The Fall of Lordaeron and the Scouring of the Eastweald' and 'On Plagues, Curses, and Blights,' documenting the downfall of the human north and the necrotic afflictions spread by the Scourge.",al={"archesonus books","what did archesonus write","archesonus lore books"}},{q="Why is Archesonus interested in the Ruins of Thaurissan?",a="She studies ancient dwarven history and sends scouts into the Burning Steppes to recover lost relics from the Ruins of Thaurissan, piecing together the catastrophe that destroyed the ancient Dark Iron capital.",al={"archesonus thaurissan quest","why does she want ruins of thaurissan","smoldering ruins of thaurissan"},it="wants"},{q="What is her role in Ironforge?",a="As the official Royal Historian, she acts as chief chronicler and archivist for King Magni Bronzebeard, compiling records on both dwarven antiquity and broader world events threatening the Alliance.",al={"archesonus title","what does royal historian do","who is archesonus"},it="identity"},{q="Whose side is Royal Historian Archesonus on?",a="Royal Historian Archesonus serves King Magni Bronzebeard and the Kingdom of Ironforge, firmly aligning her with the Alliance. Stationed directly within the High Seat, her scholarship and archival research support the royal court's understanding of ancient dwarven history, neighboring lands, and the lingering threats to their realm.",al={"archesonus faction","who does archesonus serve","is archesonus alliance"},it="side",add=true},{q="Why is Royal Historian Archesonus in the High Seat?",a="Archesonus stays in the High Seat because it serves as the center of government for Ironforge and the seat of King Magni Bronzebeard. As the royal historian, she conducts her archival studies alongside the dwarven leadership, where she can advise the throne and commission adventurers to uncover relics and forgotten histories.",al={"why is archesonus in the high seat","archesonus location why","why is royal historian archesonus here"},it="why_here",add=true},{q="Who is Royal Historian Archesonus tied to?",a="Archesonus is tied directly to King Magni Bronzebeard's royal court in Ironforge. Her scholarly position places her among the monarch's trusted advisers and record-keepers, documenting major catastrophes across the Eastern Kingdoms and seeking physical evidence from ancient ruins like those left by the Dark Iron clan.",al={"archesonus ties","who does archesonus work for","archesonus connections"},it="ties",add=true}},ang={["race:Dwarf"]="Archesonus curates the official memory of your people, preserving painful lessons from the War of the Three Hammers so the Bronzebeard clan does not repeat the hubris of the Dark Irons.",["faction:Alliance"]="Her academic works preserve the grim testimony of Lordaeron's fall, ensuring southern allies understand the nature of the plague and the forces that broke humanity's northern kingdoms."},kw={"archesonus","high seat","historian","ironforge","lordaeron","royal historian archesonus","thaurissan"},rel={"zone:ironforge","subzone:high-seat","subzone:ruins-of-thaurissan","topic:lordaeron","topic:dwarf"},src={"Royal Historian Archesonus"}}
E["npc:tiza-battleforge"] = {t="npc",n="Tiza Battleforge",z="ironforge",s="Tiza Battleforge is a veteran dwarven paladin of the Knights of the Silver Hand stationed within Ironforge's Hall of Mysteries. Renowned for her steadfast devotion and insight, she guides young dwarven paladins along the path of virtue, charity, and self-sacrifice. Through study of the sacred texts and trials in the field, she tests whether initiates are truly ready to wield the Light's gift of resurrection.",h="Tiza Battleforge is a veteran dwarven paladin of the Knights of the Silver Hand stationed within Ironforge's...",sec={{t="Mentor of the Mystic Ward",b="Within the serene chambers of the Hall of Mysteries in Ironforge, Tiza Battleforge stands as one of the most respected dwarven paladins of the Knights of the Silver Hand. Initiates across the Alliance—directed by tutors such as Brandur Ironhammer in Ironforge, Azar Stronghammer in Dun Morogh, and Lord Grayson Shadowbreaker in Stormwind—are sent to her to advance their spiritual education. Tiza believes that the Holy Light demands more than martial skill; it requires humble service, compassion, and unwavering fortitude against the encroaching darkness of the Scourge and other threats.",sp=0},{t="The Trials of Divinity",b="When young paladins arrive seeking deeper mysteries, Tiza presents them with the Tome of Divinity. Once the text has been studied, she dispatches them to perform tangible acts of selfless charity, starting by aiding those in humble need like John Turner. She then challenges initiates to put their faith and prowess on the line to aid her husband, Muiredon Battleforge, against the regional threat of the Dark Iron dwarves. Those who conquer these tests and revive fallen allies with the Symbol of Life are deemed worthy by Tiza to wield the sacred art of resurrection.",sp=1}},faq={{q="Who is Tiza Battleforge?",a="Tiza Battleforge is an esteemed dwarven paladin belonging to the Knights of the Silver Hand. Located in the Hall of Mysteries within Ironforge, she tests and mentors dwarven paladins who are seeking to deepen their bond with the Holy Light.",al={"who is tiza","tiza battleforge lore","paladin trainer tiza"},it="identity"},{q="Where can I find Tiza Battleforge?",a="She is located in the Hall of Mysteries, the center of spiritual and arcane learning situated in the Mystic Ward of Ironforge.",al={"tiza location","where is tiza battleforge","hall of mysteries paladin trainer"},gp=true},{q="What is the Tome of Divinity she gives to paladins?",a="The Tome of Divinity is a sacred instructional text containing the core virtues and teachings of the Holy Light. Tiza gives it to paladins so they may study its lessons before embarking on practical trials of charity, courage, and mercy.",al={"tome of divinity tiza","tiza book quest","what is tome of divinity"}},{q="Why does Tiza send paladins to help her husband Muiredon?",a="Her husband, Muiredon Battleforge, faces hostile threats from the Dark Iron dwarves while trying to assist his companion Narm Faulk. Tiza uses this crisis to test an initiate's combat bravery and their readiness to use the Symbol of Life to bring fallen comrades back from the brink of death.",al={"tiza husband quest","muiredon battleforge connection","why help muiredon"},it="motive"},{q="What ability does Tiza teach worthy paladins?",a="Upon completing her trials of charity and rescuing Muiredon's fallen comrade, Tiza grants the initiate the power of Redemption, the paladin's sacred rite of resurrection.",al={"tiza paladin spell","what spell does tiza teach","resurrection paladin trainer ironforge"},gp=true},{q="What is her connection to Brandur Ironhammer?",a="Brandur Ironhammer is a fellow dwarven paladin trainer stationed alongside her in Ironforge's Hall of Mysteries. Tiza once candidly pointed out to Brandur that his jealousy was a spiritual weakness, prompting him to swear to her that he would strive to overcome it.",al={"tiza and brandur","brandur ironhammer tiza","brandur jealousy"},it="ties"},{q="Whose side is Tiza Battleforge on?",a="Tiza stands proudly with the Alliance, the kingdom of Ironforge, and the Knights of the Silver Hand. As a devout paladin, her ultimate allegiance is to the Holy Light and the defense of Azeroth against evils such as the Scourge and the treacherous Dark Iron dwarves.",al={"tiza battleforge faction","who does tiza serve","tiza battleforge alliance"},it="side",add=true},{q="What does Tiza Battleforge want?",a="Tiza seeks to cultivate true virtue, charity, and steadfast faith in novice paladins. Beyond testing their martial might and devotion through sacred trials, she gathers intelligence on local dangers—such as Dark Iron incursions—to warn the city council and keep Ironforge secure.",al={"tiza battleforge goal","what does tiza want","tiza motive"},it="wants",add=true},{q="Why is Tiza Battleforge here in the Hall of Mysteries?",a="She resides in the Hall of Mysteries within Ironforge's Mystic Ward to guide aspiring dwarven paladins. Operating at the heart of the city's holy order, she mentors recruits sent by Alliance commanders, testing their selflessness and dedication to the Silver Hand before initiating them into higher mysteries of the Light.",al={"why is tiza in ironforge","tiza battleforge location reason","why is tiza here"},it="why_here",add=true},{q="Why is Tiza Battleforge respected among the dwarves?",a="Tiza is known as one of the most respected paladins in Ironforge. Seasoned veterans across the Alliance, from Stormwind's Lord Grayson Shadowbreaker to local paladin trainers, hold her wisdom in high esteem and trust her judgment implicitly to test the moral fiber of new recruits.",al={"tiza battleforge reputation","is tiza battleforge famous","tiza respect"},it="fame",add=true}},ang={["class:Paladin"]="For dwarven paladins, Tiza Battleforge is a pivotal mentor who tests your worthiness through the Tome of Divinity and entrusts you with the power to resurrect fallen allies.",["race:Dwarf"]="Tiza represents the deep integration of the Holy Light within dwarven culture and the Silver Hand, guiding Khaz Modan's defenders against threats like the Dark Iron clan.",["faction:Alliance"]="Working closely with mentors from Stormwind to Kharanos, Tiza ensures the Silver Hand maintains unified standards of virtue and martial readiness across all Alliance lands."},kw={"dwarf","hall of mysteries","ironforge","muiredon battleforge","mystic ward","paladin","redemption","silver hand","tiza battleforge","tome of divinity"},rel={"subzone:hall-of-mysteries","zone:ironforge","quest:1641","quest:2997","npc:brandur-ironhammer","npc:azar-stronghammer","npc:lord-grayson-shadowbreaker","topic:knights-of-the-silver-hand"},src={"Tiza Battleforge"}}
E["quest:1453"] = {t="quest",n="Reclaimers' Business in Desolace",z="ironforge",s="Reclaimers' Business in Desolace is an Alliance breadcrumb quest directing adventurers from Ironforge out to the harsh badlands of Desolace. Issued by Roetten Stonehammer, it sends recruits across the sea to meet Kreldig Ungor at Nijel's Point to assist the Reclaimers in recovering lost treasures and relics for a price.",h="Reclaimers' Business in Desolace is an Alliance breadcrumb quest directing adventurers from Ironforge out to...",sec={{t="A Call to the Wasteland",b="While Ironforge bustles with tradesfolk and dwarven affairs, distant Kalimdor remains an untamed frontier. Roetten Stonehammer acts as an urban liaison for the Reclaimers, an enterprising group looking to capitalize on forgotten ruins and barren lands. He recruits eager adventurers passing through the great mountain city, warning them that Desolace is an atrocious expanse overrun by warring centaur clans, yet ripe with profitable opportunity for those brave enough to make the journey.",sp=0},{t="Nijel's Point and the Reclaimers",b="The road leads far west through the Stonetalon Mountains into northern Desolace, where the Alliance maintains Nijel's Point—a fortified haven tucked away high in the cliffs. There, Kreldig Ungor welcomes fresh hands into the fold. The Reclaimers operate on a straightforward premise: across the war-torn world, people are constantly losing heirlooms, magical artifacts, and family treasures. With enough grit and the right price, Kreldig and his associates ensure those lost valuables are reclaimed from the wild.",sp=0}},faq={{q="Who gives this quest?",a="Roetten Stonehammer offers this quest in Ironforge. He directs adventurers seeking honest, lucrative work out to Kalimdor to connect with his associate.",al={"quest giver","who starts reclaimers business","roetten stonehammer location"},it="identity"},{q="Where is Nijel's Point?",a="Nijel's Point is situated in the northeastern crags of Desolace. When traveling south out of the Stonetalon Mountains into Desolace, follow the cliffs eastward until you locate the torchlit mountain path winding up into the Alliance outpost.",al={"find nijels point","how to get to nijels point","nijels point location"},it="place",gp=true},{q="Who are the Reclaimers?",a="The Reclaimers are an enterprising venture headed by dwarven operatives like Kreldig Ungor. They specialize in recovering lost heirlooms, rare antiquities, and magical relics from dangerous corners of the world on behalf of paying clients.",al={"what are reclaimers","reclaimers faction","reclaimers lore"},it="people"},{q="What threats await in Desolace?",a="Desolace is an arid, grim wasteland dominated by warring centaur tribes, undead remnants, and hostile wildlife. It presents a harsh testing ground for seasoned travelers venturing beyond Stonetalon.",al={"desolace dangers","what is in desolace"},it="threat"},{q="Who is Kreldig Ungor?",a="Kreldig Ungor is a dwarf stationed at Nijel's Point in Desolace. He coordinates salvage operations and relic hunts in the region, enlisting capable adventurers to brave the ruins and centaur camps.",al={"kreldig ungor lore","who is kreldig"},it="target"},{q="Is this quest required to quest in Desolace?",a="No, it is an optional breadcrumb quest. You can travel directly to Nijel's Point on your own, but speaking with Roetten Stonehammer provides convenient background and direction before setting out.",al={"do i need this quest","is reclaimers business required"},gp=true},{q="Why does Roetten Stonehammer send you to Desolace?",a="Roetten Stonehammer acts as a liaison for the Reclaimers back in the safety of Ironforge. His associates out at Nijel's Point are facing dangerous ground in Desolace and need steady, capable hands to handle contracts. By steering able adventurers like you toward Kreldig Ungor, Roetten ensures their treasure-hunting outfit stays staffed and profitable despite the hostile centaur lands.",al={"why send to desolace","roetten stonehammer motive","why help kreldig ungor"},it="motive",add=true},{q="Why does Roetten Stonehammer recruit adventurers instead of going himself?",a="Operating a salvage outfit across continents requires eyes and ears in major cities just as much as muscle in the field. Roetten remains in Ironforge to direct incoming talent and broker opportunities, leaving the grueling trek through the Stonetalon Mountains and the perils of Desolace to hardened travelers ready to risk their necks for coin.",al={"why does roetten need me","why not go himself","why recruit adventurers"},it="why_me",add=true}},ang={["faction:Alliance"]="Nijel's Point represents the primary Alliance sanctuary in central Kalimdor's western wastes, serving as a staging ground surrounded by hostile centaur clans.",["race:Dwarf"]="Whether through the Explorers' Guild or independent salvage groups like the Reclaimers, dwarven enterprise reaches into even the bleakest corners of Kalimdor."},kw={"centaur","desolace","ironforge","kreldig ungor","nijel's point","reclaimers","roetten stonehammer","stonetalon"},rel={"npc:roetten-stonehammer","npc:kreldig-ungor","subzone:nijel-s-point","zone:desolace","zone:stonetalon","topic:centaur"},m={start="Roetten Stonehammer",["end"]="Kreldig Ungor",faction="Alliance",id=1453},src={"Reclaimers' Business in Desolace"}}
E["quest:1645"] = {t="quest",n="The Tome of Divinity",z="ironforge",s="The Tome of Divinity marks an essential milestone in a dwarven paladin's training within Ironforge. Bestowed by Tiza Battleforge in the Hall of Mysteries, this holy text begins a trials-based journey meant to test an initiate's devotion to the Light and their readiness to defend Azeroth against dark forces like the Scourge.",h="The Tome of Divinity marks an essential milestone in a dwarven paladin's training within Ironforge.",sec={{t="A Calling to Virtue",b="Paladin mentors across the eastern kingdoms direct promising initiates to Ironforge's Hall of Mysteries once they demonstrate mastery of martial and spiritual fundamentals. Under the watchful eye of Tiza Battleforge, young dwarven paladins are introduced to the solemn principles that separate a simple warrior from an ordained champion of the Holy Light. Taking up this task represents a conscious pledge toward lifelong self-sacrifice, duty, and spiritual discipline.",sp=0},{t="The Book of Divinity",b="Accepting this charge places a Book of Divinity into the hands of the novice. This text outlines the expectations, virtues, and spiritual tenets required to wield sacred energies effectively against wicked threats. Studying its teachings is merely the introductory step; the scripture serves as a foundational guide before the initiate is sent forth across Khaz Modan and beyond to embody its lessons in real acts of faith.",sp=0}},faq={{q="What is the purpose of the Tome of Divinity quest?",a="This quest is the doorway to advanced paladin training for dwarven champions. By speaking with Tiza Battleforge, initiates receive their holy text and embark on a series of trials designed to prove their virtue and unlock the ability to call fallen allies back from death.",al={"what does tome of divinity do","tome of divinity purpose","why do this quest"},it="purpose"},{q="Who is Tiza Battleforge?",a="Tiza Battleforge is a prominent paladin trainer residing in the Hall of Mysteries in Ironforge. She is tasked with guiding dwarven paladins toward greater virtue, testing their devotion to the Light, and preparing them to confront threats such as the Scourge.",al={"tiza battleforge","who is the paladin trainer in ironforge","who gives tome of divinity"},it="identity"},{q="Why must initiates study the Book of Divinity?",a="The Book of Divinity contains core teachings regarding the duties and virtues demanded by the Holy Light. Studying it ensures that an initiate understands the spiritual discipline required before wielding miraculous sacred powers.",al={"what is the book of divinity","why read the book","book of divinity lore"},it="item"},{q="What major threats are dwarven paladins preparing to fight?",a="As outlined by Tiza Battleforge, the paladins dedicate themselves to defending Azeroth from dangerous perils across the land, with particular vigilance directed toward the encroaching undead menace of the Scourge.",al={"who do paladins fight","why train paladins ironforge","paladin purpose"},it="threat"},{q="Where does this training take place?",a="The initiation begins in the Hall of Mysteries, the quiet sanctuary nestled in the northern quarters of Ironforge where scholars, priests, mages, and paladins gather in prayer and study.",al={"where is tiza battleforge","ironforge paladin location","hall of mysteries paladin"},it="place"},{q="What comes next after receiving the book?",a="Once the initiate reads and contemplates the Book of Divinity, Tiza Battleforge delivers practical trials that require the paladin to demonstrate compassion, duty, and sacrifice outside the safety of the city gates.",al={"what happens next","next quest tome of divinity","where do i go after getting the book"},it="next_step"},{q="Why does Tiza Battleforge want you to study the Tome of Divinity?",a="Tiza Battleforge oversees the training of paladins within Ironforge. She views it as her solemn duty to guide initiates toward true virtue and devotion to the Holy Light. With the looming menace of the Scourge and other perils threatening Azeroth, she seeks to ensure that every defender she trains understands their spiritual responsibilities and is prepared to wield greater holy powers in defense of the realm.",al={"why does tiza want this done","tiza battleforge motive","why study tome of divinity"},it="motive",add=true},{q="Why does Tiza Battleforge ask you to undertake this trial instead of handling it herself?",a="Tiza cannot walk the path of virtue for you. As an instructor of the Holy Light, her responsibility is to guide and teach, but the devotion, understanding, and inner strength required of a true paladin must come from within the initiate. To earn the blessings and abilities of the Light, you must personally prove your capability and dedication through study and service.",al={"why me tome of divinity","why doesn't tiza do it","why must i study the tome"},it="why_me",add=true}},ang={["class:Paladin"]="This rite of passage bridges early martial instruction with the deeper virtues of the Holy Light, setting initiates on the path to channel the power of redemption and resurrection.",["race:Dwarf"]="For dwarven champions, taking the Tome of Divinity reinforces the alliance of faith forged between the Bronzebeard kingdom and the human knights of the Silver Hand."},kw={"book of divinity","hall of mysteries","holy light","ironforge","paladin","redemption","scourge","tiza battleforge","tome of divinity"},rel={"npc:tiza-battleforge","zone:ironforge","topic:light","topic:scourge"},m={start="Tiza Battleforge",level="12",faction="Alliance",id=1645},src={"The Tome of Divinity (dwarf 1)"}}
E["quest:1679"] = {t="quest",n="Muren Stormpike",z="ironforge",s="Muren Stormpike is an introductory quest for developing Alliance warriors, given once a recruit proves their basic mettle in Dun Morogh. Directed by Granis Swiftaxe in Kharanos, the young fighter travels into the mountain city of Ironforge to seek formal instruction in martial discipline. Meeting Muren marks the beginning of deeper training in tactical stances and dwarven military traditions.",h="Muren Stormpike is an introductory quest for developing Alliance warriors, given once a recruit proves their...",sec={{t="A Summons to Ironforge",b="After cutting their teeth against local threats in the snowy valleys of Dun Morogh, warrior novices catch the eye of Granis Swiftaxe in Kharanos. Recognizing that crude skirmishing can only take a brawler so far, Swiftaxe sends promising fighters to the heart of dwarven martial prowess: the Military Ward of Ironforge. There, within the echoing halls of the forge-city, senior combatants oversee the formal schooling of those bound for battle.",sp=0},{t="The Master of Arms",b="Upon reaching the Hall of Arms, recruits are introduced to Muren Stormpike, a seasoned veteran of a storied dwarven clan. Muren cares little for tavern tales and demands proof that his new charges can withstand real combat. Reporting to him opens the pathway toward mastering the defensive arts, learning to absorb and control enemy aggression, and earning well-crafted iron armaments fit for true front-line duty.",sp=0}},faq={{q="Who sends you to find Muren Stormpike?",a="Granis Swiftaxe, the warrior trainer stationed in Kharanos, gives you the quest once you have proven your basic martial capability in Dun Morogh.",al={"who gives muren stormpike quest","where do i get muren stormpike","quest giver muren stormpike"},it="origin"},{q="Where is Muren Stormpike located?",a="Muren Stormpike is located in the Hall of Arms, situated within the Military Ward on the eastern side of Ironforge.",al={"where is muren stormpike","muren stormpike location","how to find muren"},it="place",gp=true},{q="Why is this quest important for warriors?",a="Reporting to Muren initiates advanced warrior training. This leads directly to tasks that unlock the Defensive Stance, teach vital defensive skills like Taunt, and reward a reliable early-career weapon.",al={"what does muren stormpike unlock","why do muren stormpike","muren stormpike rewards"},it="purpose",gp=true},{q="Who is Muren Stormpike?",a="Muren is a veteran combat instructor in Ironforge belonging to the renowned Stormpike clan, an influential dwarven family known for its fierce warriors and expeditionary engineers.",al={"who is muren","muren stormpike lore","is muren stormpike clan"},it="identity"},{q="Can any class take this quest?",a="No. This quest is strictly reserved for warrior novices ready to undergo specialized martial instruction.",al={"can non warriors do muren stormpike","is muren stormpike warrior only","muren stormpike classes"},gp=true},{q="What happens after reporting to Muren?",a="After arriving and speaking with Muren, he immediately tests your resolve by directing you toward a combat trial, beginning with the quest to confront Vejrek.",al={"what is next after muren stormpike","next quest after muren stormpike","vejrek quest"},it="next_step",gp=true},{q="Why does Granis Swiftaxe send you to Muren Stormpike?",a="Granis Swiftaxe sees real promise in your fighting ability, but Kharanos can only offer you the basics. To advance your martial training and learn what it truly means to be a warrior, he refers you to Muren Stormpike, a seasoned veteran stationed at the Hall of Arms in Ironforge.",al={"granis swiftaxe motive","why send to muren","why speak to muren stormpike"},it="motive",add=true}},ang={["class:Warrior"]="This summons marks your rite of passage from a scrappy recruit into a disciplined soldier capable of holding the line and protecting allies.",["race:Dwarf"]="For dwarven fighters, reporting to the Hall of Arms connects you directly with the storied martial lineage and tactical discipline of the mountain clans.",["race:Gnome"]="Gnomish warriors, having evacuated to Dun Morogh following the fall of Gnomeregan, rely on Ironforge's Hall of Arms to master traditional heavy frontline combat."},kw={"defensive stance","granis swiftaxe","hall of arms","ironforge","kharanos","military ward","muren stormpike","warrior trainer"},rel={"npc:granis-swiftaxe","zone:ironforge","subzone:military-ward","subzone:kharanos","zone:dunmorogh","topic:dwarf"},m={start="Granis Swiftaxe",["end"]="Muren Stormpike",level="10",faction="Alliance",id=1679},src={"Muren Stormpike (quest)"}}
E["quest:1704"] = {t="quest",n="Klockmort Spannerspan",z="ironforge",s="This quest sends an adventurer from Stormwind to Ironforge to deliver trade secrets to Klockmort Spannerspan in Tinkertown. After mastering the art of fire-hardened armor, the dwarf smith Furen Longbeard eagerly shares his metallurgical discoveries with his gnomish colleague. It serves as an essential link in the journey of an aspiring warrior looking to test exotic crafting methods.",h="This quest sends an adventurer from Stormwind to Ironforge to deliver trade secrets to Klockmort Spannerspan...",sec={{t="A Colleague in Tinkertown",b="Having successfully forged a set of fire-hardened mail, Furen Longbeard compiles his detailed findings to pass along to a fellow craftsman. Rather than hoarding his newly discovered techniques, Furen trusts you to carry his notes from Stormwind to Ironforge and into the clatter and steam of Tinkertown, where the gnomish blacksmith Klockmort Spannerspan plies his trade.",sp=0},{t="Gnomish Excitement",b="Gnome blacksmiths are relatively rare compared to their dwarven hosts, and Klockmort is enthusiastic about pushing the boundaries of traditional metalwork. Upon inspecting Furen's notes, Klockmort becomes wildly excited over the breakthrough, eager to integrate these fiery techniques into his own exotic projects.",sp=0}},faq={{q="Who is Klockmort Spannerspan?",a="Klockmort Spannerspan is a gnomish blacksmith who works in Tinkertown within the subterranean city of Ironforge. He collaborates closely with dwarven smiths like Furen Longbeard on advanced metalworking techniques.",al={"klockmort spannerspan","who is klockmort","gnome blacksmith ironforge"},it="identity"},{q="Why does Furen Longbeard send you to Klockmort?",a="Furen recorded notes detailing the breakthrough techniques he discovered while crafting fire-hardened mail. Knowing Klockmort's passion for inventive blacksmithing, Furen sends you to deliver these findings so the gnome can experiment with them.",al={"why deliver notes","furen's notes","furen longbeard klockmort"},it="motive"},{q="Where can I find Klockmort Spannerspan?",a="Klockmort Spannerspan is located in Tinkertown, the gnome-dominated district in the eastern sector of Ironforge, surrounded by workbenches and machinery.",al={"klockmort location","where is klockmort","klockmort ironforge"},gp=true},{q="What happens after giving Klockmort the notes?",a="Enthralled by Furen's breakthrough, Klockmort immediately begins planning his own metallurgical projects, setting you on a path to gather unusual materials such as iron coral.",al={"quest continuation","what next after klockmort","iron coral quest"},sp=1,it="next_step"},{q="Is this quest limited to warriors?",a="Yes. This delivery is part of the dedicated armor-crafting chain available exclusively to Alliance warriors training under veteran weapon and armor masters.",al={"warrior only","can anyone do this quest","class requirement"},gp=true},{q="Why does Klockmort say he cannot tell day from night?",a="Ironforge is an entirely subterranean city carved deep into the heart of Mount Dun Morogh. Down in Tinkertown under stone vaults and glowing lamps, craftsmen have no view of the sun or sky.",al={"klockmort day night dialogue","way down here dialogue"}}},ang={["class:Warrior"]="Your journey to craft durable battle gear leads you from dwarven hearths directly into gnomish innovation, earning you the attention of Tinkertown's finest.",["race:Gnome"]="Klockmort represents the ingenious crossover between classic dwarven metallurgy and inventive gnomish experimentation in Tinkertown.",["profession:Blacksmithing"]="Furen's notes represent the collaborative exchange of cutting-edge smithing techniques between the master artisans of Ironforge."},kw={"blacksmith","fire hardened","furen","ironforge","klockmort","longbeard","notes","spannerspan","tinkertown"},rel={"quest:1701","quest:1708","npc:furen-longbeard","zone:ironforge"},m={start="Furen Longbeard",["end"]="Klockmort Spannerspan",level="28",faction="Alliance",id=1704},src={"Klockmort Spannerspan (quest)"}}
E["quest:1708"] = {t="quest",n="Iron Coral",z="ironforge",s="Iron Coral is an Alliance quest given by the gnome blacksmith Klockmort Spannerspan in Tinker Town, Ironforge. Eager to test newly shared smithing methods on a custom suit of armor, Klockmort sends you to dive for rare searing coral along the coast of the Wetlands. Completing his request allows him to fuse gnomish ingenuity with dwarven craftsmanship.",h="Iron Coral is an Alliance quest given by the gnome blacksmith Klockmort Spannerspan in Tinker Town, Ironforge.",sec={{t="A Fusion of Crafts",b="After exchanging insights with the master dwarven smith Furen Longbeard, Klockmort Spannerspan is bursting with inspiration. The eccentric gnome blacksmith wants to combine Furen's metallurgy with his own tinkering ideas to craft an exceptionally resilient suit of armor. To pull off this daring metallurgical experiment, standard mountain ores will not suffice; Klockmort requires an unusual, naturally hardened marine element known as searing coral.",sp=0},{t="Diving the Wetlands Shore",b="Searing coral is a volatile, tough oceanic deposit found in only one specific region: submerged off the coast south of Menethil Harbor in the Wetlands. Retrieving twenty clusters means wading through treacherous marshland waters, braving native aquatic predators, and hauling the dripping harvests back to Ironforge. For Klockmort, however, the prize is well worth the damp excursion, as he intends to smelt and hammer the coral directly into his experimental plating.",sp=0}},faq={{q="Who is Klockmort Spannerspan?",a="Klockmort Spannerspan is a skilled gnome blacksmith residing in Tinker Town within the mountain city of Ironforge. Passionate about mechanical tinkering and cutting-edge metallurgy, he collaborates closely with dwarven artisans to invent new armor-crafting methods.",al={"klockmort","who gives iron coral","quest giver iron coral"},it="identity"},{q="What is searing coral?",a="Searing coral is a rare oceanic growth harvested from the seabed south of Menethil Harbor in the Wetlands. It possesses unique chemical and physical qualities that allow an inventive artisan to smelt and hammer it into heavy plate reinforcement.",al={"searing coral lore","what is searing coral used for"},it="item"},{q="Where do I find the searing coral?",a="The coral beds grow exclusively underwater along the ocean shoreline situated directly south of Menethil Harbor in the Wetlands. Divers must look beneath the waves to pry the mineral-rich branches loose.",al={"searing coral location","where is iron coral located","wetlands coral location"},it="place",gp=true},{q="Why does Klockmort need searing coral instead of metal ore?",a="Klockmort is attempting to innovate upon the smithing techniques he learned from the dwarf Furen Longbeard. Rather than relying solely on traditional Ironforge ores, he hopes the unusual properties of searing coral will yield a lighter, significantly more durable finish when smelted.",al={"why coral for armor","coral metallurgy"},it="why_wanted"},{q="How is Furen Longbeard involved in this task?",a="Furen Longbeard previously developed new armor-crafting techniques with your assistance. Grateful for the aid, Furen shared his trade secrets with Klockmort, inspiring the gnome to adapt them into his own protective inventions.",al={"furen connection","furen longbeard iron coral"},it="ties"},{q="What happens after bringing the coral to Klockmort?",a="Once supplied with twenty loads of searing coral, Klockmort immediately sets to work smelting and hammering the substance at his workbench, leading directly to the unveiling of his experimental gear in the quest Klockmort's Creation.",al={"iron coral follow up","next quest iron coral"},sp=1,it="next_step"},{q="Why does Klockmort Spannerspan want the searing coral collected?",a="Klockmort is an enthusiastic gnome inventor eager to experiment. Having learned innovative smithing techniques from Furen Longbeard, he wants to combine Furen's methods with his own engineering know-how to forge an exceptionally tough suit of armor. To craft it, he specifically requires the unique properties of searing coral harvested from the Wetlands coast.",al={"why does klockmort want coral","klockmort motive iron coral","why make iron coral armor"},it="motive",add=true}},ang={["race:Gnome"]="Klockmort's pursuit of strange coastal minerals over standard mined iron reflects typical gnomish inventiveness, always striving to improve upon traditional craftsmanship through experimentation.",["race:Dwarf"]="The experiment is born directly from the metallurgic discoveries of the Ironforge master smith Furen Longbeard, showing the close collaboration between gnomes and dwarves in Tinker Town.",["profession:Blacksmithing"]="Blacksmiths will appreciate the unconventional smelting technique Klockmort attempts, turning harvested oceanic deposits into hardened plating for personal armor.",["profession:Engineering"]="The quest showcases the tinkering philosophy of testing wild material properties to achieve superior defensive utility."},kw={"armor smelting","furen longbeard","iron coral","ironforge","klockmort spannerspan","menethil harbor","searing coral","tinker town","wetlands"},rel={"quest:1704","quest:1709","npc:furen-longbeard","zone:ironforge","zone:wetlands","subzone:menethil-harbor"},m={start="Klockmort Spannerspan",level="29",faction="Alliance",id=1708,ri={"Searing Coral"}},src={"Iron Coral (quest)"}}
E["quest:1709"] = {t="quest",n="Klockmort's Creation",z="ironforge",s="Klockmort's Creation marks the successful forging of a specialized suit of armor in Ironforge's Tinker Town. Utilizing an unconventional technique devised by the master armorsmith Furen Longbeard, the gnome blacksmith Klockmort Spannerspan shapes raw materials into an extraordinarily resilient piece of gear.",h="Klockmort's Creation marks the successful forging of a specialized suit of armor in Ironforge's Tinker Town.",sec={{t="A Fusion of Disciplines",b="Forging heavy armor typically belongs to the great anvils of the Great Forge, but Klockmort Spannerspan operates out of Tinker Town. The creation of this armor represents a collaborative triumph between dwarven metallurgical tradition and gnomish mechanical innovation. By adapting Furen Longbeard's rigorous methods, Klockmort finishes a pair of armored gauntlets engineered to endure punishment that would crush ordinary steel.",sp=0},{t="Unrivaled Resilience",b="According to Klockmort, the resulting armor boasts structural integrity so great that a siege engine could roll directly over it without causing permanent distortion. The secret lies in the peculiar treatment of rare components, proving that combining ancient dwarven forging techniques with gnomish ingenuity yields armor capable of withstanding the fiercest frontline battles.",sp=0}},faq={{q="Who is Klockmort Spannerspan?",a="Klockmort Spannerspan is a skilled gnome blacksmith residing in Tinker Town within Ironforge. He assists with intricate mechanical tasks and works in conjunction with dwarven craftsmen like Furen Longbeard to fashion unique, durable gear.",al={"klockmort","who is klockmort","gnome in tinker town"},it="identity"},{q="Who designed the process to make this armor?",a="The forging process was devised by Furen Longbeard, an accomplished dwarven armorsmith. Klockmort followed Furen's exact methodology to treat the materials and bring the armor to completion.",al={"who made the process","furen longbeard armor","furen method"},it="origin"},{q="Why did a gnome blacksmith make this armor?",a="Klockmort, a gnomish blacksmith, wanted to try Furen Longbeard's new technique on a piece of armor of his own. Because you had helped Furen, he offered you the finished armor in return for gathering the searing coral he needed.",al={"why a gnome","gnome blacksmithing","engineering armor"},it="purpose"},{q="What makes this armor special compared to standard plate?",a="Klockmort claims the completed armor possesses remarkable spring and elasticity alongside rigid durability. He boasts that even if flattened beneath the tracks of a heavy siege engine, the metal would snap right back into its original shape.",al={"how strong is it","siege engine armor","armor durability"},it="power"},{q="Where does this armor fit in the path of a warrior's training?",a="This creation is the culmination of a dedicated series of tasks undertaken by promising Alliance warriors seeking to arm themselves with resilient armor custom-forged by Ironforge's finest minds.",al={"warrior quest armor","why do this quest","warrior reward"}},{q="Where is Klockmort found?",a="Klockmort Spannerspan can be found amidst the workshops, clanking gears, and steam vents of Tinker Town, the gnomish quarter of Ironforge.",al={"klockmort location","where is spannerspan"},it="place",gp=true},{q="Why is Klockmort Spannerspan helping make this armor?",a="Klockmort Spannerspan took on the task to test Furen Longbeard's radical crafting theory. Dwarven smithing rarely relies on precision gnomish engineering, so assembling the gauntlets offered Klockmort a chance to prove that combining Furen's methods with gnomish mechanics could produce a suit resilient enough to survive even a siege engine.",al={"why does klockmort help","klockmort spannerspan motive","why is klockmort forging this"},it="motive",add=true}},ang={["class:Warrior"]="Commissioning these gauntlets is an important milestone for Alliance warriors, providing custom-tempered armor built specifically to endure the crushing blows of frontline combat.",["race:Gnome"]="Klockmort's work demonstrates that gnomish ingenuity has a vital role even in heavy armorsmithing, showing how mechanical precision enhances traditional dwarven crafts.",["profession:Blacksmithing"]="The successful application of Furen Longbeard's formula highlights the value of experimenting with unconventional tempering methods and rare oceanic materials."},kw={"furen longbeard","iron coral","ironforge","klockmort","siege engine","spannerspan","tinker town","warrior armor"},rel={"quest:1708","quest:1704"},m={start="Klockmort Spannerspan",level="30",faction="Alliance",id=1709},src={"Klockmort's Creation"}}
E["quest:1715"] = {t="quest",n="The Slaughtered Lamb",z="ironforge",s="This errand directs novice gnome warlocks out of Ironforge to seek advanced instruction in human lands. With King Magni Bronzebeard keeping a vigilant watch on dark practitioners within the dwarven mountain, mentors must rely on Stormwind's hidden networks to complete their disciples' training.",h="This errand directs novice gnome warlocks out of Ironforge to seek advanced instruction in human lands.",sec={{t="Exile and Scrutiny",b="Before the fall of Gnomeregan, aspiring warlocks in Khaz Modan studied under their own tinker-mages and demonic scholars deep within the techno-city. The disaster that drove the gnomes into exile scattered those institutions. The surviving practitioners found themselves cramped into Ironforge's gloomy, subterranean caverns, operating under the distrustful eye of King Magni Bronzebeard and the dwarven guard. Unable to practice demonic arts openly or cultivate dangerous rituals in such tight quarters, senior instructors like Lago Blackwrench have little choice but to send their students away.",sp=0},{t="The Mage Quarter's Secret Cellar",b="The destination for these expatriate students is the Slaughtered Lamb, an unassuming tavern nestled in Stormwind's Mage Quarter. Beneath its taproom, concealed behind twisting stone passages and descending stairs, lies a subterranean sanctum where human warlocks gather in shadows. Overseen by seasoned summoners like Gakin the Darkbinder, the cove provides the space and dark paraphernalia required to teach novices how to summon and bind minor demons without drawing the immediate wrath of city marshals.",sp=0},{t="Growing Strain in the Shadows",b="While Stormwind's coven welcomes capable hands, the influx of refugee novices creates friction. Human mentors already walk a knife's edge to avoid detection from the city's paladins and authorities. Gakin and his colleagues find their clandestine sanctuary increasingly crowded by practitioners sent south from Khaz Modan. The steady stream of dwarven-mountain traffic risks blowing the lid on their discreet operation, yet neither side possesses an easier alternative.",sp=0}},faq={{q="Why can't gnome warlocks train in Ironforge?",a="King Magni Bronzebeard keeps the practitioners in Ironforge under tight surveillance. With Gnomeregan lost, the displaced warlocks have no private academy of their own, making risky summoning rituals inside the dwarven mountain far too dangerous.",al={"why send to stormwind","ironforge warlock training","why gnomeregan warlock leave"},it="why_here"},{q="Where were Khaz Modan warlocks trained before?",a="In times past, dark practitioners across Khaz Modan trained under the auspices of master warlocks in Gnomeregan. The trogg invasion and radiation poisoning wiped out those institutions, forcing the survivors into Ironforge.",al={"gnomeregan warlock history","past warlock training khaz modan"},it="origin"},{q="Who is Gakin the Darkbinder?",a="Gakin the Darkbinder is a senior human warlock based in the catacombs beneath the Slaughtered Lamb in Stormwind. He instructs apprentices in the binding and summoning of demons, including novice gnomes sent south from Ironforge.",al={"who is gakin","gakin role"},it="identity"},{q="What is the Slaughtered Lamb?",a="The Slaughtered Lamb is a tavern located in the Mage Quarter of Stormwind. While the street-level establishment appears typical, the deep cellar below hides a clandestine enclave of warlocks operating out of sight of city authorities.",al={"slaughtered lamb tavern","where is slaughtered lamb"},it="place"},{q="Why is Gakin frustrated with the newcomers?",a="Gakin is concerned that a massive influx of refugee gnomes will attract unwanted attention to the covert coven in Stormwind. Space and teachers are limited, and too much warlock activity risks exposure to city authorities.",al={"gakin complaining","why is gakin mad"},it="conflict"},{q="Who is Lago Blackwrench?",a="Lago Blackwrench is a gnome warlock trainer residing in the dark alleys of Ironforge. Bitter about Gnomeregan's loss and dwarven scrutiny, he dispatches promising novices to Stormwind to finish their foundational pacts.",al={"lago blackwrench","quest giver slaughtered lamb"},it="identity"},{q="Why does Lago Blackwrench send you to Stormwind?",a="Lago Blackwrench has no choice if you are to advance your demonic craft. Ever since the fall of Gnomeregan drove gnome practitioners into Ironforge, King Magni Bronzebeard has kept a watchful, suspicious eye on dark magic within his mountain stronghold. Unable to operate their own proper training sanctums under dwarven surveillance, Ironforge's exiled warlocks are forced to swallow their pride and dispatch promising novices south to human masters.",al={"why send to stormwind","blackwrench motive","why go to slaughter lamb"},it="motive",add=true}},ang={["class:Warlock"]="This journey marks an essential rite of passage for young Alliance warlocks, introducing them to the covert, underground network that binds practitioners across racial lines.",["race:Gnome"]="The quest highlights the indignity gnomes face in exile, reduced to cramped quarters in Ironforge and forced to rely on human hospitality after losing their own academies in Gnomeregan.",["race:Dwarf"]="The Ironforge authorities have zero patience for demonic dabbling, driving the city's warlock population deep into the shadows and forcing their students elsewhere."},kw={"gakin the darkbinder","gnomeregan","ironforge","lago blackwrench","mage quarter","slaughtered lamb","stormwind","warlock"},rel={"subzone:slaughtered-lamb","npc:gakin-the-darkbinder","subzone:mage-quarter","zone:ironforge","zone:gnomeregan","topic:stormwind-kingdom","topic:gnome"},m={start="Lago Blackwrench",["end"]="Gakin the Darkbinder",level="10",faction="Alliance",id=1715},src={"The Slaughtered Lamb (quest)"}}
E["quest:1717"] = {t="quest",n="Gakin's Summons",z="ironforge",s="A summons delivered to promising Alliance warlocks in Ironforge, directing them south to Stormwind. Gakin the Darkbinder awaits beneath the city's Mage Quarter to oversee their advancement into commanding greater fiends.",h="A summons delivered to promising Alliance warlocks in Ironforge, directing them south to Stormwind.",sec={{t="A Message from the Underground",b="Demonology remains a practice conducted entirely in shadows across Alliance lands. In Ironforge, Lago Blackwrench quietly keeps tabs on wandering practitioners on behalf of the brotherhood in Stormwind. When a warlock shows sufficient mastery over their initial minions, word travels quickly. Lago passes along the directive: drop whatever business keeps you in the snowy mountains of Khaz Modan and report south without delay.",sp=0},{t="Return to the Slaughtered Lamb",b="Deep beneath the cobblestones of Stormwind's Mage Quarter, beneath the tavern known as The Slaughtered Lamb, Gakin the Darkbinder coordinates the development of the city's warlocks. Gakin views every capable student as a valuable, hazardous investment. Receiving his summons marks the threshold of true demonic binding, beginning the trials required to subjugate a succubus from the Twisting Nether.",sp=0}},faq={{q="Who sends me this summons?",a="Lago Blackwrench, a warlock trainer located in Ironforge, delivers the summons on behalf of Gakin the Darkbinder, who leads demonology instruction in Stormwind.",al={"who gives quest","who starts this","lago blackwrench"},it="identity"},{q="Where do I find Gakin the Darkbinder?",a="Gakin resides hidden in the dark, winding catacombs beneath The Slaughtered Lamb, a tavern tucked away in the Mage Quarter of Stormwind.",al={"gakin location","where is gakin","slaughtered lamb location"},it="place",gp=true},{q="Why is Gakin summoning me?",a="You have advanced far enough in your craft to undertake the rituals required to summon and subjugate a succubus, expanding your demonic arsenal.",al={"quest purpose","what is this for","why summoned"},it="purpose"},{q="What happens after I speak to Gakin?",a="Gakin will send you on a quest called Devourer of Souls, dispatching you into dangerous lands to acquire the ritual components needed to conjure and bind a succubus.",al={"next step","what follows this","quest chain"},it="next_step"},{q="Why is a warlock in Ironforge taking orders from Stormwind?",a="Alliance warlocks operate as a discreet, covert network out of necessity. Practitioners across Ironforge and Stormwind maintain contact and direct promising apprentices to Gakin, who possesses specialized ritual equipment and lore beneath the Slaughtered Lamb.",al={"ironforge warlocks","gnome warlocks stormwind","warlock organization"},it="ties"},{q="Can I ignore this summons if I want to stay in Khaz Modan?",a="While you can delay visiting Stormwind, you cannot learn to summon a succubus without completing Gakin's trial, making the journey essential for any aspiring warlock.",al={"is this required","can i skip","do i need to go to stormwind"},gp=true},{q="Why does Lago Blackwrench send you to Stormwind?",a="Lago Blackwrench has explicit instructions from fellow practitioners in Stormwind to watch for promising warlocks traveling through Ironforge. The coven has already invested considerable time and resources into your dark arts, and Lago wants to ensure you do not wander astray or perish before advancing your craft under Gakin the Darkbinder's tutelage.",al={"why does lago want this done","lago blackwrench motive","why does lago send me to stormwind"},it="motive",add=true}},ang={["class:Warlock"]="This breadcrumb quest directs warlocks in Ironforge back to Stormwind to begin the multi-part ritual questline to bind their succubus minion.",["faction:Alliance"]="Shows how the covert warlock network maintains communication across Alliance capitals despite practicing demonology in secret away from civilian eyes.",["race:Gnome"]="Gnome warlocks training under Lago Blackwrench in Ironforge are directed to Stormwind's subterranean network to access deeper demonic teachings."},kw={"gakin","gakin's summons","ironforge","lago blackwrench","mage quarter","slaughtered lamb","succubus","warlock"},rel={"npc:gakin-the-darkbinder","quest:1472","quest:1471","quest:1738","subzone:mage-quarter","topic:stormwind-kingdom","quest:1685"},m={start="Lago Blackwrench",["end"]="Gakin the Darkbinder",level="20",faction="Alliance",id=1717},src={"Gakin's Summons (Succubus)"}}
E["quest:1793"] = {t="quest",n="The Tome of Valor",z="ironforge",s="The Tome of Valor is a foundational trial for Alliance paladins coming into their own. Directed by paladin mentors in Stormwind and Ironforge, initiates are challenged to prove that their courage and devotion to protecting the innocent match their martial prowess.",h="The Tome of Valor is a foundational trial for Alliance paladins coming into their own.",sec={{t="The Measure of a Paladin",b="To wield the Holy Light in battle requires more than heavy armor and martial discipline. As young paladins reach greater heights in their training, instructors in the Cathedral of Light and the Hall of Mysteries demand proof of their inner resolve. The lessons of the Tome of Valor test an initiate's readiness to confront terrifying evils—from dragons to demons—without faltering or abandoning those who cannot defend themselves.",sp=0},{t="Virtues of the Order",b="Bravery under mortal threat is considered as essential to a holy warrior as their weapon and shield. Through the trials laid out in the Tome of Valor, paladins learn that raw strength is hollow without an unwavering vow to shelter the helpless. Facing genuine peril ensures that when darkness falls upon the Alliance, its defenders will stand firm rather than break.",sp=0}},faq={{q="What is the purpose of the Tome of Valor?",a="The Tome of Valor represents a rite of passage for developing Alliance paladins. It is designed by the mentors of the Holy Light to ensure an initiate possesses genuine courage and a selfless desire to protect the vulnerable before advancing in the order.",al={"what is tome of valor","tome of valor purpose","why do tome of valor"},it="purpose"},{q="Who directs paladins on this trial?",a="Initiates are typically called to this trial by senior paladins in Alliance capitals, such as Duthorian Rall in the Cathedral of Light in Stormwind or Tiza Battleforge in Ironforge's Hall of Mysteries.",al={"who gives tome of valor","tome of valor questgiver","who starts tome of valor"},it="in_charge"},{q="Where does this trial lead?",a="The initial call serves as the gateway to a series of specific tasks that test the paladin's resolve, driving them into the field to confront real danger in defense of the realm and the innocent.",al={"what comes after tome of valor","tome of valor follow up","tome of valor quest chain"},it="next_step"},{q="Why is bravery so heavily emphasized for paladins?",a="The Holy Light responds to faith and will. When facing overwhelming horrors like demons or dragons, fear can shatter a warrior's spirit; courage ensures a paladin remains a steadfast shield for others even in the direst circumstances.",al={"why valor","why courage matters to paladins"},it="history"},{q="Do dwarf and human paladins undertake the same test?",a="While dwarf paladins train out of Ironforge and humans through Stormwind's Cathedral of Light, both traditions adhere to the same core virtues of courage, duty, and defense of the helpless under the Light.",al={"is it different for dwarfs","ironforge tome of valor","stormwind tome of valor"},it="people"},{q="What core lessons are outlined in the trial?",a="The trial centers on three fundamental responsibilities: mastering unyielding bravery regardless of the odds, actively shielding the weak from harm, and maintaining faith when confronted by terror.",al={"tome of valor lessons","what does the tome teach"}},{q="Why do the paladin masters want you to take this trial?",a="Times are growing increasingly perilous across Azeroth, threatened by looming evils like demons and dragons. While you have already proven that the Holy Light answers your call, Duthorian Rall and Tiza Battleforge know that raw faith alone is not enough. They need to test the mettle beneath your flesh to ensure you possess the unwavering bravery required of a true paladin before greater perils strike your homeland.",al={"why take trial","duthorian rall motive","tiza battleforge trial why"},it="motive",add=true},{q="Why must you undertake this trial instead of senior paladins or guards?",a="This journey is not an errand of defense that city guards or veteran knights can handle for you. It is a personal rite of passage. The masters must see how your own spirit holds up when faced with hardship, testing your personal capacity to protect the weak, hold onto your faith, and stand firm in the face of terror.",al={"why me tome of valor","why send player valor","why cant guards do it"},it="why_me",add=true}},ang={["class:Paladin"]="This rite marks the transition from a mere acolyte to a trusted defender of the Holy Light, challenging you to put selfless duty ahead of personal safety.",["race:Human"]="Organized under the watchful eye of Duthorian Rall in the Cathedral of Light, this trial reflects Stormwind's enduring devotion to the Silver Hand's founding ideals.",["race:Dwarf"]="Ironforge's paladins, led by mentors like Tiza Battleforge, treat the Tome of Valor as proof that dwarven fortitude is reinforced by holy purpose.",["faction:Alliance"]="The trials outlined in the Tome prepare champions to defend Alliance settlements against rising threats, from local bandits to monstrous invaders."},kw={"cathedral of light","duthorian rall","holy light","ironforge","paladin trial","silver hand","tiza battleforge","tome of valor"},rel={"subzone:cathedral-of-light","topic:light"},m={start="Duthorian Rall (Stormwind City), Tiza Battleforge (Ironforge)",level="20",faction="Alliance",id=1793},src={"The Tome of Valor"}}
E["quest:1802"] = {t="quest",n="Tome of the Cabal",z="ironforge",s="This quest tasks an Alliance warlock with tracking down the scattered, ruined halves of a singular grimoire known as the Tome of the Cabal. Recovering the missing pages from distant lands is essential for deciphering the dark rites necessary to bind a felhunter.",h="This quest tasks an Alliance warlock with tracking down the scattered, ruined halves of a singular grimoire...",sec={{t="A Divided Grimoire",b="Only a single copy of the Tome of the Cabal was ever scribed, and its violent history ensured it did not stay intact. Torn apart and vandalized, its remnants were scattered to entirely different corners of the world. One portion, a tattered manuscript ripped straight from the binding, somehow found its way across the sea into the rugged canyons of Kalimdor, falling into the hands of the centaur clans. The remaining section was intended for transport by sea from the shores of Lordaeron down to Khaz Modan, but the vessel foundered before reaching its port.",sp=0},{t="Across Sea and Canyon",b="Reassembling the grimoire demands surviving two treacherous perils. The sea-lost pages washed ashore off the Hillsbrad coast west of Southshore, where scavenged debris and waterlogged relics fell into the grasp of shoreline murlocs near Azurelode Mine. Meanwhile, recovering the arid half requires infiltrating Splithoof Hold in Thousand Needles, delving deep into centaur caverns to reclaim the manuscript from an ancient chest. Only by uniting these disparate halves can Krom Stoutarm inspect the lost text before it returns to Strahad Farsan.",sp=0}},faq={{q="What is the Tome of the Cabal?",a="It is a rare, singular demonic grimoire containing esoteric knowledge necessary for warlocks. Its contents hold the complex incantations and binding rituals required to summon and subjugate a felhunter from the Twisting Nether.",al={"tome of the cabal lore","what is this book","tome cabal"},it="identity"},{q="Who is Krom Stoutarm and why does he want the tome?",a="Krom Stoutarm is an Ironforge dwarf immersed in the study of rare and forgotten texts. In exchange for telling Alliance warlocks where the torn pieces of the tome ended up, he asks only for the opportunity to study the contents firsthand once they are retrieved.",al={"who is krom stoutarm","why does krom want the book","krom stoutarm ironforge"},it="motive"},{q="Where did the two pieces of the book end up?",a="The Moldy Tome was washed ashore on the Hillsbrad coast west of Southshore near Azurelode Mine, scavenged by coastal murlocs. The Tattered Manuscript ended up in Kalimdor within Splithoof Hold, tucked inside a battered chest deep within a centaur cavern in Thousand Needles.",al={"where are the tome pieces","book locations","tattered manuscript location"},it="place"},{q="Why was the tome torn apart in the first place?",a="Only one copy of the Tome of the Cabal was ever transcribed. At some point in its murky past, it was deliberately vandalized, with a large section torn clean from the binding and carted away to Kalimdor, while the rest was lost at sea during an ill-fated voyage to Menethil Harbor.",al={"why was the book ripped","who vandalized the tome"},it="history"},{q="Who is Strahad Farsan and what does he have to do with this quest?",a="Strahad Farsan is an experienced warlock residing near Ratchet in the Barrens. He directs aspiring summoners to recover the tome so they can learn the rites needed to summon and bind a felhunter under his tutelage.",al={"who is strahad","strahad farsan","strahad connection"},it="ties"},{q="Why is the Moldy Tome covered in sea grime?",a="The book was aboard a ship bound for Menethil Harbor from the Lordaeron coast that never reached its destination. The shipwreck drifted near the Hillsbrad shore, where the damp, moldering pages were gathered by coastal murlocs near Azurelode Mine.",al={"why is moldy tome wet","hillsbrad tome murlocs"},it="origin"},{q="What is the Moldy Tome?",a="The Moldy Tome represents the waterlogged remains of the primary binding of the Tome of the Cabal. It was lost at sea off the coast of Hillsbrad Foothills when a transport ship sailing toward Menethil Harbor sank. Reclaiming it recovers the core of the grimoire's sinister teachings.",al={"moldy tome","what is the moldy tome","why find moldy tome"},it="item",add=true},{q="What is the Tattered Manuscript?",a="The Tattered Manuscript is the section torn from the original Tome of the Cabal before the book was lost. Carried far across the sea, it ended up in the hands of the Galak centaur within Thousand Needles, containing the missing rites needed to assemble the complete text.",al={"tattered manuscript","what is the tattered manuscript","centaur manuscript"},it="item",add=true}},ang={["class:Warlock"]="Recovering the torn halves of this grimoire marks a rite of passage, unlocking the vital summoning rituals needed to draw a felhunter out of the Nether and enslave it.",["faction:Alliance"]="Alliance practitioners rely on Ironforge contacts like Krom Stoutarm to trace rare demonic relics across continents without drawing the open suspicion of church or crown."},kw={"azurelode mine","felhunter","ironforge","krom stoutarm","moldy tome","splithoof hold","strahad farsan","tattered manuscript","tome of the cabal"},rel={"npc:krom-stoutarm","quest:1758","quest:1471","quest:1798","subzone:splithoof-hold","subzone:azurelode-mine","zone:thousandneedles","zone:hillsbrad"},m={start="Krom Stoutarm",level="30",faction="Alliance",id=1802,ri={"Moldy Tome","Tattered Manuscript"}},src={"Tome of the Cabal (Alliance, 2)"}}
E["quest:2039"] = {t="quest",n="Find Bingles",z="ironforge",s="Find Bingles is an Alliance breadcrumb quest initiated in Ironforge by the gnome Gnoarn. Concerned about an aviator who vanished over a week ago during an aerial reconnaissance flight toward fallen Gnomeregan, Gnoarn directs adventurers to scour the shores of Loch Modan. Tracking down the missing pilot leads right to Bingles Blastenheimer, who is very much alive but in desperate need of mechanical salvage.",h="Find Bingles is an Alliance breadcrumb quest initiated in Ironforge by the gnome Gnoarn.",sec={{t="A Missing Pilot",b="In the bustling gnome enclave of Tinker Town within Ironforge, anxiety runs high over missing kin and lost machinery. The gnome aviator Bingles Blastenheimer was dispatched on an aerial reconnaissance mission over the irradiated ruins of Gnomeregan. When more than a week passed without word, Gnoarn feared the worst—suspecting Bingles had succumbed to gnome engineering's occupational hazard and blown himself out of the sky. The last reported sighting placed the eccentric flyer somewhere above the waters of the Loch.",sp=0},{t="Down at the Loch",b="Rather than a tragic pile of smoldering wreckage, searchers discover Bingles alive and kicking along the Loch Modan shoreline. Unfazed by his prolonged absence and slightly offended that his piloting skills were doubted, the stranded inventor is fixated entirely on his grander cause. Instead of returning promptly to report to Gnoarn, Bingles immediately enlists his rescuer's aid to recover the tools and Blastencapper explosives that troggs stole from him, so he can resume his duties for the gnomish movement.",sp=0}},faq={{q="Who is Bingles Blastenheimer?",a="Bingles Blastenheimer is an eccentric gnomish aviator and mechanic. He was sent aloft to conduct aerial surveillance over the fallen city of Gnomeregan before crashing his flying machine near Loch Modan.",al={"who is bingles","bingles blastenheimer lore","who is the pilot"},it="identity"},{q="Why was Bingles flying over Gnomeregan?",a="Gnomish leadership and tinkerers continuously monitor Gnomeregan after its tragic fall to troggs and radiation. Bingles took to the skies to scout enemy positions and environmental conditions from above, serving the broader effort to reclaim their home.",al={"bingles mission","why was bingles flying","gnomeregan recon"},it="purpose"},{q="Where is Bingles located?",a="Bingles can be found grounded along the shores of the Loch in Loch Modan, on its southeastern bank, trying to sort out his downed flying machine.",al={"where is bingles","find bingles location","where to find bingles"},it="place",gp=true},{q="Who is Gnoarn?",a="Gnoarn is a gnome coordinator based in Tinker Town within Ironforge. He keeps tabs on gnomish personnel and missions, and he initiates the search when Bingles fails to return on schedule.",al={"who is gnoarn","quest giver gnoarn"},it="identity"},{q="What happens after finding Bingles?",a="Finding Bingles opens the follow-up task Bingles' Missing Supplies, in which adventurers recover his wrench, screwdriver, hammer, and Blastencapper explosives from the troggs on the Loch's islands.",al={"what next after find bingles","wing nut quest","bingles follow up"},it="next_step"},{q="Is Bingles hurt from the crash?",a="Bingles is completely unharmed, though his pride is slightly ruffled that Gnoarn doubted his flying skills. His real concern is recovering the tools and explosives that troggs stole from him.",al={"is bingles injured","did bingles die"}},{q="Why does Gnoarn want Bingles found?",a="Bingles was sent on a critical reconnaissance flight over fallen Gnomeregan and has failed to report back for more than a week. Given the erratic nature of gnome machinery and Bingles's knack for disaster, Gnoarn fears the pilot has blown himself up somewhere in the wilderness. He needs someone to search the region near Loch Modan, where Bingles was last spotted, to determine his fate.",al={"why find bingles","gnoarn motive","why send to look for bingles"},it="motive",add=true}},ang={["race:Gnome"]="For gnomes, recovering Bingles is about maintaining hope for the retaking of Gnomeregan, where every scout and flying machine counts.",["profession:Engineering"]="Engineers can appreciate the occupational hazards of gnomish aviation, where losing a wing nut or an engine blast is just another Tuesday in the field.",["faction:Alliance"]="Alliance scouts frequently bridge the communications gap between the halls of Ironforge and the field operations across Loch Modan."},kw={"bingles","blastenheimer","flying machine","gnoarn","gnomeregan","ironforge","loch modan","reconnaissance","tinker town"},rel={"npc:bingles-blastenheimer","npc:gnoarn","zone:lochmodan","subzone:the-loch","zone:gnomeregan","topic:gnome"},m={start="Gnoarn",["end"]="Bingles Blastenheimer",faction="Alliance",id=2039},src={"Find Bingles"}}
E["quest:2041"] = {t="quest",n="Speak with Shoni",z="ironforge",s="This breadcrumb summons Alliance adventurers from the halls of Ironforge to find Shoni the Shilent in Stormwind City. Shoni heads an underground assault unit intended to support the ongoing reclamation of Gnomeregan.",h="This breadcrumb summons Alliance adventurers from the halls of Ironforge to find Shoni the Shilent in...",sec={{t="A Call from Tinkertown",b="Following the radioactive downfall and betrayal of Gnomeregan, the surviving gnomes established an exile quarter in Ironforge. Their engineers, tinkers, and strategists are constantly scheming to breach their lost home. While central planning remains rooted in Tinkertown, frontline preparations stretch far beyond Khaz Modan. Enterprising adventurers in the mountain city are redirected south to Stormwind, where specialized military hardware is being prepared for subterranean warfare.",sp=0},{t="Subterranean Ambitions",b="Shoni the Shilent commands an elite underground assault crew stationed among the anvils and forges of Stormwind's Dwarven District. To burrow deep toward trogg-infested sectors, her sappers require specialized machinery known as gyrodrillmatic excavationators. Reaching Shoni is straightforward thanks to the newly operational Deeprun Tram, which links Ironforge directly to Stormwind beneath the mountains.",sp=0}},faq={{q="Who is Shoni the Shilent?",a="Shoni the Shilent is a gnomish officer stationed in Stormwind City. Despite her quiet moniker, she commands an underground assault unit tasked with building and deploying heavy excavation gear to aid in the effort to retake Gnomeregan.",al={"who is shoni","shoni the shilent","who is the npc"},it="identity"},{q="Where can I find Shoni the Shilent?",a="Shoni is located in the Dwarven District of Stormwind City, near the blacksmithing trainers and forges just steps outside the Deeprun Tram terminal.",al={"where is shoni","shoni location","shoni coordinates"},it="place",gp=true},{q="How do I get to Stormwind from Ironforge?",a="The fastest route is the Deeprun Tram, an engineering marvel located on the northeastern side of Tinkertown in Ironforge. It takes travelers straight to Stormwind's Dwarven District without traversing the wilderness.",al={"travel to stormwind","ironforge to stormwind","how to reach stormwind"},gp=true},{q="What does Shoni need help with?",a="Shoni is outfitting an underground assault crew and needs essential components for her gyrodrillmatic excavationators, a task that eventually directs adventurers toward Westfall and the Deadmines.",al={"shoni quest goal","what does shoni want"},it="purpose"},{q="Is this quest required to get Underground Assault?",a="No, it is an optional breadcrumb quest. You can travel directly to the Dwarven District in Stormwind and speak with Shoni to pick up Underground Assault on your own.",al={"is speak with shoni mandatory","can i skip to shoni"},it="next_step",gp=true},{q="How does this connect to Gnomeregan?",a="Gnomish leadership is assembling forces and excavation technology to pierce the defenses of Gnomeregan. Shoni's team is developing the subterranean drill apparatus necessary to break into the contaminated city.",al={"why gnomeregan","gnome connection"},it="ties"},{q="Why does the quest giver send you to Shoni the Shilent?",a="The gnomes are fighting an uphill battle to reclaim their fallen home of Gnomeregan. Shoni the Shilent commands an underground assault crew preparing specialized gyrodrillmatic excavationators for the war effort, but her operations in Stormwind lack hands. Central command in Ironforge needs able adventurers willing to travel south and bolster her critical engineering project before their offensive can advance.",al={"why speak with shoni","why send to shoni","why visit shoni"},it="motive",add=true}},ang={["race:Gnome"]="Every gnome in Ironforge dreams of reclaiming their irradiated home; taking Shoni's orders means actively contributing to the technological effort to retake Gnomeregan.",["profession:Engineering"]="Shoni's project involves gyrodrillmatic excavationators, a complex feat of gnomish mechanical engineering designed for deep-earth tunneling.",["faction:Alliance"]="This mission demonstrates the close logistics between the Alliance capitals, utilizing the Deeprun Tram to move personnel between Ironforge and Stormwind."},kw={"deeprun tram","dwarven district","gnomeregan","gyrodrillmatic excavationator","ironforge","shoni the shilent","stormwind","tinkertown","underground assault"},rel={"npc:shoni-the-shilent","quest:2040","subzone:dwarven-district","subzone:deeprun-tram","zone:stormwind","zone:ironforge","zone:gnomeregan","zone:deadmines"},m={level="15",faction="Alliance",id=2041},src={"Speak with Shoni"}}
E["quest:291"] = {t="quest",n="The Reports",z="ironforge",s="Carry Senir Whitebeard's report on the Frostmane trolls from Kharanos to Senator Barin Redstone in Ironforge. Senir warns that the senator is sour and asks you not to mention who helped gather the information.",h="Carry Senir Whitebeard's report on the Frostmane trolls from Kharanos to Senator Barin Redstone in Ironforge.",sec={{t="A Dispatch to the Capital",b="After daring reconnaissance deep inside Frostmane Hold, Senir Whitebeard drafts an urgent report detailing the growing troll threat facing Dun Morogh. Stationed out of Kharanos, the mountaineer needs a courier to deliver these intelligence findings directly to Senator Barin Redstone in Ironforge. Eager to preserve his own reputation in the eyes of the government, Whitebeard cheerfully advises his runner not to mention who actually did the hazardous legwork out in the snowy crags.",sp=0},{t="Friction in the High Seat",b="When delivered to Senator Redstone in the royal court, the document causes immediate outrage. Rather than expressing gratitude for intelligence on hostile troll movements, the sour senator bristles at finding King Magni's personal authority invoked to sanction Whitebeard's operations. The delivery exposes an ongoing power struggle within Ironforge's governing halls, highlighting how deeply the Senate resents executive decrees and unapproved field initiatives undertaken in the King's name.",sp=1}},faq={{q="Who is Senir Whitebeard?",a="Senir Whitebeard is a dwarven mountaineer stationed near Kharanos in Dun Morogh. He oversees scouting and military reconnaissance against the Frostmane troll tribes encroaching on dwarven settlements.",al={"senir whitebeard","who gives the reports","whitebeard kharanos"},it="identity"},{q="Who is Senator Barin Redstone?",a="Barin Redstone is a sour, aristocratic dwarf senator residing in the throne room of Ironforge near King Magni Bronzebeard. He is fiercely protective of legislative authority and easily annoyed by common petitioners.",al={"barin redstone","who is the senator","redstone ironforge"},it="identity"},{q="Why is Senator Redstone angry about the report?",a="Senir warns that Redstone has a sour disposition. The senator's response to the report is discovered when you deliver it.",al={"why is redstone mad","why does the senator yell","senate vs magni"},sp=1,it="conflict"},{q="Why does Senir Whitebeard ask to keep your help secret?",a="Whitebeard wants his superiors in Ironforge to believe he personally managed and completed the arduous field scouting, bolstering his standing rather than admitting an itinerant adventurer carried out the mission.",al={"why does senir take credit","whitebeard stole credit","senir's secret"},it="motive"},{q="Where is the report delivered?",a="The report is delivered to Senator Barin Redstone inside the High Seat of Ironforge, the great chamber where King Magni Bronzebeard holds court.",al={"where to turn in the reports","barin redstone location","the reports turn in"},it="place",gp=true},{q="What does this quest reveal about Ironforge politics?",a="The delivery introduces Ironforge's Senate and the officials receiving frontier reports. Redstone's reaction provides a closer glimpse of its politics.",al={"ironforge government lore","dwarf senate lore","magni vs senate"},sp=1,it="history"},{q="Why does Senir Whitebeard need you to deliver the report instead of doing it himself?",a="Senir Whitebeard remains stationed out in Dun Morogh to oversee field operations against local threats like the Frostmane trolls. More importantly, he wants the Senate and his superiors to believe he is laboring tirelessly on the front lines, leaving courier duties and the unpleasant task of facing a grumpy senator to an expendable traveler.",al={"why send me with report","why doesnt senir deliver report","why me reports"},it="why_me",add=true}},ang={["race:Dwarf"]="For dwarves, walking into the High Seat to deliver the dispatch offers a firsthand glimpse at the delicate balance between King Magni's crown and the parliamentary power of the dwarven Senate.",["faction:Alliance"]="The delivery serves as an early introduction to Ironforge's civic layout and the political bureaucracy that shapes Alliance domestic policy within Dun Morogh."},kw={"barin redstone","dwarf senate","frostmane","high seat","ironforge","kharanos","magni bronzebeard","senir whitebeard","the reports"},rel={"npc:senir-whitebeard","quest:287","subzone:kharanos","zone:ironforge"},m={start="Senir Whitebeard",["end"]="Senator Barin Redstone",level="10",faction="Alliance",id=291},src={"The Reports"}}
E["quest:2948"] = {t="quest",n="Gnome Improvement",z="ironforge",s="After an adventurer brings him a ring he once crafted, recovered from the irradiated depths of Gnomeregan, Talvash del Kissel offers to upgrade the piece for an adventurer willing to supply the materials. Down on his luck in the dwarven capital of Ironforge, the gnome artisan combines silver, moss agate, and intricate lattice work to craft a far superior trinket.",h="After an adventurer brings him a ring he once crafted, recovered from the irradiated depths of Gnomeregan...",sec={{t="A Gnomish Artisan in Exile",b="Talvash del Kissel is one of the many gnome refugees who fled Gnomeregan following its disastrous fall to the trogg invasion and radiation. Residing in the Mystic Ward of Ironforge, Talvash finds himself down on his luck, out of stock, and desperate to prove that his talents as a master jeweler and tinkerer remain untarnished despite his exile.",sp=0},{t="Upgrading the Old Band",b="When an adventurer shows Talvash a ring of his own simple pre-fall design, cleansed of its grime by the Sparklematic 5200, Talvash is grateful but ambitious. Rather than letting a customer walk away with what he considers a dated, simple ring design, he insists on enhancing it. By layering a delicate silver and moss agate lattice over the band, he creates an improved piece that reflects his evolving mastery of metal and gemstone craft.",sp=0}},faq={{q="Who is Talvash del Kissel?",a="Talvash del Kissel is a skilled gnome craftsman and jeweler currently living as an exile in Ironforge. He ran a small jewelry shop in Gnomeregan before its fall, and one of the rings he made there can be recovered and brought to him in the Mystic Ward.",al={"talvash","talvash del kissel","gnome jeweler ironforge"},it="identity"},{q="What is the history behind the ring being upgraded?",a="The base ring is one of several simple rings Talvash crafted in his old Gnomeregan shop, later found on a Dark Iron dwarf in the ruins. After being retrieved by adventurers from the Sparklematic 5200 cleaner inside the ruined city, Talvash offers to modernise and embellish the plain band into a much finer trinket.",al={"where does the ring come from","grime encrusted ring origin"},it="history"},{q="Why does Talvash ask the player to provide the reagents?",a="Like many gnome refugees driven out of Gnomeregan, Talvash is struggling financially and has completely exhausted his raw material supplies in Ironforge. He lacks the silver and moss agate necessary to perform the delicate lattice work himself without a sponsor.",al={"why do i need silver and moss agate","why does talvash have no materials"},it="motive"},{q="Where does this quest chain begin?",a="The quest chain begins inside the Gnomeregan dungeon by obtaining a Grime-Encrusted Ring from enemies, cleaning it at the Sparklematic 5200 machine, and then following the engraved initials 'TdK' back to Talvash in Ironforge.",al={"how to start gnome improvement","ring questline start"},it="origin",gp=true},{q="Is Talvash bitter about his situation in Ironforge?",a="While he laments being stuck in what he calls an unjust financial hole, Talvash maintains high spirits and professional pride. He firmly believes that once he gets back on his feet, he will be renowned across Azeroth for crafting the finest trinkets anywhere.",al={"talvash backstory","talvash personality"},it="ties"},{q="Does the Horde have access to this quest?",a="No. While Horde players can clean Grime-Encrusted objects in Gnomeregan, their version of the ring quest redirects them to an alternate contact, Nogg in Orgrimmar, rather than Talvash in Ironforge.",al={"can horde do gnome improvement","horde ring upgrade"},gp=true},{q="What is the Silver Bar for?",a="Talvash needs the refined metal to reshape your original ring into a more intricate piece of jewelry. He uses the silver bar to forge a detailed lattice work directly onto the band, giving the simple design far greater elegance and durability than his early craftwork possessed.",al={"why silver bar","talvash silver bar","what does he need silver for"},it="item",add=true},{q="What is the Moss Agate for?",a="The moss agate serves as the decorative centerpiece for the ring's upgrade. By setting the polished green gem into the newly crafted silver lattice, Talvash intends to add flair and showcase his true expertise as an artisan, transforming a rudimentary trinket into a far more impressive work.",al={"why moss agate","talvash moss agate","what does he need agate for"},it="item",add=true}},ang={["race:Gnome"]="This quest highlights the pride and resilience of gnome craftsmen, who refuse to produce sub-par work even while displaced from their homeland and stripped of raw materials.",["profession:Mining"]="Miners provide the essential raw materials—smelted silver and cut moss agates found in subterranean deposits—required to assist Talvash's jewelry work.",["faction:Alliance"]="Taking place between Gnomeregan and Ironforge, the task reinforces the deep ties forged between Alliance heroes and the displaced refugees of the fallen gnome capital."},kw={"brilliant gold ring","gnome improvement","gnomeregan","ironforge","moss agate","silver bar","talvash"},rel={"npc:talvash-del-kissel","quest:2947","quest:2945","zone:ironforge","topic:gnome","topic:alliance"},m={start="Talvash del Kissel",faction="Alliance",id=2948,ri={"Moss Agate","Silver Bar"}},src={"Gnome Improvement"}}
E["quest:2997"] = {t="quest",n="Tome of Divinity",z="ironforge",s="The Tome of Divinity is an introductory summons calling young dwarven paladins from their field duties in Dun Morogh to the mountain city of Ironforge. Dispatched by Azar Stronghammer, the initiate is directed to seek guidance from Tiza Battleforge high in the Hall of Mysteries. It marks the formal beginning of a paladin's deeper trials in service to the Holy Light.",h="The Tome of Divinity is an introductory summons calling young dwarven paladins from their field duties in Dun...",sec={{t="A Call to the High Seat",b="While dwarven initiates begin their training protecting the snowbound villages and roads of Dun Morogh, martial prowess alone does not make a paladin. Azar Stronghammer recognizes when a defender has grown ready for deeper spiritual instruction. Rather than continuing standard martial drills, he sends promising candidates into the heart of Ironforge to begin their true initiation under the city's revered holy elders.",sp=0},{t="The Hall of Mysteries",b="The summons directs the initiate to the Mystic Ward, climbing into the quiet chambers of the Hall of Mysteries. There, surrounded by sacred relics and solemn study, stands Tiza Battleforge. As one of the most respected dwarven champions of the Light, she tests incoming paladins on their readiness to embrace self-sacrifice, mercy, and the heavy moral duties of their holy calling.",sp=0}},faq={{q="What is the purpose of this quest?",a="It serves as the opening summons directing a dwarven paladin from the outlying training grounds of Dun Morogh to Tiza Battleforge in Ironforge, initiating the trials required to understand the Holy Light and earn the power of resurrection.",al={"why do i need this quest","what is tome of divinity for","tome of divinity purpose"},it="purpose"},{q="Who is Tiza Battleforge?",a="Tiza Battleforge is a veteran dwarven paladin and respected mentor stationed upstairs in Ironforge's Hall of Mysteries. She oversees the spiritual instruction of young paladins and guides them through the sacred trials of the Tome of Divinity.",al={"who is tiza","tiza battleforge lore","who is battleforge"},it="identity"},{q="Where is the Hall of Mysteries located?",a="The Hall of Mysteries is situated within the Mystic Ward in western Ironforge. It is the spiritual and arcane center of the dwarven capital, housing priests, paladins, and mages.",al={"where is hall of mysteries","find hall of mysteries","hall of mysteries ironforge"},it="place",gp=true},{q="Who sends the paladin on this errand?",a="Azar Stronghammer, a paladin trainer operating in Dun Morogh, sends promising initiates to Ironforge once they have demonstrated their martial dedication to defending the local dwarven settlements.",al={"who starts tome of divinity","quest giver tome of divinity","azar stronghammer"},it="origin"},{q="Why must dwarven paladins study in Ironforge?",a="Field trainers like Azar teach basic combat arts, but the formal teachings, sacred texts, and elders of the Holy Light reside within the Hall of Mysteries. Advanced rites and spiritual doctrines must be studied directly under senior mentors like Tiza Battleforge.",al={"why go to ironforge","why train in ironforge"},it="why_here"},{q="What follows after speaking with Tiza Battleforge?",a="Speaking with Tiza begins the true dwarven trials of the Tome of Divinity, challenging the paladin to demonstrate devotion, compassion, and sacrifice in service to the Light.",al={"what comes next","next quest after tome of divinity","what does tiza give me"},it="next_step"},{q="Why does Azar Stronghammer want you to visit Ironforge?",a="Azar Stronghammer recognizes that your time as an apprentice aiding Dun Morogh is coming to a close. To truly serve as a champion of the Holy Light, you require deeper instruction in its mysteries, principles, and obligations. He directs you to Ironforge because Tiza Battleforge is entrusted with testing and guiding promising young paladins toward their true calling.",al={"why does azar send you","azar stronghammer motive","why go see tiza battleforge"},it="motive",add=true},{q="Why does Azar Stronghammer send you specifically?",a="This journey is not an errand that a city guard or an established veteran could undertake for you. It marks your personal progression as a paladin. Azar sends you to Tiza Battleforge because you alone must answer the call of the Light, prove your dedication to its virtues, and accept the burdens expected of a holy warrior.",al={"why send me","why azar sends you","why paladin player"},it="why_me",add=true}},ang={["class:Paladin"]="This rite of passage bridges practical military service in the snows with the deep spiritual discipline expected of holy warriors.",["race:Dwarf"]="Dwarven paladins combine the rugged endurance of their kin with the teachings of the Holy Light, centered around the sanctum of Ironforge's Hall of Mysteries.",["faction:Alliance"]="The shared veneration of the Light unites the dwarven defenders of Khaz Modan with their human allies in Lordaeron and Stormwind."},kw={"azar stronghammer","dun morogh","hall of mysteries","holy light","ironforge","mystic ward","paladin","redemption","tiza battleforge","tome of divinity"},rel={"npc:tiza-battleforge","npc:azar-stronghammer","subzone:hall-of-mysteries","subzone:mystic-ward","zone:ironforge","zone:dunmorogh","topic:light"},m={start="Azar Stronghammer",["end"]="Tiza Battleforge",level="12",faction="Alliance",id=2997},src={"Tome of Divinity (Azar Stronghammer)"}}
E["quest:2999"] = {t="quest",n="Tome of Divinity",z="ironforge",s="Tome of Divinity is a rite of passage quest offered to young dwarven paladins serving in Dun Morogh. Directed by Brandur Ironhammer, the paladin trainer in Ironforge's Hall of Mysteries, an initiate is sent upstairs to speak with the respected paladin trainer Tiza Battleforge. It marks the transition from basic martial training into the deeper spiritual duties and sacred vows of the Holy Light.",h="Tome of Divinity is a rite of passage quest offered to young dwarven paladins serving in Dun Morogh.",sec={{t="The Call to the High Seat",b="While novice paladins spend their early days defending Anvilmar and Kharanos from troggs and frost trolls, their duties eventually call for deeper devotion. Brandur Ironhammer, recognizing that an initiate has proven their martial discipline, advises them to take a break from their work in the snowy passes and seek guidance upstairs in his own Hall of Mysteries in Ironforge. There, senior paladins oversee the spiritual maturation of the order.",sp=0},{t="Guidance from Tiza Battleforge",b="Tiza Battleforge stands as one of the most revered paladins among the Ironforge dwarves. It is her responsibility to instruct initiates on the true burdens of the Light, moving past simple swordplay and hammer swings to teach compassion, justice, and self-sacrifice. Seeking her out begins the formal study of the Tome of Divinity, a sacred process aimed at granting a paladin the ability to resurrect the fallen.",sp=0}},faq={{q="What is the purpose of this quest?",a="This quest directs young dwarven paladins from their trainer, Brandur Ironhammer, to senior paladin Tiza Battleforge in Ironforge. It serves as the opening step for the trials required to study the Tome of Divinity and earn the power of spiritual resurrection.",al={"what does this quest do","tome of divinity start","why do this quest"},it="purpose"},{q="Who is Brandur Ironhammer?",a="Brandur Ironhammer is a dwarven paladin trainer stationed in the Hall of Mysteries in Ironforge's Mystic Ward. He oversees young paladins there, sending promising initiates upstairs to Tiza Battleforge when they are ready for greater sacred responsibilities.",al={"who gives this quest","brandur role","brandur ironhammer lore"},it="identity"},{q="Who is Tiza Battleforge?",a="Tiza Battleforge is a respected veteran paladin located upstairs in the Hall of Mysteries in Ironforge. She mentors younger paladins on what the Holy Light truly demands of them beyond martial prowess.",al={"where is tiza","tiza battleforge role","who is tiza"},it="target"},{q="Where does this quest lead next?",a="Speaking with Tiza Battleforge initiates the specific trials of the Tome of Divinity. These tasks test a paladin's devotion, mercy, and willingness to protect and restore life in service to the Light.",al={"next quest","what comes after","tome of divinity chain"},it="next_step"},{q="Why must dwarven paladins seek out the Tome of Divinity?",a="To wield the miracle of returning a fallen ally to life, a paladin must understand true selflessness and spiritual duty. The Tome of Divinity guides initiates through formal lessons and tests of faith necessary to channel such potent holy power.",al={"why tome of divinity","paladin res quest lore","redemption dwarf"}},{q="Do humans receive this same instruction in Ironforge?",a="Human paladins undertake a parallel journey through the Cathedral of Light in Stormwind rather than Ironforge. This specific summons from Brandur Ironhammer to Tiza Battleforge is tailored to dwarves training in Ironforge.",al={"can humans do this","is this dwarf only","human tome of divinity"}},{q="Why does Brandur Ironhammer send you to Tiza Battleforge?",a="Brandur Ironhammer recognizes that your time training in Dun Morogh has prepared you for deeper responsibilities within the Order. Rather than keeping you bound to local troubles, he wants you to advance in your calling. Tiza Battleforge is revered among dwarven paladins as a mentor who guides younger initiates when they are ready to learn what the Holy Light truly demands of them.",al={"why does brandur send you","brandur ironhammer motive","why talk to tiza battleforge"},it="motive",add=true},{q="Why must you speak to Tiza yourself instead of Brandur handling it?",a="The path of a paladin is deeply personal and cannot be walked by proxy. Brandur Ironhammer can guide your early martial training, but spiritual progression demands that you present yourself directly before your elders. Tiza Battleforge must evaluate your devotion and resolve firsthand before she can entrust you with sacred teachings like the Tome of Divinity.",al={"why me tome of divinity","why must i go to tiza","why doesn't brandur go"},it="why_me",add=true}},ang={["class:Paladin"]="This quest marks the moment an initiate transitions from rough martial drills to the profound spiritual burdens of the Holy Light, setting up the trials to earn the power of Redemption.",["race:Dwarf"]="Dwarven paladins integrate the devotion of the Holy Light with Khaz Modan's deep traditions of duty and brotherhood, answering the call within the mountain halls of Ironforge."},kw={"brandur ironhammer","hall of mystics","ironforge","paladin","redemption","tiza battleforge","tome of divinity"},rel={"npc:brandur-ironhammer","npc:tiza-battleforge","zone:ironforge","zone:dunmorogh","topic:light"},m={start="Brandur Ironhammer",["end"]="Tiza Battleforge",level="12",faction="Alliance",id=2999},src={"Tome of Divinity (Brandur Ironhammer)"}}
E["quest:3000"] = {t="quest",n="Tome of Divinity",z="ironforge",s="This errand directs dwarven paladins wandering abroad to return home to Ironforge to further their sacred calling. Offered by Lord Grayson Shadowbreaker in Stormwind, it points fledgling champions toward Tiza Battleforge, one of the most respected instructors in the Hall of Mysteries. Returning home marks the beginning of their formal trials with the Tome of Divinity.",h="This errand directs dwarven paladins wandering abroad to return home to Ironforge to further their sacred...",sec={{t="A Summons Home",b="While dwarven paladins frequently aid the kingdom of Stormwind and venture throughout human territories, their spiritual and martial roots remain anchored in Khaz Modan. Lord Grayson Shadowbreaker, recognizing when a dwarf's training in the field has progressed enough, advises them to return to the heart of Ironforge. There, their own people oversee the profound spiritual obligations expected of a full Knight of the Silver Hand.",sp=0},{t="The Hall of Mysteries",b="Upon returning to the mountainous capital, the paladin is directed to the Mystic Ward. Deep within the Hall of Mysteries, atop its upper level, resides Tiza Battleforge. She serves as a venerated mentor to the younger generation of dwarven paladins, preparing them to shoulder the burden of the Holy Light through the sacred trials recorded in the Tome of Divinity.",sp=0}},faq={{q="Why does Lord Grayson Shadowbreaker send me back to Ironforge?",a="Lord Grayson recognizes that while you have proven your mettle in the field, young dwarven paladins are meant to learn the deeper tenets and trials of the Holy Light directly from their own kin under Tiza Battleforge's guidance.",al={"why go to ironforge","why grayson sends me away","why visit tiza"},it="motive"},{q="Who is Tiza Battleforge?",a="Tiza Battleforge is one of Ironforge's most respected dwarven paladins. Stationed upstairs in the Hall of Mysteries, she mentors developing paladins and oversees the trials that test their dedication to the Light.",al={"tiza battleforge","who is tiza","paladin trainer tiza"},it="identity"},{q="Where can I find Tiza Battleforge?",a="She is located inside the Hall of Mysteries, which sits in the Mystic Ward of Ironforge. Head upstairs within the sanctuary to find her.",al={"where is tiza","tiza battleforge location","how to find tiza"},it="place",gp=true},{q="What is the Tome of Divinity?",a="The Tome of Divinity encompasses the holy teachings and rigorous trials paladins must undergo to master the Holy Light, particularly the power of resurrection and selfless devotion to fallen allies.",al={"tome of divinity meaning","what is the tome","paladin book"},it="item"},{q="Can human paladins do this version of the quest?",a="No. This particular summons specifically directs dwarven paladins to return to their homeland's instructors, whereas human paladins pursue their trials directly under Lord Grayson Shadowbreaker and Duthorian Rall in Stormwind.",al={"can humans do this","is this quest dwarf only"},gp=true},{q="What happens after reporting to Tiza Battleforge?",a="Once you introduce yourself to Tiza, she presents you with your formal dwarven trials through the Tome of Divinity, testing your readiness to wield the Light's redemptive power.",al={"what comes next","next quest after tome of divinity","after speaking to tiza"},it="next_step"},{q="Why does Lord Grayson Shadowbreaker choose me for this?",a="Lord Grayson recognizes your growing potential as a paladin, but he respects the distinct traditions of your people. Rather than instructing you entirely within the Cathedral of Light in Stormwind, he knows that young dwarven paladins must be grounded in the teachings of their own elders. He sends you home because it is time for your next sacred rite, and Tiza Battleforge is the revered mentor who guides dwarves through that spiritual milestone.",al={"why me tome of divinity","why does grayson send me","why dwarf paladin"},it="why_me",rc="Dwarf",add=true}},ang={["race:Dwarf"]="This quest bridges your adventures in human lands with your duty to Khaz Modan, calling you back to your ancestral seat in Ironforge to train under your own elders.",["class:Paladin"]="This marks a major rite of passage for dwarven paladins, setting them on the path to study the Tome of Divinity and master the gift of resurrection.",["faction:Alliance"]="The shared training and mutual respect between Stormwind's paladins and Ironforge's mentors highlight the close spiritual alliance between dwarves and humans."},kw={"dwarf paladin","hall of mysteries","ironforge","lord grayson shadowbreaker","mystic ward","redemption","tiza battleforge","tome of divinity"},rel={"npc:tiza-battleforge","npc:lord-grayson-shadowbreaker","subzone:hall-of-mysteries","subzone:mystic-ward","zone:ironforge","topic:light"},m={start="Lord Grayson Shadowbreaker",["end"]="Tiza Battleforge",level="12",faction="Alliance",id=3000},src={"Tome of Divinity (Lord Grayson Shadowbreaker)"}}
E["quest:301"] = {t="quest",n="Report to Ironforge",z="ironforge",s="This errand sends an adventurer from Thelsamar in Loch Modan into the heart of Ironforge with critical updates from Ironband's Excavation Site. Delivering the excavation progress report to Prospector Stormpike in the Assembly of Explorers sets off an investigation into missing blastpowder and stalled archaeology in the foothills.",h="This errand sends an adventurer from Thelsamar in Loch Modan into the heart of Ironforge with critical...",sec={{t="A Courier for the League",b="Archaeological expeditions throughout Khaz Modan rely heavily on funding, supplies, and oversight from the Explorers' League. When Prospector Ironband's dig site in southern Loch Modan runs short of blasting supplies, his overseers cannot simply requisition more locally. Jern Hornhelm at the Thelsamar inn entrusts an adventurer with carrying Ironband's written report across the mountain passes directly to Prospector Stormpike at League headquarters.",sp=0},{t="The Stormpike Temper",b="Prospector Stormpike represents the no-nonsense, fiery determination characteristic of his clan. Stationed within the grand Library and Hall of Explorers in Ironforge, he expects swift, tangible results from the League's digs. Upon receiving the missive, Stormpike is outraged to find that Ironband fails to account for a massive shipment of blastpowder sent weeks earlier, revealing that supply lines in Loch Modan have suffered a dangerous breakdown.",sp=1}},faq={{q="Why does this report need to go all the way to Ironforge?",a="The Explorers' League strictly governs the distribution of valuable resources like blastpowder. Field digs cannot order dangerous explosives without formal authorization from senior prospectors stationed at headquarters in the Hall of Explorers.",al={"why go to ironforge","why take report to stormpike","ironforge report reason"},it="purpose"},{q="Who is Prospector Stormpike?",a="He is a high-ranking official within the Explorers' League based in Ironforge. A member of the proud Stormpike clan, he is notorious for his short temper and impatience with stalled dig sites and missing inventory.",al={"who is stormpike","prospector stormpike lore"},it="identity"},{q="Where did Ironband's original blastpowder go?",a="A shipment of blasting powder was dispatched weeks prior, but Ironband makes no mention of ever receiving it. This raises immediate fears that troggs or bandits ambushed the transport wagon along the roads of Loch Modan.",al={"what happened to blastpowder","missing blastpowder","where is the powder"}},{q="Where do you find Prospector Stormpike in Ironforge?",a="Prospector Stormpike is located within the Assembly of Explorers, also known as the Library or Hall of Explorers, tucked in the northeastern wing of Ironforge.",al={"stormpike location","where is stormpike","assembly of explorers location"},it="place",gp=true},{q="Who gives you the report in Thelsamar?",a="Jern Hornhelm, who resides inside the Stoutlager Inn in Thelsamar, acts as the liaison coordinating reports and communications between Ironband's remote camp and the city leadership.",al={"who starts report to ironforge","jern hornhelm role"},gp=true},{q="What happens after Stormpike reads the report?",a="Furious over the unaccounted munitions and stalled progress, Stormpike orders the player to organize a new shipment of blastpowder and deliver it straight back to Prospector Ironband.",al={"what comes next","next quest after report to ironforge"},sp=1,it="next_step"},{q="Why does Jern Hornhelm want this report sent to Ironforge?",a="Prospector Ironband's excavation in Loch Modan has ground to a halt because the crew ran out of blastpowder. Jern Hornhelm cannot requisition more supplies on his own authority; he needs formal approval from the Explorers' League headquarters in Ironforge. Delivering the progress report to Prospector Stormpike is the only administrative way to secure a fresh supply of powder and keep the dig moving forward.",al={"why send report","jern hornhelm motive","why does jern want blastpowder"},it="motive",add=true},{q="Why does Jern Hornhelm send you instead of going himself?",a="Jern Hornhelm has his hands full managing logistics in Thelsamar and supporting the local excavation efforts. Beyond that, Prospector Stormpike is notorious for having a short, fiery temper when dealing with delays and setbacks. Entrusting an expendable courier to brave Stormpike's wrath spares Jern the direct fury of his superiors while keeping his focus on local operations.",al={"why send me","why not go himself","why does hornhelm need me"},it="why_me",add=true}},ang={["race:Dwarf"]="For dwarves, navigating the bureaucracy of the Explorers' League and dealing with Clan Stormpike's legendary temper is a familiar rite of passage in the halls of their capital.",["faction:Alliance"]="This task demonstrates the Alliance's logistical reach, connecting far-flung research camps in the mountain valleys to the military and scholarly leadership in Ironforge."},kw={"blastpowder","explorers' league","ironband's compound","jern hornhelm","loch modan","prospector stormpike","report to ironforge","thelsamar"},rel={"npc:prospector-stormpike","npc:jern-hornhelm","topic:explorers-league","quest:298","quest:302","zone:ironforge"},m={start="Jern Hornhelm",["end"]="Prospector Stormpike",level="15",faction="Alliance",id=301},src={"Report to Ironforge"}}
E["quest:302"] = {t="quest",n="Powder to Ironband",z="ironforge",s="Powder to Ironband is an Alliance delivery quest connecting the Explorer's League headquarters in Ironforge to Loch Modan. Having secured official approval from Prospector Stormpike, adventurers are sent to Thelsamar to oversee a crucial shipment of blasting powder bound for Ironband's Excavation.",h="Powder to Ironband is an Alliance delivery quest connecting the Explorer's League headquarters in Ironforge...",sec={{t="Bureaucracy and Blasting Powder",b="Archaeological excavation in the mountains of Khaz Modan requires heavy ordnance. When Prospector Ironband's expedition in southern Loch Modan ran short of blasting supplies, word was dispatched to the League's leadership in Ironforge. Prospector Stormpike quickly authorized the requisition, directing the runner to coordinate with Jern Hornhelm in Thelsamar, the primary logistical hub for the valley.",sp=0},{t="A Missed Departure",b="Because prior supply convoys through the Loch had vanished or suffered harassment from local troggs, Stormpike explicitly ordered the courier to personally safeguard the powder wagon. However, bureaucracy and travel time work against the League. By the time a courier arrives at the Stoutlager Inn in Thelsamar, Jern Hornhelm has already dispatched the wagon under the guard of Huldar and two dwarven porters, leaving the courier scrambling down the road to catch up.",sp=1}},faq={{q="Why is blasting powder being sent to Ironband?",a="Prospector Ironband leads a vital dwarven archaeological dig in southern Loch Modan. Uncovering titan artifacts and deep stone relics requires blasting through dense rock, and his team exhausted their supply amidst mounting trogg aggression.",al={"why need powder","ironband blasting powder","what is powder for"},it="purpose"},{q="Who is Prospector Stormpike?",a="Prospector Stormpike is a senior officer of the Dwarven Explorer's League stationed in the Hall of Explorers in Ironforge. He reviews field requests, authorizes critical equipment, and manages logistics for major dig sites across Khaz Modan.",al={"stormpike role","who gave quest"},it="identity"},{q="Who is Jern Hornhelm?",a="Jern Hornhelm is a logistics coordinator and mountaineer associate stationed in Thelsamar, Loch Modan. He prepares supplies and organizes transport teams heading into the more dangerous frontiers of the valley.",al={"jern hornhelm location","where is jern hornhelm"},it="identity"},{q="Why was personal escort requested for this shipment?",a="Earlier shipments bound for the excavation failed to reach their destination. With Loch Modan overrun by troggs spilling out of the hills and dig sites, supply lines along the main road have become increasingly hazardous.",al={"why escort powder","trogg attacks on wagons"},it="motive"},{q="What happens when you arrive in Thelsamar?",a="Jern Hornhelm has already sent the wagon on its way with Huldar and the porters Miran and Saean. You are forced to follow the southern road to catch up with them before trouble strikes.",al={"did i miss the wagon","where is the shipment"},sp=1,it="next_step"},{q="How does this quest fit into the Explorer's League storyline?",a="It serves as the courier link connecting the initial request from the dig site, through the central authorities in Ironforge, and back out to the field via Thelsamar to safeguard the expedition's ongoing excavation.",al={"ironband chain","excavation questline"},it="ties"},{q="Why does Prospector Stormpike send an adventurer instead of official guards?",a="Prospector Stormpike operates out of the Hall of Explorers in Ironforge, focused on administrative matters and securing permits rather than fielding troops. With prior blasting powder shipments already falling prey to danger along the Loch Modan roads, he trusts a capable traveler who is already heading into the field to personally see that Jern Hornhelm's supply train reaches the dig site safely.",al={"why send me","why not send guards to ironband","why an adventurer"},it="why_me",add=true}},ang={["race:Dwarf"]="For dwarves, securing excavation powder is not merely logistical support; it aids the holy endeavor of uncovering the mysterious origins of their race.",["faction:Alliance"]="Maintaining the safety of Loch Modan's transit roads is crucial for Alliance cohesion between Ironforge and the eastern frontiers.",["profession:Mining"]="Blasting powder is an essential tool of the dwarven trade, utilized equally by miners and excavators seeking to crack the deepest bedrock."},kw={"explorers league","huldar","ironforge","jern hornhelm","loch modan","powder to ironband","prospector stormpike","thelsamar"},rel={"quest:301","npc:prospector-stormpike","npc:jern-hornhelm","npc:huldar","subzone:thelsamar"},m={start="Prospector Stormpike",["end"]="Jern Hornhelm",level="15",faction="Alliance",id=302},src={"Powder to Ironband"}}
E["quest:3681"] = {t="quest",n="Tome of Divinity",z="ironforge",s="Tome of Divinity is a summons directed at developing human paladins visiting Ironforge. Master Brandur Ironhammer bids initiates make the journey south to the Cathedral of Light in Stormwind, where Master Duthorian Rall oversees advanced training in the sacred Tomes of Divinity.",h="Tome of Divinity is a summons directed at developing human paladins visiting Ironforge.",sec={{t="A Summons from Stormwind",b="While dwarven paladins train vigorously beneath the stone arches of Ironforge's High Seat, the broader traditions of the Silver Hand remain deeply entwined with the Church of the Holy Light in human lands. Word sent north from Stormwind calls on promising holy warriors to present themselves directly before the senior priesthood and paladin mentors of the Cathedral of Light.",sp=0},{t="The Road to the Cathedral",b="Master Brandur Ironhammer recognizes when a student has progressed far enough to step into the deeper mysteries of the faith. Journeying south—whether by the subterranean Deeprun Tram or across the mountain passes—brings initiates to Stormwind's Cathedral District, where Duthorian Rall prepares them to study the sacred Tomes and master the rites of redemption.",sp=0}},faq={{q="Why is an Ironforge trainer sending me to Stormwind?",a="Stormwind's Cathedral of Light serves as the administrative heart for advanced Alliance paladin instruction. Brandur Ironhammer directs promising initiates to Master Duthorian Rall so they can undertake the specific canonical trials associated with the sacred Tomes of Divinity.",al={"why go to stormwind","why send to duthorian rall","ironforge to stormwind paladin"},it="purpose"},{q="Who is Brandur Ironhammer?",a="Brandur Ironhammer is a dwarven paladin trainer based in Ironforge's High Seat. He watches over initiates, instructing them in martial devotion and guiding them toward higher studies when their inner connection to the Holy Light matures.",al={"brandur ironhammer","who is brandur"},it="identity"},{q="Who is Duthorian Rall?",a="Duthorian Rall is a senior paladin trainer and prelate stationed inside the Cathedral of Light in Stormwind. He directly tests aspiring paladins through rigorous spiritual trials before entrusting them with the Tomes of Divinity.",al={"duthorian rall","who is duthorian"},it="identity"},{q="What are the Tomes of Divinity?",a="The Tomes of Divinity are sacred texts and doctrinal handbooks used by the Church of the Holy Light to teach paladins the solemn rites of resurrection, self-sacrifice, and unwavering compassion.",al={"what is tome of divinity","tome of divinity meaning"},it="item"},{q="What is the fastest way to reach Stormwind from Ironforge?",a="The quickest and safest route is the Deeprun Tram, an engineering marvel located inside Ironforge's Tinker Town that carries travelers straight beneath the mountains into the heart of Stormwind.",al={"how to get to stormwind","deeprun tram to stormwind"},gp=true},{q="Is this trial required for all Alliance paladins?",a="No. This summons is for human paladins, who study the Tomes under Duthorian Rall in Stormwind's Cathedral of Light. Dwarven paladins begin their own Tome of Divinity trials in Ironforge with Tiza Battleforge.",al={"do dwarves have to do this","paladin class quest requirement"}},{q="Why does Brandur Ironhammer send you to Stormwind?",a="Brandur Ironhammer is answering an official summons from Stormwind's Cathedral of Light. The leaders of the Silver Hand have requested promising paladins report south for rigorous, advanced instruction. Recognizing your growing strength and devotion, Brandur knows you have reached a critical point in your calling where standard training in Ironforge is no longer enough; you are ready to study the sacred Tomes directly under Duthorian Rall.",al={"brandur ironhammer motive","why does brandur send me","brandur ironhammer stormwind"},it="motive",add=true},{q="Why are you chosen for this task instead of someone else?",a="You are chosen because the summons specifically calls for developing paladins who have proven ready for the deeper mysteries of the Holy Light. Neither guards nor seasoned veterans can undertake this journey for you, as the Tomes of Divinity represent an intensely personal spiritual and martial trial required to advance within the Silver Hand.",al={"why me tome of divinity","why send me stormwind paladin","why not another paladin"},it="why_me",add=true}},ang={["class:Paladin"]="This quest marks your official transition from a mere martial novice into an ordained servant of the Holy Light capable of channeling its most profound restorative miracles.",["race:Dwarf"]="Dwarven paladins have forged their own proud traditions in Khaz Modan, taking up the Tomes of Divinity in Ironforge even as their human brethren are summoned to Stormwind.",["faction:Alliance"]="The shared training of holy warriors in Stormwind strengthens the spiritual and military bond uniting Ironforge and the kingdom of Stormwind."},kw={"brandur ironhammer","cathedral of light","duthorian rall","ironforge","paladin","redemption","stormwind","tome of divinity"},rel={"npc:brandur-ironhammer","npc:duthorian-rall","subzone:cathedral-of-light","topic:stormwind-kingdom","topic:light"},m={start="Brandur Ironhammer",["end"]="Duthorian Rall",level="12",faction="Alliance",id=3681},src={"Tome of Divinity (5)"}}
E["quest:385"] = {t="quest",n="Crocolisk Hunting",z="ironforge",s="Farstrider Lodge in Loch Modan does a steady, if dangerous, trade in the skins and meat of the local crocolisks. Marek Ironheart regularly seeks out hardy trackers willing to brave the lake's shores and islands to harvest these prized beasts. For hunters eager to test their mettle against snapping jaws and tough hides, the Loch offers both sport and profit.",h="Farstrider Lodge in Loch Modan does a steady, if dangerous, trade in the skins and meat of the local...",sec={{t="A Lucrative Quarry",b="While Loch Modan is prized for its serene mountain waters, the lake harbors fierce predators beneath its surface. Crocolisks thrive along the shallows and muddy banks, making crossing or fishing perilous for the unwary. Yet for the outdoorsmen stationed at Farstrider Lodge, these dangerous reptiles are valuable game. Craftsmen and tailors throughout Khaz Modan constantly seek out durable crocolisk hides to fashion into rugged armor and leather goods, while rustic taverns pay good coin for fresh cuts of their flavorful, lean tail meat.",sp=0},{t="Jaws in the Shallows",b="Hunting the Loch's crocolisks is no task for novice trappers. Entrenched primarily around the rocky islets dotting the lake, these brutes possess bone-crushing jaws lined with razor-sharp teeth. Dwarven veterans like Marek Ironheart carry plenty of scars from wrestling the beasts into submission, warning newcomers that a single misstep in the water can cost a limb. Successfully skinning and butchering them requires patience, sturdy steel, and a willingness to step right into the reptile's hunting ground.",sp=0}},faq={{q="Why are crocolisks hunted in Loch Modan?",a="Merchants and craftsmen value crocolisk hides for fashioning rugged clothing and leather armor, while their meat is considered a tasty local delicacy. Farstrider Lodge conducts a steady trade in these resources to supply traders passing through Khaz Modan.",al={"why hunt crocolisks","crocolisk meat skin use","why marek wants crocs"},it="purpose"},{q="Where are the crocolisks usually found?",a="The crocolisks populate the muddy shallows, shoreline banks, and especially the rocky islands nestled in the center of the Loch.",al={"crocolisk location","where to find crocs loch modan","where are crocolisks"},gp=true},{q="Who is Marek Ironheart?",a="Marek Ironheart is a veteran dwarven mountaineer and hunter stationed at Farstrider Lodge in southeastern Loch Modan. He trades in local wildlife materials and loves recounting tales of surviving close calls with the Loch's fiercest beasts.",al={"marek ironheart","who gives crocolisk hunting","quest giver marek"},it="identity"},{q="What makes hunting them so hazardous?",a="Crocolisks in Loch Modan are aggressive, territorial predators with immense jaw strength and teeth like daggers. Hunters must enter deep water or isolated islets to engage them, risking sudden ambushes in terrain favoring the reptiles.",al={"are crocs dangerous","danger of crocolisks","why are crocs hard to hunt"},it="danger"},{q="Is crocolisk meat actually safe and edible?",a="Yes, crocolisk meat is prized by frontier cooks and tavern patrons across the dwarven lands for its firm texture and rich, hearty flavor once properly dressed and roasted.",al={"can you eat crocolisk","crocolisk meat edible","croc taste"}},{q="What is the Farstrider Lodge?",a="Farstrider Lodge is a scenic outpost in southeastern Loch Modan serving as a haven and staging ground for Alliance hunters, trackers, and mountaineers who monitor the wild reaches of the valley.",al={"what is farstrider lodge","farstrider lodge purpose","where is farstrider lodge"},it="place"},{q="Why does Marek Ironheart want crocolisks hunted?",a="Marek Ironheart conducts steady trade out of Farstrider Lodge with merchants who pay good coin for crocolisk hides and flesh. The fierce reptiles hold the islands in the Loch, making hunting hazardous, but quality specimens fetch a reliable profit from craftsmen and eager buyers.",al={"marek ironheart motive","why hunt crocolisks","why does marek want crocs"},it="motive",add=true},{q="What is the Crocolisk Meat for?",a="Marek gathers crocolisk meat to sell to visiting traders and travelers. While wrestling the ferocious beasts is perilous, certain adventurous patrons and merchants specifically enjoy the taste and pay well for fresh cuts.",al={"crocolisk meat use","why collect crocolisk meat","what is crocolisk meat used for"},it="item",add=true},{q="What is the Crocolisk Skin for?",a="The skins are prized by merchants and tanners for crafting durable clothing and sturdy leather armor. Marek sells the hides you bring back to sustain the lodge's trade with passing buyers.",al={"crocolisk skin use","why collect crocolisk skins","what is crocolisk hide for"},it="item",add=true},{q="Why are the crocolisks found in Loch Modan?",a="The crocolisks are ferocious native predators that have entrenched themselves primarily across the islands and shores of Loch Modan. Their thick hides and savage jaws make them a defining danger of the freshwater lake.",al={"loch modan crocs origin","why are crocolisks here","who are the crocs"},it="target",add=true}},ang={["class:Hunter"]="Farstrider Lodge is an ideal proving ground for aspiring marksmen and beastmasters testing their nerve against Loch Modan's aquatic terrors.",["profession:Cooking"]="Tough, lean crocolisk meat provides frontier campfires with a hearty staple for savory stews and roasts.",["race:Dwarf"]="Mountaineers take pride in taming the wilderness of Loch Modan, viewing crocolisk hunting as both practical survival and an honest living."},kw={"crocolisk hunting","crocolisk meat","crocolisk skin","dwarf hunter","farstrider lodge","loch modan","marek ironheart","the loch"},rel={"npc:marek-ironheart","subzone:farstrider-lodge","subzone:the-loch","zone:lochmodan"},m={start="Marek Ironheart",level="15",faction="Alliance",id=385,ri={"Crocolisk Meat","Crocolisk Skin (Classic)"}},src={"Crocolisk Hunting"}}
E["quest:4512"] = {t="quest",n="A Little Slime Goes a Long Way",z="ironforge",s="In the bustling halls of Ironforge, the gnome researcher Laris Geardawdle seeks to uncover the evolutionary secrets of Azeroth by studying oozes and slimes. Curious about the Royal Apothecary Society's strange fascination with these vile puddles, he tasks Alliance adventurers with journeying to tainted Felwood to bottle up specimen samples.",h="In the bustling halls of Ironforge, the gnome researcher Laris Geardawdle seeks to uncover the evolutionary...",sec={{t="A Peculiar Obsession",b="While most scholars of the Explorers' League concern themselves with ancient titan relics or buried dwarven genealogies, Laris Geardawdle has set his inquisitive mind on a squelchier subject: oozes. Ubiquitous across wetlands, cursed woods, and damp ruins, these living puddles defy standard biological classification. Having witnessed Forsaken apothecaries scooping up slime samples across Lordaeron, Laris has resolved to understand what makes these gelatinous horrors so uniquely interesting to the Undercity's alchemists.",sp=0},{t="The Primordial Secretion",b="Laris harbors a controversial theory that oozes are not mere unnatural vermin or magical byproducts, but primordial secretions intimately tied to the planetary genesis of Azeroth itself. To prove this hypothesis, he dispatches brave scouts across the ocean into the blighted canopy of Felwood to capture specimens of Cursed and Tainted Oozes in specially crafted jars.",sp=0},{t="Proving Gnomish Worth",b="Behind Laris's academic pursuit lies a deeply personal motivation shared by many of his displaced kin. Following the devastating radioactive fall of Gnomeregan, thousands of gnomes found sanctuary as refugees within the Great Forge of Ironforge. By securing a breakthrough discovery for the Explorers' League, Laris hopes to silence dwarven skeptics and affirm that welcoming gnomes into the mountain city was no act of simple charity, but an enduring asset to Alliance science.",sp=0}},faq={{q="Who is Laris Geardawdle?",a="Laris Geardawdle is a gnomish researcher and scholar residing in Ironforge. Working alongside the Explorers' League, he dedicates himself to understanding the biological origins of oozes and slimes across Azeroth.",al={"laris geardawdle","who is the quest giver","gnome ooze guy"},it="identity"},{q="Why does Laris care so much about ooze?",a="Laris suspects that oozes may be tied to the planetary origin of Azeroth as primordial secretions. Additionally, noticing that the Forsaken's Royal Apothecary Society aggressively harvests slime samples has made him eager to unravel their secret properties before the Horde does.",al={"why study slimes","why ooze jars","ooze theory"},it="motive"},{q="Where do you gather the ooze samples?",a="The samples must be gathered from Cursed Oozes and Tainted Oozes wandering the corrupted forests of Felwood in northern Kalimdor, using empty glass containers provided by Laris.",al={"where are the oozes","tainted ooze location","cursed ooze location"},it="place",gp=true},{q="Why are the Forsaken collecting oozes?",a="The Royal Apothecary Society routinely experiments with toxins, blights, and biological horrors to advance Forsaken alchemy. Their interest in raw oozes signals to Alliance scholars that the creatures harbor virulent or mutagenic compounds.",al={"undercity oozes","royal apothecary society slime","why do forsaken want ooze"},it="conflict"},{q="How does this quest connect to the fall of Gnomeregan?",a="Laris feels the pressure of being a refugee in Ironforge after Gnomeregan's loss to troggs and radiation. He believes that securing a major scientific triumph for the Explorers' League will prove that granting asylum to gnomes was truly worthwhile for the dwarven hosts.",al={"gnomeregan connection","dwarf gnome relations","gnome refugees ironforge"},it="history"},{q="What happens after you deliver the samples?",a="Laris immediately begins testing the specimens in his laboratory setup in Ironforge, further developing his theories regarding ooze taxonomy and elemental origins.",al={"slime quest follow up","what next after ooze jars"},it="next_step"},{q="What are the Filled Ooze Jars for?",a="The jars hold fresh samples extracted from the remains of cursed and tainted oozes found in Felwood. Laris Geardawdle requires them for scientific experimentation in Ironforge. He hopes to uncover the true nature of ooze creatures and prove his controversial theory that slimes are connected to the primordial creation of Azeroth itself.",al={"filled cursed ooze jar","filled tainted ooze jar","what are the ooze jars used for","ooze samples use"},it="item",add=true},{q="What creatures are you sent after in Felwood?",a="You are sent to hunt the cursed and tainted oozes lurking in the corrupted wilds of Felwood. Felwood has been heavily warped by demonic magic, producing bizarre and volatile mutations. Laris wants specimens from these particular slimes to compare against other varieties found across Azeroth and see how environmental corruption alters their makeup.",al={"what are we fighting","cursed ooze target","tainted ooze felwood","who do we kill"},it="target",add=true}},ang={["race:Gnome"]="Laris embodies the relentless intellectual drive of gnomes rebuilding their reputations and pride after the heartbreaking loss of Gnomeregan.",["race:Dwarf"]="Though traditional dwarven excavators favor stone and metal over gelatinous sludge, the Explorers' League nonetheless benefits from Laris's eccentric drive.",["faction:Alliance"]="Monitoring the Royal Apothecary Society's gathering habits gives the Alliance vital intelligence on what sinister brews the Undercity may be concocting."},kw={"cursed ooze","explorers league","felwood","gnomeregan","ironforge","laris geardawdle","ooze","royal apothecary society","slime","tainted ooze"},rel={"npc:laris-geardawdle","zone:felwood","zone:ironforge","topic:explorers-league","topic:royal-apothecary-society","zone:gnomeregan","topic:gnome","zone:undercity"},m={start="Laris Geardawdle",faction="Alliance",id=4512,ri={"Filled Cursed Ooze Jar","Filled Tainted Ooze Jar"}},src={"A Little Slime Goes a Long Way"}}
E["quest:4513"] = {t="quest",n="A Little Slime Goes a Long Way",z="ironforge",s="Following his initial study of tainted specimens, the gnome researcher Laris Geardawdle seeks untainted ooze samples to understand how these strange creatures adapt to their environment. Having realized that oozes absorb the corrupted nature of places like Felwood, he sends adventurers to discover and gather pure, unpolluted specimens from across Kalimdor.",h="Following his initial study of tainted specimens, the gnome researcher Laris Geardawdle seeks untainted ooze...",sec={{t="A Matter of Purity",b="Laris Geardawdle's preliminary experiments in Ironforge hit an immediate stumbling block: the oozes he previously examined were thoroughly polluted by the dark energies of Felwood. While this demonstrated that oozes absorb and reflect the traits of their surroundings, it left him without a control group. To understand the baseline nature of ooze life, he needs specimens untouched by demonic taint or urban filth.",sp=0},{t="Tracking the Primal Slime",b="Finding untainted slimes is no simple task on an Azeroth scarred by corruption and war. The trail ultimately leads far south to the prehistoric basin of Un'Goro Crater, where Glutinous Oozes thrive in an isolated, primordial ecosystem. By securing samples from these wild creatures, adventurers provide Laris with the rare, pure material he needs to uncover how these amorphous beings interact with Azeroth's living biomes.",sp=1}},faq={{q="Why does Laris Geardawdle need pure ooze samples?",a="His earlier specimens were tainted by the corrupt energies of Felwood. To test his theory that slimes adapt and reflect their immediate environments, Laris needs pristine samples from an unpolluted habitat to serve as a clean baseline for study.",al={"why pure ooze","laris pure slime","what is pure ooze"},it="motive"},{q="Where are the pure oozes located?",a="Pure samples can be harvested from the Glutinous Oozes dwelling in the lush, prehistoric wilderness of Un'Goro Crater in southern Kalimdor.",al={"where find pure ooze","pure sample jars location","where are pure slimes"},gp=true},{q="Who is Laris Geardawdle?",a="He is an inquisitive gnomish researcher stationed in Ironforge, deeply dedicated to unraveling the biological mysteries of Azeroth's slimes and oozes.",al={"who is laris","laris geardawdle lore"},it="identity"},{q="What makes oozes so interesting to researchers?",a="Oozes possess a unique biological adaptability, readily absorbing and reflecting the magical, environmental, and corruptive aspects of the regions they inhabit.",al={"why study slime","ooze lore"}},{q="Does this follow an earlier task for Laris?",a="Yes. Laris previously asked for oozes to begin his research, but the initial samples revealed heavy demonic taint from Felwood, prompting this search for untarnished slimes.",al={"previous quest laris","what came before this"},it="history"},{q="What does Laris intend to do with the samples?",a="He intends to compare the pure samples against corrupted ones to understand how environmental changes affect living creatures and, by extension, the wider population of Azeroth.",al={"laris ooze research","what is slime used for"},it="purpose"},{q="What is the Filled Pure Sample Jar for?",a="These jars hold uncorrupted slime taken from oozes living in pristine wilderness. Laris Geardawdle discovered that slimes in Felwood took on that forest's demonic taint, revealing that oozes naturally absorb and reflect the traits of their surrounding environment. He needs jars of pure, uncontaminated slime to serve as a baseline for his research into how these creatures adapt and how such pollution might impact Azeroth as a whole.",al={"filled pure sample jar","pure sample jar purpose","what are sample jars for"},it="item",add=true},{q="What are the pure oozes you are sent to find?",a="You are sent to harvest samples from glutinous oozes found in the primeval, untamed basin of Un'Goro Crater. Unlike the slimes dwelling in Felwood, which have absorbed demonic corruption, Un'Goro's oozes dwell in a thriving, untouched wilderness. Because oozes take on the essence of their environment, these specimens offer Laris the pure, unpolluted slime he needs to understand their biology before outside blight alters them.",al={"pure oozes","which oozes are pure","glutinous oozes"},it="target",add=true}},ang={["race:Gnome"]="Laris embodies the quintessential gnomish scientific method, insisting on isolating variables and finding an uncontaminated control group before drawing broad conclusions.",["faction:Alliance"]="Operating out of Ironforge, Alliance adventurers are tasked with journeying into the untamed wilds of Kalimdor to support gnomish scientific inquiry."},kw={"felwood","glutinous ooze","ironforge","laris geardawdle","ooze research","pure sample jars","un'goro crater"},rel={"npc:laris-geardawdle","quest:4512","zone:ironforge","zone:ungoro","zone:felwood"},m={start="Laris Geardawdle",faction="Alliance",id=4513,ri={"Filled Pure Sample Jar"}},src={"A Little Slime Goes a Long Way (2)"}}
E["quest:467"] = {t="quest",n="Stonegear's Search",z="ironforge",s="Stonegear's Search is an Alliance directive directing adventurous travelers to Pilot Stonegear at Steelgrill's Depot in Dun Morogh. The enthusiastic siege engine operator has caught wind of an exotic mineral and seeks a daring explorer to track down fresh fuel for his tank's ordnance.",h="Stonegear's Search is an Alliance directive directing adventurous travelers to Pilot Stonegear at...",sec={{t="A Tinkerer's Ambition",b="Dwarven siege engines are legendary feats of engineering, but their operators are rarely content leaving well enough alone. Word around Ironforge and Loch Modan quickly spreads that Pilot Stonegear, stationed just outside the capital, is scheming to boost his war machine's punch. Whether pointed his way by Pilot Longbeard or Mountaineer Kadrell, travelers are recruited simply to meet the ambitious pilot and hear his proposal.",sp=0},{t="Heading to Steelgrill's Depot",b="Pilot Stonegear makes his workshop at Steelgrill's Depot, the proving ground and staging yard tucked along the road just east of Kharanos. Amid clanking gears and spewing steam, Stonegear keeps watch for prospectors brave enough to pursue a volatile, rare ore known to ignite his tank's firepower to devastating new heights.",sp=0}},faq={{q="Who offers this quest?",a="You can be directed to Pilot Stonegear by either Pilot Longbeard in Ironforge or Mountaineer Kadrell along the road in Loch Modan.",al={"quest giver","who starts stonegear search","where to get quest"},gp=true},{q="Where can I find Pilot Stonegear?",a="Pilot Stonegear is stationed at Steelgrill's Depot in Dun Morogh, just down the path northeast of Kharanos.",al={"stonegear location","where is pilot stonegear","steelgrills depot stonegear"},gp=true},{q="What does Pilot Stonegear need?",a="Stonegear loves modifying his siege engine and is obsessed with finding rare mineral deposits that can dramatically enhance the firepower of his tank's munitions.",al={"stonegear goal","why does stonegear want me","what does stonegear want"},it="wants"},{q="What quest follows this one?",a="Once you report to Pilot Stonegear at the depot, he sends you on the quest Search for Incendicite, directing you to procure volatile ore from the wetlands.",al={"next quest","stonegear follow up","what comes after stonegears search"},it="next_step",gp=true},{q="Is this quest Alliance-only?",a="Yes, Pilot Stonegear and his contacts are loyal members of the Ironforge military and the Alliance.",al={"can horde do stonegears search","faction requirement"},it="side",gp=true},{q="Why is the depot interested in wild ores?",a="Dwarven engineers and tank pilots constantly experiment with new incendiary compounds, pyrotechnics, and volatile elements to give their war machines an edge against troggs, dark irons, and wild beasts.",al={"why siege engine ore","dwarf tank gunpowder"},it="purpose"},{q="Why do the quest givers send you to Pilot Stonegear?",a="Both Pilot Longbeard and Mountaineer Kadrell know that Pilot Stonegear is obsessed with tinkering on his siege engine and constantly looking to augment its firepower. When rumors reached them of a rare, explosive ore that Stonegear wants tracked down, they immediately thought of pointing a roaming adventurer his way rather than letting his restless ambition go unanswered.",al={"why send to stonegear","why does kadrell want this done","longbeard motive"},it="motive",add=true},{q="Why do they need an adventurer instead of handling it themselves?",a="Pilot Longbeard has duties tending to his own machine and affairs, while Mountaineer Kadrell is tasked with patrolling and guarding Loch Modan against threats. Investigating distant rumors of exotic ore for a tank enthusiast requires someone with wandering boots and free time, making a capable traveler the ideal scout for Stonegear's ambitions.",al={"why send me","why not longbeard or kadrell","why need an adventurer"},it="why_me",add=true}},ang={["race:Dwarf"]="For dwarven mountaineers and mechanists, lending a hand to a fellow pilot at Steelgrill's Depot is a proud duty in refining the arsenal of Khaz Modan.",["race:Gnome"]="Gnomish innovators will easily appreciate Pilot Stonegear's desire to push conventional siege weaponry beyond standard safety limits.",["profession:Mining"]="Miners with an eye for exotic and combustible earth will find Stonegear's rumors of rare subterranean ore right up their alley.",["profession:Engineering"]="Engineers who spend their days tinkering with high explosives can respect Stonegear's dedication to boosting his tank's firepower."},kw={"dun morogh","incendicite","kadrell","longbeard","pilot stonegear","siege engine","steelgrill's depot","stonegear"},rel={"npc:pilot-stonegear","quest:466","subzone:steelgrill-s-depot","zone:dunmorogh"},m={start="Pilot Longbeard, Mountaineer Kadrell",["end"]="Pilot Stonegear",level="23",faction="Alliance",id=467},src={"Stonegear's Search"}}
E["quest:5639"] = {t="quest",n="Desperate Prayer",z="ironforge",s="Desperate Prayer is a rite of passage for dwarven priests coming of age in Ironforge. Dispatched by High Priest Rohan, acolytes journey through the Deeprun Tram to Stormwind to continue their training under High Priestess Laurena. Reaching the grand Cathedral of Light marks an initiate's transition into deeper mysteries of healing and survival.",h="Desperate Prayer is a rite of passage for dwarven priests coming of age in Ironforge.",sec={{t="A Summons to Stormwind",b="Within the stone vaults of Ironforge's Mystic Ward, High Priest Rohan oversees dwarven initiates dedicated to the Holy Light. When an acolyte demonstrates sufficient discipline and faith, Rohan directs them southwest to the human kingdom of Stormwind. Human and dwarven clerics maintain close spiritual bonds, and advanced theological instruction is centralized in the grand halls of Stormwind City.",sp=0},{t="The Cathedral of Light",b="Upon arriving via the subterranean Deeprun Tram, acolytes ascend to the Cathedral Square. There, within the majestic Cathedral of Light, High Priestess Laurena tests candidates on behalf of the Church. Her instruction focuses on the desperate appeals a priest must make in the crucible of battle—pleas for divine intervention when physical endurance fails and death looms near.",sp=0}},faq={{q="Who sends me on this quest?",a="High Priest Rohan gives you this quest. He presides over the dwarven clergy in the Hall of Mysteries within Ironforge's Mystic Ward.",al={"who gives quest","quest giver","rohan location"},it="identity"},{q="Where do I need to go to complete this?",a="You need to travel to the Cathedral of Light, located at the heart of Cathedral Square in Stormwind City. High Priestess Laurena waits inside the main sanctuary.",al={"where is laurena","where to turn in","stormwind turn in"},it="place",gp=true},{q="What is the best way to get to Stormwind from Ironforge?",a="The safest and fastest route is the Deeprun Tram, an engineering marvel constructed by the gnomes. Its entrance is located in the eastern portion of Ironforge, connecting directly to the Dwarven District of Stormwind.",al={"how to get to stormwind","travel to stormwind","tram location"},gp=true},{q="Why must a dwarf priest go to a human city to train?",a="The Church of the Holy Light is rooted deeply in human tradition, and its primary seat of learning is the Cathedral of Light. Dwarven and human priesthoods work in tandem, sharing teachings and traditions across the Alliance.",al={"why stormwind","dwarf human church","why laurena"},it="why_here"},{q="What ability does this training unlock?",a="This quest line initiates you into learning Desperate Prayer, an instantaneous prayer of self-preservation that rapidly restores a priest's health in dire emergencies.",al={"quest reward","what spell do i get","desperate prayer ability"},it="power",gp=true},{q="Does this quest involve combat?",a="No. The quest is purely a pilgrimage and emissary mission, requiring you to travel safely from Ironforge to Stormwind to introduce yourself to High Priestess Laurena.",al={"is there fighting","quest combat","travel quest"},gp=true},{q="Why does High Priest Rohan send you to Stormwind?",a="High Priestess Laurena in Stormwind has reached out requesting your presence, deeming you ready to prove your worth for the next level of your sacred training. Rohan honors this call from the Cathedral of Light, trusting that your tutelage under Laurena will strengthen your devotion and deepen your command over the Light's blessings.",al={"why rohan send you","why go to stormwind priest","rohan motive desperate prayer"},it="motive",add=true}},ang={["class:Priest"]="This pilgrimage marks your graduation from local training in Ironforge into the broader hierarchy of the Church of the Holy Light.",["race:Dwarf"]="For young Khaz Modan dwarves, traveling to Stormwind offers an early glimpse of human culture, grand architecture, and shared spiritual devotion.",["faction:Alliance"]="The shared training of priests reflects the deep spiritual union and institutional cooperation between Ironforge and Stormwind."},kw={"cathedral of light","desperate prayer","ironforge","laurena","mystic ward","priest","rohan","stormwind"},rel={"npc:high-priest-rohan","npc:high-priestess-laurena","subzone:cathedral-of-light","topic:stormwind-kingdom","topic:light"},m={start="High Priest Rohan",["end"]="High Priestess Laurena",level="10",faction="Alliance",id=5639},src={"Desperate Prayer (Ironforge)"}}
E["quest:5645"] = {t="quest",n="A Lack of Fear",z="ironforge",s="A Lack of Fear is a rite-of-passage summons for dwarven priests, calling promising disciples back to the grand halls of Ironforge. High Priest Rohan awaits in the Mystic Ward to test their discipline and bestow teachings tailored to their growing resilience.",h="A Lack of Fear is a rite-of-passage summons for dwarven priests, calling promising disciples back to the...",sec={{t="A Summons to Ironforge",b="Priests serving the Alliance abroad are routinely directed by their local mentors to report back to their order's senior clergy. For dwarven disciples, that guidance leads straight to High Priest Rohan in the heart of Ironforge's Mystic Ward. The summons marks a turning point where basic spiritual practice gives way to deeper, trial-tested applications of holy magic.",sp=0},{t="The Trials of Fortitude",b="High Priest Rohan does not simply teach liturgy; dwarven tradition views the Light as a shield and an unyielding bulwark in physical conflict. Reporting for this test acknowledges that the initiate has survived baptism through fire in the wider world and possesses the mettle required to master fear itself on the front lines.",sp=0}},faq={{q="What is the purpose of this quest?",a="It serves as a formal summons from local priest trainers to High Priest Rohan in Ironforge, directing seasoned initiates to undertake advanced instruction and earn the specialized spiritual gifts practiced by the city's priesthood.",al={"why do i have to go to rohan","what does a lack of fear do","priest quest level 20 ironforge"},it="purpose"},{q="Who is High Priest Rohan?",a="High Priest Rohan is the senior leader of the dwarven priesthood in Ironforge. He trains disciples within the Hall of Mysteries in the Mystic Ward, focusing on steadfast devotion and martial resilience.",al={"who is rohan","high priest rohan lore"},it="identity"},{q="Where can High Priest Rohan be found?",a="Rohan resides inside the Hall of Mysteries, located within the Mystic Ward in the western quarters of Ironforge.",al={"where is rohan","rohan location","how to find high priest rohan"},it="place",gp=true},{q="Why is this called 'A Lack of Fear'?",a="The quest represents the priest's preparation to receive Fear Ward, a unique protective blessing cultivated by dwarven devotees of the Holy Light to safeguard minds against panic and supernatural terror.",al={"meaning of lack of fear","fear ward quest"},it="name"},{q="Who sends the priest to Ironforge?",a="Initiates are typically dispatched by their local trainers, such as High Priestess Laurena in Stormwind or Priestess Alathea in Darnassus, who direct their students to honor their heritage or study under Rohan's tutelage.",al={"who starts a lack of fear","quest givers for lack of fear"},it="origin"},{q="Does this quest involve combat?",a="No. The quest requires traveling to Ironforge and speaking to High Priest Rohan, who teaches Fear Ward.",al={"do i have to fight","is there combat in a lack of fear"},gp=true},{q="Why are you being summoned to High Priest Rohan?",a="Priest trainers in other cities recognize that your faith and combat prowess have grown significantly. High Priest Rohan in Ironforge oversees the training of Alliance priests in the region, particularly the unique disciplines and rites of the dwarves. He has summoned you because you have proven yourself ready to face your next trial and learn more advanced sacred teachings.",al={"why see rohan","a lack of fear motive","why send to ironforge"},it="motive",add=true}},ang={["class:Priest"]="This summons marks your coming of age within the priesthood, qualifying you to learn specific holy techniques refined by Ironforge's stalwart clergy.",["race:Dwarf"]="Returning to Rohan honors your people's distinct blend of unshakeable faith, physical fortitude, and martial grit in service to the Holy Light.",["faction:Alliance"]="Alliance priesthoods maintain close communion across capitals, sending acolytes across borders to study under master clergy in Ironforge."},kw={"alathea","fear ward","hall of mysteries","ironforge","laurena","mystic ward","priest","rohan"},rel={"npc:high-priest-rohan","zone:ironforge","subzone:mystic-ward","topic:light"},m={start="High Priest Rohan / High Priestess Laurena / Priestess Alathea",["end"]="High Priest Rohan",level="20",faction="Alliance",id=5645},src={"A Lack of Fear"}}
E["quest:5677"] = {t="quest",n="Arcane Feedback",z="ironforge",s="Arcane Feedback is a priest quest given by High Priest Rohan in Ironforge to human acolytes visiting Khaz Modan. Rohan directs the developing priest home to the Cathedral of Light in Stormwind to receive teachings tailored specifically to the traditions of humankind. It marks a key moment of progression where young disciples begin mastering racial manifestations of their faith.",h="Arcane Feedback is a priest quest given by High Priest Rohan in Ironforge to human acolytes visiting Khaz...",sec={{t="A Gentle Redirection",b="When a human priest seeks advanced spiritual tutelage in the halls of the Mystic Ward, High Priest Rohan greets them with reverence but sets a boundary. While dwarven and human priests share devotion to the Holy Light, each civilization nurtures its own particular rites, disciplines, and defensive prayers. Rather than imparting Ironforge's unique secrets, Rohan sends human clergy back to their cultural roots in Elwynn, ensuring they master their people's distinct heritage.",sp=0},{t="Return to the Cathedral",b="Upon returning to Stormwind City, the acolyte reports to High Priestess Laurena within the grand Cathedral of Light. Laurena is relieved to see Rohan's guidance reach the traveler, welcoming them back just as their nascent powers begin to flourish. This return paves the way for deeper initiation into the Kingdom of Stormwind's spiritual practices, preparing practitioners to wield the Holy Light against the rising threats encircling the realm.",sp=0}},faq={{q="Why does High Priest Rohan refuse to teach human priests?",a="High Priest Rohan respects human practitioners, but dwarven clergy hold distinct rites and blessings passed down through their own cultural lineage. He believes human priests must learn the specific, specialized techniques preserved by their own mentors in Stormwind.",al={"why send to stormwind","why rohan won't train","dwarf priest won't train me"},it="motive"},{q="Who is High Priestess Laurena?",a="High Priestess Laurena is a prominent spiritual leader and trainer stationed inside the Cathedral of Light in Stormwind City. She oversees the growth of promising human priests, guiding their intermediate studies and rites.",al={"high priestess laurena","who is laurena","cathedral priest trainer"},it="identity"},{q="Where can High Priest Rohan be found?",a="High Priest Rohan resides in the Hall of Mysteries, located within the Mystic Ward in the great dwarven mountain city of Ironforge.",al={"rohan location","where is high priest rohan","find rohan"},gp=true},{q="What is the purpose of this quest?",a="It serves as a breadcrumb quest directing intermediate human priests back from dwarven lands to their primary racial training hub in the Cathedral of Light, enabling them to pursue species-specific spiritual techniques.",al={"arcane feedback quest purpose","why do this quest","what does this quest do"},it="purpose"}},ang={["class:Priest"]="This quest represents a pivotal milestone where priests discover that different races channel and express the Holy Light through unique cultural traditions.",["race:Human"]="Human priests are gently recalled from dwarven sanctuaries back to Stormwind to ground themselves in the sacred ways of the Cathedral of Light.",["race:Dwarf"]="Dwarven mentors like High Priest Rohan honor their alliance with humans while keeping the specific rites of Khaz Modan within their own folk."},kw={"arcane feedback","cathedral of light","high priest rohan","high priestess laurena","ironforge","mystic ward","priest quest","stormwind"},rel={"npc:high-priest-rohan","npc:high-priestess-laurena","subzone:cathedral-of-light","topic:light","topic:stormwind-kingdom"},m={start="High Priest Rohan",["end"]="High Priestess Laurena",level="20",faction="Alliance",id=5677},src={"Arcane Feedback (Ironforge)"}}
E["quest:6388"] = {t="quest",n="Gryth Thurden",z="ironforge",s="This errand introduces adventurers to Ironforge's gryphon network by tasking them with carrying a bundle of ceremonial tools to the city's gryphon master. Entrusted with the Honorary Picks by Golnir Bouldertoe, the courier must deliver them to Gryth Thurden so they can be dispatched back to Loch Modan.",h="This errand introduces adventurers to Ironforge's gryphon network by tasking them with carrying a bundle of...",sec={{t="A Courier for the Miners",b="After traveling from Loch Modan to the Great Forge, couriers receive a bundle of Honorary Picks from Golnir Bouldertoe meant for Brock Stoneseeker's mining apprentices. Rather than making the trek back down the mountain passes on foot, Golnir advises taking advantage of the dwarven gryphon network, sending the messenger across the city to coordinate with Ironforge's master handler.",sp=0},{t="Taking Wing to Thelsamar",b="Gryth Thurden manages the flight roosts within the great mountain hall, connecting Ironforge to dwarven settlements across Khaz Modan. Thurden agrees to arrange transport back to Thorgrum Borrelson in Thelsamar provided the adventurer has already scouted the route and spoken with the local handler there. The delivery teaches fledgling heroes the vital role aerial couriers play in tying the dwarven kingdom together.",sp=0}},faq={{q="What are the Honorary Picks for?",a="The Honorary Picks are ceremonial tools crafted in Ironforge by Golnir Bouldertoe for the students of Brock Stoneseeker, a mining instructor stationed in Thelsamar.",al={"honorary picks","why honorary picks","picks for brock"},it="item"},{q="Who is Gryth Thurden?",a="Gryth Thurden is the master gryphon handler stationed in Ironforge. He oversees flight routes connecting the dwarven capital to surrounding settlements throughout Khaz Modan and beyond.",al={"who is gryth thurden","ironforge gryphon master","gryth thurden lore"},it="identity"},{q="Where is Gryth Thurden located in Ironforge?",a="Gryth Thurden can be found at the Great Forge's flight roost, near the main central thoroughfare and gates of Ironforge.",al={"gryth thurden location","where to find gryth thurden","ironforge flight master"},it="place",gp=true},{q="Why do I need to talk to Thorgrum Borrelson first?",a="Gryphon handlers only dispatch riders along charted routes. Before Gryth Thurden can send a rider to Thelsamar, the traveler must have established contact with Thorgrum Borrelson, the handler stationed in Loch Modan.",al={"thorgrum borrelson requirement","why need thelsamar flight path","cant fly to thelsamar"},gp=true},{q="What happens after giving the picks to Gryth Thurden?",a="Once Gryth inspects the parcel, he prepares a gryphon flight allowing you to return to Thelsamar and deliver the tools directly to Brock Stoneseeker.",al={"what next after gryth thurden","next quest after gryth thurden"},it="next_step"},{q="Who sends you to Gryth Thurden?",a="Golnir Bouldertoe, an artisan found working around the Great Forge in Ironforge, gives you the picks and directs you to Gryth.",al={"who starts gryth thurden","who gives this quest"},it="origin"},{q="Why does Golnir Bouldertoe send you to Gryth Thurden?",a="Golnir Bouldertoe has prepared the Honorary Picks meant for Brock Stoneseeker's mining students out in Thelsamar. Instead of having you hike back down through the snowy pass on foot, Golnir directs you to Gryth Thurden, Ironforge's gryphon master, so you can learn how to arrange a gryphon flight directly back across the mountains.",al={"why send to gryth","golnir bouldertoe motive","why gryth thurden picks"},it="motive",add=true}},ang={["race:Dwarf"]="For dwarves, relying on gryphons is a point of ancestral pride and practical necessity, linking mountain halls across treacherous peaks.",["profession:Mining"]="The delivery directly aids Brock Stoneseeker's mining apprentices in Loch Modan, celebrating their craft with honorary picks forged in the capital.",["faction:Alliance"]="Ironforge's gryphon roosts serve as an indispensable transport hub for Alliance envoys moving between Dun Morogh, Loch Modan, and the broader kingdoms."},kw={"flight master","golnir bouldertoe","gryth thurden","honorary picks","ironforge","loch modan","thelsamar","thorgrum borrelson"},rel={"zone:ironforge","quest:6392","npc:golnir-bouldertoe","npc:thorgrum-borrelson","subzone:thelsamar"},m={start="Golnir Bouldertoe",["end"]="Gryth Thurden",level="10",faction="Alliance",id=6388},src={"Gryth Thurden (Classic)"}}
E["quest:6391"] = {t="quest",n="Ride to Ironforge",z="ironforge",s="Ride to Ironforge is an introductory courier quest that sends newly trained adventurers on their first gryphon flight from Thelsamar in Loch Modan into the dwarven capital. Entrusted with a list of top mining students from Brock Stoneseeker, the traveler carries the dispatch straight to Golnir Bouldertoe at the Great Forge.",h="Ride to Ironforge is an introductory courier quest that sends newly trained adventurers on their first...",sec={{t="Taking to the Skies",b="For many young mountaineers and travelers, the flight from Thelsamar to Ironforge marks their very first journey astride a gryphon. Handled by Gryphon Master Thorgrum Borrelson, this short passage carries travelers over Dun Morogh's snowy ridges and directly into the cavernous entry of the mountain fortress.",sp=0},{t="Honors of the Deep Mountain Guild",b="The errand itself serves the Deep Mountain Mining Guild. Brock Stoneseeker regularly sends word of his most promising mining pupils from Thelsamar. Waiting at the Great Forge is Golnir Bouldertoe, who inscribes the apprentices' names onto ceremonial honorary picks to reward their hard work in Loch Modan's quarries and mines.",sp=0}},faq={{q="Where does this flight start and end?",a="The journey begins at the flight master Thorgrum Borrelson in Thelsamar in Loch Modan and carries you straight into the flight roost at the Great Forge inside Ironforge.",al={"flight path route","where do i fly","ride destination"},it="place",gp=true},{q="What is Brock's List?",a="Brock's List is a roster compiled by the mining trainer Brock Stoneseeker in Thelsamar. It records his finest students so that the guild in Ironforge can reward their diligence.",al={"brocks list lore","who is brock","what is the paper"},it="item"},{q="Who is Golnir Bouldertoe?",a="Golnir Bouldertoe is a representative of the Deep Mountain Mining Guild based within the Great Forge of Ironforge. He receives rosters from local trainers and chisels the students' names into honorary picks.",al={"golnir role","where is golnir","who is golnir bouldertoe"},it="identity"},{q="What happens after you deliver the list?",a="Once Golnir receives the roster, he directs you over to Gryth Thurden, Ironforge's master gryphon handler, further acquainting you with the kingdom's aerial transport network.",al={"next quest","what to do after","follow up"},it="next_step"},{q="Why use a gryphon instead of walking?",a="While the mountain road and tunnels lead straight into Ironforge's Gates, the quest serves as practical instruction in Alliance gryphon travel, showing new adventurers how quickly they can leap between settlements.",al={"why fly","can i walk to ironforge","why gryphon"},it="purpose"},{q="What is an honorary pick?",a="Honorary picks are ceremonial tools crafted by the Deep Mountain Mining Guild to recognize outstanding mining students who have mastered basic excavation and geology under regional instructors.",al={"honorary picks","pick reward","mining pick ceremony"}},{q="Why does Thorgrum Borrelson want you to ride to Ironforge?",a="Thorgrum Borrelson is Thelsamar's gryphon master in Loch Modan, and his trade depends on travelers taking wing from his roost. By arranging your flight to Ironforge to deliver Brock's list of promising mining students to Golnir Bouldertoe, he introduces you to the speed and convenience of gryphon travel while ensuring important guild correspondence reaches the capital without delay.",al={"thorgrum borrelson motive","why send to ironforge","why deliver brocks list"},it="motive",add=true}},ang={["profession:Mining"]="This task directly highlights the Deep Mountain Mining Guild's tradition of recognizing and engraving honors for promising miners emerging from Loch Modan's pits.",["race:Dwarf"]="For young Bronzebeard dwarves, taking wing on a gryphon into the Great Forge is a proud rite of passage between rural outposts and the heart of the kingdom.",["faction:Alliance"]="The gryphon flight network forms the backbone of Alliance logistics across Khaz Modan, seamlessly connecting frontline garrisons to the grand capital."},kw={"brock's list","deep mountain mining guild","golnir bouldertoe","great forge","gryphon","kharanos","ride to ironforge","thorgrum borrelson"},rel={"npc:thorgrum-borrelson","npc:golnir-bouldertoe","zone:ironforge","subzone:great-forge"},m={start="Thorgrum Borrelson",["end"]="Golnir Bouldertoe",level="10",faction="Alliance",id=6391},src={"Ride to Ironforge (Classic)"}}
E["quest:6392"] = {t="quest",n="Return to Brock",z="ironforge",s="Having delivered Brock Stoneseeker's missive to Ironforge, you are entrusted with a batch of Honorary Picks to carry back to Thelsamar. Taking advantage of the dwarven aerial transit network, you board a gryphon with Gryth Thurden to return quickly across the mountains.",h="Having delivered Brock Stoneseeker's missive to Ironforge, you are entrusted with a batch of Honorary Picks...",sec={{t="Taking to the Skies",b="The great mountain stronghold of Ironforge relies on a coordinated network of gryphon roosts to maintain communication and trade with outlying settlements like Loch Modan. Gryth Thurden, Ironforge's gryphon master, oversees this transit from the city's central flight master platform. Because travelers must first establish a rapport with an aerie's handler before flying there, Gryth ensures you have already spoken with Thorgrum Borrelson in Thelsamar before saddling a mount for the return trip.",sp=0},{t="Picks for the Pupils",b="Your journey serves a practical purpose beyond introducing you to gryphon travel: Brock Stoneseeker, a respected mining instructor in Thelsamar, needs new equipment for his apprentices. With the Honorary Picks safely delivered to his hands, young miners across the valley can begin working the rich copper and tin veins that line the hills surrounding the Loch.",sp=0}},faq={{q="Who is Brock Stoneseeker?",a="Brock Stoneseeker is a dwarf mining trainer stationed in Thelsamar in Loch Modan. He instructs fledgling miners on extracting raw ore and stone from the surrounding hills.",al={"brock stoneseeker","who is brock","brock in thelsamar"},it="people"},{q="Why do I need to fly on a gryphon to finish this quest?",a="The quest introduces travelers to the Alliance flight system. Gryth Thurden explains that gryphons can only ferry you to aeries you have personally visited beforehand, such as Thorgrum Borrelson's roost in Thelsamar.",al={"why fly","flight path quest","gryphon ride"},gp=true},{q="What are the Honorary Picks for?",a="They are newly forged mining tools Brock Stoneseeker ordered from Ironforge for his novice mining students to use across the mineral-rich cliffs of Loch Modan.",al={"honorary picks","what are the picks"},it="item"},{q="Who is Gryth Thurden?",a="Gryth Thurden is the gryphon master of Ironforge, stationed at the Great Forge. He manages the capital's outbound and inbound flights throughout Khaz Modan and beyond.",al={"gryth thurden","ironforge flight master"},it="people"},{q="Can I just walk back to Thelsamar instead of flying?",a="While the lesson is designed to teach you how to use flight paths, Brock Stoneseeker only cares that you safely deliver the Honorary Picks to him in Thelsamar, regardless of how you travel there.",al={"can i walk back","do i have to take gryphon"},gp=true},{q="Where in Thelsamar is Brock located?",a="Brock Stoneseeker can be found outdoors near the forge and anvil in Thelsamar, ready to assist miners working in Loch Modan.",al={"where is brock","brock stoneseeker location","find brock"},gp=true},{q="Why does Gryth Thurden want me to deliver the picks?",a="Gryth Thurden manages Ironforge's gryphon roosts and keeps the kingdom's flight routes connected. Brock Stoneseeker down in Thelsamar is waiting on an urgent shipment of Honorary Picks for his mining students. Since you have already charted the path between Ironforge and Thorgrum Borrelson's roost, Gryth uses this delivery both to fulfill Brock's supply needs and to ensure you master the art of gryphon travel across Khaz Modan.",al={"why does gryth want this","gryth thurden motive","why send picks to brock"},it="motive",add=true},{q="Why does Gryth Thurden send an adventurer instead of handling it himself?",a="Gryth Thurden cannot abandon his post at the Great Forge, where he oversees the constant flow of riders and the care of Ironforge's prized gryphons. Because you personally carried Brock's missive into the city and unlocked the flight route back to Thelsamar, you are the ideal courier to test the newly established link and bring the supplies straight back into the miner's hands.",al={"why does gryth need me","why send an adventurer to thelsamar","why not send a courier"},it="why_me",add=true}},ang={["profession:Mining"]="Delivering these Honorary Picks puts essential tools into the hands of Loch Modan's newest miners, sustaining the dwarven tradition of excavation and prospecting.",["race:Dwarf"]="The route between Ironforge and Thelsamar highlights the vital role Wildhammer gryphons and Ironforge handlers play in binding together the dwarven holds."},kw={"brock stoneseeker","flight master","gryphon","gryth thurden","honorary picks","ironforge","return to brock","thelsamar"},rel={"npc:brock-stoneseeker","quest:6388","subzone:thelsamar","zone:ironforge","zone:lochmodan"},m={start="Gryth Thurden",["end"]="Brock Stoneseeker",level="10",faction="Alliance",id=6392},src={"Return to Brock"}}
E["quest:6625"] = {t="quest",n="Alliance Trauma",z="ironforge",s="Alliance Trauma is a summons directing accomplished field medics to report to Theramore Isle in Dustwallow Marsh. Dispatched by first aid instructors across Alliance capitals, it invites skilled practitioners to study under Doctor Gustaf VanHowzen, the chief physician of the Alliance's elite medical corps.",h="Alliance Trauma is a summons directing accomplished field medics to report to Theramore Isle in Dustwallow...",sec={{t="A Call to the Field",b="Once a medic masters the fundamental techniques taught in the great Alliance cities, local instructors can teach them little more. For those who demonstrate exceptional aptitude with needle, cloth, and triage, word is sent directly to Doctor Gustaf VanHowzen. Operating from the frontier stronghold of Theramore Isle, VanHowzen oversees Alliance Trauma, the organization charged with saving lives in the most brutal warzones of Kalimdor and beyond.",sp=0},{t="The Road to Theramore",b="Instructors such as Nissa Firestone in Ironforge treat a personal summons from VanHowzen as an extraordinary privilege. Theramore Isle is constantly pressured by regional threats, skirmishes, and harsh wilderness conditions, producing a steady influx of grievously wounded soldiers. Reaching VanHowzen's clinic requires a long journey across the sea to Dustwallow Marsh, where only the most composed battlefield surgeons can hope to pass his rigorous triage standards.",sp=0}},faq={{q="What is Alliance Trauma?",a="Alliance Trauma is the elite medical branch responsible for advanced battlefield medicine and emergency triage across the Alliance. Headed by Chief Physician Gustaf VanHowzen, the corps handles critical wounds that standard field dressing cannot treat.",al={"alliance trauma lore","who are alliance trauma"},it="purpose"},{q="Who sends you on this quest?",a="Alliance first aid instructors, such as Nissa Firestone in the Great Forge of Ironforge, dispatch promising practitioners once they reach the pinnacle of standard civic training.",al={"who gives alliance trauma","ironforge first aid quest giver"},it="identity"},{q="Where do you have to travel?",a="You must travel to the human port fortress of Theramore Isle, located along the eastern coast of Dustwallow Marsh on the continent of Kalimdor.",al={"where is vanhowzen","alliance trauma destination"},it="place",gp=true},{q="Who is Doctor Gustaf VanHowzen?",a="Doctor Gustaf VanHowzen is the chief physician of Alliance Trauma. Stationed at the military clinic in Theramore, he is considered one of the foremost authorities on emergency medicine and surgical triage in the Alliance.",al={"gustaf vanhowzen","chief physician vanhowzen"},it="target"},{q="What happens after reporting to Doctor VanHowzen?",a="Upon reporting to Theramore, VanHowzen puts candidates through an intense hands-on triage evaluation, testing their ability to save waves of dying soldiers before admitting them into the upper ranks of field medicine.",al={"what comes after alliance trauma","triage quest next"},it="next_step"},{q="Why is the clinic based in Theramore instead of Stormwind or Ironforge?",a="Theramore is an active frontier garrison surrounded by hostile marshlands, dangerous beasts, and territorial skirmishes. The constant arrival of critically wounded troops makes it the ideal staging ground for high-intensity trauma training.",al={"why theramore clinic","why dustwallow for trauma"},it="why_here"},{q="Why does Nissa Firestone send you to Theramore?",a="Doctor Gustaf VanHowzen, the chief physician of Alliance Trauma, issued a personal request for you to join his ranks in Theramore. Nissa Firestone holds the renowned surgeon in the highest esteem and views working under him as an unmatched honor. She passes along the summons because she wants to ensure you do not squander such a rare medical opportunity.",al={"why does nissa want this done","nissa firestone motive","why send to theramore"},it="motive",add=true},{q="Why does Doctor VanHowzen ask for you specifically?",a="Doctor Gustaf VanHowzen needs capable, experienced field medics who can handle severe casualties under pressure. Having proven your exceptional mastery in first aid, you have caught the attention of the Alliance's senior surgical corps, prompting VanHowzen to summon you personally to Theramore to assess your skills under battlefield conditions.",al={"why me alliance trauma","why does vanhowzen want me","why send player to theramore"},it="why_me",add=true}},ang={["faction:Alliance"]="Alliance Trauma ensures that frontline fighters across Kalimdor and the Eastern Kingdoms have skilled field medics capable of stabilizing critical injuries under fire.",["race:Dwarf"]="Instructors like Nissa Firestone in Ironforge eagerly scout promising practitioners from the Great Forge to represent the Alliance's finest medical talents in Theramore."},kw={"alliance trauma","dustwallow marsh","first aid","ironforge","nissa firestone","theramore","triage","vanhowzen"},rel={"npc:doctor-gustaf-vanhowzen","npc:nissa-firestone","zone:dustwallow","topic:alliance"},m={start="Nissa Firestone",["end"]="Doctor Gustaf VanHowzen",faction="Alliance",id=6625},src={"Alliance Trauma (quest)"}}
E["quest:686"] = {t="quest",n="A King's Tribute",z="ironforge",s="A King's Tribute is an Alliance quest offered by King Magni Bronzebeard in the High Seat of Ironforge. Deeply moved by the grief of Sara Balloo, whose husband Sully fell defending the Thandol Span, the King decides to honor the fallen soldier with a lasting monument. He dispatches an adventurer to relay his royal commission to Grand Mason Marblesten.",h="A King's Tribute is an Alliance quest offered by King Magni Bronzebeard in the High Seat of Ironforge.",sec={{t="A Sovereign's Burden",b="When King Magni Bronzebeard receives the plea of Sara Balloo, he does not dismiss the grieving widow. While he acknowledges that common folk may struggle to understand the brutal necessities of war, the loss of every soldier fighting beneath the Alliance banner weighs heavily upon his conscience. Unable to reverse the grim finality of death on the front lines, Magni chooses to ensure Sully Balloo's sacrifice is never forgotten.",sp=0},{t="The Mason's Chisel",b="Rather than issuing empty platitudes, the King resolves to raise a physical memorial in Sully's honor. He appoints the adventurer as custodian of his royal will, sending them across Ironforge to confer with Grand Mason Marblesten. Entrusted with the King's personal commission, the master stonemason prepares to carve the memory of a fallen defender into stone.",sp=0}},faq={{q="Who was Sully Balloo?",a="Sully Balloo was a dwarven soldier who lost his life fighting for the Alliance during the defense of the Thandol Span. His widow, Sara Balloo, petitioned King Magni Bronzebeard after learning of his death.",al={"who is sully","sully balloo lore","who died"},it="people"},{q="Why does King Magni commission a memorial?",a="King Magni carries the weight of every dwarven life lost in the Alliance's ongoing struggles. Though he cannot restore Sully to his widow, he intends to honor the soldier's courage with an enduring royal monument.",al={"why build memorial","magni motive","kings tribute purpose"},it="motive"},{q="Who is Grand Mason Marblesten?",a="Grand Mason Marblesten is Ironforge's master stoneworker, tasked with executing major civic and royal architectural projects throughout the city. King Magni relies on him to sculpt Sully Balloo's memorial.",al={"who is marblesten","grand mason role"},it="identity"},{q="Where does this quest take place?",a="The quest takes place entirely within Ironforge, beginning at the High Seat with King Magni Bronzebeard and leading to Grand Mason Marblesten elsewhere in the capital.",al={"where is this quest","quest location"},it="place"},{q="What comes before this quest?",a="Before receiving this quest, an adventurer must complete 'Sara Balloo's Plea', delivering the widow's heartfelt letter directly to King Magni Bronzebeard.",al={"prerequisites","previous quest"},gp=true},{q="Is this memorial only for Sully Balloo?",a="While specifically commissioned in name of Sully Balloo to console his widow Sara, the tribute symbolizes the King's reverence for every dwarven fighter who perishes in service to the Alliance.",al={"who does it honor","is it just for sully"},it="purpose"},{q="Why does King Magni choose you as custodian for the tribute?",a="You were the one who carried Sara Balloo's heartfelt plea directly into the High Seat, bringing her personal tragedy before the throne. Because you chose to hear a grieving widow's sorrow and deliver her words to the king, Magni entrusts you to see the royal honor carried out, making you the custodian of his bidding rather than delegating it to palace bureaucrats.",al={"why me kings tribute","why does magni send you","why pick me"},it="why_me",add=true}},ang={["race:Dwarf"]="This task demonstrates King Magni's dedication to his folk, showing that even the lowliest dwarven foot soldier is remembered by the throne.",["faction:Alliance"]="The fallen at the Thandol Span gave their lives guarding crucial supply lines between Khaz Modan and the northern kingdoms for the Alliance."},kw={"ironforge","magni bronzebeard","marblesten","memorial","sara balloo","sully balloo","thandol span"},rel={"npc:magni-bronzebeard","npc:grand-mason-marblesten","topic:dwarf","topic:alliance"},m={start="King Magni Bronzebeard",["end"]="Grand Mason Marblesten",level="30",faction="Alliance",id=686},src={"A King's Tribute"}}
E["quest:700"] = {t="quest",n="A King's Tribute",z="ironforge",s="A King's Tribute marks the final step in honoring the sacrifice of the fallen dwarven soldier Sully Balloo. After fine granite is gathered from the ruins of Lordaeron, Grand Mason Marblesten sculpts a solemn memorial monument in Ironforge on the orders of King Magni Bronzebeard.",h="A King's Tribute marks the final step in honoring the sacrifice of the fallen dwarven soldier Sully Balloo.",sec={{t="A Monument Carved in Grief",b="King Magni Bronzebeard commissioned a permanent monument to honor Sully Balloo, a brave dwarf who lost his life in service to his people. Crafted by Grand Mason Marblesten using high-quality granite transported from the war-torn lands of Lordaeron, the finished memorial stands in Ironforge as an enduring testament to fallen soldiers whose sacrifices preserve the dwarven kingdom.",sp=0},{t="A Sovereign's Reflection",b="When presented with news of the monument's completion, Magni reflects somberly on the limits of stone and mortality. While acknowledging that carved rock can never truly equate to a brave dwarf's life, he hopes the memorial endures so future generations walking Azeroth will never forget the heroes who bled to secure their tomorrow.",sp=0}},faq={{q="Who is being honored by this memorial?",a="The monument is built in memory of Sully Balloo, a brave dwarven soldier who gave his life fighting valiantly for his people and the Alliance.",al={"who is this memorial for","sully balloo monument","who died"},it="purpose"},{q="Why was the stone gathered from Lordaeron?",a="Grand Mason Marblesten required the finest granite suitable for a lasting royal tribute. Lordaeron produces exceptional quarried stone, even though the region itself has fallen into ruin following the Scourge.",al={"why lordaeron stone","lordaeron granite","marblesten stone"},it="origin"},{q="Where does this quest take place?",a="The quest begins with Grand Mason Marblesten and finishes with King Magni Bronzebeard in the High Seat of Ironforge.",al={"where to turn in","who completes quest"},it="place",gp=true},{q="Why does King Magni commission this tribute personally?",a="Magni believes that rulers must honor the foot soldiers who defend their realms. He views memorial stone as a vital reminder to future generations of the high price paid by common soldiers for their safety.",al={"why does magni care","magni bronzebeard sully balloo"},it="motive"},{q="What happens after the memorial is finished?",a="Reporting to King Magni concludes the memorial chain. The crafted statue remains in Ironforge as a solemn, permanent landmark for Sully Balloo.",al={"what comes next","kings tribute follow up"},it="next_step"},{q="What is the masonry significance of the statue?",a="Grand Mason Marblesten is among the most accomplished dwarven artisans in Ironforge. Working the imported Lordaeron granite, he shaped the raw stone into a fitting national work of art on the monarch's behalf.",al={"marblesten role","grand mason craft"}},{q="Why does Grand Mason Marblesten send you to the King?",a="You were the one who braved the dangerous journey to the ruins of Lordaeron to retrieve the fine granite for the sculpture. Having secured the stone and made the tribute possible, Grand Mason Marblesten entrusts you with delivering the proud news directly to King Magni Bronzebeard that Sully Balloo's memorial is complete.",al={"why send me to Magni","why tell king magni","why marblesten sends player"},it="why_me",add=true}},ang={["race:Dwarf"]="For dwarves, honoring ancestral fallen warriors in enduring stone is one of their most sacred cultural traditions.",["faction:Alliance"]="The monument serves as a poignant reminder of the heavy toll exacted across Khaz Modan and the northern kingdoms during recent conflicts.",["class:Warrior"]="Magni's words directly honor the selfless valor of frontline soldiers like Sully Balloo who sacrificed everything in battle."},kw={"a king's tribute","granite","ironforge","lordaeron","magni bronzebeard","marblesten","memorial","sully balloo"},rel={"npc:magni-bronzebeard","npc:grand-mason-marblesten","quest:686","topic:dwarf","topic:lordaeron"},m={start="Grand Mason Marblesten",["end"]="King Magni Bronzebeard",level="31",faction="Alliance",id=700},src={"A King's Tribute (3)"}}
E["quest:7025"] = {t="quest",n="Treats for Greatfather Winter",z="ironforge",s="During the Feast of Winter Veil, the performer portraying Greatfather Winter in Ironforge grows tired and asks passersby for a seasonal treat. Bringing him freshly baked gingerbread cookies and ice cold milk earns a festive reward and his warm gratitude.",h="During the Feast of Winter Veil, the performer portraying Greatfather Winter in Ironforge grows tired and...",sec={{t="A Long Day in the Seat",b="While Winter Veil has its roots in ancient titan lore and dwarven myths of an immortal figure cloaked in winter's chill, modern festivities rely heavily on the commercial sponsorship of Smokywood Pastures. Stationed by the holiday tree in the Commons of Ironforge, an ordinary dwarf spends grueling hours suited up as Greatfather Winter, fielding holiday wishes from citizens and eager children alike.",sp=0},{t="Baking Holiday Cheer",b="After listening to requests for gifts all day, the resident Greatfather Winter inevitably develops a hearty appetite of his own. Rather than asking for something extravagant, he requests a simple comfort: five freshly baked gingerbread cookies made with holiday spices and an ice cold milk to wash them down. The trade offers a moment of relief to an exhausted festival worker and spreads goodwill throughout the snowy capital.",sp=0}},faq={{q="Where do I find Greatfather Winter in Ironforge?",a="Greatfather Winter sits beside the large holiday tree and the Smokywood Pastures display in the Commons of Ironforge, surrounded by festive decorations.",al={"where is greatfather winter","greatfather winter location ironforge","ironforge santa location"},it="place",gp=true},{q="How do you make Gingerbread Cookies?",a="The recipe is sold by Smokywood Pastures vendors near Greatfather Winter. Baking them requires Cooking skill along with holiday spices purchased from the festival merchant and small eggs gathered from wild birds.",al={"where to get gingerbread cookies","gingerbread recipe","how to bake cookies"},gp=true},{q="Where do I get Ice Cold Milk?",a="Ice Cold Milk can be purchased from almost any innkeeper, food vendor, or drink seller in major Alliance cities, including the taverns across Ironforge.",al={"ice cold milk vendor","where to buy milk","milk ironforge"},it="item",gp=true},{q="Is this Greatfather Winter the real mythic figure?",a="No, he is a dwarven performer hired by Smokywood Pastures to represent the legendary titan-associated figure for the Winter Veil holiday celebrations.",al={"is greatfather winter real","who is the guy in ironforge","is he really greatfather winter"},it="identity"},{q="What does Greatfather Winter send you after finishing the quest?",a="Upon receiving the cookies and milk, Greatfather Winter hands you a Smokywood Pastures Gift Pack as a little something for the effort.",al={"treats for greatfather winter reward","mail from greatfather winter","smokywood pastures sampler"},sp=1,gp=true},{q="Can Horde players complete this specific quest?",a="This particular quest is offered in Ironforge to Alliance players. Horde members have their own equivalent quest visiting Greatfather Winter in Orgrimmar.",al={"can horde do this quest","horde treats for greatfather winter"},gp=true},{q="Why does Greatfather Winter want this done?",a="Greatfather Winter has been sitting in Ironforge listening to holiday wishes and greeting visitors all day without a break. While the Feast of Winter Veil brings joy to everyone else, all the talk of festival treats has left him exhausted and hungry, so he asks you to fetch him a much-needed snack.",al={"greatfather winter cookies motive","why does greatfather winter want cookies","why treats for greatfather winter"},it="motive",add=true},{q="What is the Ice Cold Milk for?",a="The Ice Cold Milk is simply a refreshing drink to wash down the batch of warm gingerbread cookies. Spending all day greeting travelers and shouting festive well-wishes is thirsty work, and nothing complements sweet festival biscuits better than an ice-cold beverage.",al={"why ice cold milk","milk for greatfather winter","ice cold milk purpose"},it="item",add=true},{q="What are the Gingerbread Cookies for?",a="The Gingerbread Cookies serve as a personal holiday treat for Greatfather Winter himself. After handing out treats and hearing requests from citizen after citizen, he craves a traditional Winter Veil confection made with holiday spices to restore his energy.",al={"gingerbread cookies treats for greatfather","why gingerbread cookies","cookies for greatfather winter"},it="item",add=true},{q="Why does Greatfather Winter need you rather than getting treats himself?",a="Greatfather Winter cannot abandon his post amidst the festival festivities. He is stationed by the tree in Ironforge to greet the crowds and spread cheer for Smokywood Pastures, meaning he is stuck in place and relies on generous passersby like you to run errands for food.",al={"why does greatfather winter need me","why can't greatfather winter get his own cookies","why does greatfather winter ask an adventurer"},it="why_me",add=true}},ang={["profession:Cooking"]="The quest requires simple culinary skills to mix small eggs and holiday spices into festive gingerbread cookies.",["race:Dwarf"]="For dwarves, Greatfather Winter represents an ancient legend tied to the titans and winter's bounty, though seeing one snacking on cookies in the Commons brings the myth down to earth.",["faction:Alliance"]="Ironforge serves as the Alliance's primary hub for Winter Veil festivities, drawing travelers from across the Eastern Kingdoms to the holiday tree in the Commons."},kw={"feast of winter veil","gingerbread cookie","greatfather winter","ice cold milk","ironforge","smokywood pastures","treats for greatfather winter"},rel={"npc:greatfather-winter","zone:ironforge"},m={start="Greatfather Winter",faction="Alliance",id=7025,ri={"Gingerbread Cookie","Ice Cold Milk"}},src={"Treats for Greatfather Winter"}}
E["quest:8353"] = {t="quest",n="Chicken Clucking for a Mint",z="ironforge",s="Chicken Clucking for a Mint is a lighthearted seasonal Alliance quest offered in Ironforge during the Hallow's End festival. To earn a traditional Ironforge Mint on behalf of the young orphan Jesper, adventurers must put aside their battle-hardened dignity and flap their arms while clucking like a chicken for the tavern's amusement. Innkeeper Firebrew gladly rewards anyone willing to swallow their pride to bring holiday cheer to a child.",h="Chicken Clucking for a Mint is a lighthearted seasonal Alliance quest offered in Ironforge during the...",sec={{t="A Hallow's End Tradition",b="During Hallow's End, spirits run high across Azeroth as folk celebrate the break between harvest and winter with costumed revelry and seasonal treats. While seasoned heroes might normally feel too old to go door-to-door begging for candy, the plight of sick or orphaned children offers an honorable excuse. In Stormwind, young Jesper longs for holiday sweets, prompting visiting Alliance champions to gather iconic regional confections from innkeepers across the Alliance capitals.",sp=0},{t="Innkeeper Firebrew's Price",b="Behind the counter at Ironforge's bustling tavern stands Innkeeper Firebrew, guardian of the famed Ironforge Mints. Never one to let an adventurer off easy, Firebrew refuses to hand over the confection simply for asking. He insists on entertainment, demanding that hardened warriors and stoic spellcasters flap and squawk like barnyard fowl before coughing up the prize. It is all in the name of festival merriment, providing tavern patrons with a good laugh at a hero's expense.",sp=0}},faq={{q="Why does Innkeeper Firebrew want me to cluck like a chicken?",a="Innkeeper Firebrew is embracing the playful spirit of Hallow's End. Since seasoned adventurers are far too old to trick-or-treat normally, he demands a comical trick before parting with his treat. Believing that watching a mighty champion flap their arms and squawk provides good tavern entertainment, he cheerfully trades an Ironforge Mint for a bit of public humiliation.",al={"why chicken cluck","firebrew chicken reason","why do i have to cluck"},it="motive"},{q="Who is Jesper and why am I getting mints for him?",a="Jesper is a sick orphan staying in Stormwind who cannot partake in the city's Hallow's End festivities himself. To bring him joy, Alliance adventurers run seasonal errands across the world to collect four special holiday candies from each major Alliance city, including the crisp Ironforge Mint from Dun Morogh.",al={"who is jesper","why get mints","jesper orphan"}},{q="Where does this quest fit into the Hallow's End holiday?",a="This quest is one of four regional tasks tied to the overarching seasonal mission 'Hallow's End Treats for Jesper!' alongside requests from the innkeepers of Stormwind and Darnassus and from Talvash del Kissel in Ironforge. Each of them demands a specific humiliating or theatrical emote before surrendering their city's signature candy.",al={"hallows end chain","jesper candy questline","quest order"},it="purpose"},{q="Where can I find Innkeeper Firebrew?",a="Innkeeper Firebrew is stationed behind the hearth bar inside the Stonefire Tavern in Ironforge's Commons, serving drinks and boarding travelers right in the heart of the dwarven capital.",al={"where is firebrew","firebrew location","ironforge innkeeper"},it="place",gp=true},{q="What do I receive for clucking?",a="Upon clucking, Innkeeper Firebrew hands you an Ironforge Mint, an event-exclusive holiday candy needed to bring back to Stormwind to complete Jesper's assortment of Hallow's End treats.",al={"quest reward","what is the mint","ironforge mint"},gp=true},{q="Can Horde players complete this task?",a="No, this quest is exclusive to the Alliance. Horde adventurers have their own counterpart in the orphan Spoops, who sends champions across Horde capitals to collect confections from innkeepers in Orgrimmar, the Undercity, and Thunder Bluff.",al={"is this alliance only","horde chicken quest","can horde do this"},gp=true}},ang={["faction:Alliance"]="This seasonal errand highlights the camaraderie of the Alliance capitals, connecting the dwarven hospitality of Ironforge directly to cheering up an orphaned child in Stormwind.",["race:Dwarf"]="Dwarves appreciate good humor, hearty drink, and festival traditions, and Firebrew's demand shows that no Ironforge patron takes themselves entirely too seriously."},kw={"chicken","cluck","firebrew","hallow's end","innkeeper","ironforge mint","jesper","treats"},rel={"quest:8311","npc:innkeeper-firebrew","zone:ironforge"},m={start="Innkeeper Firebrew",faction="Alliance",id=8353},src={"Chicken Clucking for a Mint (Alliance)"}}
E["quest:8355"] = {t="quest",n="Incoming Gumdrop",z="ironforge",s="Incoming Gumdrop is a seasonal Hallow's End quest found in Ironforge, given by the gnome artisan Talvash del Kissel. In order to obtain a festive treat for a sick child in Stormwind, adventurers must first perform a playful train impression for the delighted gnome.",h="Incoming Gumdrop is a seasonal Hallow's End quest found in Ironforge, given by the gnome artisan Talvash del...",sec={{t="A Whimsical Toll",b="During the autumn celebration of Hallow's End, trick-or-treaters scour the major Alliance strongholds gathering unique regional confections. In Ironforge's Mystic Ward, the gnome Talvash del Kissel holds the coveted Gnomeregan Gumdrop. While sympathetic to the plight of the young orphan who desires it, Talvash insists on upholding the holiday's spirit of mischief before parting with his sweet, demanding a convincing train impression from anyone seeking a handout.",sp=0},{t="Holiday Charity",b="The quest forms a piece of an overarching seasonal endeavor to bring cheer to Jesper, an ailing orphan resting in Stormwind City. Jesper longs for four distinct treats from across the Alliance territories: nougat from Stormwind, a mint from Ironforge, a marzipan piece from Darnassus, and a gumdrop from Gnomeregan. By mimicking a chugging locomotive to entertain Talvash, champions secure the gnome treat to complete the young boy's holiday wish.",sp=0}},faq={{q="What do I need to do to complete Incoming Gumdrop?",a="You must perform a train impression for Talvash del Kissel by targeting him and using the train gesture. Once he hears the train noise, he will gladly hand over the Gnomeregan Gumdrop.",al={"how to do incoming gumdrop","incoming gumdrop objective","talvash gumdrop trick"},it="purpose",gp=true},{q="Who is Talvash del Kissel?",a="Talvash del Kissel is a gnome jeweler from Gnomeregan residing in the Mystic Ward within the dwarven mountain city of Ironforge. During Hallow's End, he acts as the Alliance distributor for Gnomeregan's signature gumdrops.",al={"who is talvash","talvash del kissel lore"},it="identity"},{q="What is the Gnomeregan Gumdrop used for?",a="The Gnomeregan Gumdrop is one of four distinct festival candies gathered to fulfill the Hallow's End request of Jesper, an orphan boy resting in the orphanage of Stormwind City.",al={"gnomeregan gumdrop purpose","what is the gumdrop for"},it="item",gp=true},{q="Where can Talvash del Kissel be found?",a="Talvash can be found in the Mystic Ward of Ironforge.",al={"where is talvash","talvash location"},it="place",gp=true},{q="Why does Talvash make you imitate a train?",a="Hallow's End is rooted in the tradition of trick-or-treating. Talvash playfully demands a harmless trick—a locomotive impression—before he is willing to surrender his festive treat.",al={"why train noise","why do train for talvash"},it="motive"},{q="Is this quest available year-round?",a="No, this quest is only available during the annual autumn festival of Hallow's End.",al={"can i do incoming gumdrop anytime","is this seasonal"},gp=true}},ang={["race:Gnome"]="For exiled gnomes in Tinker Town, offering a Gnomeregan Gumdrop during Hallow's End is a cheerful reminder of home and mechanical ingenuity amid their displacement.",["faction:Alliance"]="The pursuit of the festival gumdrop sends Alliance heroes traversing the kingdoms to ensure an ailing child in Stormwind shares in the holiday season."},kw={"gnomeregan gumdrop","hallow's end","incoming gumdrop","ironforge","jesper","talvash del kissel","tinker town","train emote"},rel={"npc:talvash-del-kissel","quest:8311","topic:gnome","zone:gnomeregan"},m={start="Talvash del Kissel",faction="Alliance",id=8355},src={"Incoming Gumdrop (Alliance)"}}
E["quest:8827"] = {t="quest",n="Winter's Presents",z="ironforge",s="Winter's Presents is an Alliance holiday breadcrumb quest celebrating the Feast of Winter Veil in Ironforge. Joyful revelers and PX-238 Wonderform Operators urge travelers to visit Greatfather Winter beside the Smokywood Pastures market stalls. There, beneath the grand holiday tree, festive gifts await hearty adventurers.",h="Winter's Presents is an Alliance holiday breadcrumb quest celebrating the Feast of Winter Veil in Ironforge.",sec={{t="A Season of Cheer",b="As the chill of winter sets in across the peaks of Khaz Modan, Ironforge transforms into the heart of Alliance festivities for the Feast of Winter Veil. Revelers and holiday enthusiasts throughout the city spread word of good cheer, excitedly directing passersby toward the grand decorated tree nestled near the Smokywood Pastures vendors.",sp=0},{t="Smokywood Pastures and Greatfather Winter",b="Behind the generous distribution of wrapped parcels sits the goblin enterprise of Smokywood Pastures, partnered alongside Greatfather Winter himself. While the jovial figure greets visitors with warm seasonal greetings, the goblin merchants are never shy about reminding happy gift-recipients that their festive treats and seasonal wares make wonderful gifts for friends and family.",sp=0}},faq={{q="Who sends me to speak with Greatfather Winter?",a="Either a Holiday Enthusiast or a Wonderform Operator tending the PX-238 Winter Wondervolt machines in Ironforge will invite you to visit Greatfather Winter at the decorated tree.",al={"quest giver","who starts winter's presents","who gives the quest"},it="identity"},{q="Where can I find Greatfather Winter in Ironforge?",a="He sits right beside the festive holiday tree and the Smokywood Pastures vendor stalls in Ironforge, welcoming holiday visitors of all Alliance races.",al={"where is greatfather winter","greatfather winter location ironforge","find greatfather winter"},it="place",gp=true},{q="What is the PX-238 Winter Wondervolt mentioned by the operator?",a="The PX-238 Winter Wondervolt is a whimsical holiday invention run by goblin operators that temporarily disguises adventurous festival-goers as merry little holiday helpers.",al={"px-238","winter wondervolt","wondervolt machine"}},{q="Why is Smokywood Pastures involved in Winter Veil?",a="Smokywood Pastures is an entrepreneurial goblin merchant organization that sponsors seasonal treats, holiday novelties, and feasts across Azeroth, pairing genuine festive spirit with lucrative seasonal commerce.",al={"smokywood pastures role","why goblins winter veil","goblin holiday"},it="history"},{q="Can Horde players do this quest?",a="No, this particular invitation is purely for the Alliance in Ironforge. The Horde celebrates their own Winter Veil customs under Greatfather Winter's guidance in Orgrimmar.",al={"is this alliance only","horde winter presents","can horde turn this in"},gp=true},{q="What happens after speaking to Greatfather Winter?",a="Greatfather Winter welcomes you, confirms he has not forgotten you, and encourages you to inspect the colorful packages placed beneath the surrounding holiday tree.",al={"what comes next","opening presents","after quest turn in"},it="next_step",gp=true},{q="Why do the Wonderform Operator and Holiday Enthusiast send you to Greatfather Winter?",a="They simply want you to share in the cheer of the Feast of Winter Veil. Greatfather Winter has arrived in Ironforge and laid out gifts under the tree with the backing of Smokywood Pastures. While the Wonderform Operator is bound by duty to supervise the PX-238 Winter Wondervolt and cannot leave their post, they make sure passersby do not miss out on the holiday celebration and the presents waiting for them.",al={"why send me to greatfather winter","why winter's presents quest","holiday enthusiast motive"},it="motive",add=true}},ang={["faction:Alliance"]="Ironforge serves as the grand gathering point for all Alliance races during the winter season, drawing elves, humans, and gnomes into the warm subterranean dwarven halls to share festive cheer.",["race:Dwarf"]="For dwarves, welcoming travelers to celebrate the Feast of Winter Veil within the Great Forge brings lively song, warm hearth fires, and cold ale to their mountain home.",["race:Gnome"]="Gnome mechanics marvel at the ingenious holiday contraptions brought in for the season, such as the PX-238 Winter Wondervolts operated across town."},kw={"feast of winter veil","greatfather winter","holiday enthusiast","ironforge","smokywood pastures","winter veil","winter's presents","wonderform operator"},rel={"npc:greatfather-winter","zone:ironforge"},m={start="Wonderform Operator / Holiday Enthusiast",["end"]="Greatfather Winter",faction="Alliance",id=8827},src={"Winter's Presents (Alliance)"}}
E["quest:8846"] = {t="quest",n="Five Signets for War Supplies",z="ironforge",s="Field Marshal Snowfall in Ironforge oversees the collection of provisions and equipment for the Grand Alliance's war effort. Champions contributing to the stockpiles can barter their commendation signets directly for field rations, bandages, and critical combat supplies. It ensures that those working tirelessly on the home front remain equipped for the coming conflicts.",h="Field Marshal Snowfall in Ironforge oversees the collection of provisions and equipment for the Grand...",sec={{t="Supplying the Front",b="The massive staging of armies requires more than just raw courage; it demands a relentless logistical pipeline. Field Marshal Snowfall acts as one of the Alliance's primary quartermasters in Ironforge, organizing the flow of materials destined for active fronts. When couriers and heroes bring in commendation signets earned through civic service, Snowfall offers survival rations and tactical materiel in direct exchange.",sp=0},{t="A Pragmatic Trade",b="While commendation signets are often turned in to royal heralds for public honor and civic standing, Snowfall offers an unceremonious alternative. Trading five signets for an allotment of field gear yields no pomp, glory, or official recognition. Instead, it provides tangible, life-saving goods to ensure soldiers and volunteers stay alive when marching into hostile lands.",sp=0}},faq={{q="Who is Field Marshal Snowfall?",a="Field Marshal Snowfall is a senior Alliance military officer stationed in the dwarven capital of Ironforge. He is tasked with gathering raw materials and dispersing supplies to soldiers and adventurers who aid the war effort.",al={"snowfall ironforge","field marshal snowfall","who is snowfall"},it="identity"},{q="What are Alliance Commendation Signets?",a="Alliance Commendation Signets are official tokens awarded to citizens and adventurers who donate critical trade goods, bandages, herbs, and ores to support the Alliance's widespread mobilization.",al={"commendation signets","alliance signets","what are signets"},it="item"},{q="Why trade signets for supplies rather than prestige?",a="Exchanging signets for supply crates bypasses civic reputation in favor of immediate, practical resources. For frontline fighters who need consumables, rations, and field bandages right away, practical gear often outweighs ceremonial standing.",al={"why do this quest","signets for supplies worth it","snowfall supplies trade"},it="motive"},{q="Where does this exchange take place?",a="The exchange takes place in Ironforge, where Field Marshal Snowfall stands near the war staging grounds and supply depots, coordinating shipments across Khaz Modan and beyond.",al={"where is snowfall","quest location","snowfall ironforge location"},it="place",gp=true},{q="Can I repeat this exchange?",a="Yes. Field Marshal Snowfall is prepared to continuously authorize additional supply bundles as long as you provide the requisite five commendation signets each time.",al={"is this repeatable","can i do this again","turn in more signets"},gp=true},{q="Does this turn-in grant reputation?",a="No. Field Marshal Snowfall explicitly warns that trading signets directly for personal supplies grants no civic recognition or prestige with the Alliance factions, as the value is returned in physical goods.",al={"does this give rep","ironforge rep signets","recognition for signets"},gp=true}},ang={["faction:Alliance"]="This logistics requisition is a direct lifeline for Alliance champions preparing for major campaigns across Azeroth, ensuring troops have bandages and rations.",["race:Dwarf"]="With the bustling forge-city serving as an Alliance distribution hub, dwarven defenders take pride in seeing their halls arming all allied races."},kw={"commendation","ironforge","materiel","rations","signets","snowfall","war supplies"},rel={"npc:field-marshal-snowfall","topic:alliance"},m={start="Field Marshal Snowfall",level="19",faction="Alliance",id=8846,ri={"Alliance Commendation Signet"}},src={"Five Signets for War Supplies (Alliance)"}}
E["quest:8866"] = {t="quest",n="Bronzebeard the Elder",z="ironforge",s="Bronzebeard the Elder is a Lunar Festival encounter with Elder Bronzebeard within the dwarven mountain city of Ironforge. Honoring him during this ancestral celebration rewards travelers with wisdom and a token of his esteem. It reflects the deep reverence the folk of Khaz Modan hold for their forebears and long-lived heritage.",h="Bronzebeard the Elder is a Lunar Festival encounter with Elder Bronzebeard within the dwarven mountain city...",sec={{t="Homage to the Mountain Clan",b="During the Lunar Festival, spirits and venerable elders manifest across Azeroth to share their wisdom with travelers honoring the past. In Ironforge, Elder Bronzebeard stands as an embodiment of the stalwart resilience of the Bronzebeard clan. When approached by adventurers seeking to pay their respects, he expresses quiet satisfaction that the people of this land still acknowledge and honor the lineage of the olden races.",sp=0},{t="Tokens of Ancestral Esteem",b="The encounter requires no great trial or perilous expedition, asking only that travelers pause, acknowledge the elder's presence, and offer greeting. In turn, Elder Bronzebeard extends his well wishes and bestows a Coin of Ancestry. These sacred festival tokens serve as physical reminders of the living connection between modern heroes and the generations who forged Khaz Modan from stone and fire.",sp=0}},faq={{q="Who is Elder Bronzebeard?",a="Elder Bronzebeard is an ancestral dwarf honored during the Lunar Festival, found resting inside the subterranean stronghold of Ironforge to greet visitors and celebrate their heritage.",al={"elder bronzebeard","who is the elder","ironforge elder"}},{q="What does honoring Elder Bronzebeard signify?",a="Greeting him is an act of venerating the ancestors during the Lunar Festival. He commends travelers for remembering the roots and ancient sacrifices of the early races of Azeroth.",al={"why honor bronzebeard","bronzebeard elder purpose"}},{q="Where in Ironforge is Elder Bronzebeard found?",a="He can be found standing within Ironforge, accessible to those exploring the mountain city to seek festival elders and pay their respects.",al={"elder bronzebeard location","where is bronzebeard the elder","ironforge elder spot"}},{q="Can Horde players speak with Elder Bronzebeard?",a="Elder Bronzebeard will acknowledge anyone willing to greet him, but Horde adventurers must brave the fortified depths of Ironforge and dodge the dwarven guards to reach him.",al={"can horde do this quest","horde elder bronzebeard"}},{q="What reward does the elder bestow?",a="He offers his ancestral blessing alongside a festival coin, serving as a token of goodwill and proof of honoring the ancient generations.",al={"elder bronzebeard reward","what token does he give"}},{q="Does this quest involve any combat?",a="No combat is required to speak with him; it simply entails approaching the venerable elder respectfully, though hostile territory may pose danger along the journey.",al={"do i have to fight","bronzebeard the elder fight"}}},ang={["race:Dwarf"]="For dwarves, paying homage to Elder Bronzebeard is a direct communion with the noble ancestors who built their mountain kingdom out of stone and iron.",["faction:Alliance"]="The elder resides peacefully within the capital of Ironforge, welcoming Alliance members looking to celebrate ancient traditions under the mountain.",["faction:Horde"]="Reaching Elder Bronzebeard represents a perilous intrusion into Ironforge's fortified core, requiring stealth or daring to offer greetings."},kw={"ancestors","bronzebeard","coin of ancestry","elder","ironforge","lunar festival"},rel={"npc:elder-bronzebeard"},m={start="Elder Bronzebeard",id=8866},src={"Bronzebeard the Elder"}}
E["quest:9261"] = {t="quest",n="Investigate the Scourge of Ironforge",z="ironforge",s="Lieutenant Nevell of the Argent Dawn calls upon brave defenders as the Scourge arrives directly outside the gates of Ironforge. Undead troops and ominous runic circles threaten the snowy passes of Dun Morogh beneath a hovering necropolis. Defenders are tasked with destroying the walking corpses and deciphering the purpose behind these strange glowing sigils.",h="Lieutenant Nevell of the Argent Dawn calls upon brave defenders as the Scourge arrives directly outside the...",sec={{t="Death at the Mountain Gates",b="The Scourge invasion does not stop at Lordaeron or the plagued lands of the north. Floating necropolises cast grim shadows across Azeroth, including the frigid heights of Dun Morogh right outside Ironforge's mountain entrance. The Argent Dawn has stationed observers such as Lieutenant Nevell to monitor and counter this creeping blight before it can breach the fortress of the Bronzebeards.",sp=0},{t="Unholy Inscriptions",b="Beneath the shadow of the necropolis, the undead have established encampments marked by glowing runic circles and pulsing necrotic stones. By standing near these ominous circles, scouts discover dark, murmuring voices echoing through the ambient magic. Lieutenant Nevell deduces that these circles serve as dark conduits for communication, although he does not know whom the Scourge are contacting.",sp=1}},faq={{q="Who is Lieutenant Nevell?",a="Lieutenant Nevell is an officer of the Argent Dawn stationed at Ironforge to coordinate defense against the Scourge invasion. He tasks adventurers with collecting necrotic stones and discovering the purpose of the unholy sigils surrounding the invaders' camps.",al={"nevell","lieutenant nevell","quest giver"},it="identity"},{q="Why is the Scourge attacking Ironforge?",a="The assignment concerns Scourge forces camped outside Ironforge beneath a necropolis. Lieutenant Nevell asks defenders to thin their numbers and investigate the strange runic circles nearby.",al={"scourge outside ironforge","why undead in dun morogh","ironforge invasion"},it="threat"},{q="What are Dim Necrotic Stones?",a="Dim Necrotic Stones are recovered from Scourge invaders and brought to the Argent Dawn as proof of slain undead.",al={"necrotic stones","dim necrotic stone","scourge stones"},it="item"},{q="What is the purpose of the glowing runic circles?",a="The glowing runic circles appear near the Scourge invasion forces. Lieutenant Nevell asks you to investigate their purpose.",al={"runic circles","glowing circles","what are the runes"},it="purpose"},{q="Why does Lieutenant Nevell want this investigated?",a="With the Scourge marching upon Ironforge's doorstep and a Necropolis looming overhead, Lieutenant Nevell and the Argent Dawn refuse to remain idle. Strange runic circles glowing with unholy magic have appeared near the undead encampments outside the gates. Nevell knows these rituals bear grim significance, and he needs you to uncover what sinister forces the invaders are channeling before the city faces an even greater catastrophe.",al={"nevell motive","why investigate scourge ironforge","why does nevell want this done"},it="motive",add=true},{q="Who are you sent to fight outside Ironforge?",a="You are sent against the vanguard of the Scourge encamped right outside the gates of Ironforge. Dispatched under the command of the Lich King and bolstered by a hovering Necropolis, these undead horrors seek to terrorize Dun Morogh and lay siege to the dwarven kingdom.",al={"who to fight","scourge targets ironforge","who am i fighting"},it="target",add=true}},ang={["race:Dwarf"]="The desecration of Dun Morogh's clean snows by rotting abominations is an outrage to every dwarf. Defending the mountain entrance is a matter of home and hearth.",["faction:Alliance"]="Ironforge serves as a vital economic and martial pillar of the Alliance; an undead foothold at its gates threatens logistical lines across the Eastern Kingdoms.",["class:Paladin"]="The Scourge represents the antithesis of the Holy Light. Investigating the runic malice of the Lich King and purging his mindless thralls falls squarely within a paladin's sacred calling.",["class:Priest"]="The psychic echoes murmuring through the runic circles pose a distinct danger to the sanity of ordinary soldiers, requiring spiritual fortitude to resist."},kw={"argent dawn","dim necrotic stone","dun morogh","investigate the scourge of ironforge","ironforge","lich king","lieutenant nevell","necropolis","runic circle","scourge"},rel={"npc:lieutenant-nevell","zone:ironforge","topic:scourge","topic:argent-dawn","topic:lich-king"},m={start="Lieutenant Nevell",level="10",faction="Alliance",id=9261},src={"Investigate the Scourge of Ironforge"}}
E["subzone:commons"] = {t="subzone",n="Commons",z="ironforge",s="The Commons serves as the vibrant commercial heart of Ironforge, connecting the city entrance directly to its vast caverns. Teeming with merchants, travelers, and bankers, it is the busiest thoroughfare in the dwarven capital and the central marketplace for the entire Alliance.",h="The Commons serves as the vibrant commercial heart of Ironforge, connecting the city entrance directly to its...",sec={{t="The Commercial Hub of the Mountain",b="Located just northeast of the Gates of Ironforge, the Commons is the first district that greets travelers entering the mountain kingdom. Carved directly out of the stone, this bustling market street houses the primary Alliance Auction House, the Stonefire Tavern, and the city's central bank within the Vault of Ironforge. Broad avenues connect it seamlessly to the Great Forge, the Mystic Ward, and the Military Ward, ensuring that nearly all foot traffic in the mountain passes through its bustling storefronts.",sp=0},{t="A Crossroads for the Alliance",b="Due to Ironforge's central location on the Eastern Kingdoms continent and its direct underground Deeprun Tram link to Stormwind, the Commons functions as the Alliance's primary trade nexus. Adventurers converge here to trade goods brought from every corner of Azeroth, purchase armaments from merchants like Steelfury and Barim, or meet under the warm lantern light of the local inn before heading out into the Khaz Modan snows.",sp=0}},faq={{q="What makes the Commons so crowded compared to other districts?",a="The Commons hosts the Alliance's primary Auction House, the city's main bank in the Vault of Ironforge, and the bustling Stonefire Tavern. Its position directly inside the main gates makes it the most convenient gathering and trading place in the entire kingdom.",al={"why is commons busy","why so many players here","ironforge trade hub"},it="fame"},{q="Where does the Commons lead?",a="The Commons connects to almost every major district in Ironforge. Heading southwest leads back to the city gates, northeast connects to the Great Forge, east branches toward the Military Ward, and north leads into the Mystic Ward.",al={"commons exits","how to leave commons","commons directions"},gp=true},{q="What key shops and services are found here?",a="Beyond the Auction House and the bank, the Commons features the Ironforge Visitor's Center, Steelfury's Weapon Emporium, the Ironforge Armory, Barim's Reagents, and Fizzlespinner's General Goods.",al={"commons vendors","services in commons","ironforge commons amenities"},it="purpose"},{q="Is the bank located here?",a="Yes. The Vault of Ironforge stands across from the Auction House in the Commons and serves as the city's main bank.",al={"where is ironforge bank","ironforge vault","bank location"},it="place",gp=true},{q="What is the Commons?",a="The Commons serves as the primary commercial thoroughfare of Ironforge. Situated just past the city gates and connecting to nearly every other district, it functions as the vibrant economic heart of the dwarven capital. Here, travelers and citizens gather to trade goods at the Auction House, access the city vaults, stay at the Stonefire Tavern, or browse the wares of various local merchants.",al={"what is the commons","ironforge commons","about the commons"},it="place",add=true},{q="Is the Commons dangerous?",a="Not in the slightest. The Commons is one of the most secure and heavily populated districts in all of Khaz Modan. Protected by the mountain's impenetrable stone walls and patrolled constantly by vigilant Ironforge guards, visitors have nothing to fear from wild beasts or enemy incursions while conducting their business here.",al={"is commons dangerous","danger in the commons","is it safe here"},it="danger",add=true}},ang={["faction:Alliance"]="The Commons acts as the de facto trading floor of the Alliance, drawing heroes from Teldrassil, Stormwind, and Gnomeregan to auction valuable spoils and stock up on supplies.",["race:Dwarf"]="To the Bronzebeard dwarves, the Commons is a source of pride, proving that dwarven hospitality, industry, and commerce can thrive deep within a frozen mountain."},kw={"auction house","bank","commons","ironforge","market","stonefire tavern","vault of ironforge"},rel={"zone:ironforge","subzone:vault-of-ironforge","subzone:stonefire-tavern","subzone:gates-of-ironforge","subzone:great-forge","subzone:military-ward","subzone:mystic-ward","topic:alliance"},src={"Commons"}}
E["subzone:deeprun-tram"] = {t="subzone",n="Deeprun Tram",z="ironforge",s="The Deeprun Tram is an subterranean marvel of gnomish engineering linking the Alliance capitals of Ironforge and Stormwind City. Commissioned by King Magni Bronzebeard following the Second War, it allows citizens and soldiers to cross vast distances beneath the earth in mere minutes. The enclosed twin tracks cut beneath mountain and lake, serving as a vital artery for Alliance military support and commerce.",h="The Deeprun Tram is an subterranean marvel of gnomish engineering linking the Alliance capitals of Ironforge...",sec={{t="A Marvel of Subterranean Engineering",b="Following the devastation of the Second War, King Magni Bronzebeard grew increasingly frustrated with how slowly dwarven aid and construction supplies reached Stormwind across the mountain passes. To solve the logistical hurdle and guarantee that dwarven soldiers could rapidly reinforce the human capital in times of crisis, Magni turned to High Tinker Gelbin Mekkatorque. The master gnomish engineer drafted designs for an enclosed underground railway powered by cutting-edge technology. Despite excavation complications—including cutting right through a vast subterranean lake and battling relentless infestations of underground rats—the tram became a crowning achievement of the Alliance, moving thousands of travelers free of charge between Ironforge and Stormwind.",sp=0}},faq={{q="Why was the Deeprun Tram built?",a="After the Second War, King Magni Bronzebeard needed a faster way to transport supplies and dwarven troops to assist in rebuilding and defending Stormwind. He commissioned High Tinker Gelbin Mekkatorque, who drafted and executed the subterranean railway project to seamlessly bind the two capitals together.",al={"why build the tram","tram purpose","who built deeprun tram"},it="purpose"},{q="How does the tram travel underwater?",a="During the excavation between Dun Morogh and Stormwind, gnomish engineers breached a massive subterranean lake. Rather than routing around it, they constructed a sealed, reinforced glass viewing tunnel directly through the deep water, allowing passengers to watch wild threshadons and sharks swim alongside the track.",al={"tram water window","underwater tram","deeprun tram lake"}},{q="Why are there so many rats along the tracks?",a="The damp, dark subterranean shafts provide an ideal breeding ground for vermin. Gnomish station masters constantly struggle to keep the rat population from chewing through cables or overrunning the platforms, occasionally relying on travelers and rat catchers like Monty to cull their numbers.",al={"deeprun rats","why rats in tram","rat problem"},it="threat"},{q="Is the tram free to ride?",a="Yes. Sponsored as an open civic and military project by the governments of Ironforge and Stormwind, the tram operates continuously and without fare for all citizens and allies of the Alliance.",al={"tram cost","tram ticket price","how much to ride tram"},gp=true},{q="What is the Deeprun Tram?",a="The Deeprun Tram is an underground and underwater railway system designed by gnomes that connects the Alliance capitals of Ironforge and Stormwind City. Consisting of double tracks and two sets of three wagons, it provides rapid, free transit between the dwarven mountain stronghold and the human kingdom.",al={"what is deeprun tram","deeprun tram info","about deeprun tram"},it="place",add=true},{q="What happened at the Deeprun Tram?",a="Following the Second War, King Magni Bronzebeard wanted a faster way to transport dwarven supplies and troops to help rebuild the battered kingdom of Stormwind. He commissioned High Tinker Gelbin Mekkatorque to design the subterranean line. Despite facing an unexpected subterranean lake and an ongoing rat invasion during construction, the railway was completed and became an indispensable lifeline for the Alliance.",al={"deeprun tram history","history of deeprun tram","how was deeprun tram built"},it="history",add=true},{q="Who maintains and runs the Deeprun Tram?",a="Gnomish engineers work on the Deeprun Tram daily to ensure its mechanical wagons run smoothly and safely between the capitals. Alongside the engineering crews, tram stations and tunnels are frequented by local vendors, rail workers, and pest catchers like Monty, who tirelessly attempts to rein in the persistent rat population along the tracks.",al={"who runs deeprun tram","deeprun tram staff","who works in deeprun tram"},it="residents",add=true},{q="Is the Deeprun Tram dangerous?",a="The tram ride itself is remarkably smooth and secure, engineered to safely ferry travelers beneath mountains and subterranean waters. Walking the tracks on foot, however, exposes you to speeding wagons and a notorious infestation of deeprun rats. Outside the reinforced glass tubes, aquatic predators like threshadons and sharks lurk in the dark lake depths, safely separated from passengers.",al={"deeprun tram danger","is the tram safe","hazards in deeprun tram"},it="danger",add=true}},ang={["profession:Engineering"]="The entire railway is an unparalleled gnomish masterpiece, showcasing advanced track propulsion, pressurized glasswork capable of withstanding subterranean lake depths, and intricate electrical switching stations.",["faction:Alliance"]="The tram serves as the primary strategic artery connecting the Alliance's two most fortified capitals, allowing for rapid troop redeployment and mutual defense within minutes."},kw={"deeprun tram","dwarven district","gelbin mekkatorque","magni bronzebeard","subterranean lake","subway","tinkertown","tram"},rel={"zone:ironforge","zone:stormwind","npc:gelbin-mekkatorque","npc:magni-bronzebeard","topic:alliance","topic:second-war","topic:gnome"},src={"Deeprun Tram"}}
E["subzone:forlorn-cavern"] = {t="subzone",n="Forlorn Cavern",z="ironforge",s="Tucked along the northern shores of Ironforge's subterranean lake, the Forlorn Cavern is a dimly lit, secluded district far removed from the city's bustling Great Forge. It serves as a shadowy refuge where thieves, cutpurses, and practitioners of the dark arts conduct their business away from prying dwarven guards.",h="Tucked along the northern shores of Ironforge's subterranean lake, the Forlorn Cavern is a dimly lit...",sec={{t="Ironforge's Shaded Corner",b="While the rest of Ironforge clangs with anvil strikes and radiates heat from the Great Forge, the Forlorn Cavern is cold, damp, and hushed. Wrapping along the northern edge of the mountain's underground lake, the winding pathways sit comfortably out of sight between the Mystic Ward and the Hall of Explorers. Its gloom makes it an ideal gathering place for those who prefer to keep their affairs discreet. Rogues and warlocks train here alongside vendors serving them, while weapon merchants and fishermen also work beside the lake.",sp=0}},faq={{q="Where is the Forlorn Cavern located in Ironforge?",a="The cavern sits in the northern portion of Ironforge along the subterranean lake. You can enter it by heading east out of the Mystic Ward or west along the tunnel from the Hall of Explorers.",al={"forlorn cavern location","how to get to forlorn cavern","where is forlorn cavern"},gp=true},{q="Why do rogues and warlocks gather here?",a="The cavern is naturally dark and secluded, making it a discreet meeting place. Rogue and warlock trainers and merchants serving both groups can be found here.",al={"why warlocks here","why rogues in forlorn cavern","shady district ironforge"},it="purpose"},{q="What shops and services can be found in the Forlorn Cavern?",a="Aside from rogue and warlock trainers, the cavern features Bonegrip's Runes and Dooms catering to practitioners of dark magic, the Stoneblade weapon shop, and a quiet angling supply post known as The Traveling Fisherman.",al={"forlorn cavern vendors","shops in forlorn cavern"},gp=true},{q="What is the Forlorn Cavern?",a="The Forlorn Cavern is a dark, winding district wrapped around an underground lake deep within Ironforge. Tucked away between the Mystic Ward and the Hall of Explorers, its secluded shadows provide a quiet refuge for Ironforge's less savory residents, including local rogues, covert warlocks, and niche merchants who prefer to operate away from prying dwarven eyes.",al={"what is forlorn cavern","forlorn cavern overview","about forlorn cavern"},it="place",add=true},{q="Is the Forlorn Cavern dangerous?",a="While it is guarded as part of Ironforge, you should still tread carefully. The cavern's dim corners shelter shady characters, thieves, cutpurses, and practitioners of dark fel magic. As long as you keep your wits about you and respect the delicate business being conducted, the district remains peaceful enough for travelers to pass through unharmed.",al={"is forlorn cavern safe","danger in forlorn cavern","threats in forlorn cavern"},it="danger",add=true}},ang={["class:Rogue"]="The cavern serves as the Alliance's primary rogue hub within Khaz Modan, offering poisons, specialized blades, and discreet trainers hidden along the damp stone walkways.",["class:Warlock"]="Warlocks gather within Bonegrip's Runes and Dooms to train and obtain supplies in this secluded part of Ironforge."},kw={"bonegrip","forlorn cavern","hall of explorers","ironforge lake","mystic ward","rogue trainers","stoneblade","warlock trainers"},rel={"zone:ironforge","subzone:mystic-ward","subzone:hall-of-explorers"},src={"Forlorn Cavern"}}
E["subzone:gates-of-ironforge"] = {t="subzone",n="Gates of Ironforge",z="ironforge",s="The Gates of Ironforge serve as the monumental main entrance leading travelers from the snowy mountain vales of Dun Morogh into the dwarven capital. Carved directly into the sheer stone face of the mountain, they are guarded inside by a colossal statue of High King Modimus Anvilmar.",h="The Gates of Ironforge serve as the monumental main entrance leading travelers from the snowy mountain vales...",sec={{t="The Threshold of the Mountain",b="Approached by climbing the winding, fortified ramp ascending from central Dun Morogh, the Gates of Ironforge present an imposing facade visible across much of the snowy lowlands. Beyond the massive portal, visitors enter the city proper, greeted immediately by an enormous stone statue honoring High King Modimus Anvilmar—the legendary ruler who united the dwarven clans before the War of the Three Hammers. Passing through these gates leads directly into the bustling commercial district of the Commons.",sp=0}},faq={{q="Where do the Gates of Ironforge lead?",a="They connect the exterior mountain terrain of Dun Morogh to the city of Ironforge. Passing through the threshold brings you directly into the southwestern part of the Commons, the city's lively trade and banking hub.",al={"ironforge entrance","where do the gates go","gates of ironforge location"},it="purpose"},{q="Who is the statue inside the gates depicting?",a="The monumental sculpture just inside the entrance depicts High King Modimus Anvilmar. He was the wise and revered monarch who presided over all dwarven clans before political rifts fractured them into the Bronzebeard, Wildhammer, and Dark Iron factions.",al={"ironforge gate statue","giant dwarf statue","who is the statue at the gate"},it="identity"},{q="How do you reach the gates from Dun Morogh?",a="From central Dun Morogh, head north and climb the broad, fortified stone ramp carved into the mountainside. The ramp leads straight to the exterior threshold of the mountain fortress.",al={"how to get into ironforge","path to ironforge gates","ironforge ramp"},it="arrival",gp=true},{q="What are the Gates of Ironforge?",a="The Gates of Ironforge, also known as the Ironforge Main Gate, form the monumental entrance carved directly into the mountain face, connecting the snowy wilderness of Dun Morogh with the dwarven capital city inside. Dominating the landscape, these massive stone portals welcome travelers arriving from the great ramp to the south, leading them straight past an imposing statue of High King Modimus Anvilmar and into the bustling Commons.",al={"what are the gates of ironforge","ironforge main gate","gates of ironforge overview"},it="place",add=true},{q="Are the Gates of Ironforge dangerous?",a="No, the Gates of Ironforge are completely safe for members of the Alliance and peaceful visitors. Guarded vigilantly by the stalwart mountain kings and Ironforge guards, this grand threshold is heavily fortified against any hostile incursions, standing as an impenetrable defense for the underground kingdom against the troggs, frost trolls, and wild beasts roaming the crags of Dun Morogh.",al={"is gates of ironforge safe","ironforge gate danger","are the gates safe"},it="danger",add=true},{q="Why are they called the Gates of Ironforge?",a="They are named quite literally for their function: they serve as the grand, fortified main gateway into Ironforge, the ancient mountain home of the Bronzebeard dwarves. Through these colossal arches, visitors pass from the harsh elements of central Dun Morogh into the subterranean fires and stone halls of the kingdom itself.",al={"why called gates of ironforge","gates of ironforge name meaning","ironforge main gate name"},it="name",add=true}},ang={["race:Dwarf"]="Standing beneath the grand likeness of High King Modimus Anvilmar reminds every dwarf of the ancient era when all clans lived under one mountain as a single kin.",["faction:Alliance"]="The Gates of Ironforge stand as one of the Alliance's most fortified redoubts, virtually impervious to siege from the frigid valleys of Dun Morogh."},kw={"commons","dun morogh","gates of ironforge","ironforge entrance","ironforge main gate","modimus anvilmar"},rel={"zone:ironforge","zone:dunmorogh","subzone:commons","subzone:anvilmar"},src={"Gates of Ironforge"}}
E["subzone:great-forge"] = {t="subzone",n="Great Forge",z="ironforge",s="The Great Forge is the fiery heart and namesake of the dwarven capital of Ironforge. Situated at the very center of the city, its massive furnaces and famed Great Anvil never rest, producing legendary armaments and serving as the bustling center of civic life.",h="The Great Forge is the fiery heart and namesake of the dwarven capital of Ironforge.",sec={{t="Heart of the Mountain",b="The Great Forge was the very first structure built by the early dwarves beneath Ironforge Mountain, and the grand capital grew in concentric rings around it. Molten stone and slag pour constantly from giant foundries into glowing channels, illuminating the cavern with an amber haze. At its center stands the massive Great Anvil, overseen by Master of the Forge Myolor Sunderfury. Renowned masters of metalwork gather around its rim, hammering out armor, tools, and weapons day and night.",sp=0},{t="Hub of the Alliance",b="Beyond its smithing operations, the Great Forge is the bustling crossroads of the entire mountain city. Ringed with guild offices, supply shops, and the city's primary gryphon roost maintained by Gryth Thurden, travelers from every corner of the Alliance mingle amid the clatter of hammers.",sp=0}},faq={{q="Why is the city named after this forge?",a="When the dwarves first carved out the mountain, the Great Forge was the first part of the settlement they constructed. As the subterranean halls expanded outward from this central chamber, the entire mountain city was named Ironforge in honor of the colossal furnace at its center.",al={"why ironforge named ironforge","city namesake","ironforge origin"},it="name"},{q="What notable items have been created here?",a="The Great Anvil has yielded historic masterpieces throughout dwarven history. King Magni Bronzebeard personally forged the legendary blade Ashbringer upon its surface. The dwarves also crafted two monumental alliance bells here, sending one as a gift to Lordaeron and the other to Stormwind City, alongside ancient relics like the Aerie Battle Mace.",al={"what was made at the great anvil","great forge famous weapons","ashbringer forged here"},it="history"},{q="Who oversees the forge?",a="The day-to-day operations and maintenance of the massive hearth are directed by Myolor Sunderfury, who bears the title Keeper of the Great Forge.",al={"keeper of the great forge","who runs the forge"},it="residents"},{q="Why is it always so crowded here?",a="The forge sits at the geographic center of Ironforge, connecting directly to the outer ring and nearby districts. It hosts essential crafting trainers, merchant shops, and Ironforge's central gryphon roost, ensuring that citizens, couriers, and foreign adventurers pass through constantly.",al={"why so many people at the forge","why is the forge busy"}},{q="What is the Great Forge?",a="The Great Forge is the fiery heart and namesake of Ironforge. Situated at the very center of the subterranean mountain city, it is a bustling, soot-filled hub centered around the legendary Great Anvil. Ringed by roaring foundries, busy shops, trade trainers, and the city's gryphon roost, the forge never shuts down, serving as both an economic powerhouse and the lively crossroads of dwarven life.",al={"what is great forge","great forge ironforge","about the great forge"},it="place",add=true},{q="Is the Great Forge dangerous?",a="Within the secure underground borders of Ironforge, you are safe from wild beasts and hostile armies, guarded by stalwart dwarven sentries. However, the forge itself is an active industrial marvel filled with open troughs of molten slag, blistering heat, and heavy machinery. A careless misstep over the railing or into the blazing pits will quickly prove fatal to anyone unprepared.",al={"is great forge dangerous","great forge hazards","can you fall in great forge"},it="danger",add=true}},ang={["profession:Blacksmithing"]="The Great Anvil is considered the premier smithing site in the Alliance, home to high-ranking trainers and the legendary anvil where King Magni forged the Ashbringer.",["race:Dwarf"]="The forge represents the very foundation of dwarven civilization under the mountain, keeping centuries of smithing tradition alive without ever letting its fires go cold."},kw={"ashbringer","foundry","great anvil","great forge","gryth thurden","ironforge","magni bronzebeard","myolor sunderfury"},rel={"zone:ironforge","subzone:high-seat","npc:magni-bronzebeard","quest:6388","topic:dwarf","topic:alliance","zone:stormwind"},src={"Great Forge"}}
E["subzone:hall-of-arms"] = {t="subzone",n="Hall of Arms",z="ironforge",s="The Hall of Arms serves as the headquarters of Ironforge's military might and the chief arsenal of the dwarven kingdom. Located within the Military Ward, this fortified compound trains dwarven combatants and orchestrates the deployment of heavy armor and aerial war machines.",h="The Hall of Arms serves as the headquarters of Ironforge's military might and the chief arsenal of the...",sec={{t="Heart of the Mountain's Arsenal",b="Situated in the southeastern corner of the Military Ward, the Hall of Arms is the operational command center for the armed forces of Ironforge. Beyond housing veteran trainers for warriors and hunters, the expansive facility serves as a massive depot and staging ground for mechanized warfare. Heavy steam tanks are assembled and maintained on-site to reinforce Alliance battlefields, while gyrocopters and flying machines are brought up via industrial conveyor belts and launched directly through vertical access shafts in the cavern ceiling toward the Ironforge Airfield above.",sp=0}},faq={{q="What is the purpose of the Hall of Arms?",a="It serves as the headquarters and command center for Ironforge's military forces. It functions as both a training ground for warriors and hunters and a vital depot where war machines like steam tanks and gyrocopters are maintained and deployed.",al={"what is hall of arms","hall of arms role","why hall of arms exists"},it="purpose"},{q="Where do the flying machines launched from the ceiling go?",a="Dwarven flying machines are raised by conveyor systems and launched through vertical shafts in the ceiling directly out to the Ironforge Airfield on the mountain slopes above. This chimney is one of the only direct surface exits out of the mountain besides the main gates.",al={"ceiling shaft ironforge","flying machine tunnel","where do copters go"}},{q="Who can I find training inside the Hall?",a="The facility houses instructors for warriors and hunters, as well as Alliance battlemasters organizing troop movements and enlistments for wider battlefronts across the continent.",al={"trainers in hall of arms","who teaches here"},it="residents"},{q="Where is the Hall of Arms located?",a="It is located in the southeastern quadrant of Ironforge, anchoring the back of the Military Ward.",al={"hall of arms location","how to get to hall of arms"},it="place",gp=true},{q="What is the Hall of Arms?",a="The Hall of Arms serves as the command center and primary headquarters of Ironforge's military power. Located within the mountain city's Military Ward, it functions as a vital arsenal, training barracks, and mechanical depot where dwarven siege engines and flying machines are built, maintained, and readied for war across the Alliance.",al={"what is hall of arms","hall of arms info","about hall of arms"},it="place",add=true},{q="Is the Hall of Arms dangerous?",a="Not for citizens and allies of Ironforge. While it bristles with dwarven weaponry, siege machinery, and heavily armed troops, it is one of the most secure bastions in the kingdom. Only those foolish enough to threaten the city or cross the Alliance need fear the firepower assembled inside.",al={"is hall of arms safe","hall of arms danger","danger hall of arms"},it="danger",add=true},{q="Why is it called the Hall of Arms?",a="The complex earns its name by serving as the kingdom's central arsenal and martial heart. It is the repository where Ironforge gathers its arms—from personal weapons and armor used to drill warriors and hunters to heavy mechanized war machines like steam tanks and gyrocopters.",al={"why named hall of arms","hall of arms name origin","hall of arms meaning"},it="name",add=true}},ang={["race:Dwarf"]="For dwarves, the Hall of Arms exemplifies Khaz Modan's union of martial discipline and mechanical ingenuity, housing the tanks and aerial squadrons that protect the mountain kingdom.",["class:Warrior"]="The facility functions as the premier gathering ground for dwarven armsmen and veterans in the capital, offering instruction and battlemaster leadership."},kw={"battlemasters","dwarven army","flying machines","hall of arms","ironforge","military ward","steam tanks"},rel={"subzone:military-ward","zone:ironforge","subzone:ironforge-airfield","topic:alliance","subzone:command-center"},src={"Hall of Arms"}}
E["subzone:hall-of-explorers"] = {t="subzone",n="Hall of Explorers",z="ironforge",s="The Hall of Explorers is the sprawling archaeological wing of Ironforge and the bustling headquarters of the dwarven Explorers' League. Part museum, part archive, and part expedition command, it gathers relics, fossils, and ancient tomes from every corner of Azeroth to piece together the forgotten origins of the dwarven race.",h="The Hall of Explorers is the sprawling archaeological wing of Ironforge and the bustling headquarters of the...",sec={{t="Headquarters of the League",b="Occupying the northeastern cavern of Ironforge, the Hall of Explorers—sometimes referred to as the Assembly of Explorers—serves as the nerve center for all Alliance-sanctioned archaeological endeavors. Under the direction of High Explorer Muninn Magellas, scholars and field agents coordinate digs across distant lands, shipping back mysterious relics, ancient titan machinery, and prehistoric bones. The vast Library at its center functions as both a public museum and a restricted storehouse of historical lore.",sp=0}},faq={{q="What is the Hall of Explorers used for?",a="It serves as the global headquarters and archival museum of the Explorers' League. Scholars analyze field reports, catalog relics from excavations, and organize archaeological digs to uncover the origins of the dwarves and ancient Azeroth.",al={"hall of explorers purpose","what happens here","explorers league base"},it="purpose"},{q="Who leads the operations here?",a="High Explorer Muninn Magellas oversees the hall's expeditions, museum curation, and research archives from within the district.",al={"who runs hall of explorers","explorers league leader","high explorer"},it="in_charge"},{q="How does this place connect to the rest of Ironforge?",a="The Hall of Explorers lies in the northeastern section of the city. Archways connect it directly to the Great Forge to the southwest, the Forlorn Cavern to the west, and Tinker Town to the south.",al={"how to get here","hall of explorers exits","where is hall of explorers"},it="place",gp=true},{q="What is the Hall of Explorers?",a="The Hall of Explorers, sometimes called the Assembly of Explorers, is a prominent northeastern district within Ironforge. It serves as the world headquarters of the dwarven Explorers' League. Beyond housing offices and research archives, it acts as a grand museum and library displaying ancient relics, massive skeletons, and historical tomes recovered from excavations across Azeroth.",al={"what is hall of explorers","hall of explorers ironforge","assembly of explorers"},it="place",add=true},{q="Is the Hall of Explorers dangerous?",a="Not at all. The hall rests safely within the heavily fortified heart of Ironforge. While the expeditions sent out into the wilds face perilous ruins, hostile beasts, and ancient curses, the district itself is a quiet, scholarly sanctuary filled with archivists, archaeologists, and Alliance dignitaries studying their finds.",al={"is hall of explorers dangerous","danger hall of explorers","is it safe here"},it="danger",add=true},{q="Why is it called the Hall of Explorers?",a="The district takes its name directly from its founding tenants and leaders, the dwarven Explorers' League. Established to unearth the origins of the dwarven race and piece together titan history, the League turned this wing of the mountain city into the central staging ground and archive for its intrepid explorers.",al={"why hall of explorers","why is it named hall of explorers","hall of explorers name origin"},it="name",add=true}},ang={["race:Dwarf"]="For dwarven adventurers, the hall is the ultimate repository of your race's heritage, housing relics aimed at uncovering your ancient origins and connection to the Titans."},kw={"archaeology","explorers' league","hall of explorers","ironforge library","magellas","museum"},rel={"topic:explorers-league","subzone:library-ironforge","zone:ironforge","subzone:great-forge","subzone:tinker-town","subzone:forlorn-cavern","quest:301","quest:2300"},src={"Hall of Explorers"}}
E["subzone:hall-of-mysteries"] = {t="subzone",n="Hall of Mysteries",z="ironforge",s="Tucked into the Mystic Ward of Ironforge, the Hall of Mysteries serves as the city's spiritual and scholarly heart for the arcane and the divine. Within its blue-lit interior, dwarven and gnomish practitioners study ancient texts, train in the mysteries of the Holy Light, and weave arcane enchantments far from the clang of the Great Forge.",h="Tucked into the Mystic Ward of Ironforge, the Hall of Mysteries serves as the city's spiritual and scholarly...",sec={{t="A Temple of Magic and Faith",b="Illuminated by a distinctive blue and purple luminescence, the Hall of Mysteries stands out starkly against the rest of Ironforge. While the city around it thrives on stone, iron, and heavy plate, the hall's five soaring pillars shelter scholars draped in soft, flowing robes. It bridges both arcane wizardry and holy devotion, serving as the headquarters for the dwarven priesthood and the Order of the Silver Hand within Khaz Modan. Here, young clerics and knights study holy texts like the Tome of Divinity and receive guidance before their journeys carry them onward to Stormwind's Cathedral of Light.",sp=0}},faq={{q="What is the purpose of the Hall of Mysteries?",a="The Hall of Mysteries is Ironforge's foremost center for both divine devotion and arcane learning. It serves as a temple for the Holy Light and a study hall where dwarven and gnomish priests, paladins, and mages gather to practice their crafts, research old scripture, and train newcomers.",al={"what is this place","hall of mysteries purpose","why visit hall of mysteries"},it="purpose"},{q="Who leads the clergy here?",a="High Priest Rohan oversees the priesthood within the hall, serving as the spiritual guide for dwarven practitioners of the Light, alongside paladin mentors such as Valgar Highforge who direct the city's knights of the Silver Hand.",al={"who runs hall of mysteries","priest leader ironforge","who is high priest rohan"},it="in_charge"},{q="How does it compare to the Cathedral of Light in Stormwind?",a="While Stormwind's Cathedral of Light is dedicated purely to the holy faith and grand ceremonial worship, the Hall of Mysteries seamlessly blends holy study with arcane scholarship under one roof. Its atmosphere is scholarly and quiet rather than strictly liturgical.",al={"cathedral of light vs hall of mysteries","is it like stormwind cathedral"},it="place"},{q="Can paladins complete their training trials here?",a="Yes. Dwarven paladins are sent to the hall to study the Tome of Divinity under the mentorship of the Silver Hand, receiving instruction and sacred trials designed to test their compassion, devotion, and courage.",al={"paladin quests ironforge","tome of divinity ironforge","dwarf paladin quests"},gp=true},{q="What is the Hall of Mysteries?",a="The Hall of Mysteries is a grand temple and sanctuary located within Ironforge's Mystic Ward. Dominated by a soft blue-purple glow and towering geometric pillars, it serves as the capital's central hub for both divine devotion and the arcane arts. Within its chambers, dwarven and gnomish scholars, priests, paladins, and mages gather to study, practice their arts, and instruct new apprentices.",al={"what is hall of mysteries","hall of mysteries ironforge","mystic ward temple"},it="place",add=true},{q="Who resides in the Hall of Mysteries?",a="The hall is populated primarily by dwarven and gnomish scholars clad in flowing robes, contrasting with the heavy plate seen elsewhere in Ironforge. Its resident clergy and mentors include High Priest Rohan of the Church of the Light and Valgar Highforge of the Order of the Silver Hand, alongside esteemed mage instructors who guide students in arcane lore.",al={"who lives in hall of mysteries","hall of mysteries inhabitants","who is in hall of mysteries"},it="residents",add=true},{q="Is the Hall of Mysteries dangerous?",a="Not in the slightest. The Hall of Mysteries is a thoroughly secure sanctuary deep in the heart of Ironforge. Guarded by the kingdom's finest paladins, priests, and mages, it is a safe refuge for Alliance citizens seeking healing, spiritual contemplation, or academic study.",al={"is hall of mysteries safe","danger hall of mysteries","enemies in hall of mysteries"},it="danger",add=true}},ang={["class:Paladin"]="For dwarven champions of the Silver Hand, the hall is a foundation of their calling, where masters assign trials of virtue and grant access to the sacred Tome of Divinity.",["class:Priest"]="High Priest Rohan guides acolytes of the Light through spiritual lessons here before sending promising priests south to confer with the leadership in Stormwind."},kw={"hall of mysteries","ironforge","mage","mystic ward","paladin","priest","rohan","silver hand","tome of divinity"},rel={"subzone:mystic-ward","zone:ironforge","npc:high-priest-rohan","subzone:cathedral-of-light","quest:1641","topic:light","zone:stormwind","topic:dwarf"},src={"Hall of Mysteries"}}
E["subzone:high-seat"] = {t="subzone",n="High Seat",z="ironforge",s="The High Seat is the grand throne room of Ironforge, situated between the Commons and the Great Forge. From this elevated chamber, King Magni Bronzebeard presides over the dwarven realm alongside his royal advisors and historians. The room also houses the sealed passageway leading down into the ancient depths of Old Ironforge.",h="The High Seat is the grand throne room of Ironforge, situated between the Commons and the Great Forge.",sec={{t="Heart of Dwarven Rule",b="Overlooking the vibrant bustling rings of Ironforge, the High Seat serves as the royal seat of power for the kingdom of Khaz Modan. Within this vaulted chamber, King Magni Bronzebeard hears petitioners, holds council with his advisors, and directs the defense of the Alliance's northern bastions. Flanked by royal dignitaries such as Royal Historian Archesonus and Senator Barin Redstone, the High Seat remains a symbol of unyielding Bronzebeard authority and dwarven resilience amid troubling times across Azeroth.",sp=0},{t="Gateway to Old Ironforge",b="Behind the majestic stone appointments of the throne room lies a heavy doorway leading into the shadowy expanse of Old Ironforge. These lower ruins represent the original, ancestral halls carved out by the dwarves before the city was reconfigured around the Great Forge. Guarded and sealed to general traffic, the portal reminds visitors of the vast antiquity and cavernous history resting beneath the modern capital's stones.",sp=0}},faq={{q="Who rules from the High Seat?",a="King Magni Bronzebeard rules Ironforge from the throne within the High Seat. He directs the affairs of the Bronzebeard clan, listens to subjects, and coordinates military and diplomatic matters with the Grand Alliance.",al={"who is on the throne","ironforge king","magni throne room"},it="in_charge"},{q="Where is the High Seat located in Ironforge?",a="The chamber is centrally located in Ironforge, connected directly to the outer ring between the Commons and the Great Forge, allowing easy access for visiting citizens and envoys.",al={"where is high seat","find high seat","throne room location"},gp=true},{q="What is the sealed corridor at the back of the throne room?",a="The large archway at the rear of the High Seat leads into Old Ironforge, the cavernous ancestral ruins that lie directly beneath the modern mountain city. Access to these lower passages remains restricted.",al={"door behind magni","old ironforge door","high seat basement"}},{q="Who else can be found advising the King here?",a="King Magni is attended by prominent dwarven figures, including Royal Historian Archesonus, who safeguards the records and relics of the Bronzebeard dynasty, and Senator Barin Redstone.",al={"high seat npcs","magni advisors"},it="residents"},{q="What is the High Seat?",a="The High Seat, also known as the High Throne, is the great throne room of the kingdom of Ironforge. Situated at the very heart of the mountain city just off the Great Forge, this grand stone hall is where the dwarven monarch holds court, receives emissaries, and hears petitions from subjects across Khaz Modan.",al={"what is high seat","ironforge throne room","high seat ironforge"},it="place",add=true},{q="Is the High Seat dangerous?",a="Not if you are a friend to the Alliance. It is the heart of dwarven governance, heavily guarded by the King's personal protectors and veteran dwarven guards. Unless an invading Horde army manages to breach Ironforge's deep mountain defenses, visitors under the King's peace have nothing to fear within these halls.",al={"is high seat safe","high seat danger","threats in the high seat"},it="danger",add=true}},ang={["race:Dwarf"]="The High Seat represents the unbroken lineage of Khaz Modan's sovereignty, where King Magni Bronzebeard continues to lead his people with an iron will.",["faction:Alliance"]="As the seat of dwarven power, this chamber is critical to Alliance logistics and high-level strategy, housing envoys, advisors, and royal decrees."},kw={"archesonus","barin redstone","bronzebeard","high seat","ironforge","magni","throne"},rel={"npc:magni-bronzebeard","zone:ironforge","subzone:old-ironforge","npc:royal-historian-archesonus","subzone:great-forge","subzone:commons"},src={"High Seat"}}
E["subzone:library-ironforge"] = {t="subzone",n="Library (Ironforge)",z="ironforge",s="Tucked inside the eastern wing of the Hall of Explorers, the Library serves as Ironforge's foremost repository of historical knowledge, archeological relics, and ancient lore. Maintained diligently by the Explorers' League, it houses extensive historical tomes alongside rare artifacts recovered from digs across Azeroth.",h="Tucked inside the eastern wing of the Hall of Explorers, the Library serves as Ironforge's foremost...",sec={{t="Heart of the Explorers' League",b="Occupying a massive chamber within the Hall of Explorers, the Library is where dwarven scholars sift through the relics and field reports recovered by adventurers across the world. Administered by the Explorers' League, the shelves are packed with foundational chronicles detailing the War of the Three Hammers, the ancient Troll Wars, and the origins of the dwarven race. Inquiries regarding rare books or archival locations are directed to Librarian Mae Paledust.",sp=0},{t="The Museum Displays",b="Beyond rows of dense bookshelves, the Library doubles as a working museum overseen by Curator Thorius. Here, physical specimens collected from deep excavations, abandoned ruins, and distant shorelines are analyzed, preserved, and displayed. The League's curators preserve everything from crude murloc idols and carved knives to mysterious relics recovered frozen in northern ice, cataloging each find to piece together the hidden history of the Titans and early Azeroth.",sp=0}},faq={{q="What is the purpose of the Library in Ironforge?",a="It serves as the main research archive and museum for the Explorers' League. League members bring recovered artifacts, tomes, and field notes here to be cataloged, deciphered, and preserved for the dwarven people and the Alliance.",al={"ironforge library purpose","what is this place","hall of explorers library"},it="purpose"},{q="Who manages the collections here?",a="The Library's written collections and archival searches are assisted by Librarian Mae Paledust, while the museum wing and its physical historical artifacts are curated and maintained by Curator Thorius.",al={"who runs the library","ironforge librarian","museum curator"},it="residents"},{q="What kind of books can be read here?",a="The Library contains foundational histories covering ancient and modern events, including the Old Gods, the Dragonflights, the Troll Wars, the War of the Three Hammers, the Rise of the Horde, and the formation of the Alliance of Lordaeron.",al={"ironforge books","readable tomes","what lore is here"},it="item"},{q="Where in Ironforge is the Library located?",a="The Library occupies the eastern wing of the Hall of Explorers, situated in the northeastern quadrant of Ironforge.",al={"ironforge library location","how to find the library"},gp=true},{q="What is the Library of Ironforge?",a="The Library is an expansive repository of knowledge, history, and ancient artifacts housed within the eastern wing of the Hall of Explorers in Ironforge. Arguably the largest singular structure in the mountain city, it functions as both an immense archive of historical tomes and an active museum. It serves as the primary base of operations for the dwarven scholars and field agents of the Explorers' League.",al={"what is the library","library ironforge info","ironforge library"},it="place",add=true},{q="Is the Ironforge Library dangerous?",a="The Library rests safely within Ironforge, bustling with scholars, archivists, and members of the Explorers' League studying recovered relics and historical records.",al={"is library dangerous","library danger ironforge","threats in the library"},it="danger",add=true}},ang={["race:Dwarf"]="For dwarves, this hall represents King Magni Bronzebeard's push to uncover their Titan origins, housing the very accounts of the Awakening and the War of the Three Hammers.",["faction:Alliance"]="The Library is an invaluable strategic archive for the Alliance, preserving crucial records from the Alliance of Lordaeron and eyewitness reports from the Second and Third Wars."},kw={"books","curator thorius","explorers league","hall of explorers","ironforge","library","mae paledust","museum"},rel={"subzone:hall-of-explorers","zone:ironforge","topic:explorers-league","topic:alliance","topic:alliance-of-lordaeron","subzone:grim-batol","topic:old-god","topic:troll"},src={"Library (Ironforge)"}}
E["subzone:military-ward"] = {t="subzone",n="Military Ward",z="ironforge",s="The Military Ward serves as the martial heart of Ironforge, housing the city's command infrastructure, weapons masters, and barracks. Marked by bold red banners, it is where dwarven soldiers, hunters, and siege engineers train alongside mechanized siege engines and flying machines.",h="The Military Ward serves as the martial heart of Ironforge, housing the city's command infrastructure...",sec={{t="The Anvil of Dwarven Might",b="Situated within the northern perimeter of the mountain fortress, the Military Ward concentrates Ironforge's defensive forces into a bustling staging ground. The central complex, the Hall of Arms, accommodates warrior and hunter trainers, battlemasters, and hangars housing dwarven flying machines and steam tanks. Surrounding the drill squares and training dummies are supply outlets such as Craghelm's Plate and Chain, Goldfury's Hunting Supplies, and Timberline Arms, making the ward the primary staging point for mountaineers and city defenders.",sp=0},{t="A Garrison under Banners of War",b="Distinguished from the pale blue of the Commons and the fiery orange of the Great Forge, the Military Ward is draped in martial red banners. Between drills and weapons inspections, soldiers and off-duty guards gather at Bruuk's Corner for an ale, while Weapon Master Buliwyf Stonehand instructs recruits in ancient dwarven martial traditions.",sp=0}},faq={{q="What is the Military Ward?",a="It is the martial quarter of Ironforge, serving as the central base for the dwarven army, warrior and hunter trainers, weapons merchants, and siege machinery.",al={"military ward ironforge","ironforge barracks","ironforge warrior district"},it="place"},{q="Where can I train in weapons in Ironforge?",a="Weapon Master Buliwyf Stonehand is stationed at Timberline Arms within the Military Ward, offering training in various armaments to Alliance fighters.",al={"ironforge weapon master","where is buliwyf stonehand","learn weapons ironforge"},gp=true},{q="What is kept inside the Hall of Arms?",a="The Hall of Arms functions as the military headquarters, containing combat instructors, battlemasters, and large bays storing steam tanks and dwarven flying machines.",al={"hall of arms ironforge","what is in hall of arms","ironforge siege engines"},it="purpose"},{q="Why are the banners red in this district?",a="Ironforge's districts use specific heraldic colors for navigation and tradition; the Military Ward is draped in bold red banners to represent the martial arm of the mountain city.",al={"military ward colors","red banners ironforge"}},{q="Is the Military Ward dangerous?",a="Not to you or any ally of the Alliance. The Military Ward is one of the most heavily fortified and secure areas in the entire mountain kingdom. It serves as the primary garrison and staging ground for Ironforge's armed forces, packed with seasoned warriors, battlemasters, and active steam tanks. Unless an enemy force breaches the mountain gates, it remains entirely under dwarven martial control.",al={"is military ward safe","military ward danger","danger in military ward"},it="danger",add=true},{q="Why is it called the Military Ward?",a="The district earns its name directly from its role as the command center and headquarters of Ironforge's standing military. Everything here is dedicated to the art of war, from the Hall of Arms and weapon shops to supply outposts and vehicle bays housing siege engines and gyrocopters.",al={"why military ward","how did military ward get its name","military ward name origin"},it="name",add=true}},ang={["class:Warrior"]="The Military Ward is the chief martial hub in Ironforge, offering warrior trainers, training dummies for combat practice, and weapon masters to broaden your battlefield arsenal.",["class:Hunter"]="Rangers and mountaineers will find beast masters and supplies in the Hall of Arms, alongside Goldfury's Hunting Supplies for munitions and gear."},kw={"buliwyf stonehand","flying machines","hall of arms","ironforge","military ward","steam tanks","timberline arms"},rel={"zone:ironforge","subzone:great-forge","subzone:commons"},src={"Military Ward"}}
E["subzone:mystic-ward"] = {t="subzone",n="Mystic Ward",z="ironforge",s="The Mystic Ward is the northwestern district of Ironforge, serving as the dwarven capital's quiet sanctuary for spiritual devotion and arcane study. Distinguishable by its cool, pale blue banners and quiet halls, it stands in stark contrast to the clanging anvils of the nearby Great Forge. Its grandest structure, the Hall of Mysteries, gathers priests, paladins, and mages beneath cavernous stone arches.",h="The Mystic Ward is the northwestern district of Ironforge, serving as the dwarven capital's quiet sanctuary...",sec={{t="A Sanctuary of Faith and Sorcery",b="While dwarves are famed across Azeroth for their prowess at the forge and on the battlefield, the Mystic Ward represents the kingdom's quieter intellectual and spiritual pursuits. Marked by pale blue heraldry, this cavernous quarter connects the bustling Commons to the Forlorn Cavern and the Great Forge. Within its reaches, merchants supply scholars and spellweavers with regalia, scrolls, and alchemical reagents from shops like The Fighting Wizard and Maeva's Mystical Apparel. Dominating the district is the majestic Hall of Mysteries, where the holy disciplines of the Holy Light intersect with the practiced arts of arcane magic, offering guidance to those who wield unseen powers in defense of the Alliance.",sp=0}},faq={{q="What is the Mystic Ward used for?",a="The Mystic Ward is Ironforge's dedicated district for arcane magic, scholarly research, and spiritual worship. It provides spellcaster supplies, reagent shops, and training grounds for paladins, priests, and mages.",al={"purpose of mystic ward","what happens here","mystic ward role"},it="purpose"},{q="What is the main building in the Mystic Ward?",a="The district is anchored by the Hall of Mysteries, a grand vaulted chamber housing the capital's trainers for holy and arcane spellcasters, as well as a prominent ornamental pool.",al={"hall of mysteries","big temple","mystic ward building"}},{q="Why are the banners in this ward pale blue?",a="Ironforge uses distinct heraldry to delineate its city districts. While the Military Ward flies martial red and the Great Forge features fiery orange, the Mystic Ward displays pale blue banners to symbolize contemplation, wisdom, and magical study.",al={"blue banners ironforge","why blue flags"}},{q="Where does the Mystic Ward lead?",a="The ward sits in the northwestern quadrant of the city. Passages connect it south toward the Commons, southeast to the Great Forge, and east directly into the Forlorn Cavern.",al={"mystic ward connections","how to get to mystic ward"},gp=true},{q="What is the Mystic Ward?",a="The Mystic Ward is the northwestern district of Ironforge, dedicated to the study and practice of arcane and holy arts. Far quieter than the bustling Great Forge, it houses magical merchants, reagent shops, and the grand Hall of Mysteries, where practitioners of magic gather to study and train beneath pale blue banners.",al={"mystic ward ironforge","what is mystic ward"},it="place",add=true},{q="Who lives in or runs the Mystic Ward?",a="The ward serves as a haven for scholars, mages, paladins, and priests within the dwarven capital. Rather than a single governor, it is populated by prominent magic instructors and spiritual leaders based out of the Hall of Mysteries, alongside local arcane purveyors and reagent shopkeepers.",al={"who runs mystic ward","mystic ward leaders","who is in mystic ward"},it="residents",add=true},{q="Is the Mystic Ward dangerous?",a="Not to visitors and allies of Ironforge. The Mystic Ward is a peaceful, secure quarter of the Alliance capital. While potent magical and divine powers are channeled within its halls, they are kept under tight control by disciplined teachers and scholars.",al={"is mystic ward safe","is mystic ward hostile"},it="danger",add=true},{q="Why is it called the Mystic Ward?",a="The district takes its name from its focus on the mystical arts. Unlike the industrial Great Forge or martial Military Ward, this enclave is entirely devoted to the kingdom's arcane and divine pursuits, reagent trade, and magical instruction.",al={"mystic ward name origin","why called mystic ward"},it="name",add=true}},ang={["class:Mage"]="For Alliance spellweavers, the Mystic Ward serves as the premier center in Khaz Modan for arcane supplies, spell tomes, and advanced study outside the academies of Stormwind.",["class:Priest"]="The ward and its grand Hall of Mysteries provide a peaceful haven where dwarven and visiting practitioners of the Holy Light gather for prayer, guidance, and communion."},kw={"hall of mysteries","ironforge","longberrys reagents","maevas mystical apparel","mage trainer","mystic ward","priest trainer","the fighting wizard"},rel={"subzone:hall-of-mysteries","zone:ironforge","subzone:commons","subzone:great-forge","subzone:forlorn-cavern","subzone:military-ward"},src={"Mystic Ward"}}
E["subzone:old-ironforge"] = {t="subzone",n="Old Ironforge",z="ironforge",s="Old Ironforge, also called the Assembly of Thanes, is an ancient subterranean chamber lying directly beneath the High Seat of Ironforge. Carved deep into the mountain's roots above glowing magma veins, it represents the ancestral heart of the dwarven capital. In the present day, its heavy access gates in the royal throne room remain sealed and vigilantly guarded.",h="Old Ironforge, also called the Assembly of Thanes, is an ancient subterranean chamber lying directly beneath...",sec={{t="The Assembly of Thanes",b="Beneath King Magni Bronzebeard's throne in the High Seat rests the cavernous hall known as Old Ironforge or the Assembly of Thanes. Deep inside these fiery subterranean foundations, winding stone bridges cross pools of subterranean lava. Long before the bustling halls of the Great Forge and the Commons echoed with modern dwarven commerce, early thanes gathered in these cavernous depths to deliberate and govern the mountain kingdom.",sp=0},{t="A Sealed Chamber",b="Currently, entrance to Old Ironforge from the throne room is securely barred. The Ironforge royal guard keeps strict watch over the thresholds leading down into the old vaults. Even Master Mathias Shaw of Stormwind's SI:7 notes the presence of heavy security around these lower levels, warning that any attempt to trespass or meddle in the secured undercity risks severe dwarven justice.",sp=0}},faq={{q="What is Old Ironforge?",a="Old Ironforge, historically known as the Assembly of Thanes, is the ancient lower district carved directly beneath the modern city of Ironforge. It consists of cavernous halls and lava conduits.",al={"assembly of thanes","what is old ironforge","subterranean ironforge"},it="place"},{q="Can players enter Old Ironforge?",a="No. The main gates in the High Seat throne room are sealed shut, and the entryway is heavily guarded by the dwarven royal guard. The chambers below remain closed to regular citizens and adventurers.",al={"how to get into old ironforge","is old ironforge open","old ironforge door locked"},gp=true},{q="Where is the entrance located?",a="The entrance is located directly inside the High Seat, the royal audience chamber where King Magni Bronzebeard sits in the city of Ironforge.",al={"where is old ironforge entrance","old ironforge location"},it="place",gp=true},{q="Why is Old Ironforge significant to dwarven history?",a="Known as the Assembly of Thanes, it served as an ancient meeting ground for dwarven leaders and mountain kings in early eras before the upper rings of the modern mountain capital were fully established.",al={"history of old ironforge","why is it called assembly of thanes"},it="history"}},ang={["race:Dwarf"]="For dwarves, Old Ironforge and the Assembly of Thanes are sacred connections to their ancestral roots, preserving the deepest stone foundations carved out during the dawn of their mountain realm.",["class:Rogue"]="Stormwind's spymaster Mathias Shaw strictly warns against attempting to sneak into Old Ironforge, noting the intense security and the grim cost of getting caught by King Magni's guards."},kw={"aegrim's study","assembly of thanes","high seat","ironforge","magni bronzebeard","old ironforge"},rel={"subzone:high-seat","zone:ironforge","npc:magni-bronzebeard","npc:mathias-shaw"},src={"Old Ironforge"}}
E["subzone:stonefire-tavern"] = {t="subzone",n="Stonefire Tavern",z="ironforge",s="The Stonefire Tavern is the primary inn serving travelers inside the mountain city of Ironforge. Situated in the bustling Commons district just north of the city gates, it provides a warm hearth, strong dwarven ale, and a resting place for adventurers arriving from across Khaz Modan.",h="The Stonefire Tavern is the primary inn serving travelers inside the mountain city of Ironforge.",sec={{t="Heart of the Commons",b="Located immediately north of the fortress gates in the Commons, the Stonefire Tavern serves as the premier public house in Ironforge. Run by Innkeeper Firebrew alongside his daughter Gwenna, the inn offers weary wayfarers hearty meals, local brews, and lodging beneath the mountain. Whether seeking respite from the harsh mountain snows of Dun Morogh or looking to trade tales and supplies before venturing deep into the city, travelers from all corners of the Alliance routinely gather around its roaring hearth.",sp=0}},faq={{q="Where is the Stonefire Tavern located?",a="The tavern sits in the Commons district of Ironforge, just a short walk north after passing through the main city gates.",al={"stonefire tavern location","ironforge inn location","where is stonefire"},it="place",gp=true},{q="Who operates the Stonefire Tavern?",a="The tavern is managed by Innkeeper Firebrew with the assistance of his daughter, Gwenna Firebrew.",al={"who runs stonefire tavern","stonefire innkeeper","firebrew inn"},it="residents"},{q="Can travelers bind their hearthstones here?",a="Yes. Innkeeper Firebrew welcomes Alliance travelers seeking to make the Stonefire Tavern their home base within Ironforge.",al={"set hearth ironforge","ironforge home inn","hearthstone stonefire"},gp=true},{q="What amenities are nearby?",a="Right outside the tavern entrance sits a city mailbox, and the surrounding Commons are filled with banks, merchants, and trade supplies.",al={"stonefire services","mailbox near stonefire"},gp=true},{q="What is the Stonefire Tavern?",a="The Stonefire Tavern serves as one of the primary gathering places and inns within Ironforge. Situated in the bustling Commons district just north of the city gates, it provides a warm hearth, strong dwarven brew, and a welcoming place to rest for weary travelers, soldiers, and visitors arriving in the mountain capital.",al={"what is stonefire tavern","stonefire tavern ironforge","ironforge stonefire inn"},it="place",add=true},{q="Is the Stonefire Tavern dangerous?",a="Not in the slightest. The Stonefire Tavern is a secure, friendly refuge nestled deep inside the fortified heart of Ironforge. Guarded by the dwarven patrol and surrounded by fellow Alliance patrons, the only real hazard you might face here is drinking a mug too many of the Firebrews' potent ale.",al={"is stonefire tavern safe","stonefire tavern danger","threats stonefire tavern"},it="danger",add=true}},ang={["race:Dwarf"]="For dwarves returning from expeditions across Khaz Modan, the Stonefire Tavern is the first place in the capital to grab a cold pint of Firebrew ale and catch up on local gossip.",["faction:Alliance"]="As the closest major inn to the Ironforge front gates, the Stonefire is often the central staging ground for Alliance travelers visiting the dwarven capital."},kw={"commons","dwarven inn","gwenna firebrew","innkeeper firebrew","ironforge","khaz modan","stonefire tavern"},rel={"npc:innkeeper-firebrew","subzone:commons","zone:ironforge"},src={"Stonefire Tavern"}}
E["subzone:thistlefuzz-arcanery"] = {t="subzone",n="Thistlefuzz Arcanery",z="ironforge",s="Thistlefuzz Arcanery is a prominent workshop and academy of the magical arts located east of the Great Forge in Ironforge. Run primarily by gnome practitioners, it serves as the capital's premier haven for enchanters and scholars seeking to weave magic into metal and parchment. Its busy chambers hum with arcane energy right alongside the roaring fires of dwarven industry.",h="Thistlefuzz Arcanery is a prominent workshop and academy of the magical arts located east of the Great Forge...",sec={{t="Arcane Craft in the Mountain",b="Tucked directly east of the thundering Great Forge, Thistlefuzz Arcanery offers a stark contrast to the clanging anvils of dwarven smiths. Within its two levels, scholars, practitioners, and apprentices gather to master the subtle disciplines of enchanting and magical study. While the Ironforge dwarves prefer to reshape steel through muscle and fire, the gnomes of the Arcanery demonstrate how raw arcane energy can be bound directly into weaponry, armor, and curious tools. It stands as an essential sanctuary for spellcasters navigating the mountain stronghold.",sp=0}},faq={{q="Where is Thistlefuzz Arcanery located?",a="Thistlefuzz Arcanery sits along the eastern ring of the Great Forge in central Ironforge, easily identified by the arcane apparatuses and enchanting supplies displayed around its doors.",al={"arcanery location","where is thistlefuzz","ironforge enchanting shop"},gp=true},{q="What services are offered inside the Arcanery?",a="The shop caters to practitioners of magical crafts. Enchanting trainers, spellcraft suppliers, and scholars gather here to teach apprentices, trade rare reagents, and conduct experiments away from the physical soot of the smithies.",al={"what is in thistlefuzz arcanery","trainers in thistlefuzz"},it="purpose",gp=true},{q="Why is an arcane workshop situated so close to the Great Forge?",a="Positioning an enchanting workshop right beside the Great Forge is practical. Newly forged blades, armor plates, and mechanical components produced by the dwarven smiths can immediately be carried east to be imbued with protective enchantments and elemental power.",al={"why is it near the forge","arcanery great forge connection"}},{q="What is Thistlefuzz Arcanery?",a="Thistlefuzz Arcanery is an arcane workshop and shop nestled just east of the Great Forge in the heart of Ironforge. While the surrounding city rings with the clash of anvils and molten iron, this quiet establishment caters to practitioners of the mystic arts, offering training and supplies for aspiring enchanters.",al={"thistlefuzz arcanery","what is thistlefuzz arcanery","ironforge arcanery"},it="place",add=true},{q="Is Thistlefuzz Arcanery dangerous?",a="Not in the slightest, provided you are welcome in Ironforge. The Arcanery is a peaceful commercial shop protected by the city guards and the Ironforge authorities. Unless you are hostile to the Alliance, you can browse its shelves and converse with its practitioners without fear of harm.",al={"is thistlefuzz dangerous","thistlefuzz arcanery danger"},it="danger",add=true}},ang={["race:Gnome"]="For gnomes residing in Ironforge, Thistlefuzz Arcanery is a comfortable reminder of their love for arcane theory, technical study, and delicate experimentation amidst a city dominated by heavy dwarven iron.",["class:Mage"]="Visiting mages find familiar reagents, quiet corners of theory, and kindred spellcasters among the otherwise martial, weapon-focused halls of the dwarf capital."},kw={"arcane","enchanter","enchanting","gnome","great forge","ironforge","thistlefuzz arcanery"},rel={"zone:ironforge","subzone:great-forge"},src={"Thistlefuzz Arcanery"}}
E["subzone:tinker-town"] = {t="subzone",n="Tinker Town",z="ironforge",s="Tinker Town is the bustling gnomish quarter nestled within the subterranean dwarven city of Ironforge. Established to shelter refugees following the tragic fall of Gnomeregan, the district serves as the seat of High Tinker Gelbin Mekkatorque's government-in-exile and the primary terminus for the Deeprun Tram.",h="Tinker Town is the bustling gnomish quarter nestled within the subterranean dwarven city of Ironforge.",sec={{t="A Home in Exile",b="When subterranean troggs overran the high-tech city of Gnomeregan, the dwarven hosts of Ironforge opened their gates to the survivors. To accommodate the sudden influx of refugees, a cavernous district—previously home to dwarven residents and the entrance to the Deeprun Tram—was set aside for them. Under the watchful eye of High Tinker Gelbin Mekkatorque and his council, Tinker Town quickly became an energetic hub of whirring gears, experimental alchemy, and gadgetry. Despite being cramped guests in a stone city, the gnomes have rebuilt a semblance of their civilization around a massive spherical contraption, determined to reclaim their subterranean homeland.",sp=0},{t="Subway and Secrets",b="Beyond housing the gnomish leadership, Tinker Town is one of the most strategically significant transit hubs on the continent. The district hosts the Ironforge entrance to the Deeprun Tram, an engineering wonder that swiftly links the dwarven capital to Stormwind.",sp=0}},faq={{q="Why are gnomes living in Ironforge instead of their own city?",a="Gnomeregan fell to a sudden, devastating invasion of primitive troggs. Rather than burdening the Alliance during the Third War, the gnomes fought alone and were ultimately forced to evacuate. King Magni Bronzebeard offered Ironforge as a sanctuary, allowing High Tinker Mekkatorque to establish this district as their temporary capital in exile.",al={"why are gnomes here","why do gnomes live in ironforge","gnome refugees ironforge"},it="history"},{q="What is the Deeprun Tram entrance doing here?",a="The Deeprun Tram was built as a collaborative engineering marvel between gnomes and dwarves to connect Ironforge directly to Stormwind City. The tram's Ironforge terminus opens right into Tinker Town, providing high-speed transit between the two Alliance capitals.",al={"where does the tram go","tram in tinkertown","tinkertown portal"}},{q="Did dwarves get displaced to make room for Tinker Town?",a="Yes. When the sudden mass of refugees flooded out of Gnomeregan, Ironforge quickly repurposed this ward to house them. Several former dwarven residents, such as Skuerto, found themselves pushed out of the city entirely to make space for the newcomers.",al={"dwarves kicked out for gnomes","who lived here before"}},{q="What is Tinker Town?",a="Tinker Town is the gnomish quarter of Ironforge, carved out around the grand entrance to the Deeprun Tram. After the fall of Gnomeregan, the Ironforge dwarves welcomed their displaced allies into the mountain, granting them this district to re-establish their community, workshops, and engineering laboratories.",al={"what is tinker town","tinker town info","gnome district ironforge"},it="place",add=true},{q="Who rules Tinker Town?",a="Tinker Town serves as the seat of the gnomish government-in-exile, led by High Tinker Gelbin Mekkatorque and his council of senior advisers. Beneath his leadership, the district bustles with displaced gnomes, master engineers, alchemists, and inventors trying to forge a new future.",al={"who leads tinker town","tinker town leader","who is in charge of tinker town"},it="residents",add=true},{q="Is Tinker Town dangerous?",a="Tinker Town is entirely safe from external enemies, resting deep within the fortified heart of Ironforge. However, with volatile alchemical concoctions, whirring cogwheels, and experimental explosives packed into crowded workshops, minor mechanical mishaps and fiery accidents are never entirely out of the question.",al={"tinker town safe","is tinker town safe","tinker town threats"},it="danger",add=true},{q="Why is it called Tinker Town?",a="The district takes its name from the gnomish passion for tinkering, invention, and mechanical tinkering, as well as the title of their elected leader, High Tinker Gelbin Mekkatorque. It serves as a bustling center for tinkerers, engineers, and inventors working within the dwarven capital.",al={"why is it called tinker town","tinker town name origin","where did tinker town get its name"},it="name",add=true}},ang={["race:Gnome"]="Tinker Town is the heart of your exiled people. Here, surrounded by clanking prototypes and fellow survivors, High Tinker Mekkatorque directs ongoing efforts to reclaim Gnomeregan.",["profession:Engineering"]="For engineers, Tinker Town is an essential stop in Ironforge, offering specialized trainers, gadget vendors, and parts alongside the Deeprun Tram."},kw={"deeprun tram","engineering","gnomeregan","ironforge","mekkatorque","skuerto","tinker town","tinkertown"},rel={"zone:ironforge","zone:gnomeregan","subzone:deeprun-tram","topic:gnome","topic:trogg","npc:skuerto"},src={"Tinker Town"}}
E["subzone:vault-of-ironforge"] = {t="subzone",n="Vault of Ironforge",z="ironforge",s="The Vault of Ironforge is the primary banking house and treasure repository for the dwarven capital. Situated in the bustling Commons directly opposite the Auction House, it serves as a central hub where citizens and travelers across the Alliance securely store their wealth. The vault's operations are overseen by Dinita and the esteemed Stonemantle family.",h="The Vault of Ironforge is the primary banking house and treasure repository for the dwarven capital.",sec={{t="Heart of Dwarven Commerce",b="Carved deep into the mountain rock of the Commons, the Vault of Ironforge stands as a symbol of dwarven fiscal security and craft. With the city's trade booming, travelers, soldiers, and merchants gather here daily to deposit coin, relics, and provisions under the vigilant eyes of city guards and tellers. Overseen by Dinita and the trusted Stonemantle family, the institution offers Alliance patrons absolute peace of mind.",sp=0}},faq={{q="What is the Vault of Ironforge used for?",a="The Vault serves as the central bank and safe-deposit storehouse for the city of Ironforge. Citizens and Alliance travelers rely on it to keep their gold, gear, and prized possessions secure within the mountain's heavy stone walls.",al={"vault purpose","ironforge bank","what is this place"},it="purpose"},{q="Who operates the bank?",a="The facility is maintained by Dinita alongside members of the Stonemantle family, who manage deposits, transactions, and storage for visitors.",al={"bankers","who runs the vault","stonemantle family"},it="residents"},{q="Where is the Vault located?",a="You can find it directly in the Commons district of Ironforge, sitting just across the plaza from the bustling city Auction House.",al={"vault location","where is ironforge bank","how to find vault"},it="place",gp=true},{q="What is the Vault of Ironforge?",a="The Vault of Ironforge serves as the central bank and primary treasure repository for the dwarven capital. Situated directly across from the bustling Auction House in the Commons, it provides secure storage for travelers, merchants, and champions of the Alliance seeking a trustworthy haven for their hard-earned valuables.",al={"what is vault of ironforge","ironforge bank lore","vault of ironforge"},it="place",add=true},{q="Is the Vault of Ironforge dangerous?",a="Not in the slightest for Alliance travelers. Located safely in the heart of the city's Commons district, the Vault is heavily guarded and protected by the full might of Ironforge's city watch. Unless hostile Horde forces manage an audacious raid into the mountain itself, it remains one of the safest establishments in the realm.",al={"is vault of ironforge safe","ironforge bank danger","vault safe"},it="danger",add=true},{q="Why is it called the Vault of Ironforge?",a="It takes its name from its function and fortress-like construction. Built as the grand treasury of the city, this cavernous hall is reinforced to safeguard wealth and relics beneath the mountain's solid stone, making it the definitive vault of the dwarven nation.",al={"why is it called the vault","vault of ironforge name origin","name vault of ironforge"},it="name",add=true}},ang={["race:Dwarf"]="For dwarves, the Vault is a matter of mountain pride, representing unyielding security and an enduring reputation for safeguarding dwarven wealth.",["faction:Alliance"]="Positioned right across from the city's Auction House, the Vault serves as a cornerstone of Alliance trade, keeping adventurers well-funded and supplied."},kw={"dinita","ironforge","ironforge bank","stonemantle","the commons","vault of ironforge"},rel={"zone:ironforge","subzone:commons","topic:alliance"},src={"Vault of Ironforge"}}
E["zone:ironforge"] = {t="city",n="Ironforge",z="ironforge",s="Carved into the heart of Ironforge Mountain in snowy Dun Morogh, Ironforge is the ancestral capital of the Bronzebeard dwarves and an unassailable bastion of the Alliance. Centered on the molten heat of the Great Forge, this sprawling underground city serves as a bustling hub of commerce, industry, and ancient dwarven lore. Under the steadfast rule of King Magni Bronzebeard, it now also shelters the displaced gnomes of nearby Gnomeregan.",h="Carved into the heart of Ironforge Mountain in snowy Dun Morogh, Ironforge is the ancestral capital of the...",sec={{t="A City of Stone and Fire",b="Ironforge was founded twenty-five hundred years ago when the first generation of dwarves awakened in Uldaman and journeyed west into Dun Morogh's jagged peaks. Delving into the tallest mountain, they built a massive shrine to their titan progenitor Khaz'goroth alongside the colossal Great Forge. Ever since, the city has expanded in concentric rings around that fiery hearth. Unlike surface capitals, Ironforge is entirely enclosed beneath stone ceilings, warmed by roaring hearths and subterranean rivers of molten magma. Its fortified gates and cavernous depths have proven near-impregnable throughout centuries of war.",sp=0},{t="The War of the Three Hammers",b="For generations, three dwarven clans coexisted within Ironforge: the Bronzebeards, the Wildhammers, and the Dark Irons. When High King Modimus Anvilmar died in 230 BDP, a bitter civil war erupted for dominion over the mountain. The Bronzebeard clan prevailed and expelled their rivals. Later, Sorcerer-Thane Thaurissan led a vengeful Dark Iron siege that penetrated to the heart of Ironforge before being repulsed by Bronzebeard forces. Thaurissan accidentally summoned Ragnaros the Firelord to the south, shattering the Redridge Mountains and dooming his own host. The Bronzebeards have held undisputed control of Ironforge ever since.",sp=0},{t="Honor to the Alliance",b="During the Second War, the Bleeding Hollow orc clan overran much of Khaz Modan, but Ironforge held firm behind its sealed gates until the Alliance of Lordaeron lifted the siege. Bound by this debt of honor, King Magni Bronzebeard pledged Ironforge's eternal loyalty to the Alliance, standing firm even when kingdoms like Gilneas and Quel'Thalas abandoned it. In the Third War, Magni channeled his grief over the loss of his brother Muradin in Northrend to forge the famed blade Ashbringer at the Great Anvil. Today, Ironforge remains one of the Alliance's fiercest bulwarks.",sp=0},{t="A Haven for Exiles",b="Following the tragic fall of Gnomeregan to trogg invaders and irradiation, King Magni opened Ironforge's gates to thousands of gnome refugees. Under High Tinker Gelbin Mekkatorque, the exiles established Tinker Town, carving out a buzzing technological haven within the stone city. Coupled with the subterranean Deeprun Tram connecting Ironforge directly to Stormwind City, the dwarven stronghold has transformed into a lively crossroads of dwarven steelcraft and gnomish ingenuity.",sp=0}},faq={{q="Who rules Ironforge?",a="King Magni Bronzebeard rules Ironforge and the kingdom of Khaz Modan from the High Seat. A skilled warrior and master blacksmith, he has governed his people through the Second and Third Wars and remains a deeply loyal pillar of the Alliance.",al={"ironforge king","ruler of ironforge","who is the dwarf king"},it="leader"},{q="Why are there so many gnomes in Ironforge?",a="When the nearby gnomish capital of Gnomeregan fell to a sudden trogg invasion and a disastrous radiation accident, the surviving gnomes fled into Dun Morogh. King Magni welcomed them into Ironforge, granting them an entire quarter of the city now known as Tinker Town.",al={"gnomes in ironforge","why are gnomes here","tinker town gnomes"},it="people"},{q="What is the Great Forge?",a="The Great Forge is the fiery industrial heart of the city, fed by underground waterfalls of molten magma. It surrounds the Great Anvil, where dwarven weaponsmiths craft legendary arms and armor. King Magni himself forged the famed holy blade Ashbringer upon this anvil.",al={"great forge","ironforge anvil","center of ironforge"},it="place"},{q="How do you travel between Ironforge and Stormwind?",a="Ironforge is connected directly to Stormwind City by the Deeprun Tram, an extraordinary subterranean railway built by gnomish engineering that cuts straight through the mountain bedrock of the Eastern Kingdoms.",al={"ironforge to stormwind","deeprun tram","train to stormwind"},gp=true},{q="Has Ironforge ever fallen to an enemy army?",a="Ironforge has never fallen to an outside invader. Kilrogg Deadeye's Bleeding Hollow clan laid siege to it for months during the Second War, and the Dark Irons fought into the city during the War of the Three Hammers, but the gates and defenders held.",al={"has ironforge been conquered","did ironforge fall","ironforge siege"},it="history"},{q="Where did the other dwarf clans go?",a="After the War of the Three Hammers, the defeated Wildhammer clan relocated north into the Wetlands and the Hinterlands, while the hostile Dark Iron clan settled within the Redridge and Blackrock regions under the thrall of the Firelord.",al={"where are wildhammers","where are dark irons","three hammer clans"},it="ties"},{q="What is Ironforge?",a="Ironforge is the ancestral capital city of the dwarves and one of the oldest settlements on Azeroth. Carved deep beneath the stone of Ironforge Mountain in snowy Dun Morogh, it stands as the heart of the dwarven Kingdom of Khaz Modan and a cornerstone of the Alliance. It is a fortified underground metropolis arranged in concentric rings of cavernous chambers, roaring forges, and lively stone halls bustling with craftsmen, explorers, and soldiers.",al={"ironforge city overview","what kind of place is ironforge","about ironforge"},it="place",add=true,nx={8,9}},{q="Who built Ironforge inside the mountain?",a="Thousands of years ago, early dwarven ancestors emerged from the titan ruins of Uldaman and journeyed west into Dun Morogh. Discovering the region's tallest mountain, they carved their home deep into its bedrock, constructing an altar to the titan Khaz'goroth and igniting the Great Forge around which the underground city grew.",al={"who built ironforge","how was ironforge created","who carved ironforge"},it="origin",add=true},{q="Why is there lava running through the middle of Ironforge?",a="The city was deliberately delved around natural subterranean torrents and waterfalls of molten rock. Dwarven metalworkers harnessed this boundless geothermal heat to power the Great Forge, fueling foundries, smelters, and smithies that allow Ironforge's armorers and weaponsmiths to craft world-renowned arms and armor without ever letting the fires die.",al={"why is there lava in ironforge","lava in the great forge","why magma in ironforge"},it="place",add=true},{q="What happened at Ironforge throughout its history?",a="Long after its founding, civil war broke out when High King Modimus Anvilmar died. The Bronzebeard clan drove out the rival Wildhammer and Dark Iron clans, subsequently defending the city from a brutal Dark Iron invasion. Centuries later during the Second War, the orcish Horde besieged Ironforge, but the mountain fortress held firm until the Alliance arrived to break the siege. Today, it remains an unbroken bastion.",al={"ironforge history","history of ironforge","what happened in ironforge history"},it="history",add=true},{q="Who lives in Ironforge?",a="Ironforge is home primarily to the Bronzebeard dwarves who govern Khaz Modan. However, the catastrophic fall of Gnomeregan brought a large population of gnomish refugees into the city, establishing their own district in Tinker Town under High Tinker Gelbin Mekkatorque. Human ambassadors, traveling merchants, and Alliance adventurers of all stripes regularly walk its stone thoroughfares.",al={"who lives in ironforge","ironforge population","races in ironforge"},it="residents",add=true},{q="Is Ironforge dangerous?",a="Within its massive sealed gates, Ironforge is considered one of the safest and most secure bastions in the world. Guards patrol every ring, and its mountain walls have repelled every besieging army. However, unwary visitors can fall into the blistering molten slag pits around the Great Forge, and shadowy conspirators are known to lurk in secluded corners.",al={"is ironforge safe","threats in ironforge","is it safe here"},it="danger",add=true},{q="Why is the city called Ironforge?",a="The city took its name from the Great Forge, the colossal heart of industry and craft that dwarven settlers built upon first delving into the mountain peak. Both the surrounding cavern city and the mountain itself were named in honor of that towering, eternal foundry.",al={"ironforge name origin","why called ironforge","where did ironforge get its name"},it="name",add=true},{q="Who is in charge of Ironforge?",a="King Magni Bronzebeard, Thane of Ironforge and chieftain of the Bronzebeard clan, rules the kingdom from the High Seat. A veteran commander of the Second and Third Wars, Magni directs the dwarven nation and coordinates closely with Alliance leaders to secure Khaz Modan and the surrounding regions.",al={"ironforge leader","who leads ironforge","who is in charge"},it="in_charge",add=true,nx={15,16}},{q="Is King Magni a good king?",a="Magni is widely revered by his people as a steadfast, courageous, and capable monarch who protected his kingdom through the Horde's siege and the Scourge's onslaught. Though he personally wrestles with grief over his missing brother Muradin and tensions with his daughter Moira, he is a dedicated ruler fiercely committed to his folk and his allies.",al={"is magni bronzebeard a good king","how is king magni regarded","is magni well liked"},it="leader",add=true},{q="Does King Magni answer to Stormwind?",a="No. Ironforge is a completely sovereign kingdom. King Magni treats Stormwind as an equal and valued partner within the Alliance, tied by ancient honor and mutual defense pacts. The dwarves helped rebuild Stormwind after the Second War, and the Deeprun Tram connects their capitals, but Magni answers only to his mountain throne.",al={"does magni answer to stormwind","is ironforge under stormwind","ironforge stormwind relationship"},it="ties",add=true},{q="Why is there a gnomish district inside Ironforge?",a="When the underground gnome capital of Gnomeregan fell to a sudden trogg invasion and toxic irradiation, High Tinker Gelbin Mekkatorque led the surviving survivors to Ironforge. King Magni offered unconditional sanctuary to his longstanding neighbors, setting aside a district that became Tinker Town to shelter their court in exile.",al={"why do gnomes live in ironforge","why is tinker town here","gnomes in ironforge history"},it="history",add=true,nx={18,19}},{q="What happened to Gnomeregan?",a="Vicious subterranean primitives called troggs erupted into Gnomeregan from deep fissures. Desperate to purge the invaders without burdening the Alliance during the Third War, the gnomes vented radioactive waste into the lower levels. The radiation failed to wipe out the troggs and instead irradiated the city, sickening many citizens and forcing the survivors to flee.",al={"what happened at gnomeregan","fall of gnomeregan","why did gnomeregan fall"},it="history",add=true},{q="Are the gnomes planning to reclaim Gnomeregan?",a="Yes. Tinker Town serves as the staging ground for High Tinker Mekkatorque and his engineers as they scheme, invent, and build machines to reclaim their irradiated home. Gnomish commandos and Alliance volunteers routinely launch strikes into the city's corridors to clear troggs and eliminate traitorous threats.",al={"will gnomes take back gnomeregan","are gnomes retaking gnomeregan","gnomeregan retaking plans"},it="wants",add=true},{q="How did I end up in Ironforge?",a="If you are a dwarf or gnome, you likely marched up the great stone ramparts from Dun Morogh after proving yourself in Coldridge Valley and Kharanos, sent to present yourself to the city's leadership. If you hail from farther away, you likely arrived via the Deeprun Tram straight from the heart of Stormwind, or flew directly into the Great Forge on the back of a gryphon to trade, study, or answer King Magni's call to arms.",al={"how did i get here","how did i get to ironforge","how did i reach ironforge"},it="arrival",add=true},{q="What am I supposed to be doing in Ironforge?",a="Ironforge serves as the beating heart of trade, training, and military planning for the Alliance in Khaz Modan. Here you can master your profession around the roaring fires of the Great Forge, seek advanced training in your class, or consult the Explorers' League in the Hall of Explorers. High Tinker Mekkatorque coordinates gnome resistance from Tinker Town, while King Magni Bronzebeard oversees the realm's defense against rising threats across the Eastern Kingdoms.",al={"what should i do in ironforge","why am i here","what is my goal here"},it="purpose",add=true}},ang={["race:Dwarf"]="Ironforge is the ancestral home of your kin, standing as a proud testament to your resilience, your mastery of stone, and the sacred lineage tracing back to the titans.",["race:Gnome"]="Since the disaster that consumed Gnomeregan, Tinker Town has served as your temporary home and command center as High Tinker Mekkatorque plots the liberation of your city.",["profession:Blacksmithing"]="The Great Forge is revered across Azeroth as the premier center of metalworking, housing the Great Anvil where master smiths and King Magni himself shape metal into legend.",["faction:Alliance"]="Connected seamlessly to Stormwind via the Deeprun Tram, Ironforge stands as the Alliance's northern anchor and one of its most reliable military fortresses."},kw={"bronzebeard","deeprun tram","dun morogh","great forge","high seat","ironforge","khaz modan","magni bronzebeard","tinker town"},rel={"npc:magni-bronzebeard","subzone:great-forge","subzone:tinker-town","subzone:deeprun-tram","subzone:high-seat","zone:dunmorogh","npc:gelbin-mekkatorque","topic:bronzebeard-clan"},src={"Ironforge"}}
